part of '../main.dart';

enum _DriverRidesHubSegment { available, myRides, history }

// STREET-RIDE-HISTORY-DUPLICATE-ZERO-BOOKING-1A: relational-field accessors for
// raw `/trips/history` trip maps, used by the canonical dedupe in the KPI /
// completed-today paths. PII-free: read only structural relation fields.
Map<String, dynamic> _tripMapBookingDetails(Map<String, dynamic> t) {
  final d = t['booking_details'];
  if (d is Map) return Map<String, dynamic>.from(d);
  return const <String, dynamic>{};
}

String _tripMapParentBookingId(Map<String, dynamic> t) {
  final details = _tripMapBookingDetails(t);
  return (t['parent_booking_id'] ??
          t['parentBookingId'] ??
          details['parent_booking_id'] ??
          details['parentBookingId'] ??
          '')
      .toString()
      .trim();
}

bool _tripMapIsOperationalLeg(Map<String, dynamic> t) {
  final details = _tripMapBookingDetails(t);
  final flag = details['is_operational_leg'] ?? details['isOperationalLeg'];
  if (flag == true) return true;
  if (flag is String) {
    final s = flag.toLowerCase();
    if (s == 'true' || s == '1') return true;
  }
  final legId =
      (details['leg_id'] ?? details['legId'] ?? '').toString().trim();
  final legType =
      (details['leg_type'] ?? details['legType'] ?? '').toString().trim();
  return legId.isNotEmpty || legType.isNotEmpty;
}

bool? _tripMapWorkerShadowHint(Map<String, dynamic> t) {
  final v = t['is_operational_shadow'];
  if (v is bool) return v;
  if (v is String) {
    final s = v.toLowerCase();
    if (s == 'true' || s == '1') return true;
    if (s == 'false' || s == '0') return false;
  }
  return null;
}

String _tripMapLinkedTrackingTripId(Map<String, dynamic> t) {
  final details = _tripMapBookingDetails(t);
  return (t['linked_tracking_trip_id'] ??
          t['linkedTrackingTripId'] ??
          details['linked_tracking_trip_id'] ??
          details['linkedTrackingTripId'] ??
          '')
      .toString()
      .trim();
}

/// Cross-instance cache of the last known good driver photo URL keyed by
/// driverId. Survives State recreation across navigation, theme change, and
/// short windows where [activeDriverSessionNotifier] is null while standalone
/// restore is in progress. Never mixes photos across different driverIds.
final Map<String, String> _lastKnownDriverPhotoByDriverId = <String, String>{};

void _rememberLastKnownDriverPhoto(String? driverId, String? photoUrl) {
  final id = (driverId ?? '').trim();
  final url = (photoUrl ?? '').trim();
  if (id.isEmpty || url.isEmpty) return;
  _lastKnownDriverPhotoByDriverId[id] = url;
}

String? _readLastKnownDriverPhoto(String? driverId) {
  final id = (driverId ?? '').trim();
  if (id.isEmpty) return null;
  final cached = _lastKnownDriverPhotoByDriverId[id];
  if (cached == null) return null;
  return cached.trim().isEmpty ? null : cached;
}

/// NAV-ORIENTATION-VIEWPORT-STABILITY-P0-1: pure signature capturing the
/// effective navigation viewport (rounded size + orientation). The rounding
/// tolerates sub-pixel MediaQuery jitter that would otherwise trigger a
/// spurious epoch bump every frame, while any real portrait ↔ landscape
/// swap flips [isLandscape] and any non-trivial viewport-size change (>= 1px
/// in either axis) rounds to a different key.
@immutable
class _NavViewportSignature {
  const _NavViewportSignature({
    required this.widthKey,
    required this.heightKey,
    required this.isLandscape,
  });

  factory _NavViewportSignature.fromSize({
    required Size size,
    required bool isLandscape,
  }) {
    return _NavViewportSignature(
      widthKey: size.width.isFinite ? size.width.round() : -1,
      heightKey: size.height.isFinite ? size.height.round() : -1,
      isLandscape: isLandscape,
    );
  }

  final int widthKey;
  final int heightKey;
  final bool isLandscape;

  bool get hasFinitePositiveExtent => widthKey > 0 && heightKey > 0;

  /// True when the orientation flag is consistent with the viewport shape.
  /// A transitional frame in which the framework flipped [isLandscape] but
  /// has not yet republished a matching size returns false and must not be
  /// promoted to the settled signature.
  bool get isShapeConsistent {
    if (widthKey <= 0 || heightKey <= 0) return false;
    if (isLandscape) return widthKey > heightKey;
    return heightKey >= widthKey;
  }

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) return true;
    return other is _NavViewportSignature &&
        other.widthKey == widthKey &&
        other.heightKey == heightKey &&
        other.isLandscape == isLandscape;
  }

  @override
  int get hashCode => Object.hash(widthKey, heightKey, isLandscape);

  @override
  String toString() =>
      '_NavViewportSignature(${widthKey}x$heightKey, landscape=$isLandscape)';
}

