  DateTime? _reroutePackagePreparedAt;
  bool _lastRerouteFailed = false;
  String? _rerouteReason;
  DateTime? _offRouteRerouteDebounceStartedAt;
  // FLUXIDI-REROUTE-DETERMINISTIC-FASTPATH-P0-1 field telemetry anchors.
  DateTime? _rerouteSuspectedAt;
  DateTime? _rerouteConfirmedAt;
  DateTime? _rerouteTriggerAt;
  String? _lastNavRerouteCandidateSignature;
  String? _lastNavRerouteBannerSignature;
  // Legacy constants retained for call-site readability; live policy lives in
  // [NavRerouteDecisionConfig] / [navRerouteEvaluateCooldown].
  static const Duration _rerouteCooldown = Duration(seconds: 12);
  // NAV-R12-B: route-deviation off-route must correct fast, and a failed
  // reroute retries on a short backoff instead of the full cooldown.
  static const Duration _rerouteCooldownRouteDeviation = Duration(seconds: 8);
  static const Duration _rerouteFailedRetryBackoff = Duration(seconds: 3);
  int _routeCleanupEpoch = 0;
  // NAV-SIGNAL-P0B: network request generation (not applied route version).
  final DriverRouteRequestGenerationClock _routeRequestGeneration =
      DriverRouteRequestGenerationClock();
  NavigationWorkerOfflineCorridorMetadata? _lastOfflineCorridorMetadata;
  bool _offlineCorridorMetadataLoading = false;
  bool _offlineCorridorMetadataError = false;
  String? _offlineCorridorMetadataFingerprint;
  DateTime? _offlineCorridorMetadataFetchedAt;
  int _offlineCorridorMetadataRequestId = 0;
  int _mapRedrawCountThisMinute = 0;
  int _routeRedrawCountThisMinute = 0;
  Timer? _renderDebugWindowTimer;

  /// NAV-SIGNAL-P0B2: invalidate async map draws only. Never increments
  /// `_routeStepsVersion` and never announces a new accepted route to
  /// streetlevel / native-follow / stabilization / complexity.
  void _invalidateRouteRenderEpoch({required String reason}) {
    _routeRenderEpoch += 1;
    debugPrint(
      formatNavRouteRenderDiag(
        action: 'invalidate',
        reason: reason,
        renderEpoch: _routeRenderEpoch,
        activeRouteVersion: _routeStepsVersion,
        sessionGeneration: _navigationSessionGeneration,
        styleGeneration: _styleRequestGeneration,
      ),
    );
  }

  void _logNavRideBoundary({
    required NavRideBoundaryEvent event,
    String? extra,
  }) {
    debugPrint(
      formatNavRideBoundaryDiag(
        event: event,
        sessionGeneration: _navigationSessionGeneration,
        styleGeneration: _styleRequestGeneration,
        routeVersion: _routeStepsVersion,
        renderEpoch: _routeRenderEpoch,
        extra: extra,
      ),
    );
  }

  void _logNavRouteRenderOwner({
    required NavRouteRenderOwnerEvent event,
    String? rejectionReason,
  }) {
    debugPrint(
      formatNavRouteRenderOwnerDiag(
        event: event,
        sessionGeneration: _navigationSessionGeneration,
        styleGeneration: _styleRequestGeneration,
        routeVersion: _routeStepsVersion,
        renderEpoch: _routeRenderEpoch,
        rejectionReason: rejectionReason,
      ),
    );
  }

  /// Bump ride/session ownership. Prior async style/route work becomes stale.
  int _bumpNavigationSessionGeneration({required String reason}) {
    final prior = _navigationSessionGeneration;
    _navigationSessionGeneration += 1;
    if (prior > 0) {
      _logNavRideBoundary(
        event: NavRideBoundaryEvent.priorSessionInvalidated,
        extra: 'reason=$reason prior=$prior',
      );
    }
    return _navigationSessionGeneration;
  }

  /// Idempotent hard clear at a ride boundary. Invalidates render ownership,
  /// clears route geometry/markers/banner/lane/progress/reroute state, and
  /// drops pending style-restore eligibility for the prior session. Preserves
  /// user preferences (map style choice, vehicle, View level).
  void _hardClearAtRideBoundary({
    required String reason,
    bool bumpSession = false,
    bool renderAlreadyInvalidated = false,
  }) {
    if (bumpSession) {
      _bumpNavigationSessionGeneration(reason: reason);
    }
    // NAV-RELEASE-FINAL-FLOW-1: ride boundary always ends unmetered NAV
    // guidance so style/zoom gates fall back to the next surface phase.
    _navigationGuidanceActive = false;
    if (reason == 'stop_begin' ||
        reason == 'dispose' ||
        reason == 'booking_open') {
      _activeNavTargetOwner.clear();
      _arrivalEvaluatorSnapshotId = null;
      _navPhaseTransitionStaleGuard = false;
      _navPhaseTransitionAt = null;
    }
    // Style generation advances so in-flight style restores from the prior
    // session cannot repaint after this boundary.
    _styleRequestGeneration += 1;
    if (!renderAlreadyInvalidated) {
      _invalidateRouteRenderEpoch(reason: reason);
    }
    _routeCleanupEpoch++;
    _routeRequestGeneration.invalidateAll();
    _resetNavProgressState(
      clearRoute: true,
      renderInvalidateReason: reason,
      renderAlreadyInvalidated: true,
    );
    _lastRouteDrawSignature = '';
    _lastRouteDrawAt = null;
    _lastPinsDrawSignature = '';
    _routeLineProgressTrimmed = false;
    _lastRouteLineTrimProgressM = 0.0;
    _lastRouteLineTrimAt = null;
    _activeRouteRenderOwner = RouteRenderOwnerPackage(
      sessionGeneration: _navigationSessionGeneration,
      styleGeneration: _styleRequestGeneration,
      routeVersion: _routeStepsVersion,
      renderEpoch: _routeRenderEpoch,
    );
    _logNavRideBoundary(
      event: NavRideBoundaryEvent.routeStateCleared,
      extra: 'reason=$reason',
    );
    _logNavRouteRenderOwner(event: NavRouteRenderOwnerEvent.cleared);
    unawaited(_reconcileMapZoomGestures(reason: reason));
    // Fire-and-forget Mapbox annotation deletes; shared refs are nulled first
    // so a concurrent draw cannot orphan a prior line via shared-field races.
    // NAV-STYLE-MANAGER-CRASH-TELLERS-MARKER-1: capture gate ownership and
    // re-check before every native delete. If the manager was drained/disposed
    // (style swap), the op is a no-op — never cross the Flutter → native
    // boundary against a removed manager id (Android fatal).
    final outline = _routeLineOutline;
    final line = _routeLine;
    final completed = _routeLineCompleted;
    final mgr = _routeLineManager;
    _routeLineOutline = null;
    _routeLine = null;
    _routeLineCompleted = null;
    if (mgr != null) {
      // NAV-ANNOTATION-MANAGER-TRANSACTIONAL-LIFECYCLE-2: one lease covers all
      // three deletes so disposal awaits them (no check-then-act gap between
      // the per-annotation awaits).
      // NAV-ANNOTATION-LIFECYCLE-REPAIR-1: each delete is idempotent / serialized
      // and never throws — overlapping clear vs replace cannot surface
      // unhandled PlatformException through DartMessenger.
      unawaited(
        _runAnnotationTx<void>(
          gate: _routeAnnotationGate,
          kind: NavAnnotationOperationKind.delete,
          nativeOp: () => _safeDeleteRoutePolylines(
            <mb.PolylineAnnotation?>[outline, line, completed],
            mgr: mgr,
            reason: 'ride_boundary_$reason',
          ),
        ),
      );
    }
    unawaited(
      _clearNavigationDestinationMarker(
        action: 'clear',
        result: 'cleared',
        source: 'none',
        reason: 'ride_boundary_$reason',
      ),
    );
    final pickup = _pickupPin;
    final dropoff = _dropoffPin;
    final pinsMgr = _pinsPointManager;
    _pickupPin = null;
    _dropoffPin = null;
    if (pinsMgr != null) {
      unawaited(
        _runAnnotationTx<void>(
          gate: _pinsAnnotationGate,
          kind: NavAnnotationOperationKind.delete,
          nativeOp: () async {
            if (pickup != null) await pinsMgr.delete(pickup);
            if (dropoff != null) await pinsMgr.delete(dropoff);
          },
        ),
      );
    }
  }

  void _activateRouteRenderOwnerPackage() {
    final previous = _activeRouteRenderOwner;
    final next = RouteRenderOwnerPackage(
      sessionGeneration: _navigationSessionGeneration,
      styleGeneration: _styleRequestGeneration,
      routeVersion: _routeStepsVersion,
      renderEpoch: _routeRenderEpoch,
      hasFullRoute: _routeCoords.length >= 2,
      hasCompletedRoute: _routeLineCompleted != null,
      hasRemainingRoute: _routeCoords.length >= 2,
      hasDestinationMarker: _destinationMarker != null,
      hasManeuverBannerState: _activeBanner != null,
      hasLaneState: _activeLaneGuidance != null,
    );
    _activeRouteRenderOwner = previous == null
        ? next
        : previous.replacedBy(next);
    _logNavRouteRenderOwner(
      event: previous == null || previous.isEmpty
          ? NavRouteRenderOwnerEvent.activated
          : NavRouteRenderOwnerEvent.replaced,
    );
    _logNavRideBoundary(event: NavRideBoundaryEvent.newRouteActivated);
  }

  void _resetNavProgressState({
    bool clearRoute = false,
    String renderInvalidateReason = 'hard_clear',
    bool renderAlreadyInvalidated = false,
  }) {
    if (clearRoute) {
      _routeCoords = [];
      _routeKm = null;
      _routeDurationSec = null;
      // New ride / cleared session: allow a fresh terminal-fallback attempt.
      // App resume must never call this path solely to reopen the prompt.
      _resetExternalNavFallbackLatchForNewAttempt(reason: 'route_cleared');
    }
    _routeSteps = const <_NavStep>[];
    _nextStepIndex = 0;
    _nextNavInstruction = null;
    _nextNavStreet = null;
    _nextNavDistanceM = null;
    _nextNavType = null;
    _nextNavModifier = null;
    _navInstructionSnapshot = null;
    _activeBanner = null;
    _activeLaneGuidance = null;
    _lastLaneResolveDiag = null;
    _lastRouteSnap = null;
    _lastMovementBearing = null;
    // NAV-PARKING-2 Commit 1: a previous ride's heading must never seed the new
    // session's camera/marker. Clear the last GPS/course bearing at every
    // progress reset so startup orientation starts from fresh evidence only.
    _lastKnownBearing = 0.0;
    _navParkingArrival.reset();
    _navParkingArrivalConfirmed = false;
    _lastNavArrivalEvent = null;
    _arrivalEvaluatorSnapshotId = null;
    // Do not clear the active target here — ride-boundary / START install owns
    // snapshot lifecycle. Progress reset alone must not resurrect pickup A.
    _useMatchedVisual = false;
    _matchEnterHits = 0;
    _matchExitHits = 0;
    _lastVisualProgressM = null;
    _routeLineProgressTrimmed = false;
    _lastRouteLineTrimProgressM = 0.0;
    _lastRouteLineTrimAt = null;
    _lastMarkerLagM = 0.0;
    _offRouteHitCount = 0;
    _offRouteLikely = false;
    _offRouteReason = 'none';
    // NAV-DIRECTIONS-FAILURE-SECURITY-AND-RECOVERY-1: a full route-state teardown
    // also clears any pending route-failure/retry so a stale connectivity banner
    // or auto-retry can never survive into the next session.
    _clearNavRouteFailure();
    _isRerouting = false;
    _pendingRerouteAfterInFlight = false;
    _pendingRerouteReason = null;
    _rerouteOwnershipAccepted = false;
    _rerouteApplyForwardOwnershipActive = false;
    _rerouteApplyStaleWriters.reset();
    _lastRerouteAt = null;
    _lastRerouteSuccessAt = null;
    _lastRerouteFailureAt = null;
    _routeAcceptedAt = null;
    _rerouteDecisionEligibleAt = null;
    _rerouteRequestStartedAt = null;
    _reroutePackagePreparedAt = null;
    _lastRerouteFailed = false;
    _rerouteReason = null;
    _offRouteRerouteDebounceStartedAt = null;
    _rerouteSuspectedAt = null;
    _rerouteConfirmedAt = null;
    _rerouteTriggerAt = null;
    _lastNavRerouteCandidateSignature = null;
    _lastNavRerouteBannerSignature = null;
    _lastRerouteDecision = null;
    _rerouteDecision.reset();
    // FLUXIDI NAV-STREETLEVEL-FLUID-MOTION-2 (Phase 1, Part F): clear the
    // stabilisation gate whenever nav progress state is reset (route
    // clearing, ride end, driver session swap).
    _rerouteStabilization.reset();
    _driverNavEngine.reset();
    _lastNavEngineOutput = null;
    _lastNavEngineRefreshKey = null;
    _resetNavR3MotionState();
    _resetNavRouteProgressState();
    _resetNavCameraPolicyState();
    _resetNavConfidenceState();
    _resetNavComplexityState();
    _resetNavMotionPredictionState();
    _resetNavInstructionPolicyState();
    if (clearRoute) {
      // NAV-SIGNAL-P0B2: invalidate in-flight builders + render epoch only.
      if (!renderAlreadyInvalidated) {
        _invalidateRouteRenderEpoch(reason: renderInvalidateReason);
      }
      _routeRequestGeneration.invalidateAll();
      // Drop pending follow poses without announcing a new accepted route.
      _streetlevelFollowPump.reset();
      _resetOfflineCorridorMetadataState();
      _resetNavValidationState();
    }
  }

  void _resetNavValidationState({bool flushReport = false}) {
    if (flushReport) {
      _flushNavValidationReport(reason: 'tracking_stop');
      return;
    }
    _driverNavValidationEngine.reset();
    _lastNavValidationSampleAt = null;
    _lastNavPredictionReason = null;
    _navValidationPendingCameraFollowed = false;
    _navValidationPendingCameraSkipReason = null;
  }

  void _flushNavValidationReport({required String reason}) {
    // NAV-R10 (Part G): fold in the camera stale-target drops observed by the
    // follow pump before building the final report.
    _driverNavValidationEngine.noteCameraStaleTargetDrops(
      _streetlevelFollowPump.droppedStaleTargets,
    );
    final report = _driverNavValidationEngine.buildReport();
    if (report.sampleCount > 0) {
      debugPrint(
        '[NAV_R10_REPORT] durationSec=${report.durationSec} '
        'samples=${report.sampleCount} '
        'score=${report.overallDriverOsScore.toStringAsFixed(1)} '
        'gps=${report.avgGpsScore.toStringAsFixed(1)} '
        'route=${report.avgRouteConfidence.toStringAsFixed(1)} '
        'confidence=${report.avgOverallConfidence.toStringAsFixed(1)} '
        'snapAvg=${report.avgSnapDistanceM.toStringAsFixed(1)} '
        'predictionEvents=${report.predictionEvents} '
        'offRouteEvents=${report.offRouteEvents} '
        'cameraSkips=${report.cameraSkipEvents} '
        'medianCallbackMs=${report.medianCallbackIntervalMs} '
        'p95CallbackMs=${report.p95CallbackIntervalMs} '
        'maxSourceAgeMs=${report.maxSourceAgeMs} '
        'maxMarkerLagMs=${report.maxMarkerLagMs} '
        'predGapExceeded=${report.predictionGapExceededCount}/'
        '${report.predictionGapExceededMs} '
        'cameraStaleDrops=${report.cameraStaleTargetDrops} '
        'reroute=${report.rerouteObservation.logLabel} '
        'label=${report.summaryLabel.logLabel} '
        'reason=$reason',
      );
      unawaited(
        NavDiagnosticsRecorder.instance.recordValidationReport(
          durationSec: report.durationSec,
          sampleCount: report.sampleCount,
          overallScore: report.overallDriverOsScore,
          gpsScore: report.avgGpsScore,
          routeConfidence: report.avgRouteConfidence,
          overallConfidence: report.avgOverallConfidence,
          snapAvgM: report.avgSnapDistanceM,
          predictionEvents: report.predictionEvents,
          offRouteEvents: report.offRouteEvents,
          cameraSkips: report.cameraSkipEvents,
          label: report.summaryLabel.logLabel,
          reason: reason,
          medianCallbackIntervalMs: report.medianCallbackIntervalMs,
          p95CallbackIntervalMs: report.p95CallbackIntervalMs,
          maxSourceAgeMs: report.maxSourceAgeMs,
          maxMarkerLagMs: report.maxMarkerLagMs,
          predictionGapExceededCount: report.predictionGapExceededCount,
          predictionGapExceededMs: report.predictionGapExceededMs,
          cameraStaleTargetDrops: report.cameraStaleTargetDrops,
          rerouteObservation: report.rerouteObservation.logLabel,
        ),
      );
    }
    unawaited(
      NavDiagnosticsRecorder.instance.endSessionIfActive(reason: reason),
    );
    _driverNavValidationEngine.reset();
    _lastNavValidationSampleAt = null;
    _lastNavPredictionReason = null;
    _navValidationPendingCameraFollowed = false;
    _navValidationPendingCameraSkipReason = null;
  }

  void _maybeAddNavValidationSample(geo.Position pos) {
    if (!_isActiveDriverNavEngineContext()) return;

    final now = DateTime.now();
    final lastSampleAt = _lastNavValidationSampleAt;
    if (lastSampleAt != null &&
        now.difference(lastSampleAt).inMilliseconds < 1000) {
      return;
    }
    _lastNavValidationSampleAt = now;

    final progress = _lastNavRouteProgress;
    final confidence = _lastNavConfidence;
    final prediction = _lastNavMotionPrediction;
    final engineOutput = _lastNavEngineOutput;

    _driverNavValidationEngine.addSample(
      NavValidationSample(
        timestamp: now,
        gpsAccuracyM: pos.accuracy.isFinite && pos.accuracy > 0
            ? pos.accuracy
            : null,
        speedKmh: _speedKmhFor(pos),
        routeConfidence: progress?.confidence,
        snapDistanceM: progress?.snapDistanceM,
        overallConfidence: confidence?.overallScore,
        cameraScore: confidence?.cameraScore,
        instructionScore: confidence?.instructionScore,
        predictionActive: prediction?.predictionActive ?? false,
        offRouteLikely: progress?.offRouteLikely ?? _offRouteLikely,
        markerAnimated:
            _navR3MotionActive || (engineOutput?.shouldAnimateMarker ?? false),
        cameraFollowed: _navValidationPendingCameraFollowed,
        cameraSkippedReason: _navValidationPendingCameraSkipReason,
      ),
    );
  }

  void _resetOfflineCorridorMetadataState() {
    _offlineCorridorMetadataRequestId++;
    _lastOfflineCorridorMetadata = null;
    _offlineCorridorMetadataLoading = false;
    _offlineCorridorMetadataError = false;
    _offlineCorridorMetadataFingerprint = null;
    _offlineCorridorMetadataFetchedAt = null;
  }

  String _routeGeometryFingerprint() {
    if (_routeCoords.length < 2) return '';
    final first = _routeCoords.first;
    final last = _routeCoords.last;
    return '${_routeCoords.length}|'
        '${first.lat.toStringAsFixed(3)}|${first.lon.toStringAsFixed(3)}|'
        '${last.lat.toStringAsFixed(3)}|${last.lon.toStringAsFixed(3)}|'
        '${(_routeKm ?? 0).toStringAsFixed(1)}';
  }

  Map<String, dynamic> _routeGeometryGeoJson() {
    return <String, dynamic>{
      'type': 'LineString',
      'coordinates': _routeCoords
          .map((coord) => <double>[coord.lon, coord.lat])
          .toList(growable: false),
    };
  }

  bool _hasOfflineCorridorNavContext() {
    return _cameraMode == _CameraMode.follow || _liveRideActive;
  }

  void _logCloudNav3({required String result, required String reason}) {
    _logNavBounded(
      'CLOUD_NAV_3',
      'endpoint=offline result=$result reason=$reason',
      intervalMs: 2500,
    );
  }

  String _formatCorridorByteRange(int minBytes, int maxBytes) {
    String one(int bytes) {
      if (bytes < 1024) return '$bytes B';
      if (bytes < 1024 * 1024) {
        return '${(bytes / 1024).toStringAsFixed(0)} KB';
      }
      return '${(bytes / (1024 * 1024)).toStringAsFixed(1)} MB';
    }

    return '${one(minBytes)} - ${one(maxBytes)}';
  }

  Future<void> _maybeFetchOfflineCorridorMetadata({bool force = false}) async {
    if (!kUseNavigationWorker) {
      _logCloudNav3(result: 'disabled', reason: 'flag_off');
      return;
    }
    if (_routeCoords.length < 2) {
      _logCloudNav3(result: 'skipped', reason: 'no_route_geometry');
      return;
    }
    if (!_hasOfflineCorridorNavContext() && !force) {
      _logCloudNav3(result: 'skipped', reason: 'no_nav_context');
      return;
    }

    final fingerprint = _routeGeometryFingerprint();
    if (!force &&
        fingerprint == _offlineCorridorMetadataFingerprint &&
        _lastOfflineCorridorMetadata != null) {
      _logCloudNav3(result: 'ready', reason: 'cached');
      return;
    }
    if (_offlineCorridorMetadataLoading &&
        fingerprint == _offlineCorridorMetadataFingerprint) {
      return;
    }

    if (fingerprint != _offlineCorridorMetadataFingerprint) {
      _lastOfflineCorridorMetadata = null;
      _offlineCorridorMetadataError = false;
      _offlineCorridorMetadataFetchedAt = null;
    }

    final requestId = ++_offlineCorridorMetadataRequestId;
    if (mounted) {
      setState(() {
        _offlineCorridorMetadataLoading = true;
        _offlineCorridorMetadataError = false;
      });
    } else {
      _offlineCorridorMetadataLoading = true;
      _offlineCorridorMetadataError = false;
    }
    _logCloudNav3(result: 'loading', reason: 'fetch_start');

    try {
      final client = DriverNavigationWorkerClient(
        baseUrl: kNavigationWorkerBaseUrl,
      );
      final metadata = await client.offlineCorridorMetadata(
        geometry: _routeGeometryGeoJson(),
        country: _navigationWorkerCountryCode(),
        routeId: _activeTripId?.trim(),
      );
      if (requestId != _offlineCorridorMetadataRequestId) return;
      if (fingerprint != _routeGeometryFingerprint()) {
        _logCloudNav3(result: 'skipped', reason: 'stale_geometry');
        return;
      }
      if (metadata == null) {
        if (mounted) {
          setState(() {
            _offlineCorridorMetadataLoading = false;
            _offlineCorridorMetadataError = true;
          });
        } else {
          _offlineCorridorMetadataLoading = false;
          _offlineCorridorMetadataError = true;
        }
        _logCloudNav3(result: 'error', reason: 'worker_null');
        return;
      }
      if (mounted) {
        setState(() {
          _lastOfflineCorridorMetadata = metadata;
          _offlineCorridorMetadataFingerprint = fingerprint;
          _offlineCorridorMetadataFetchedAt = DateTime.now();
          _offlineCorridorMetadataLoading = false;
          _offlineCorridorMetadataError = false;
        });
      } else {
        _lastOfflineCorridorMetadata = metadata;
        _offlineCorridorMetadataFingerprint = fingerprint;
        _offlineCorridorMetadataFetchedAt = DateTime.now();
        _offlineCorridorMetadataLoading = false;
        _offlineCorridorMetadataError = false;
      }
      _logCloudNav3(result: 'ready', reason: metadata.supportedStatus);
    } catch (_) {
      if (requestId != _offlineCorridorMetadataRequestId) return;
      if (mounted) {
        setState(() {
          _offlineCorridorMetadataLoading = false;
          _offlineCorridorMetadataError = true;
        });
      } else {
        _offlineCorridorMetadataLoading = false;
        _offlineCorridorMetadataError = true;
      }
      _logCloudNav3(result: 'error', reason: 'fetch_failed');
    }
  }

  Widget _buildNavOfflineCorridorPrepPanel({required Color navText}) {
    final style = TextStyle(
      color: navText.withOpacity(0.72),
      fontSize: 10.5,
      height: 1.25,
    );

    if (!kUseNavigationWorker) {
      return Text(
        _tr(
          nl: 'Route-corridor voorbereiding beschikbaar zodra Navigation Core actief is.',
          en: 'Route corridor preparation is available when Navigation Core is active.',
          fr: 'La preparation du corridor de route sera disponible quand Navigation Core sera actif.',
          es: 'La preparacion del corredor de ruta estara disponible cuando Navigation Core este activo.',
        ),
        textAlign: TextAlign.center,
        style: style,
      );
    }

    if (_offlineCorridorMetadataLoading) {
      return Text(
        _tr(
          nl: 'Offline route-corridor wordt berekend…',
          en: 'Preparing offline route corridor…',
          fr: 'Preparation du corridor de route hors ligne…',
          es: 'Preparando corredor de ruta sin conexion…',
        ),
        textAlign: TextAlign.center,
        style: style,
      );
    }

    if (_offlineCorridorMetadataError) {
      return Text(
        _tr(
          nl: 'Offline corridor kon niet worden voorbereid. Lokale GPS/predictie blijft actief.',
          en: 'Offline corridor could not be prepared. Local GPS/prediction remains active.',
          fr: 'Le corridor hors ligne n\'a pas pu etre prepare. GPS/prediction locale reste actif.',
          es: 'No se pudo preparar el corredor sin conexion. GPS/prediccion local sigue activo.',
        ),
        textAlign: TextAlign.center,
        style: style,
      );
    }

    final metadata = _lastOfflineCorridorMetadata;
    if (metadata != null) {
      final sizeRange = _formatCorridorByteRange(
        metadata.estimatedSizeBytesMin,
        metadata.estimatedSizeBytesMax,
      );
      return Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Text(
            _tr(
              nl:
                  'Corridor: ${metadata.estimatedTileCountMin}-${metadata.estimatedTileCountMax} tegels · '
                  '$sizeRange · buffer ${metadata.corridorBufferMeters} m · '
                  'zoom ${metadata.zoomMin}-${metadata.zoomMax} · ${metadata.supportedStatus}',
              en:
                  'Corridor: ${metadata.estimatedTileCountMin}-${metadata.estimatedTileCountMax} tiles · '
                  '$sizeRange · buffer ${metadata.corridorBufferMeters} m · '
                  'zoom ${metadata.zoomMin}-${metadata.zoomMax} · ${metadata.supportedStatus}',
              fr:
                  'Corridor: ${metadata.estimatedTileCountMin}-${metadata.estimatedTileCountMax} tuiles · '
                  '$sizeRange · tampon ${metadata.corridorBufferMeters} m · '
                  'zoom ${metadata.zoomMin}-${metadata.zoomMax} · ${metadata.supportedStatus}',
              es:
                  'Corredor: ${metadata.estimatedTileCountMin}-${metadata.estimatedTileCountMax} teselas · '
                  '$sizeRange · buffer ${metadata.corridorBufferMeters} m · '
                  'zoom ${metadata.zoomMin}-${metadata.zoomMax} · ${metadata.supportedStatus}',
            ),
            textAlign: TextAlign.center,
            style: style,
          ),
          const SizedBox(height: 4),
          Text(
            // P0-FIELD-REPAIR-1 (C): state the actual capability boundary
            // instead of only denying "full offline navigation".
            _tr(
              nl:
                  'Kaartweergave kan offline beschikbaar zijn. Routeberekening, '
                  'zoeken, verkeersinformatie en herberekenen vereisen momenteel internet.',
              en:
                  'Map display can be available offline. Route calculation, search, '
                  'traffic information and rerouting currently require internet.',
              fr:
                  'L\'affichage de la carte peut etre disponible hors ligne. Le calcul '
                  'd\'itineraire, la recherche, le trafic et le recalcul necessitent internet.',
              es:
                  'La vista del mapa puede estar disponible sin conexion. El calculo de '
                  'ruta, la busqueda, el trafico y el recalculo requieren internet.',
            ),
            textAlign: TextAlign.center,
            style: style.copyWith(fontSize: 10, fontStyle: FontStyle.italic),
          ),
        ],
      );
    }

    return Text(
      _tr(
        nl: 'Offline route-corridor wordt berekend…',
        en: 'Preparing offline route corridor…',
        fr: 'Preparation du corridor de route hors ligne…',
        es: 'Preparando corredor de ruta sin conexion…',
      ),
      textAlign: TextAlign.center,
      style: style,
    );
  }

  bool _isRouteTaskStillValid({
    required int epoch,
    String? expectedBookingId,
    bool requireDirectRide = false,
  }) {
    if (epoch != _routeCleanupEpoch) return false;
    if (requireDirectRide && !_directRideActive) return false;
    if (expectedBookingId != null) {
      final activeId = _activeBooking?.bookingId;
      if (activeId == null || activeId != expectedBookingId) return false;
    }
    return true;
  }

  DriverRouteAcceptanceSnapshot _driverRouteAcceptanceSnapshot() {
    return DriverRouteAcceptanceSnapshot(
      mounted: mounted,
      latestRequestGeneration: _routeRequestGeneration.latest,
      cleanupEpoch: _routeCleanupEpoch,
      activeBookingId: _activeBooking?.bookingId,
      activeTripId: _activeTripId?.trim().isEmpty == true
          ? null
          : _activeTripId?.trim(),
      directRideActive: _directRideActive,
      liveRideActive: _liveRideActive,
    );
  }

  DriverRouteRequestContext _beginDriverRouteRequest({
    required DriverRouteApplyPurpose purpose,
    String? expectedBookingId,
    bool requireDirectRide = false,
    String? expectedTripId,
    bool expectDirectRideActive = false,
  }) {
    final effectivePurpose = _isRerouting
        ? DriverRouteApplyPurpose.reroute
        : purpose;
    return DriverRouteRequestContext(
      requestGeneration: _routeRequestGeneration.begin(),
      cleanupEpoch: _routeCleanupEpoch,
      purpose: effectivePurpose,
      expectedBookingId: expectedBookingId,
      requireDirectRide: requireDirectRide,
      expectedTripId: expectedTripId?.trim().isEmpty == true
          ? null
          : expectedTripId?.trim(),
      expectDirectRideActive: expectDirectRideActive || requireDirectRide,
    );
  }

  /// NAV-SIGNAL-P0B: final guard + atomic geometry/steps activation.
  bool _tryActivatePreparedDriverRoute({
    required DriverRouteRequestContext context,
    required DriverPreparedRoutePackage package,
  }) {
    final decision = evaluateDriverRouteAcceptance(
      context: context,
      snapshot: _driverRouteAcceptanceSnapshot(),
      package: package,
    );
    if (!decision.accepted) {
      debugPrint(
        formatNavRouteApplyDiag(
          requestGeneration: context.requestGeneration,
          latestGeneration: _routeRequestGeneration.latest,
          accepted: false,
          reason: decision.reason,
        ),
      );
      return false;
    }

    // Initial (non-reroute) activation opens a new navigation attempt latch.
    // Successful mid-ride reroutes must not reset the sticky dismissal.
    if (!_isRerouting) {
      _resetExternalNavFallbackLatchForNewAttempt(reason: 'route_activated');
    }

    // RELEASE-P0: reject a reroute package that cannot initialize forward
    // progress at the *current* vehicle position (course-compatible). Do not
    // accept merely because route start is Euclidean-near the car.
    NavRerouteApplyProgressResult? applyProgress;
    if (_isRerouting && _lastPos != null && package.coords.isNotEmpty) {
      final applyCoords = <NavRerouteApplyLatLon>[
        for (final c in package.coords)
          NavRerouteApplyLatLon(lat: c.lat, lon: c.lon),
      ];
      final course = _lastPos!.heading.isFinite && _lastPos!.heading >= 0
          ? _lastPos!.heading
          : _lastMovementBearing;
      applyProgress = navRerouteSelectApplyProgress(
        routeCoords: applyCoords,
        vehicleLat: _lastPos!.latitude,
        vehicleLon: _lastPos!.longitude,
        vehicleCourseDeg: course,
      );
      if (!applyProgress.accepted) {
        _logNavBounded(
          'NAV_R17_REROUTE_APPLY',
          'result=rejected reason=${applyProgress.reason} '
              'gen=${context.requestGeneration}',
          intervalMs: 500,
        );
        debugPrint(
          formatNavRerouteApplyProgressDiag(
            generation: context.requestGeneration,
            progress: applyProgress,
            requestOriginDeltaM: 0,
            writer: 'activate_reject',
          ),
        );
        // Do not install a behind-vehicle package; request a fresh reroute
        // from the current vehicle position after this attempt clears.
        _pendingRerouteAfterInFlight = true;
        _pendingRerouteReason = 'apply_no_forward';
        return false;
      }
    }

    // NAV-REROUTE-CURRENT-POSITION-HEADING-P0: stale coordinator generation
    // must never install geometry/maneuvers after a newer confirm.
    if (_isRerouting &&
        !_navRerouteCoordinator.acceptResponseGeneration(
          _activeRerouteRequestGeneration,
        )) {
      debugPrint(
        formatNavRouteApplyDiag(
          requestGeneration: context.requestGeneration,
          latestGeneration: _routeRequestGeneration.latest,
          accepted: false,
          reason: DriverRouteRejectReason.staleGeneration,
        ),
      );
      return false;
    }

    // NAV-SIGNAL-P0B2: content version and render epoch advance together on
    // accept, but remain distinct concepts (values need not stay equal forever).
    _routeStepsVersion += 1;
    _routeRenderEpoch += 1;
    // NAV-MANEUVER-OWNER-REBASE-1: a replaced route replaces its owner. The
    // maneuver from the old route may never come back on screen.
    _navManeuverOwner = null;
    _lastNavManeuverOwnerDiag = null;
    final appliedVersion = _routeStepsVersion;
    final renderEpoch = _routeRenderEpoch;
    final acceptedAt = DateTime.now();
    _routeAcceptedAt = acceptedAt;
    // NAV-REROUTE-P0: accepted package ownership clears complexity/reroute
    // warning state even if the async request Future has not finished.
    if (_isRerouting) {
      final firstStep = package.navSteps.isNotEmpty
          ? package.navSteps.first
          : null;
      final deadEnd = NavRerouteCoordinator.looksLikeDeadEndUturn(
        maneuverType: firstStep?.type,
        maneuverModifier: firstStep?.modifier,
        instructionText: firstStep?.instruction,
      );
      _navRerouteCoordinator.activateAtomic(
        responseGeneration: _activeRerouteRequestGeneration,
        at: acceptedAt,
        deadEndUturn: deadEnd,
      );
      _rerouteOwnershipAccepted = true;
      _lastRerouteSuccessAt = acceptedAt;
      _lastRerouteFailed = false;
      _rerouteDecision.noteRerouteApplied(acceptedAt);
      _offRouteLikely = false;
      _offRouteReason = 'none';
      _offRouteHitCount = 0;
      _offRouteRerouteDebounceStartedAt = null;
      _lastRerouteDecision = null;
      _reroutePackagePreparedAt ??= acceptedAt;
      final requestStarted = _rerouteRequestStartedAt;
      final eligibleAt = _rerouteDecisionEligibleAt;
      if (requestStarted != null) {
        _logNavLatencyReroute(
          phase: 'package_accepted',
          reason: _rerouteReason ?? 'reroute',
          requestDurationMs: acceptedAt.difference(requestStarted).inMilliseconds,
          oldRouteVersion: appliedVersion - 1,
          newRouteVersion: appliedVersion,
          elapsedFromCandidateMs: eligibleAt == null
              ? null
              : acceptedAt.difference(eligibleAt).inMilliseconds,
        );
      }
    }

    _resetNavComplexityState();
    _driverNavRouteProgress.reset();
    _lastNavRouteProgress = null;
    _navRouteProgressRouteFingerprint = package.geometryFingerprint;
    _resetNavCameraPolicyState();
    _resetNavConfidenceState();
    _resetNavMotionPredictionState();
    _resetNavInstructionPolicyState();
    _lastRouteSnap = null;
    _lastVisualProgressM = null;
    _routeLineProgressTrimmed = false;
    _lastRouteLineTrimProgressM = 0.0;
    _lastRouteLineTrimAt = null;
    _rerouteApplyForwardOwnershipActive = false;

    var activeCoords = List<_LonLat>.from(package.coords);
    // RELEASE-P0: on reroute, trim behind apply-time forward progress and
    // seed the progress engine so the first camera/render tick owns ahead.
    if (_isRerouting && applyProgress != null && applyProgress.accepted) {
      final trimmed = navRerouteTrimCoordsAhead(
        routeCoords: [
          for (final c in package.coords)
            NavRerouteApplyLatLon(lat: c.lat, lon: c.lon),
        ],
        progress: applyProgress,
      );
      activeCoords = [
        for (final c in trimmed) _LonLat(c.lon, c.lat),
      ];
      final originDelta = package.coords.isEmpty
          ? 0.0
          : _metersBetween(
              _LonLat(package.coords.first.lon, package.coords.first.lat),
              _LonLat(_lastPos!.longitude, _lastPos!.latitude),
            );
      debugPrint(
        formatNavRerouteApplyProgressDiag(
          generation: context.requestGeneration,
          progress: applyProgress,
          requestOriginDeltaM: originDelta,
          writer: 'activate_trim',
        ),
      );
    }

    _routeCoords = activeCoords;
    _routeKm = package.distanceMeters / 1000.0;
    _routeDurationSec = package.durationSeconds;

    final navSteps = package.navSteps;
    _routeSteps = navSteps;
    _nextStepIndex = 0;
    // NAV-SIGNAL-P1B: do not seed depart type + step-0 banner text that may
    // describe maneuver 1. Wait for the first coherent presentation resolve.
    _nextNavInstruction = null;
    _nextNavStreet = null;
    _nextNavDistanceM = null;
    _nextNavType = null;
    _nextNavModifier = null;
    _navInstructionSnapshot = navSteps.isEmpty
        ? NavInstructionSnapshot.none
        : null;
    _activeBanner = null;
    _activeLaneGuidance = null;
    _lastLaneResolveDiag = null;

    if (_isRerouting && applyProgress != null && applyProgress.accepted) {
      // Trimmed geometry starts at the snap point → seed segment 0.
      _driverNavRouteProgress.seedAtProjection(
        segmentIndex: 0,
        distanceAlongRouteM: 0.0,
        snappedLatitude: applyProgress.snappedLat ?? _lastPos!.latitude,
        snappedLongitude: applyProgress.snappedLon ?? _lastPos!.longitude,
      );
      _routeLineProgressTrimmed = true;
      _lastRouteLineTrimProgressM = 0.0;
      _lastRouteLineTrimAt = acceptedAt;
      _rerouteApplyForwardOwnershipActive = true;
      _rerouteApplyStaleWriters.reset();
      if (applyProgress.snappedLat != null &&
          applyProgress.snappedLon != null) {
        _lastRouteSnap = DriverRouteSnap(
          point: DriverLonLat(
            applyProgress.snappedLon!,
            applyProgress.snappedLat!,
          ),
          distanceFromRouteM: applyProgress.snapDistanceM ?? 0.0,
          distanceAlongRouteM: 0.0,
          segmentIndex: 0,
          segmentT: 0.0,
        );
        _useMatchedVisual = true;
      }
      // Seed camera from the accepted forward segment, not route index 0 of
      // the untrimmed request-origin stub.
      final seedBearing = applyProgress.segmentBearingDeg ??
          navFirstMeaningfulRouteSegmentBearing(_routeCoords);
      if (seedBearing != null) {
        // NAV-CAMERA-ZERO-OLD-ROUTE-HOLD-P0: seed the *target* from the new
        // forward segment, but do NOT reset the applied bearing controller —
        // blend from current travel bearing along the shortest arc so there
        // is no old-route snap-back or pause.
        final seeded = _navStationaryBearingGate.seedInitialRouteBearing(
          routeTangentBearingDeg: seedBearing,
          routeSegmentIndex: 0,
        );
        if (seeded != null) {
          _navBearingAnchorLat = _lastPos?.latitude;
          _navBearingAnchorLon = _lastPos?.longitude;
          _logNavBounded(
            'NAV_BEARING_SEED',
            'reason=reroute_apply_forward bearing=${seeded.toStringAsFixed(1)} '
                'source=forward_segment',
            intervalMs: 1000,
          );
        }
      }
      _navCameraNewRouteBlendUntil = DateTime.now().add(
        const Duration(milliseconds: kNavCameraNewRouteBlendMs),
      );
      _updateNavCameraBearingOwner(
        reason: 'new_route_accepted',
        forceInvalidatePassive: true,
      );
    } else {
      // Non-reroute (initial route): seed from first meaningful segment.
      _seedNavStationaryBearingFromRoute(reason: 'route_applied');
      _navCameraNewRouteBlendUntil = null;
      _updateNavCameraBearingOwner(reason: 'route_applied');
    }

    // Content consumers: accepted route-steps version only.
    _streetlevelFollowPump.setExpectedRouteGeneration(appliedVersion);
    _streetlevelFollowPump.setExpectedRenderEpoch(renderEpoch);
    _nativeFollow?.noteRouteGenerationApplied(appliedVersion);
    _logNavR12Banner(state: 're_resolved', reason: 'route_steps_applied');
    debugPrint(
      formatNavRouteApplyDiag(
        requestGeneration: context.requestGeneration,
        latestGeneration: _routeRequestGeneration.latest,
        accepted: true,
        routeVersion: appliedVersion,
        renderEpoch: renderEpoch,
      ),
    );
    debugPrint(
      '[NAV_E1] steps=${navSteps.length} bannerSteps=${package.stepsWithBannerCount} '
      'laneSteps=${package.stepsWithLaneGuidanceCount}',
    );
    _activateRouteRenderOwnerPackage();
    return true;
  }

  bool _isCurrentRouteRenderEpoch(int routeRenderEpoch) {
    final stale = shouldIgnoreStaleRouteDraw(
      drawAppliedRouteVersion: routeRenderEpoch,
      currentAppliedRouteVersion: _routeRenderEpoch,
    );
    if (stale) {
      _rerouteApplyStaleWriters.note('route_line_coords');
      _logNavBounded(
        'NAV_R17_REROUTE_APPLY',
        formatNavRerouteApplyStaleWriterDiag(
          writer: 'route_line_coords',
          writerGeneration: routeRenderEpoch,
          activeGeneration: _routeRenderEpoch,
          rejectedCount: _rerouteApplyStaleWriters.total,
        ),
        intervalMs: 800,
      );
    }
    return !stale;
  }

  Future<void> _clearRouteAndPinAnnotationsOnly() async {
    // NAV-ANNOTATION-MANAGER-TRANSACTIONAL-LIFECYCLE-2: each manager's deletes
    // run under one lease so a concurrent style-swap disposal awaits them.
    final routeMgr = _routeLineManager;
    final outline = _routeLineOutline;
    final line = _routeLine;
    final completed = _routeLineCompleted;
    _routeLineOutline = null;
    _routeLine = null;
    _routeLineCompleted = null;
    if (routeMgr != null) {
      await _runAnnotationTx<void>(
        gate: _routeAnnotationGate,
        kind: NavAnnotationOperationKind.delete,
        nativeOp: () => _safeDeleteRoutePolylines(
          <mb.PolylineAnnotation?>[outline, line, completed],
          mgr: routeMgr,
          reason: 'clear_route_pins',
        ),
      );
    }

    final pinsMgr = _pinsPointManager;
    final pickup = _pickupPin;
    final dropoff = _dropoffPin;
    _pickupPin = null;
    _dropoffPin = null;
    if (pinsMgr != null) {
      await _runAnnotationTx<void>(
        gate: _pinsAnnotationGate,
        kind: NavAnnotationOperationKind.delete,
        nativeOp: () async {
          if (pickup != null) await pinsMgr.delete(pickup);
          if (dropoff != null) await pinsMgr.delete(dropoff);
        },
      );
    }
    await _clearNavigationDestinationMarker(
      action: 'clear',
      result: 'cleared',
      source: 'none',
      reason: 'route_pins_cleared',
    );
  }

  Future<void> _clearActiveRouteAndNavigationState({
    required String reason,
    String? bookingId,
    bool clearActiveSelection = true,
  }) async {
    final activeBookingId = _activeBooking?.bookingId;
    final hasPolylineBefore = _routeLine != null || _routeLineOutline != null;
    final routeCoordsBefore = _routeCoords.length;
    final navStepsBefore = _routeSteps.length;
    if (!clearActiveSelection &&
        !hasPolylineBefore &&
        routeCoordsBefore == 0 &&
        navStepsBefore == 0) {
      return;
    }

    // NAV-SIGNAL-P0B2: logically deactivate BEFORE awaiting Mapbox deletes so
    // GPS/UI never observe a bumped render epoch while the old session is
    // still eligible for reroute/follow processing. `_routeStepsVersion` is
    // intentionally unchanged (not a new accepted route).
    final renderReason = reason.trim().isEmpty
        ? 'hard_clear'
        : (reason == 'stop'
              ? 'stop'
              : (reason == 'manual_clear_selection' || reason == 'delete'
                    ? 'hard_clear'
                    : reason));

    void deactivateLogically() {
      // NAV-RIDE-BOUNDARY: bump session + hard-clear route ownership before any
      // further awaits so late style/route callbacks cannot restore this ride.
      _hardClearAtRideBoundary(
        reason: renderReason,
        bumpSession: true,
        renderAlreadyInvalidated: false,
      );
      _routePhase = _RideRoutePhase.trip;
      _navStepsLoading = false;
      _cameraMode = _CameraMode.overview;
      _hasSwitchedToFollow = false;
      _followCar = false;
      _allowOverviewCamera = false;
      if (clearActiveSelection) {
        _activeTripId = null;
        _activeDirectTripId = null;
        _activeDirectBookingId = null;
        _directRideKey = null;
        _activeBooking = null;
        _directRideActive = false;
        _directStopFinalizePending = false;
        _directRideDestinationText = null;
        _directRideDestinationPoint = null;
        _directRideEstimatedFare = null;
        _directRideEstimateLoading = false;
        _directRideEstimateError = null;
        _directRideEstimateCurrency = kDefaultCurrency;
        _directRideEstimateSignature = null;
        _directRideLocationRetryCount = 0;
        _directRideLocationRetryDestination = null;
        _lastPing = '—';
        _pingCount = 0;
        _kmDriven = 0.0;
        _trackingStartedAt = null;
        _isWaiting = false;
        _waitStartedAt = null;
        _waitElapsed = Duration.zero;
      }
    }

    if (mounted) {
      setState(deactivateLogically);
    } else {
      deactivateLogically();
    }

    await _clearRouteAndPinAnnotationsOnly();
    if (!mounted) return;
    _setNavigationWakelock(false);
    await _applyMapStyleForMode();
    if (!_liveRideActive) {
      _startBookingPolling(reason: 'route_state_cleared');
    }
  }

  bool _isClosedRideStatus(String? rawStatus) {
    final s = (rawStatus ?? '').trim().toUpperCase();
    return s == 'COMPLETED' ||
        s == 'COMPLETE' ||
        s == 'CANCELLED' ||
        s == 'CANCELED' ||
        s == 'DELETED' ||
        s == 'ARCHIVED' ||
        s == 'CLOSED' ||
        s == 'DONE' ||
        s == 'FAILED' ||
        s == 'EXPIRED' ||
        s == 'DECLINED';
  }

  String _bookingActionKeyForUi(BookingItem b) {
    if (b.isOperationalLeg && b.legId.trim().isNotEmpty) {
      return b.rowKey;
    }
    return b.bookingId;
  }

  String? _effectiveStatusFor(BookingItem b) {
    return _bookingStatusOverrides[b.rowKey] ??
        _bookingStatusOverrides[b.bookingId] ??
        b.status;
  }

  Map<String, dynamic> _bookingScopeViewFor(BookingItem b) {
    return <String, dynamic>{
      ...b.details,
      'booking_id': b.bookingId,
      'bookingId': b.bookingId,
      if (b.details['booking'] is! Map)
        'booking': <String, dynamic>{...b.details},
    };
  }

  String _resolvedAssignedVehicleIdFromBookingItem(BookingItem b) {
    final booking = _bookingScopeViewFor(b);
    return (_bookingScopeFirstText(booking, const [
              ['assigned_vehicle_id'],
              ['assignedVehicleId'],
              ['vehicle_id'],
              ['vehicleId'],
              ['details', 'assigned_vehicle_id'],
              ['details', 'assignedVehicleId'],
              ['details', 'vehicle_id'],
              ['details', 'vehicleId'],
              ['booking', 'assigned_vehicle_id'],
              ['booking', 'assignedVehicleId'],
              ['booking', 'vehicle_id'],
              ['booking', 'vehicleId'],
              ['record', 'assigned_vehicle_id'],
              ['record', 'assignedVehicleId'],
              ['record', 'vehicle_id'],
              ['record', 'vehicleId'],
              ['record', 'booking', 'assigned_vehicle_id'],
              ['record', 'booking', 'assignedVehicleId'],
              ['record', 'booking', 'vehicle_id'],
              ['record', 'booking', 'vehicleId'],
            ]) ??
            '')
        .trim();
  }

  ({String actorVehicleId, String source}) _plannedTripActorVehicleContext(
    BookingItem b,
  ) {
    final assignedVehicleId = _resolvedAssignedVehicleIdFromBookingItem(b);
    if (assignedVehicleId.isNotEmpty) {
      return (actorVehicleId: assignedVehicleId, source: 'assigned_vehicle');
    }
    final sessionVehicleId =
        activeDriverSessionNotifier.value?.assignedVehicleId?.trim() ?? '';
    if (sessionVehicleId.isNotEmpty) {
      return (actorVehicleId: sessionVehicleId, source: 'session_vehicle');
    }
    final linkedVehicleIds = _activeDriverLinkedVehicleIds().toList(
      growable: false,
    )..sort();
    if (linkedVehicleIds.isNotEmpty) {
      return (actorVehicleId: linkedVehicleIds.first, source: 'linked_vehicle');
    }
    return (
      actorVehicleId: _directRideVehicleId().trim(),
      source: 'fallback_direct',
    );
  }

  bool _canOperateBookingWithGuard(
    Map<String, dynamic> booking, {
    required String action,
  }) {
    final allowed = _canActiveDriverOperateBooking(booking);
    final bookingId =
        _bookingScopeFirstText(booking, const [
          ['booking_id'],
          ['bookingId'],
          ['id'],
          ['booking', 'booking_id'],
          ['booking', 'bookingId'],
        ]) ??
        'unknown';
    final assignedVehicleId =
        _bookingScopeFirstText(booking, const [
          ['assigned_vehicle_id'],
          ['assignedVehicleId'],
          ['vehicle_id'],
          ['vehicleId'],
          ['booking', 'assigned_vehicle_id'],
          ['booking', 'assignedVehicleId'],
          ['booking', 'vehicle_id'],
          ['booking', 'vehicleId'],
        ]) ??
        '';
    final activeDriverId = _resolvedActiveDriverIdForScope();
    if (!allowed) {
      debugPrint(
        '[DRIVER_SCOPE][BLOCK] action=$action booking_id=$bookingId assigned_vehicle_id=$assignedVehicleId active_driver_id=$activeDriverId active_vehicle_id=${_activeDriverSessionVehicleIdForScope()} allowed=false',
      );
      _toast(_driverOwnershipBlockedMessage());
      return false;
    }
    return true;
  }

  /// Canonical identity view of a booking row for the street/direct decision.
  ///
  /// Uses the raw backend payload (`details`) plus the canonical booking id so
  /// the filter reads `is_street_direct` / `source` / `booking_source` /
  /// `ride_type` and never a localized display label.
  Map<String, dynamic> _canonicalRideIdentityFor(BookingItem b) {
    return <String, dynamic>{
      ...b.details,
      'booking_id': b.bookingId,
      'bookingId': b.bookingId,
    };
  }

  List<BookingItem> _scopeFilteredOpenBookings({
    String segment = 'scope_open',
  }) {
    final enforceScope = _shouldEnforceDriverRideScopeFilter();
    // P0-FIELD-REPAIR-1 (A): client safety net for "a street/direct ride is
    // never planned". The booking worker already excludes these rows from the
    // planned/open projection; this guarantees a stale worker, a cached
    // response or a future read path cannot resurrect the ghost row under
    // Gepland / Volgende rit. History and completed-count canonicalisation are
    // untouched (they do not flow through this getter).
    final withoutStreetDirect = filterPlannedRidesExcludingStreetDirect<BookingItem>(
      _bookings,
      canonicalFieldsOf: _canonicalRideIdentityFor,
      statusOf: (b) => _effectiveStatusFor(b) ?? '',
      segment: segment,
      onLog: (log) => debugPrint(log.toLogLine()),
    );
    return withoutStreetDirect
        .where((b) => !_deletedBookingIds.contains(b.bookingId))
        .where((b) => !_isClosedRideStatus(_effectiveStatusFor(b)))
        .where((b) {
          if (!enforceScope) return true;
          if (kDriverAllowAllCompanyRidesDebug) return true;
          final booking = _bookingScopeViewFor(b);
          final decision = _driverRideScopeVisibilityDecision(
            booking,
            segment: segment,
          );
          final bookingId = b.bookingId;
          final assignedDriverId = _bookingScopeAssignedDriverId(booking) ?? '';
          final assignedVehicleId =
              _bookingScopeAssignedVehicleId(booking) ?? '';
          debugPrint(
            '[DRIVER_SCOPE][FILTER] booking_id=${_safeRefPreview(bookingId)} assigned_driver_id=${_safeRefPreview(assignedDriverId)} assigned_vehicle_id=${_safeRefPreview(assignedVehicleId)} active_driver_id=${_safeRefPreview(_resolvedActiveDriverIdForScope())} active_vehicle_id=${_safeRefPreview(_activeDriverSessionVehicleIdForScope())} segment=$segment allowed=${decision.allowed} reason=${decision.reason}',
          );
          return decision.allowed;
        })
        .toList(growable: false);
  }

  List<BookingItem> get _myAssignedVisibleBookings {
    final open = _scopeFilteredOpenBookings(segment: 'my_rides');
    if (!_shouldEnforceDriverRideScopeFilter()) {
      return _dedupeDriverVisibleBookingItems(open);
    }
    final assigned = open
        .where((b) => _bookingIsMyAssignedDriverRide(_bookingScopeViewFor(b)))
        .toList(growable: false);
    return _dedupeDriverVisibleBookingItems(assigned);
  }

  List<BookingItem> get _availableUnassignedVisibleBookings {
    if (!_shouldEnforceDriverRideScopeFilter()) return const [];
    return buildDriverAvailableUnassignedVisibleBookings(
      _scopeFilteredOpenBookings(segment: 'available'),
    );
  }

  List<BookingItem> get _historyAssignedVisibleBookings {
    final closed = _bookings
        .where((b) => !_deletedBookingIds.contains(b.bookingId))
        .where((b) => _isClosedRideStatus(_effectiveStatusFor(b)))
        .where((b) {
          if (!_shouldEnforceDriverRideScopeFilter()) return true;
          return _bookingIsMyAssignedDriverRide(_bookingScopeViewFor(b));
        })
        .toList(growable: false);
    return _dedupeDriverVisibleBookingItems(closed);
  }

  List<BookingItem> _ridesHubSegmentBookings() {
    switch (_ridesHubSegment) {
      case _DriverRidesHubSegment.available:
        return _availableUnassignedVisibleBookings;
      case _DriverRidesHubSegment.myRides:
        return _myAssignedVisibleBookings;
      case _DriverRidesHubSegment.history:
        return _historyAssignedVisibleBookings;
    }
  }

  /// Assigned/planned rides for the active driver (excludes available-unassigned pool).
  List<BookingItem> get _visibleBookings => _myAssignedVisibleBookings;

