  Future<Map<String, dynamic>> _fetchPaymentFieldsForHistory(
    String bookingId,
  ) async {
    Map<String, dynamic> asMap(dynamic value) =>
        value is Map ? Map<String, dynamic>.from(value) : <String, dynamic>{};
    String? text(dynamic value) {
      final s = value?.toString().trim();
      if (s == null || s.isEmpty || s.toLowerCase() == 'null') return null;
      return s;
    }

    Map<String, dynamic> parsePayment(dynamic rootRaw) {
      final root = asMap(rootRaw);
      final data = asMap(root['data']);
      final record = asMap(root['record']);
      final booking = asMap(root['booking']);
      final dataRecord = asMap(data['record']);
      final dataBooking = asMap(data['booking']);
      final recordBooking = asMap(record['booking']);
      final dataRecordBooking = asMap(dataRecord['booking']);

      final paymentStatus = text(
        root['payment_status'] ??
            root['paymentStatus'] ??
            record['payment_status'] ??
            record['paymentStatus'] ??
            recordBooking['payment_status'] ??
            recordBooking['paymentStatus'] ??
            booking['payment_status'] ??
            booking['paymentStatus'] ??
            data['payment_status'] ??
            data['paymentStatus'] ??
            dataRecord['payment_status'] ??
            dataRecord['paymentStatus'] ??
            dataBooking['payment_status'] ??
            dataBooking['paymentStatus'] ??
            dataRecordBooking['payment_status'] ??
            dataRecordBooking['paymentStatus'],
      );
      final paidAt = text(
        root['paid_at'] ??
            root['paidAt'] ??
            record['paid_at'] ??
            record['paidAt'] ??
            booking['paid_at'] ??
            booking['paidAt'] ??
            data['paid_at'] ??
            data['paidAt'] ??
            dataRecord['paid_at'] ??
            dataRecord['paidAt'] ??
            dataBooking['paid_at'] ??
            dataBooking['paidAt'],
      );
      final paymentProvider = text(
        root['payment_provider'] ??
            root['paymentProvider'] ??
            record['payment_provider'] ??
            record['paymentProvider'] ??
            booking['payment_provider'] ??
            booking['paymentProvider'] ??
            data['payment_provider'] ??
            data['paymentProvider'] ??
            dataRecord['payment_provider'] ??
            dataRecord['paymentProvider'] ??
            dataBooking['payment_provider'] ??
            dataBooking['paymentProvider'],
      );
      final paymentId = text(
        root['payment_id'] ??
            root['paymentId'] ??
            record['payment_id'] ??
            record['paymentId'] ??
            booking['payment_id'] ??
            booking['paymentId'] ??
            data['payment_id'] ??
            data['paymentId'] ??
            dataRecord['payment_id'] ??
            dataRecord['paymentId'] ??
            dataBooking['payment_id'] ??
            dataBooking['paymentId'],
      );
      final maps = _referenceLookupMaps(<Map<String, dynamic>>[
        root,
        data,
        record,
        booking,
        dataRecord,
        dataBooking,
        recordBooking,
        dataRecordBooking,
      ]);
      final refs = _extractBusinessReferenceAliasesFromMaps(maps);

      return <String, dynamic>{
        if (paymentStatus != null) ...{
          'payment_status': paymentStatus,
          'paymentStatus': paymentStatus,
        },
        if (paidAt != null) ...{'paid_at': paidAt, 'paidAt': paidAt},
        if (paymentProvider != null) ...{
          'payment_provider': paymentProvider,
          'paymentProvider': paymentProvider,
        },
        if (paymentId != null) ...{
          'payment_id': paymentId,
          'paymentId': paymentId,
        },
        if (refs.receipt != null) ...{
          'receipt_reference': refs.receipt,
          'receiptReference': refs.receipt,
        },
        if (refs.planning != null) ...{
          'planning_reference': refs.planning,
          'planningReference': refs.planning,
        },
        if (refs.publicBooking != null) ...{
          'public_booking_reference': refs.publicBooking,
          'publicBookingReference': refs.publicBooking,
        },
        if (refs.booking != null) ...{
          'booking_reference': refs.booking,
          'bookingReference': refs.booking,
        },
        if (refs.publicRef != null) ...{
          'public_reference': refs.publicRef,
          'publicReference': refs.publicRef,
        },
      };
    }

    Future<Map<String, dynamic>> fetchAndParse(Uri uri) async {
      final res = await http
          .get(uri, headers: _driverBearerHeaders())
          .timeout(const Duration(seconds: 10));
      if (res.statusCode < 200 || res.statusCode >= 300)
        return <String, dynamic>{};
      final decoded = jsonDecode(res.body);
      if (decoded is! Map) return <String, dynamic>{};

      final root = Map<String, dynamic>.from(decoded);
      final parsed = parsePayment(root);
      if (parsed.isNotEmpty) return parsed;
      return <String, dynamic>{};
    }

    try {
      final byId = _withActiveBookingScope(
        kBookingBaseUrl,
        '/bookings/${Uri.encodeComponent(bookingId)}',
      );
      final parsedById = await fetchAndParse(byId);
      if (parsedById.isNotEmpty) return parsedById;
    } catch (_) {}

    return <String, dynamic>{};
  }

  void _enterWaitMode() {
    if (!_liveRideActive) return;
    if (_isWaiting) return;
    setState(() {
      _isWaiting = true;
      _waitStartedAt = DateTime.now();
    });
    debugPrint(
      '[METER][WAIT_START] km=${_kmDriven.toStringAsFixed(3)} waitSec=${_effectiveWaitElapsed.inSeconds} total=${_liveMeterTotalEur.toStringAsFixed(2)}',
    );
    _startMeterTicker();
    unawaited(
      _sendDirectTripWaitEvent(
        path: kDirectTripWaitStartPath,
        logLabel: 'WAIT_START',
        timestampKey: 'client_wait_started_at',
      ),
    );
  }

  void _exitWaitMode() {
    if (!_liveRideActive) return;
    if (!_isWaiting) return;
    final started = _waitStartedAt;
    setState(() {
      _isWaiting = false;
      _waitStartedAt = null;
      if (started != null) {
        _waitElapsed += DateTime.now().difference(started);
      }
    });
    debugPrint(
      '[METER][WAIT_RESUME] km=${_kmDriven.toStringAsFixed(3)} waitSec=${_effectiveWaitElapsed.inSeconds} total=${_liveMeterTotalEur.toStringAsFixed(2)}',
    );
    _startMeterTicker();
    unawaited(
      _sendDirectTripWaitEvent(
        path: kDirectTripWaitEndPath,
        logLabel: 'WAIT_END',
        timestampKey: 'client_wait_ended_at',
      ),
    );
  }

  void _startMeterTicker() {
    _meterTicker?.cancel();
    if (!_liveRideActive) return;
    _meterTicker = Timer.periodic(const Duration(seconds: 5), (_) {
      if (!mounted || !_liveRideActive) {
        _meterTicker?.cancel();
        _meterTicker = null;
        return;
      }
      _debugLiveMeter(reason: 'ticker');
      // NAV-MOBILE-DATA-MINIMAL-SAFE-RELEASE-P0-1 Part E: publish through
      // the meter notifier so only the meter/HUD subtree repaints. Avoids
      // rebuilding the MapWidget subtree once every 5 s.
      _publishDriverRideMetersSnapshot();
      if (_externalNavigationSession != null) {
        unawaited(
          _persistActiveRideDurableSnapshot(reason: 'meter_ticker'),
        );
      }
    });
  }

  void _stopMeterTicker() {
    _meterTicker?.cancel();
    _meterTicker = null;
  }

  /// NAV-MOBILE-DATA-MINIMAL-SAFE-RELEASE-P0-1 Part E: publish an up-to-date
  /// snapshot into the meter notifier. Consumers subscribed via
  /// ValueListenableBuilder repaint in isolation; the enclosing State does
  /// not need to call setState().
  void _publishDriverRideMetersSnapshot() {
    if (!mounted) return;
    _driverRideMetersNotifier.publish(_buildDriverRideMetersSnapshot());
  }

  /// NAV-MOBILE-DATA-MINIMAL-SAFE-RELEASE-P0-1 Part B: runner for the ping
  /// dispatcher. Executes the existing [_sendPing] logic; any exception is
  /// contained by the dispatcher and reported through its observer.
  Future<void> _runPingDispatcherOwner(geo.Position pos) async {
    if (!mounted) return;
    await _sendPing(pos);
  }

  /// NAV-MOBILE-DATA-MINIMAL-SAFE-RELEASE-P0-1 Part C: runner for the
  /// route-presentation dispatcher. Skips silently when the map or style is
  /// not ready — the dispatcher's eligibility check will typically already
  /// have short-circuited, but this belt-and-suspenders check makes the
  /// runner robust against a raced style swap.
  Future<void> _runRoutePresentationDispatcherOwner(geo.Position pos) async {
    if (!mounted) return;
    if (_map == null || _mapStyleChanging) return;
    await _syncVisibleRouteLineWithProgress(pos);
  }

  /// NAV-MOBILE-DATA-MINIMAL-SAFE-RELEASE-P0-1 Part D: enforce the fixed
  /// safe navigation-day/-night style at ride START and discard any pre-start
  /// Standard/Satellite preview so the active ride never enters a partially
  /// initialized custom style.
  ///
  /// Called from both `_startTrip` (planned) and `_startDirectRide` (street)
  /// with the setState that flips `_activeTripId` / `_directRideActive`
  /// bracketing this reset. The reset itself does NOT run setState — the
  /// caller's setState covers the same frame.
  void _applyActiveRideStartStyleDecision({required String reason}) {
    final prefersDark = _effectiveMapThemeFor(_CameraMode.follow) ==
        MapThemeMode.dark;
    final decision = decideNavActiveRideStart(prefersDark: prefersDark);
    // NAV-PRESTART-PREVIEW-AND-STABLE-BEARING-P0 (Problem 1): a style the driver
    // deliberately chose on the preview surface is the active-ride style. Only
    // an inherited theme default is normalised to the navigation-day/-night
    // pair; the preview camera level becomes the starting level rather than
    // being discarded.
    final carryOver = decideNavPreStartCarryOver(
      selection: NavPreStartSelection(
        styleSelected: _preStartStyleSelected,
        viewLevel: _preStartViewLevel,
      ),
      defaultViewLevel: _driverCockpitViewLevel,
    );
    if (!carryOver.preserveStyle) {
      _driverMapVisualMode = DriverMapVisualMode.street;
      if (kNavigation3dCockpitSceneEnabled) {
        _driverCockpitMapVisualStyle = prefersDark
            ? DriverCockpitMapVisualStyle.dark
            : DriverCockpitMapVisualStyle.light;
      }
    }
    _driverCockpitViewLevel = clampDriverCockpitViewLevel(
      carryOver.startViewLevel,
    );
    // NAV-RELEASE-SIMPLE-STREETLEVEL-1: START must enter fixed streetlevel
    // ownership — never leave a lingering overview mode after enterStreetLevel.
    if (decision.enterStreetLevel) {
      _navCameraViewMode = NavCameraViewMode.streetView;
      _allowOverviewCamera = false;
    }
    logNavActiveRideStart(
      style: carryOver.preserveStyle
          ? _driverCockpitMapStyleLabel()
          : navActiveRideStyleLabel(decision.style),
      enterStreetLevel: decision.enterStreetLevel,
      discardPreviewZoom: false,
      styleGeneration: _styleRequestGeneration,
    );
    _logNavBounded(
      'NAV_ACTIVE_RIDE_START',
      'reason=$reason '
      'style=${carryOver.preserveStyle ? _driverCockpitMapStyleLabel() : navActiveRideStyleLabel(decision.style)} '
      'streetLevel=${decision.enterStreetLevel} '
      'preserveStyle=${carryOver.preserveStyle} '
      'startViewLevel=$_driverCockpitViewLevel '
      'carryOver=${carryOver.reason}',
    );
  }

  /// PII-free label for the currently selected driver map style.
  String _driverCockpitMapStyleLabel() {
    if (_driverMapVisualMode == DriverMapVisualMode.satellite) {
      return 'satellite';
    }
    if (_driverMapVisualMode == DriverMapVisualMode.threeD) {
      return '3d';
    }
    if (!kNavigation3dCockpitSceneEnabled) return 'street';
    switch (_driverCockpitMapVisualStyle) {
      case DriverCockpitMapVisualStyle.light:
        return 'light';
      case DriverCockpitMapVisualStyle.dark:
        return 'dark';
      case DriverCockpitMapVisualStyle.standard3d:
        return '3d';
      case DriverCockpitMapVisualStyle.satellite:
        return 'satellite';
    }
  }

  Duration get _effectiveWaitElapsed {
    if (_isWaiting && _waitStartedAt != null) {
      return _waitElapsed + DateTime.now().difference(_waitStartedAt!);
    }
    return _waitElapsed;
  }

  bool get _liveRideActive => _activeTripId != null || _directRideActive;
  bool get _directRideDraft =>
      !_directRideActive &&
      _activeTripId == null &&
      _activeBooking == null &&
      (_directRideDestinationText ?? '').trim().isNotEmpty;

  /// NAV-PRESTART-PREVIEW-AND-STABLE-BEARING-P0 (Problem 1): single source of
  /// truth for which map controls the current phase exposes. Preview owns them,
  /// the active ride locks them, STOP restores them.
  NavMapControlAvailability get _navMapControls =>
      resolveNavMapControlAvailability(
        liveRideActive: _liveRideActive,
        hasPreviewDestination: _directRideDraft || _activeBooking != null,
        routePointCount: _routeCoords.length,
        navigationGuidanceActive: _navigationGuidanceActive,
      );

  /// True when a prepared booking or street draft owns the fixed streetlevel
  /// camera (no fitBounds / overview framing).
  bool get _fixedStreetLevelPreviewDraft =>
      _directRideDraft || (_activeBooking != null && !_liveRideActive);

  /// NAV-FIXED-HUD-PRESENTATION-1: which route phase the surface is in.
  NavFixedHudPhase get _navFixedHudPhase => resolveNavFixedHudPhase(
        liveRideActive: _liveRideActive,
        navigationGuidanceActive: _navigationGuidanceActive,
        preparedRouteDraft: _fixedStreetLevelPreviewDraft,
      );

  /// NAV-FIXED-HUD-PRESENTATION-1: the single activation predicate for the
  /// screen-fixed HUD marker and the fixed Street Level camera. Replaces the
  /// former `follow && _liveRideActive` gate so prepared route, NAV-to-pickup
  /// and the live ride share one identical deterministic presentation.
  bool get _navFixedHudPresentationActive => navFixedHudPresentationActive(
        phase: _navFixedHudPhase,
        cameraFollowMode: _cameraMode == _CameraMode.follow,
      );

  /// NAV-PHASE-CAMERA-TARGET-1: resolves the camera target coordinate for
  /// the preview surface. Uses the phase to decide whether pickup A, the
  /// first route point, the snapped position, or (last resort) raw driver
  /// GPS owns the vehicle anchor.
  NavPhaseCameraTarget _resolvePhaseCameraTargetForPreview(geo.Position pos) {
    final booking = _activeBooking;
    _LonLat? pickup;
    if (booking != null) {
      pickup = _usableNavLonLat(_extractPreviewEndpoints(booking).pickup);
    }
    _LonLat? firstRoutePoint;
    if (_routeCoords.isNotEmpty) {
      firstRoutePoint = _routeCoords.first;
    }
    final progress = _lastNavRouteProgress;
    return resolveNavPhaseCameraTarget(
      phase: _navFixedHudPhase,
      hasPickup: booking != null && pickup != null,
      pickupLat: pickup?.lat,
      pickupLon: pickup?.lon,
      firstRouteLat: firstRoutePoint?.lat,
      firstRouteLon: firstRoutePoint?.lon,
      snappedLat: progress?.snappedLatitude,
      snappedLon: progress?.snappedLongitude,
      driverLat: pos.latitude,
      driverLon: pos.longitude,
    );
  }

  /// NAV-RELEASE-FINAL-FLOW-1: NAV-to-pickup is booking-only on the prepared
  /// surface. Direct street draft is already at A.
  bool get _showNavToPickupAction => navToPickupActionVisible(
        hasBooking: _activeBooking != null,
        directRideDraft: _directRideDraft,
        directRideActive: _directRideActive,
      );

  double? get _fixedBookingPriceEur {
    final b = _activeBooking;
    if (b == null) return null;
    return _driverDisplayPriceForBooking(b);
  }

  /// True when the active booking is a street/direct ride (live meter UI).
  bool get _activeBookingIsStreetDirect {
    final b = _activeBooking;
    if (b == null) return false;
    return bookingRecordIsStreetDirect(<String, dynamic>{
      ...b.details,
      if (b.bookingId.trim().isNotEmpty) 'booking_id': b.bookingId,
    });
  }

  /// PLANNED-RIDE-FIXED-PRICE-PRESENTATION-AND-DURABILITY-1: fixed booking/leg
  /// price for planned rides; live meter only for street/direct.
  DriverCockpitFarePresentation get _cockpitFarePresentation {
    return resolveDriverCockpitFarePresentation(
      hasActiveBooking: _activeBooking != null,
      isStreetOrDirectBooking: _activeBookingIsStreetDirect,
      fixedBookingPriceEur: _fixedBookingPriceEur,
      liveMeterPreviewEur: _liveMeterPreviewEur,
      language: appConfig.currentLanguage,
    );
  }

  ({
    String source,
    double startFee,
    double perKm,
    double waitPerMin,
    double vatRate,
    String vatMode,
    String currency,
  })
  _resolveDirectRidePricing() {
    final settings = businessSettingsNotifier.value;
    final vat = localBackendTaxProfileNotifier.value;
    final base = settings.pricingBaseFare;
    final perKm = settings.pricingPerKm;
    final wait = settings.pricingWaitPerMinute;
    final settingsUsable =
        base.isFinite &&
        base >= 0 &&
        perKm.isFinite &&
        perKm >= 0 &&
        wait.isFinite &&
        wait >= 0;
    final source = settingsUsable ? 'settings' : 'fallback';
    final vatRateBase = vat?.vatRate ?? settings.pricingVatRate;
    final vatRate =
        (vatRateBase.isFinite ? vatRateBase : settings.pricingVatRate)
            .clamp(0.0, 1.0)
            .toDouble();
    var vatMode = (vat?.vatDisplayMode ?? settings.pricingVatMode)
        .trim()
        .toLowerCase();
    if (vatMode.isEmpty) vatMode = 'incl';
    if (vatMode != 'incl' && vatMode != 'excl') vatMode = 'incl';
    final currency = settings.defaultCurrency.trim().isEmpty
        ? kDefaultCurrency
        : settings.defaultCurrency.trim().toUpperCase();
    return (
      source: source,
      startFee: settingsUsable ? base : _fallbackStartFee,
      perKm: settingsUsable ? perKm : _fallbackPerKm,
      waitPerMin: settingsUsable ? wait : _fallbackWaitPerMin,
      vatRate: vatRate,
      vatMode: vatMode,
      currency: currency,
    );
  }

  double _directRideCustomerTotalFromRaw(double rawTotal) {
    final pricing = _resolveDirectRidePricing();
    if (pricing.vatMode == 'excl') {
      return rawTotal * (1.0 + pricing.vatRate);
    }
    return rawTotal;
  }

  Map<String, dynamic> _directRidePricingSnapshotPayload() {
    final pricing = _resolveDirectRidePricing();
    debugPrint(
      '[DIRECT_RIDE][PRICING_SNAPSHOT] source=${pricing.source} '
      'base=${pricing.startFee.toStringAsFixed(2)} '
      'perKm=${pricing.perKm.toStringAsFixed(2)} '
      'wait=${pricing.waitPerMin.toStringAsFixed(4)} '
      'vatRate=${pricing.vatRate.toStringAsFixed(4)} '
      'vatMode=${pricing.vatMode}',
    );
    return <String, dynamic>{
      'start_fee': pricing.startFee,
      'per_km': pricing.perKm,
      'wait_per_min': pricing.waitPerMin,
      'vat_rate': pricing.vatRate,
      'vat_mode': pricing.vatMode,
      'currency': pricing.currency,
    };
  }

  double get _liveMeterTotalEur {
    final km = _kmDriven;
    final waitMin = _effectiveWaitElapsed.inMilliseconds / 60000.0;
    final pricing = _resolveDirectRidePricing();
    final raw =
        pricing.startFee +
        (km * pricing.perKm) +
        (waitMin * pricing.waitPerMin);
    return _directRideCustomerTotalFromRaw(raw);
  }

  /// FARE-ROUNDING-CENTRAL-0_10-1 — live DISPLAY PREVIEW of the running meter.
  ///
  /// Shows the raw fare rounded to the nearest €0.10 using the same canonical
  /// rule as finalization, so the cockpit steps in €0.10 increments (e.g. raw
  /// €3.21 → €3.20, raw €3.25 → €3.30). This is display only: it reads the raw
  /// accumulator and never writes back into it, so there is no cumulative
  /// rounding drift during the ride.
  double get _liveMeterPreviewEur {
    final raw = _liveMeterTotalEur;
    final preview = roundFareEuroToNearestTenCents(raw);
    if (preview == null) return raw;
    _logPreviewFareRoundingIfChanged(rawEur: raw, previewEur: preview);
    return preview;
  }

  void _logPreviewFareRoundingIfChanged({
    required double rawEur,
    required double previewEur,
  }) {
    final roundedCents = (previewEur * 100).round();
    if (_lastPreviewRoundedCents == roundedCents) return;
    _lastPreviewRoundedCents = roundedCents;
    if (!kDebugMode) return;
    debugPrint(
      '[FARE_ROUNDING] phase=preview rawCents=${(rawEur * 100).round()} '
      'roundedCents=$roundedCents alreadyFinalized=false source=street',
    );
  }

  void _logFinalizeFareRounding({
    required double rawEur,
    required double finalEur,
    required bool alreadyFinalized,
    required String source,
    String? reason,
  }) {
    if (!kDebugMode) return;
    final buffer = StringBuffer()
      ..write('[FARE_ROUNDING] phase=finalize ')
      ..write('rawCents=${(rawEur * 100).round()} ')
      ..write('roundedCents=${(finalEur * 100).round()} ')
      ..write('alreadyFinalized=$alreadyFinalized ')
      ..write('source=$source');
    if (reason != null && reason.isNotEmpty) {
      buffer.write(' reason=$reason');
    }
    debugPrint(buffer.toString());
  }

  /// FARE-ROUNDING-CENTRAL-0_10-1 — applies the canonical €0.10 rounding once
  /// to a raw fare that this client is finalizing (e.g. the planned-ride quote
  /// or a local street-ride fallback), emitting a bounded diagnostic. Returns
  /// the raw value unchanged for defensive/invalid inputs so a bad amount is
  /// never silently coerced to €0.
  double _finalizedFareForPersistence(
    double rawEur, {
    required String source,
    String? reason,
  }) {
    final rounded = roundFareEuroToNearestTenCents(rawEur);
    if (rounded == null) return rawEur;
    _logFinalizeFareRounding(
      rawEur: rawEur,
      finalEur: rounded,
      alreadyFinalized: false,
      source: source,
      reason: reason,
    );
    return rounded;
  }

  void _debugLiveMeter({required String reason}) {
    final now = DateTime.now();
    final last = _lastMeterDebugAt;
    if (last != null && now.difference(last).inSeconds < 5) return;
    _lastMeterDebugAt = now;
    final waitMin = _effectiveWaitElapsed.inMilliseconds / 60000.0;
    final pricing = _resolveDirectRidePricing();
    final kmCost = _kmDriven * pricing.perKm;
    final waitCost = waitMin * pricing.waitPerMin;
    final raw = pricing.startFee + kmCost + waitCost;
    final total = _directRideCustomerTotalFromRaw(raw);
    debugPrint(
      '[METER][$reason] waiting=$_isWaiting km=${_kmDriven.toStringAsFixed(3)} kmCost=${kmCost.toStringAsFixed(2)} waitSec=${_effectiveWaitElapsed.inSeconds} waitCost=${waitCost.toStringAsFixed(2)} total=${total.toStringAsFixed(2)}',
    );
  }

  /// Price text shown in the cockpit / Tellers.
  ///
  /// PLANNED-RIDE-FIXED-PRICE-PRESENTATION-AND-DURABILITY-1:
  /// - Planned booking (prepare / START / active): canonical fixed booking/leg
  ///   price via [_driverDisplayPriceForBooking]; never `_liveMeterTotalEur`.
  /// - Missing planned price: `€ —` (no street-meter fallback).
  /// - Street/direct (or no booking): existing live meter preview.
  String get _displayTotalText => _cockpitFarePresentation.amountText;

  String get _displayPriceLabel => _cockpitFarePresentation.cockpitLabel;

  String get _tellersFareLabel => _cockpitFarePresentation.tellersLabel;

  String get _cockpitPriceText =>
      _displayTotalText.replaceFirst('€', '').trim();

  String _formatDirectRideEstimateText(double amount, String currency) {
    final normalizedCurrency = currency.trim().isEmpty
        ? kDefaultCurrency
        : currency.trim().toUpperCase();
    if (normalizedCurrency == 'EUR') {
      return '€ ${amount.toStringAsFixed(2)}';
    }
    return '$normalizedCurrency ${amount.toStringAsFixed(2)}';
  }

  double? _quoteNumber(dynamic value) {
    if (value is num) {
      final v = value.toDouble();
      return v.isFinite ? v : null;
    }
    if (value is String) {
      var s = value.trim();
      if (s.isEmpty) return null;
      s = s.replaceAll(RegExp(r'[^0-9,\.\-]'), '');
      if (s.contains(',') && !s.contains('.')) s = s.replaceAll(',', '.');
      if (s.contains(',') && s.contains('.')) s = s.replaceAll(',', '');
      final parsed = double.tryParse(s);
      if (parsed == null || !parsed.isFinite) return null;
      return parsed;
    }
    return null;
  }

  String _directRideEstimateCurrencyFrom(dynamic data) {
    if (data is! Map) return kDefaultCurrency;
    final map = Map<String, dynamic>.from(data);
    final direct = map['currency']?.toString().trim();
    if (direct != null && direct.isNotEmpty) return direct.toUpperCase();
    final quote = map['quote'];
    if (quote is Map) {
      final nested = quote['currency']?.toString().trim();
      if (nested != null && nested.isNotEmpty) return nested.toUpperCase();
      final pricing = quote['pricing'];
      if (pricing is Map) {
        final pricingCurrency = pricing['currency']?.toString().trim();
        if (pricingCurrency != null && pricingCurrency.isNotEmpty) {
          return pricingCurrency.toUpperCase();
        }
      }
    }
    final pricing = map['pricing'];
    if (pricing is Map) {
      final pricingCurrency = pricing['currency']?.toString().trim();
      if (pricingCurrency != null && pricingCurrency.isNotEmpty) {
        return pricingCurrency.toUpperCase();
      }
    }
    return kDefaultCurrency;
  }

  ({double? amount, String? source}) _extractQuoteEstimateResult(dynamic data) {
    Map<String, dynamic> asMap(dynamic value) =>
        value is Map ? Map<String, dynamic>.from(value) : <String, dynamic>{};
    final root = asMap(data);
    final quote = asMap(root['quote']);
    final pricing = asMap(root['pricing']);
    final quotePricing = asMap(quote['pricing']);
    final quotePricingMain = asMap(
      quote['pricing_main'] ?? quote['pricingMain'],
    );
    final pricingMain = asMap(root['pricing_main'] ?? root['pricingMain']);
    final candidates = <({String source, dynamic value})>[
      (
        source: 'root.total_price_incl_vat',
        value: root['total_price_incl_vat'],
      ),
      (source: 'root.price_incl_vat', value: root['price_incl_vat']),
      (source: 'root.total_price', value: root['total_price']),
      (source: 'root.total', value: root['total']),
      (source: 'root.price', value: root['price']),
      (source: 'root.amount', value: root['amount']),
      (source: 'root.eur', value: root['eur']),
      (
        source: 'quote.total_price_incl_vat',
        value: quote['total_price_incl_vat'],
      ),
      (source: 'quote.price_incl_vat', value: quote['price_incl_vat']),
      (source: 'quote.total_price', value: quote['total_price']),
      (source: 'quote.total', value: quote['total']),
      (source: 'quote.price', value: quote['price']),
      (source: 'quote.amount', value: quote['amount']),
      (source: 'quote.eur', value: quote['eur']),
      (source: 'pricing.price_incl_vat', value: pricing['price_incl_vat']),
      (source: 'pricing.total_price', value: pricing['total_price']),
      (source: 'pricing.total', value: pricing['total']),
      (source: 'pricing.price', value: pricing['price']),
      (source: 'pricing.amount', value: pricing['amount']),
      (source: 'pricing.eur', value: pricing['eur']),
      (
        source: 'quote.pricing.price_incl_vat',
        value: quotePricing['price_incl_vat'],
      ),
      (source: 'quote.pricing.total_price', value: quotePricing['total_price']),
      (source: 'quote.pricing.total', value: quotePricing['total']),
      (source: 'quote.pricing.price', value: quotePricing['price']),
      (source: 'quote.pricing.amount', value: quotePricing['amount']),
      (source: 'quote.pricing.eur', value: quotePricing['eur']),
      (
        source: 'quote.pricing_main.price_incl_vat',
        value: quotePricingMain['price_incl_vat'],
      ),
      (
        source: 'pricing_main.price_incl_vat',
        value: pricingMain['price_incl_vat'],
      ),
    ];
    for (final candidate in candidates) {
      final parsed = _quoteNumber(candidate.value);
      if (parsed != null) {
        return (amount: parsed, source: candidate.source);
      }
    }
    return (amount: null, source: null);
  }

  double? _extractQuoteEstimateTotal(dynamic data) {
    return _extractQuoteEstimateResult(data).amount;
  }

  String _estimateMapKeys(dynamic value) {
    if (value is! Map) return '-';
    final keys = value.keys.map((k) => k.toString()).toList(growable: false);
    if (keys.isEmpty) return '-';
    if (keys.length <= 10) return keys.join(',');
    return '${keys.take(10).join(',')},...';
  }

  void _scheduleDirectRideLocationRetry({required String reason}) {
    _directRideEstimateLocationRetryTimer?.cancel();
    final destination = (_directRideDestinationText ?? '').trim();
    if (!_directRideDraft || destination.isEmpty) {
      return;
    }
    if (_directRideLocationRetryCount >= _maxDirectRideLocationRetries) {
      debugPrint(
        '[DIRECT_RIDE][ESTIMATE][RETRY_SKIP] reason=$reason retries=$_directRideLocationRetryCount max=$_maxDirectRideLocationRetries',
      );
      return;
    }
    _directRideLocationRetryCount += 1;
    final retryAttempt = _directRideLocationRetryCount;
    debugPrint(
      '[DIRECT_RIDE][ESTIMATE][RETRY_SCHEDULE] reason=$reason attempt=$retryAttempt delay_ms=1800',
    );
    _directRideEstimateLocationRetryTimer = Timer(
      const Duration(milliseconds: 1800),
      () {
        if (!mounted) return;
        final latestDestination = (_directRideDestinationText ?? '').trim();
        if (!_directRideDraft || latestDestination.isEmpty) return;
        unawaited(
          _refreshDirectRideEstimate(reason: 'location_retry_$retryAttempt'),
        );
      },
    );
  }

  void _scheduleDirectRideEstimateRefresh({required String reason}) {
    if (!_directRideDraft) {
      _directRideEstimateDebounce?.cancel();
      _directRideEstimateLocationRetryTimer?.cancel();
      return;
    }
    final destination = (_directRideDestinationText ?? '').trim();
    if (_directRideLocationRetryDestination != destination) {
      _directRideLocationRetryDestination = destination;
      _directRideLocationRetryCount = 0;
      _directRideEstimateLocationRetryTimer?.cancel();
    }
    if (destination.isEmpty) {
      _directRideEstimateDebounce?.cancel();
      _directRideEstimateLocationRetryTimer?.cancel();
      if (!mounted) return;
      setState(() {
        _directRideEstimatedFare = null;
        _directRideEstimateLoading = false;
        _directRideEstimateError = null;
        _directRideEstimateCurrency = kDefaultCurrency;
        _directRideEstimateSignature = null;
        _directRideLocationRetryCount = 0;
        _directRideLocationRetryDestination = null;
      });
      return;
    }
    _directRideEstimateDebounce?.cancel();
    _directRideEstimateDebounce = Timer(const Duration(milliseconds: 450), () {
      unawaited(_refreshDirectRideEstimate(reason: reason));
    });
  }

  Future<({geo.Position? position, String source, String? failureReason})>
  _resolveDirectRideEstimateOriginPosition({required String reason}) async {
    final serviceEnabled = await geo.Geolocator.isLocationServiceEnabled();
    var permission = await geo.Geolocator.checkPermission();
    debugPrint(
      '[DIRECT_RIDE][ESTIMATE][LOCATION_STATUS] reason=$reason serviceEnabled=$serviceEnabled permission=${permission.name} source=resolver',
    );

    final cached = _lastPos;
    if (cached != null) {
      debugPrint(
        '[DIRECT_RIDE][ESTIMATE][POSITION_RESOLVED] reason=$reason source=lastPos',
      );
      return (position: cached, source: 'lastPos', failureReason: null);
    }

    if (!serviceEnabled) {
      debugPrint(
        '[DIRECT_RIDE][ESTIMATE][POSITION_FAILED] reason=service_disabled source=resolver',
      );
      return (
        position: null,
        source: 'none',
        failureReason: 'service_disabled',
      );
    }

    if (permission == geo.LocationPermission.denied) {
      permission = await geo.Geolocator.requestPermission();
      debugPrint(
        '[DIRECT_RIDE][ESTIMATE][LOCATION_STATUS] reason=$reason serviceEnabled=$serviceEnabled permission=${permission.name} source=request',
      );
    }

    if (permission == geo.LocationPermission.denied ||
        permission == geo.LocationPermission.deniedForever) {
      debugPrint(
        '[DIRECT_RIDE][ESTIMATE][POSITION_FAILED] reason=permission_denied source=resolver',
      );
      return (
        position: null,
        source: 'none',
        failureReason: 'permission_denied',
      );
    }

    try {
      final lastKnown = await geo.Geolocator.getLastKnownPosition();
      if (lastKnown != null) {
        _lastPos = lastKnown;
        debugPrint(
          '[DIRECT_RIDE][ESTIMATE][POSITION_RESOLVED] reason=$reason source=lastKnown',
        );
        return (position: lastKnown, source: 'lastKnown', failureReason: null);
      }
    } catch (e) {
      debugPrint(
        '[DIRECT_RIDE][ESTIMATE][POSITION_FAILED] reason=exception source=lastKnown error=$e',
      );
    }

    try {
      final current = await geo.Geolocator.getCurrentPosition(
        desiredAccuracy: geo.LocationAccuracy.best,
      ).timeout(const Duration(seconds: 8));
      _lastPos = current;
      debugPrint(
        '[DIRECT_RIDE][ESTIMATE][POSITION_RESOLVED] reason=$reason source=current',
      );
      return (position: current, source: 'current', failureReason: null);
    } on TimeoutException {
      debugPrint(
        '[DIRECT_RIDE][ESTIMATE][POSITION_FAILED] reason=timeout source=current',
      );
      return (position: null, source: 'none', failureReason: 'timeout');
    } catch (e) {
      debugPrint(
        '[DIRECT_RIDE][ESTIMATE][POSITION_FAILED] reason=exception source=current error=$e',
      );
      return (position: null, source: 'none', failureReason: 'exception');
    }
  }

  Future<void> _refreshDirectRideEstimate({required String reason}) async {
    final destination = (_directRideDestinationText ?? '').trim();
    final shouldEstimate = _directRideDraft;
    debugPrint(
      '[DIRECT_RIDE][ESTIMATE][START] reason=$reason hasDestination=${destination.isNotEmpty} hasLastPos=${_lastPos != null} isDraft=$shouldEstimate',
    );
    if (!shouldEstimate || destination.isEmpty) return;

    final resolvedPosition = await _resolveDirectRideEstimateOriginPosition(
      reason: reason,
    );
    final pos = resolvedPosition.position;

    if (pos == null) {
      if (!mounted) return;
      setState(() {
        _directRideEstimateLoading = false;
        _directRideEstimateError = 'location_unavailable';
      });
      debugPrint(
        '[DIRECT_RIDE][ESTIMATE][WARN] reason=$reason hasPosition=false failure=${resolvedPosition.failureReason ?? 'unknown'} error=location_unavailable',
      );
      if (resolvedPosition.failureReason != 'permission_denied' &&
          resolvedPosition.failureReason != 'service_disabled') {
        _scheduleDirectRideLocationRetry(reason: reason);
      }
      return;
    }

    final pickupText =
        '${pos.longitude.toStringAsFixed(6)},${pos.latitude.toStringAsFixed(6)}';
    final signature =
        '$pickupText|$destination|${_routeKm?.toStringAsFixed(3) ?? '-'}|${_routeDurationSec ?? -1}';
    if (!_directRideEstimateLoading &&
        _directRideEstimateSignature == signature &&
        _directRideEstimatedFare != null) {
      return;
    }

    final requestSeq = ++_directRideEstimateRequestSeq;
    if (mounted) {
      setState(() {
        _directRideEstimateLoading = true;
        _directRideEstimateError = null;
      });
    }

    final settings = businessSettingsNotifier.value;
    final vat = localBackendTaxProfileNotifier.value;
    final vatRateBase = vat?.vatRate ?? settings.pricingVatRate;
    final vatRate =
        (vatRateBase.isFinite ? vatRateBase : settings.pricingVatRate)
            .clamp(0.0, 1.0)
            .toDouble();
    final vatMode = (vat?.vatDisplayMode ?? 'incl').trim().isEmpty
        ? 'incl'
        : (vat?.vatDisplayMode ?? 'incl').trim();
    final scope = _activeBookingScopeQuery();
    final hasStrictScope = _strictActiveBookingScopeQuery() != null;
    debugPrint(
      '[DIRECT_RIDE][ESTIMATE][CONTEXT] reason=$reason hasPosition=true hasScope=${scope.isNotEmpty} hasStrictScope=$hasStrictScope tenant=${scope['tenant_id'] ?? '-'} company=${scope['company_id'] ?? '-'}',
    );
    final pickupAt = DateTime.now().add(const Duration(minutes: 5));
    String two(int v) => v.toString().padLeft(2, '0');
    final date = '${pickupAt.year}-${two(pickupAt.month)}-${two(pickupAt.day)}';
    final time = '${two(pickupAt.hour)}:${two(pickupAt.minute)}';
    final pickupIso = '${date}T$time:00';
    final bookingCurrency = normalizeExplicitIsoCurrencyCode(
      settings.defaultCurrency,
    );

    final body = <String, dynamic>{
      'from': pickupText,
      'to': destination,
      'date': date,
      'time': time,
      'pickup_iso': pickupIso,
      'tier': 'COMFORT',
      'service': 'AIRPORT',
      'pax': 1,
      'bags': 0,
      'wait_min': 0,
      'return': false,
      'return_enabled': false,
      'return_from': '',
      'return_to': '',
      'return_date': '',
      'return_time': '',
      'return_pickup_iso': '',
      'vat_rate': vatRate,
      'vat_mode': vatMode,
      if (bookingCurrency.isNotEmpty) 'currency': bookingCurrency,
      'pricing_profile': <String, dynamic>{
        'base_fare': settings.pricingBaseFare,
        'price_per_km': settings.pricingPerKm,
        'price_per_minute': settings.pricingPerMinute,
        'minimum_fare': settings.pricingMinimumFare,
        'wait_per_minute': settings.pricingWaitPerMinute,
        'return_enabled': settings.pricingReturnEnabled,
        'return_fee': settings.pricingReturnFee,
        'fuel_surcharge': settings.pricingFuelSurcharge,
        'vat_rate': vatRate,
        'vat_mode': vatMode,
        if (bookingCurrency.isNotEmpty) 'currency': bookingCurrency,
      },
      'surcharge_fuel': settings.pricingFuelSurcharge,
      'return_fee': 0,
      'extra_service': 'NONE',
      'extra_service_key': 'NONE',
      ...scope,
    };

    try {
      final uri = _withActiveBookingScope(kBookingBaseUrl, '/quote');
      // /quote is a public pricing endpoint — no auth header is required.
      final res = await http
          .post(uri, headers: _headers(), body: jsonEncode(body))
          .timeout(const Duration(seconds: 12));
      if (res.statusCode < 200 || res.statusCode >= 300) {
        final bodySnippet = res.body
            .replaceAll(RegExp(r'\s+'), ' ')
            .trim()
            .replaceAll(RegExp(r'[\r\n\t]'), ' ');
        final safeSnippet = bodySnippet.length > 280
            ? '${bodySnippet.substring(0, 280)}...'
            : bodySnippet;
        throw Exception(
          'quote_http_${res.statusCode}${safeSnippet.isNotEmpty ? ': $safeSnippet' : ''}',
        );
      }
      final decoded = jsonDecode(res.body);
      final estimateResult = _extractQuoteEstimateResult(decoded);
      final estimate = estimateResult.amount;
      if (estimate == null) {
        if (decoded is Map) {
          final root = Map<String, dynamic>.from(decoded);
          final quote = root['quote'];
          final pricing = root['pricing'];
          final quotePricing = quote is Map ? quote['pricing'] : null;
          debugPrint(
            '[DIRECT_RIDE][ESTIMATE][PARSE_MISS] reason=$reason rootKeys=${_estimateMapKeys(root)} quoteKeys=${_estimateMapKeys(quote)} pricingKeys=${_estimateMapKeys(pricing)} quotePricingKeys=${_estimateMapKeys(quotePricing)}',
          );
        }
        throw Exception('quote_total_missing');
      }
      if (!mounted || requestSeq != _directRideEstimateRequestSeq) return;
      setState(() {
        _directRideEstimatedFare = estimate;
        _directRideEstimateCurrency = _directRideEstimateCurrencyFrom(decoded);
        _directRideEstimateLoading = false;
        _directRideEstimateError = null;
        _directRideEstimateSignature = signature;
        _directRideLocationRetryCount = 0;
      });
      debugPrint(
        '[DIRECT_RIDE][ESTIMATE][OK] reason=$reason amount=${estimate.toStringAsFixed(2)} source=${estimateResult.source ?? 'unknown'}',
      );
    } catch (e) {
      if (!mounted || requestSeq != _directRideEstimateRequestSeq) return;
      final errorText = e.toString();
      final safeError = errorText.contains('quote_total_missing')
          ? 'quote_total_missing'
          : errorText;
      setState(() {
        _directRideEstimateLoading = false;
        _directRideEstimateError = safeError;
      });
      debugPrint('[DIRECT_RIDE][ESTIMATE][WARN] reason=$reason error=$e');
    }
  }

  Future<void> _sendDirectTripWaitEvent({
    required String path,
    required String logLabel,
    required String timestampKey,
  }) async {
    final tripId = _activeDirectTripId;
    if (!_directRideActive || tripId == null || tripId.trim().isEmpty) return;
    try {
      final strictScope = _strictBookingScopeForMutation(
        action: 'direct_trip_wait_event_$logLabel',
        showUx: false,
      );
      if (strictScope == null) return;
      final payload = <String, dynamic>{
        'trip_id': tripId,
        ...strictScope,
        timestampKey: DateTime.now().toUtc().toIso8601String(),
      };
      final res = await http
          .post(
            _uriWithScope(kWorkerBaseUrl, path, strictScope),
            headers: _driverBearerHeaders(),
            body: jsonEncode(payload),
          )
          .timeout(const Duration(seconds: 5));
      if (res.statusCode != 200) {
        throw Exception('HTTP ${res.statusCode}: ${res.body}');
      }
      debugPrint('[DIRECT_TRIP][$logLabel][OK] trip_id=$tripId');
    } catch (e) {
      debugPrint('[DIRECT_TRIP][$logLabel][WARN] local wait only: $e');
    }
  }

  String _directRideVehicleId() {
    final activeCompanyId =
        companyProfileNotifier.value?.companyId.trim().isNotEmpty == true
        ? companyProfileNotifier.value!.companyId.trim()
        : (activeCompanySessionNotifier.value?.companyId.trim().isNotEmpty ==
                  true
              ? activeCompanySessionNotifier.value!.companyId.trim()
              : '');
    final activeDriverId = kDriverId.trim();
    final candidateVehicles = activeCompanyId.isNotEmpty
        // Company-scoped fallback prevents cross-company vehicle reuse in direct rides.
        ? vehiclesNotifier.value
              .where(
                (vehicle) =>
                    (vehicle.companyId?.trim() ?? '') == activeCompanyId,
              )
              .toList(growable: false)
        : vehiclesNotifier.value;

    for (final vehicle in candidateVehicles) {
      if (vehicle.isActive &&
          vehicle.driverId == activeDriverId &&
          vehicle.id.trim().isNotEmpty) {
        return vehicle.id.trim();
      }
    }
    for (final vehicle in candidateVehicles) {
      if (vehicle.isActive && vehicle.id.trim().isNotEmpty) {
        return vehicle.id.trim();
      }
    }
    if (candidateVehicles.isNotEmpty) {
      final firstId = candidateVehicles.first.id.trim();
      if (firstId.isNotEmpty) return firstId;
    }
    if (activeCompanyId.isNotEmpty) return '';
    return 'vh_1';
  }

  Map<String, dynamic> _currentOriginPayload(geo.Position? pos) {
    if (pos == null) {
      return <String, dynamic>{'label': _receiptText('currentLocation')};
    }
    return <String, dynamic>{
      'label':
          '${pos.latitude.toStringAsFixed(6)}, ${pos.longitude.toStringAsFixed(6)}',
      'lat': pos.latitude,
      'lon': pos.longitude,
    };
  }

  Map<String, dynamic> _plannedBookingDetailsPayload(BookingItem booking) {
    Map<String, dynamic> asMap(dynamic value) =>
        value is Map ? Map<String, dynamic>.from(value) : <String, dynamic>{};
    List<dynamic> asList(dynamic value) => value is List ? value : const [];
    String? text(dynamic value) {
      final s = value?.toString().trim();
      return s == null || s.isEmpty ? null : s;
    }

    num? number(dynamic value) {
      if (value is num) return value;
      if (value is String) return num.tryParse(value.replaceAll(',', '.'));
      return null;
    }

    dynamic pick(List<List<String>> paths) {
      for (final path in paths) {
        dynamic current = booking.details;
        for (final key in path) {
          if (current is Map && current.containsKey(key)) {
            current = current[key];
          } else {
            current = null;
            break;
          }
        }
        if (current != null) return current;
      }
      return null;
    }

    final bookingMap = asMap(booking.details['booking']);
    final detailMap = booking.details;
    final quote = asMap(booking.details['quote']);
    final record = asMap(booking.details['record']);
    final recordQuote = asMap(record['quote']);
    final recordPayload = asMap(record['payload']);
    final payloadQuote = asMap(recordPayload['quote']);
    if (quote.isEmpty && recordQuote.isNotEmpty) {
      quote.addAll(recordQuote);
    }
    if (quote.isEmpty && payloadQuote.isNotEmpty) {
      quote.addAll(payloadQuote);
    }
    final inputs = asMap(quote['inputs']);
    final pricing = asMap(quote['pricing']);
    final pricingMain = asMap(quote['pricing_main'] ?? quote['pricingMain']);
    final pricingReturn = asMap(
      quote['pricing_return'] ?? quote['pricingReturn'],
    );
    final returnInfo = asMap(quote['return']);
    final tracking = asMap(booking.details['tracking_booking']);
    final payload = recordPayload;
    final customer = asMap(payload['customer']);
    final bookingCustomer = asMap(bookingMap['customer']);
    final payloadBooking = asMap(payload['booking']);
    final payloadBookingCustomer = asMap(payloadBooking['customer']);
    final customerName = text(
      bookingMap['custName'] ??
          bookingMap['customer_name'] ??
          bookingMap['customerName'] ??
          bookingMap['name'] ??
          bookingCustomer['name'] ??
          bookingCustomer['full_name'] ??
          detailMap['customer_name'] ??
          detailMap['customerName'] ??
          detailMap['name'] ??
          payload['name'] ??
          payload['customer_name'] ??
          payload['customerName'] ??
          payloadBooking['customer_name'] ??
          payloadBooking['customerName'] ??
          payloadBooking['name'] ??
          payloadBookingCustomer['name'] ??
          payloadBookingCustomer['full_name'] ??
          customer['name'] ??
          customer['full_name'] ??
          pick([
            ['customer', 'name'],
            ['booking', 'customer', 'name'],
            ['record', 'payload', 'customer', 'name'],
            ['record', 'payload', 'booking', 'customer', 'name'],
          ]),
    );
    final customerPhone = text(
      bookingMap['custPhone'] ??
          bookingMap['customer_phone'] ??
          bookingMap['customerPhone'] ??
          bookingMap['phone'] ??
          bookingMap['tel'] ??
          bookingMap['mobile'] ??
          bookingCustomer['phone'] ??
          bookingCustomer['tel'] ??
          bookingCustomer['mobile'] ??
          detailMap['customer_phone'] ??
          detailMap['customerPhone'] ??
          detailMap['phone'] ??
          detailMap['tel'] ??
          detailMap['mobile'] ??
          payload['phone'] ??
          payload['customer_phone'] ??
          payload['customerPhone'] ??
          payload['tel'] ??
          payload['mobile'] ??
          payloadBooking['customer_phone'] ??
          payloadBooking['customerPhone'] ??
          payloadBooking['phone'] ??
          payloadBooking['tel'] ??
          payloadBooking['mobile'] ??
          payloadBookingCustomer['phone'] ??
          payloadBookingCustomer['tel'] ??
          payloadBookingCustomer['mobile'] ??
          customer['phone'] ??
          customer['tel'] ??
          customer['mobile'] ??
          pick([
            ['customer', 'phone'],
            ['booking', 'customer', 'phone'],
            ['record', 'payload', 'customer', 'phone'],
            ['record', 'payload', 'booking', 'customer', 'phone'],
          ]),
    );
    final customerEmail = text(
      bookingMap['custEmail'] ??
          bookingMap['customer_email'] ??
          bookingMap['customerEmail'] ??
          bookingMap['email'] ??
          bookingCustomer['email'] ??
          detailMap['customer_email'] ??
          detailMap['customerEmail'] ??
          detailMap['email'] ??
          payload['email'] ??
          payload['customer_email'] ??
          payload['customerEmail'] ??
          payloadBooking['customer_email'] ??
          payloadBooking['customerEmail'] ??
          payloadBooking['email'] ??
          payloadBookingCustomer['email'] ??
          customer['email'] ??
          pick([
            ['customer', 'email'],
            ['booking', 'customer', 'email'],
            ['record', 'payload', 'customer', 'email'],
            ['record', 'payload', 'booking', 'customer', 'email'],
          ]),
    );
    final customerCountry = text(
      bookingMap['customer_country'] ??
          bookingMap['customerCountry'] ??
          bookingMap['country'] ??
          bookingMap['countryCode'] ??
          bookingMap['country_iso'] ??
          bookingMap['countryIso'] ??
          detailMap['customer_country'] ??
          detailMap['customerCountry'] ??
          detailMap['country'] ??
          detailMap['countryCode'] ??
          detailMap['country_iso'] ??
          detailMap['countryIso'] ??
          payload['customer_country'] ??
          payload['customerCountry'] ??
          payload['country'] ??
          payload['countryCode'] ??
          payload['country_iso'] ??
          payload['countryIso'] ??
          payload['locale'] ??
          payload['language'] ??
          customer['country'] ??
          customer['countryCode'] ??
          customer['countryIso'],
    );
    final phoneCountryCode = text(
      bookingMap['phone_country_code'] ??
          bookingMap['phoneCountryCode'] ??
          detailMap['phone_country_code'] ??
          detailMap['phoneCountryCode'] ??
          payload['phone_country_code'] ??
          payload['phoneCountryCode'] ??
          customer['phone_country_code'] ??
          customer['phoneCountryCode'],
    );
    final dialCode = text(
      bookingMap['dial_code'] ??
          bookingMap['dialCode'] ??
          detailMap['dial_code'] ??
          detailMap['dialCode'] ??
          payload['dial_code'] ??
          payload['dialCode'] ??
          customer['dial_code'] ??
          customer['dialCode'],
    );

    final pickupAddress =
        text(booking.from) ??
        text(quote['from']) ??
        text(inputs['from']) ??
        text(bookingMap['from']) ??
        text(tracking['pickup']);
    final destinationAddress =
        text(booking.to) ??
        text(quote['to']) ??
        text(inputs['to']) ??
        text(bookingMap['to']) ??
        text(tracking['dropoff']);
    String? normalizeServiceToken(String? raw) {
      final token = raw?.trim();
      if (token == null || token.isEmpty) return null;
      final normalized = token
          .toLowerCase()
          .replaceAll('-', '_')
          .replaceAll(' ', '_');
      if (normalized == 'airport' ||
          normalized == 'airport_transfer' ||
          normalized == 'luchthaven') {
        return 'airport';
      }
      if (normalized == 'business' || normalized == 'zakelijk') {
        return 'business';
      }
      if (normalized == 'passenger' ||
          normalized == 'passenger_transport' ||
          normalized == 'personenvervoer') {
        return 'passenger';
      }
      return normalized;
    }

    String? normalizeTierToken(String? raw) {
      final token = raw?.trim();
      if (token == null || token.isEmpty) return null;
      final normalized = token
          .toLowerCase()
          .replaceAll('-', '_')
          .replaceAll(' ', '_');
      if (normalized == 'comfort' ||
          normalized == 'private' ||
          normalized == 'premium') {
        return normalized;
      }
      return normalized;
    }

    final service = normalizeServiceToken(
      text(
        bookingMap['service_type'] ??
            bookingMap['serviceType'] ??
            bookingMap['service'] ??
            detailMap['service_type'] ??
            detailMap['serviceType'] ??
            detailMap['service'] ??
            payload['service_type'] ??
            payload['serviceType'] ??
            payload['service'] ??
            inputs['service_type'] ??
            inputs['serviceType'] ??
            inputs['service'] ??
            pick([
              ['service_type'],
              ['serviceType'],
              ['service'],
            ]),
      ),
    );
    final tier = normalizeTierToken(
      text(
        booking.tier ??
            bookingMap['tier'] ??
            bookingMap['vehicle_tier'] ??
            bookingMap['vehicleTier'] ??
            detailMap['tier'] ??
            detailMap['vehicle_tier'] ??
            detailMap['vehicleTier'] ??
            payload['tier'] ??
            payload['vehicle_tier'] ??
            payload['vehicleTier'] ??
            inputs['tier'] ??
            inputs['vehicle_tier'] ??
            inputs['vehicleTier'],
      ),
    );
    final scheduledPickup =
        text(booking.pickupIso) ??
        text(bookingMap['pickupStartIso']) ??
        text(bookingMap['pickup_iso']) ??
        text(inputs['pickup_iso']);
    final totalPackage =
        number(bookingMap['price_incl_vat']) ??
        number(pricing['price_incl_vat']) ??
        number(pricing['total_price_incl_vat']) ??
        number(quote['total_price_incl_vat']) ??
        number(quote['price_incl_vat']) ??
        booking.price;
    final operationalLeg = booking.isOperationalLeg;
    final legTypeToken = operationalLeg
        ? _operationalLegTypeToken(booking)
        : null;
    final segmentPrice = operationalLeg
        ? _driverDisplayPriceForBooking(booking)
        : (booking.bookingId.endsWith('-R')
              ? (number(bookingMap['price_incl_vat_return']) ??
                    number(pricingReturn['price_incl_vat']) ??
                    number(returnInfo['price_incl_vat']) ??
                    number(asMap(returnInfo['pricing'])['price_incl_vat']))
              : (number(bookingMap['price_incl_vat_main']) ??
                    number(pricingMain['price_incl_vat']) ??
                    number(quote['price_incl_vat'])));
    final returnPickup =
        text(bookingMap['returnPickupIso']) ??
        text(inputs['return_pickup_iso']) ??
        text(
          pick([
            ['return_pickup_iso'],
          ]),
        );
    final returnFrom =
        text(bookingMap['return_from']) ??
        text(inputs['return_from']) ??
        text(returnInfo['from']);
    final returnTo =
        text(bookingMap['return_to']) ??
        text(inputs['return_to']) ??
        text(returnInfo['to']);
    final hasReturnInfo =
        returnPickup != null ||
        returnFrom != null ||
        returnTo != null ||
        returnInfo['enabled'] == true ||
        pricingReturn.isNotEmpty;
    final paymentStatus = text(
      bookingMap['payment_status'] ??
          bookingMap['paymentStatus'] ??
          detailMap['payment_status'] ??
          detailMap['paymentStatus'] ??
          payload['payment_status'] ??
          payload['paymentStatus'] ??
          pick([
            ['payment_status'],
            ['paymentStatus'],
            ['booking', 'payment_status'],
            ['booking', 'paymentStatus'],
          ]),
    );
    final paidAt = text(
      bookingMap['paid_at'] ??
          bookingMap['paidAt'] ??
          detailMap['paid_at'] ??
          detailMap['paidAt'] ??
          payload['paid_at'] ??
          payload['paidAt'],
    );
    final paymentProvider = text(
      bookingMap['payment_provider'] ??
          bookingMap['paymentProvider'] ??
          detailMap['payment_provider'] ??
          detailMap['paymentProvider'] ??
          payload['payment_provider'] ??
          payload['paymentProvider'],
    );
    final paymentId = text(
      bookingMap['payment_id'] ??
          bookingMap['paymentId'] ??
          detailMap['payment_id'] ??
          detailMap['paymentId'] ??
          payload['payment_id'] ??
          payload['paymentId'],
    );

    List<Map<String, dynamic>> normalizeSegments(dynamic raw) {
      final result = <Map<String, dynamic>>[];
      for (final value in asList(raw)) {
        if (value is! Map) continue;
        final segment = Map<String, dynamic>.from(value);
        final from = text(
          segment['from'] ??
              segment['origin'] ??
              segment['start'] ??
              segment['start_address'],
        );
        final to = text(
          segment['to'] ??
              segment['destination'] ??
              segment['end'] ??
              segment['end_address'],
        );
        result.add(<String, dynamic>{
          if (from != null) 'from': from,
          if (to != null) 'to': to,
          if (number(segment['distance_km'] ?? segment['km']) != null)
            'distance_km': number(segment['distance_km'] ?? segment['km']),
          if (number(segment['duration_min'] ?? segment['minutes']) != null)
            'duration_min': number(
              segment['duration_min'] ?? segment['minutes'],
            ),
        });
      }
      return result;
    }

    final routeSegments = normalizeSegments(
      quote['route_segments'] ??
          quote['legs'] ??
          bookingMap['route_segments'] ??
          bookingMap['legs'],
    );
    if (routeSegments.isEmpty &&
        pickupAddress != null &&
        destinationAddress != null) {
      final distance = number(
        quote['distance_km'] ?? bookingMap['distance_km'],
      );
      final duration = number(
        quote['duration_min'] ?? bookingMap['duration_route_min'],
      );
      if (distance != null || duration != null) {
        routeSegments.add(<String, dynamic>{
          'from': pickupAddress,
          'to': destinationAddress,
          if (distance != null) 'distance_km': distance,
          if (duration != null) 'duration_min': duration,
        });
      }
    }
    if (hasReturnInfo) {
      final returnDistance = number(
        returnInfo['distance_km'] ?? bookingMap['return_distance_km'],
      );
      final returnDuration = number(
        returnInfo['duration_min'] ?? bookingMap['return_duration_min'],
      );
      if (returnFrom != null ||
          returnTo != null ||
          returnDistance != null ||
          returnDuration != null) {
        routeSegments.add(<String, dynamic>{
          if (returnFrom != null) 'from': returnFrom,
          if (returnTo != null) 'to': returnTo,
          if (returnDistance != null) 'distance_km': returnDistance,
          if (returnDuration != null) 'duration_min': returnDuration,
          'kind': 'return',
        });
      }
    }
    final refMaps = _referenceLookupMaps(<Map<String, dynamic>>[
      detailMap,
      bookingMap,
      payload,
      quote,
      record,
      recordPayload,
      payloadBooking,
    ]);
    final refs = _extractBusinessReferenceAliasesFromMaps(refMaps);

    return <String, dynamic>{
      if (pickupAddress != null) 'pickup_address': pickupAddress,
      if (destinationAddress != null) 'destination_address': destinationAddress,
      if (scheduledPickup != null) 'scheduled_pickup_at': scheduledPickup,
      if (operationalLeg && legTypeToken == 'return') 'subtype': 'Retourrit',
      if (operationalLeg && legTypeToken == 'outbound') 'subtype': 'Heenrit',
      if (!operationalLeg && booking.bookingId.endsWith('-R'))
        'subtype': 'Retourrit',
      if (!operationalLeg && !booking.bookingId.endsWith('-R') && hasReturnInfo)
        'subtype': 'Heenrit',
      if (operationalLeg && booking.legId.trim().isNotEmpty) ...{
        'leg_id': booking.legId.trim(),
        'legId': booking.legId.trim(),
        'is_operational_leg': true,
        'isOperationalLeg': true,
      },
      if (operationalLeg && legTypeToken != null) ...{
        'leg_type': legTypeToken,
        'legType': legTypeToken,
      },
      if (customerName != null) 'customer_name': customerName,
      if (customerPhone != null) 'customer_phone': customerPhone,
      if (customerEmail != null) 'customer_email': customerEmail,
      if (customerName != null ||
          customerPhone != null ||
          customerEmail != null)
        'customer': <String, dynamic>{
          if (customerName != null) 'name': customerName,
          if (customerPhone != null) 'phone': customerPhone,
          if (customerEmail != null) 'email': customerEmail,
        },
      if (customerCountry != null) 'customer_country': customerCountry,
      if (phoneCountryCode != null) 'phone_country_code': phoneCountryCode,
      if (dialCode != null) 'dial_code': dialCode,
      if (service != null) ...{
        'service_type': service,
        'serviceType': service,
        'service': service,
      },
      if (tier != null) ...{
        'tier': tier,
        'vehicle_tier': tier,
        'vehicleTier': tier,
      },
      if (number(booking.pax ?? bookingMap['pax'] ?? inputs['pax']) != null)
        'passengers': number(booking.pax ?? bookingMap['pax'] ?? inputs['pax']),
      if (number(booking.bags ?? bookingMap['bags'] ?? inputs['bags']) != null)
        'luggage_count': number(
          booking.bags ?? bookingMap['bags'] ?? inputs['bags'],
        ),
      if (number(bookingMap['wait_min'] ?? inputs['wait_min']) != null)
        'booked_wait_minutes': number(
          bookingMap['wait_min'] ?? inputs['wait_min'],
        ),
      if ((booking.status ?? '').trim().isNotEmpty)
        'booking_status': booking.status!.trim(),
      if (paymentStatus != null) ...{
        'payment_status': paymentStatus,
        'paymentStatus': paymentStatus,
      },
      if (paidAt != null) ...{'paid_at': paidAt, 'paidAt': paidAt},
      if (paymentProvider != null) ...{
        'payment_provider': paymentProvider,
        'paymentProvider': paymentProvider,
      },
      if (paymentId != null) ...{
        'payment_id': paymentId,
        'paymentId': paymentId,
      },
      if (refs.receipt != null) ...{
        'receipt_reference': refs.receipt,
        'receiptReference': refs.receipt,
      },
      if (refs.planning != null) ...{
        'planning_reference': refs.planning,
        'planningReference': refs.planning,
      },
      if (refs.publicBooking != null) ...{
        'public_booking_reference': refs.publicBooking,
        'publicBookingReference': refs.publicBooking,
      },
      if (refs.booking != null) ...{
        'booking_reference': refs.booking,
        'bookingReference': refs.booking,
      },
      if (refs.publicRef != null) ...{
        'public_reference': refs.publicRef,
        'publicReference': refs.publicRef,
      },
      if (totalPackage != null) 'booking_total_eur': totalPackage,
      if (segmentPrice != null) 'segment_price_eur': segmentPrice,
      if (operationalLeg && segmentPrice != null) ...{
        'leg_price_incl_vat': segmentPrice,
        'legPriceInclVat': segmentPrice,
      },
      if (bookingMap['price_incl_vat_main'] != null ||
          pricingMain['price_incl_vat'] != null)
        'outbound_price_eur': number(
          bookingMap['price_incl_vat_main'] ?? pricingMain['price_incl_vat'],
        ),
      if (bookingMap['price_incl_vat_return'] != null ||
          pricingReturn['price_incl_vat'] != null)
        'return_price_eur': number(
          bookingMap['price_incl_vat_return'] ??
              pricingReturn['price_incl_vat'],
        ),
      if (returnPickup != null) 'return_scheduled_pickup_at': returnPickup,
      if (returnFrom != null || returnTo != null)
        'return_route': [returnFrom, returnTo].whereType<String>().join(' → '),
      if (routeSegments.isNotEmpty) 'route_segments': routeSegments,
      if (asList(
        bookingMap['stops'] ?? inputs['stops'] ?? quote['stops'],
      ).isNotEmpty)
        'stops': asList(
          bookingMap['stops'] ?? inputs['stops'] ?? quote['stops'],
        ).join(' → '),
      if (text(
            bookingMap['extra_service_label'] ?? inputs['extra_service_label'],
          ) !=
          null)
        'extras': text(
          bookingMap['extra_service_label'] ?? inputs['extra_service_label'],
        ),
      if (text(
            bookingMap['message'] ??
                payload['message'] ??
                customer['message'] ??
                pick([
                  ['customer', 'message'],
                ]),
          ) !=
          null)
        'notes': text(
          bookingMap['message'] ??
              payload['message'] ??
              customer['message'] ??
              pick([
                ['customer', 'message'],
              ]),
        ),
      if ((booking.currency ?? '').trim().isNotEmpty)
        'currency': booking.currency!.trim(),
    };
  }

  /// Calls `/trip/start-direct`. When [requireLiveLocalRide] is false (P0
  /// worker-first street start), entitlement/auth denials return without
  /// mutating local ride state. When true (retry after local activation),
  /// auth/entitlement denials hard-abort an already-live ride.
  Future<DirectTripWorkerStartResult> _startDirectTripSessionOnWorker({
    required String destination,
    required String directRideKey,
    bool requireLiveLocalRide = true,
  }) async {
    try {
      final strictScope = _strictBookingScopeForMutation(
        action: 'start_direct_trip',
      );
      if (strictScope == null) {
        return const DirectTripWorkerStartResult(
          outcome: DirectTripWorkerStartOutcome.transportOrOther,
        );
      }
      final point = _directRideDestinationPoint;
      final destinationPayload = <String, dynamic>{
        'label': destination,
        if (point != null) 'lat': point.lat,
        if (point != null) 'lon': point.lon,
      };
      final payload = withDirectRideBookingStartFields(<String, dynamic>{
        ...strictScope,
        'driver_id': kDriverId,
        'vehicle_id': _directRideVehicleId(),
        'origin': _currentOriginPayload(_lastPos),
        'destination': destinationPayload,
        'pricing_snapshot': _directRidePricingSnapshotPayload(),
        'client_started_at': DateTime.now().toUtc().toIso8601String(),
        ..._driverMutationActorFields(actorVehicleId: _directRideVehicleId()),
      }, directRideKey: directRideKey);
      final res = await http
          .post(
            _uriWithScope(kWorkerBaseUrl, kStartDirectTripPath, strictScope),
            headers: _driverBearerHeaders(),
            body: jsonEncode(payload),
          )
          .timeout(const Duration(seconds: 6));
      if (res.statusCode != 200) {
        throw Exception('HTTP ${res.statusCode}: ${res.body}');
      }
      final decoded = jsonDecode(res.body);
      final startResult = parseDirectRideStartResponse(decoded);
      if (!startResult.ok) {
        throw Exception('Invalid direct trip start response: ${res.body}');
      }
      final tripId = startResult.tripId;
      if (tripId.isEmpty) throw Exception('No trip_id returned');
      debugPrint(
        '[DIRECT_TRIP][START][OK] trip_id=$tripId '
        'booking_id=${startResult.bookingId ?? "-"} '
        'link_state=${startResult.bookingLinkState}',
      );
      if (requireLiveLocalRide) {
        if (!mounted || !_directRideActive) {
          return DirectTripWorkerStartResult(
            outcome: DirectTripWorkerStartOutcome.ok,
            tripId: tripId,
            bookingId: startResult.bookingId,
          );
        }
        setState(() {
          _directRideKey = directRideKey;
          _activeDirectTripId = tripId;
          _activeDirectBookingId = startResult.bookingId;
          _directTripStartWorkerOk = true;
          _directTripStopWorkerOk = false;
        });
        unawaited(_persistDirectTripSession(
          localLifecycle: kDirectTripLocalLifecycleActive,
          bookingFinalizeState: kDirectTripFinalizePending,
        ));
      }
      return DirectTripWorkerStartResult(
        outcome: DirectTripWorkerStartOutcome.ok,
        tripId: tripId,
        bookingId: startResult.bookingId,
      );
    } catch (e) {
      final classification = classifyDirectTripStartError(e);
      if (classification.isEntitlementFailure) {
        debugPrint(
          '[DIRECT_TRIP][START][ABORT] reason=entitlement_${classification.httpStatus ?? "denied"}',
        );
        if (requireLiveLocalRide && _directRideActive) {
          _abortDirectRideAfterAuthFailure(
            httpStatus: classification.httpStatus,
          );
        }
        return const DirectTripWorkerStartResult(
          outcome: DirectTripWorkerStartOutcome.entitlementDenied,
        );
      }
      if (classification.isAuthFailure) {
        debugPrint(
          '[DIRECT_TRIP][START][ABORT] reason=auth_${classification.httpStatus ?? "unknown"}',
        );
        if (requireLiveLocalRide && _directRideActive) {
          _abortDirectRideAfterAuthFailure(
            httpStatus: classification.httpStatus,
          );
        }
        return const DirectTripWorkerStartResult(
          outcome: DirectTripWorkerStartOutcome.authDenied,
        );
      }
      debugPrint('[DIRECT_TRIP][START][WARN] transport_or_other: $e');
      return const DirectTripWorkerStartResult(
        outcome: DirectTripWorkerStartOutcome.transportOrOther,
      );
    }
  }

  /// SECURITY-REMOVE-CLIENT-ADMIN-TOKEN-P0-1 (Field Failure Fix, Commit 2)
  ///
  /// Deterministic teardown after `/trip/start-direct` returns HTTP 401 or
  /// 403. Called from the catch of `_startDirectTripSessionOnWorker` only
  /// when the classifier confirmed an auth failure. Semantics:
  ///
  ///   - Meter stops.
  ///   - Tracking stops.
  ///   - Wakelock is released.
  ///   - Route, pins, destination and every direct-ride identity field are
  ///     cleared via `_clearActiveRouteAndNavigationState(clearActiveSelection:
  ///     true)` so the UI leaves the "in-flight ride" surface immediately.
  ///   - No compliance-ledger row is written: no ride actually happened.
  ///   - No local-only history record is appended: nothing to appear as a
  ///     completed ride.
  ///   - A localized session-required snackbar is shown so the operator sees
  ///     why the ride did not start.
  ///
  /// This must never be called for transport errors — those keep the ride
  /// running and let `_stopTrip` decide the truthful teardown.
  void _abortDirectRideAfterAuthFailure({required int? httpStatus}) {
    if (!mounted) {
      _directRideActive = false;
      _activeDirectTripId = null;
      _activeDirectBookingId = null;
      _directRideKey = null;
      _directTripStartWorkerOk = false;
      _directTripStopWorkerOk = false;
      return;
    }
    _stopMeterTicker();
    _stopTrackingInternal();
    _setNavigationWakelock(false);
    setState(() {
      _directRideActive = false;
      _activeDirectTripId = null;
      _activeDirectBookingId = null;
      _directRideKey = null;
      _directTripStartWorkerOk = false;
      _directTripStopWorkerOk = false;
      _directRideDestinationText = null;
      _directRideDestinationPoint = null;
      _directRideEstimatedFare = null;
      _directRideEstimateLoading = false;
      _directRideEstimateError = null;
      _directRideEstimateCurrency = kDefaultCurrency;
      _directRideEstimateSignature = null;
      _directRideLocationRetryCount = 0;
      _directRideLocationRetryDestination = null;
      _kmDriven = 0.0;
      _trackingStartedAt = null;
      _isWaiting = false;
      _waitStartedAt = null;
      _waitElapsed = Duration.zero;
      _cameraMode = _CameraMode.overview;
      _hasSwitchedToFollow = false;
      _followCar = false;
      _allowOverviewCamera = false;
    });
    unawaited(
      _deterministicStopTeardown(
        outcome: StopTeardownOutcome.authFailure,
        preservePendingDirectIdentity: false,
      ),
    );
    _showDriverSessionRequiredSnackbar(
      reason: httpStatus == 403 ? 'forbidden' : 'missing_token',
    );
  }

  /// SECURITY-REMOVE-CLIENT-ADMIN-TOKEN-P0-1 (Field Failure Fix, Commit 4)
  ///
  /// Deterministic STOP / navigation teardown. Called after every STOP
  /// outcome (backend-confirmed, local-only, finalize-pending, auth-failure)
  /// AND from the early-return guards inside `_stopTrip`.
  ///
  /// Live-navigation is NOT a separate route — it is `DriverHomePage`
  /// rendered in `_liveRideActive` mode. Exiting therefore means clearing
  /// operational ride state so `_liveRideActive` resolves `false` and the
  /// widget rebuilds into its normal driver-home / business-preview
  /// rendering. This helper never calls `Navigator.pop`, `popUntil`, or
  /// `maybePop` — the invariant is enforced by
  /// `direct_trip_stop_teardown_always_exits_nav_test.dart`.
  ///
  /// Contract:
  ///   - Idempotent: re-entry during a single teardown returns immediately
  ///     via `_stopTeardownInProgress`. Two independent user STOP taps still
  ///     each execute a full teardown.
  ///   - Unconditional live-ride timer/callback cancellation. Every timer
  ///     is cancelled explicitly (not delegated to `_stopTrackingInternal`,
  ///     which early-returns when `_posSub == null`).
  ///   - `_activeBooking` is always cleared, including finalize-pending.
  ///   - When `preservePendingDirectIdentity == true` (only when direct-ride
  ///     finalize is legitimately pending), the minimum reconcile identity
  ///     survives: `_activeDirectTripId`, `_activeDirectBookingId`,
  ///     `_directRideKey`, `_directStopFinalizePending`.
  ///   - Receipt / history / compliance ledger state is never touched.
  ///   - Drawer close uses `_scaffoldKey.currentState?.closeDrawer()`
  ///     (Scaffold-owned). Bookings-hub close flips `_bookingsHubVisible`.
  Future<void> _deterministicStopTeardown({
    required StopTeardownOutcome outcome,
    bool preservePendingDirectIdentity = false,
  }) async {
    if (_stopTeardownInProgress) {
      debugPrint(
        '[STOP_TEARDOWN][REENTRY] outcome=${outcome.name} '
        'generation=$_stopTeardownGeneration',
      );
      return;
    }
    _stopTeardownInProgress = true;
    _stopTeardownGeneration += 1;
    _publishBearerBusyState();
    final generation = _stopTeardownGeneration;
    try {
      final drawerOpen =
          _scaffoldKey.currentState?.isDrawerOpen ?? false;
      final context = DriverStopTeardownContext(
        outcome: outcome,
        isMounted: mounted,
        bookingsHubVisible: _bookingsHubVisible,
        drawerOpen: drawerOpen,
        preservePendingDirectIdentity: preservePendingDirectIdentity,
      );
      final plan = planDriverStopTeardown(context);

      // ------------------------------------------------------------------
      // Unconditional live-ride timer / callback cancellation.
      //
      // Every cancel below runs regardless of `_posSub` state so an already-
      // stopped tracking session (e.g. duplicate STOP tap, dispose-race)
      // still guarantees the timer wall is fully torn down. NEVER delegate
      // these to a helper that early-returns on `_posSub == null`.
      // ------------------------------------------------------------------
      _stopMeterTicker();
      _markerSelfHealTimer?.cancel();
      _markerSelfHealTimer = null;
      _navRouteRetryTimer?.cancel();
      _navRouteRetryTimer = null;
      _driver3dActivationConfirmRetryTimer?.cancel();
      _driver3dActivationConfirmRetryTimer = null;
      _directRideEstimateDebounce?.cancel();
      _directRideEstimateDebounce = null;
      _directRideEstimateLocationRetryTimer?.cancel();
      _directRideEstimateLocationRetryTimer = null;
      _resetPendingFollowCamera();
      _stopStreetlevelFollowPump();
      _resetNavR3MotionState();
      _resetNavValidationState(flushReport: true);
      _posSub?.cancel();
      _posSub = null;
      _activeGeolocatorSubscriptionCount = 0;
      _pendingMarkerUpdatePos = null;
      _consecutiveMarkerUpdateFailures = 0;
      _markerLifecycle.reset();
      _resetDriverVehicleModelMovementSync();
      _cameraInFlightLifecycle.invalidate(reason: 'stop_teardown');
      _navPresentationMode.reset();
      _tellersViewport.reset();
      _driverNavEngine.reset();
      _lastNavEngineOutput = null;
      _lastNavEngineRefreshKey = null;
      _resetNavRouteProgressState();
      _resetNavCameraPolicyState();
      _resetNavConfidenceState();
      _resetNavComplexityState();
      _resetNavMotionPredictionState();
      _resetNavInstructionPolicyState();
      _navStartupBootstrap.reset();
      _navParkingArrival.reset();
      _navParkingArrivalConfirmed = false;
      _lastNavArrivalEvent = null;
      _navSessionStartedAt = null;
      _navBootstrapPrevLat = null;
      _navBootstrapPrevLon = null;
      _lastKnownBearing = 0.0;
      _startPos = null;
      _lastFollowCameraAt = null;
      _gpsQualityWeak = false;
      _lastSmoothedCameraBearing = null;
      _stopBookingPolling(reason: 'stop_teardown_${outcome.name}');
      _setNavigationWakelock(false);
      if (_nativeFollow != null) {
        unawaited(_nativeFollow!.disable());
      }
      // Belt-and-braces: `_stopTrackingInternal` performs additional nav
      // engine / marker / camera resets on paths that expect it. Because we
      // just nulled `_posSub` above, its own early-return will short-circuit
      // — that is intentional; we already ran the equivalent explicit
      // resets. This call remains here to preserve any additional side
      // effects future changes may add to `_stopTrackingInternal` (idempotent).
      _stopTrackingInternal();

      // ------------------------------------------------------------------
      // Clear operational ride state.
      //
      // `_directRideActive = false` and `_activeTripId = null` are always
      // cleared so `_liveRideActive` resolves false and DriverHomePage
      // rebuilds into normal (non-live) rendering. `_activeBooking` is
      // always cleared, including finalize-pending. Only the minimum
      // reconcile identity survives when `preservePendingDirectIdentity`.
      // ------------------------------------------------------------------
      void clearOperationalRideState() {
        _directRideActive = false;
        _activeTripId = null;
        _activeBooking = null;
        _isStartingTrip = false;
        _cameraMode = _CameraMode.overview;
        _hasSwitchedToFollow = false;
        _followCar = false;
        _allowOverviewCamera = false;
        _isWaiting = false;
        _waitStartedAt = null;
        _waitElapsed = Duration.zero;
        _directRideDestinationText = null;
        _directRideDestinationPoint = null;
        _directRideEstimatedFare = null;
        _directRideEstimateLoading = false;
        _directRideEstimateError = null;
        _directRideEstimateCurrency = kDefaultCurrency;
        _directRideEstimateSignature = null;
        _directRideLocationRetryCount = 0;
        _directRideLocationRetryDestination = null;
        _kmDriven = 0.0;
        _trackingStartedAt = null;
        _lastPing = '—';
        _pingCount = 0;
        _routePhase = _RideRoutePhase.trip;
        _navStepsLoading = false;
        if (!plan.preservePendingDirectIdentity) {
          _activeDirectTripId = null;
          _activeDirectBookingId = null;
          _directRideKey = null;
          _directStopFinalizePending = false;
          _directTripStartWorkerOk = false;
          _directTripStopWorkerOk = false;
        }
      }
      if (mounted) {
        setState(clearOperationalRideState);
      } else {
        clearOperationalRideState();
      }

      // ------------------------------------------------------------------
      // Route / pin annotation cleanup.
      //
      // Runs regardless of whether `_routeCoords` / `_routeSteps` are
      // empty. `_hardClearAtRideBoundary` bumps session/render generations
      // so any in-flight style/route restore becomes a stale no-op.
      // `_clearRouteAndPinAnnotationsOnly` performs the Mapbox annotation
      // deletes. `_applyMapStyleForMode` refreshes the map style so no
      // leftover live-ride style survives the rebuild.
      // ------------------------------------------------------------------
      _hardClearAtRideBoundary(
        reason: 'stop_teardown_${outcome.name}',
        bumpSession: true,
      );
      await _clearRouteAndPinAnnotationsOnly();
      if (mounted) {
        await _applyMapStyleForMode();
      }

      // ------------------------------------------------------------------
      // Restart booking polling unconditionally.
      //
      // After the state clears above, `_liveRideActive` resolves false, so
      // the polling can run without racing an active tracking session.
      // ------------------------------------------------------------------
      if (!_liveRideActive) {
        _startBookingPolling(reason: 'stop_teardown_${outcome.name}');
      }

      // ------------------------------------------------------------------
      // Non-Navigator UI closes.
      //
      // Drawer is closed through Scaffold-owned `closeDrawer()` (never
      // Navigator.pop). Bookings-hub is a boolean overlay inside
      // DriverHomePage — flipping `_bookingsHubVisible = false` rebuilds
      // the tree without it.
      // ------------------------------------------------------------------
      if (plan.closeScaffoldDrawer) {
        _scaffoldKey.currentState?.closeDrawer();
      }
      if (plan.hideBookingsHubPanel) {
        if (mounted) {
          setState(() {
            _bookingsHubVisible = false;
          });
        } else {
          _bookingsHubVisible = false;
        }
      }

      debugPrint(
        '[STOP_TEARDOWN][EXIT] outcome=${outcome.name} '
        'generation=$generation '
        'preserve_pending=${plan.preservePendingDirectIdentity} '
        'hub_hidden=${plan.hideBookingsHubPanel} '
        'drawer_closed=${plan.closeScaffoldDrawer} '
        'live_ride_active_after=$_liveRideActive',
      );
    } finally {
      _stopTeardownInProgress = false;
      _publishBearerBusyState();
    }
  }

  Future<DirectRideStopOutcome> _stopDirectTripSessionOnWorker({
    required String tripId,
    required double kmTotal,
    required int waitSecondsTotal,
    String? clientStoppedAtIso,
    String? bookingIdOverride,
    String? directRideKeyOverride,
    String? startedAtIsoOverride,
    double? frozenTotalEur,
  }) async {
    final resolvedBookingId =
        (bookingIdOverride ?? _activeDirectBookingId ?? '').trim();
    final stoppedAtIso = (clientStoppedAtIso ?? '').trim().isNotEmpty
        ? clientStoppedAtIso!.trim()
        : DateTime.now().toUtc().toIso8601String();
    final frozenFare = frozenTotalEur;
    Future<void> persistStopped({
      required String trackingStopState,
      required String bookingFinalizeState,
    }) {
      return _persistDirectTripSession(
        localLifecycle: kDirectTripLocalLifecycleStopped,
        bookingFinalizeState: bookingFinalizeState,
        trackingStopState: trackingStopState,
        stoppedAtIso: stoppedAtIso,
        frozenKmTotal: kmTotal,
        frozenWaitSecondsTotal: waitSecondsTotal,
        frozenTotalEur: frozenFare,
        tripIdOverride: tripId,
        bookingIdOverride: resolvedBookingId,
        directRideKeyOverride: directRideKeyOverride,
        startedAtIsoOverride: startedAtIsoOverride,
      );
    }

    try {
      final strictScope = _strictBookingScopeForMutation(
        action: 'stop_direct_trip',
        showUx: false,
      );
      if (strictScope == null) {
        await persistStopped(
          trackingStopState: kDirectTripTrackingStopPending,
          bookingFinalizeState: kDirectTripFinalizePending,
        );
        return DirectRideStopOutcome.unknown;
      }
      final payload = withDirectRideBookingStopFields(<String, dynamic>{
        'trip_id': tripId,
        ...strictScope,
        'km_total': kmTotal,
        'wait_seconds_total': waitSecondsTotal,
        'client_stopped_at': stoppedAtIso,
        ..._driverMutationActorFields(actorVehicleId: _directRideVehicleId()),
      }, bookingId: resolvedBookingId.isEmpty ? null : resolvedBookingId);
      final res = await http
          .post(
            _uriWithScope(kWorkerBaseUrl, kStopDirectTripPath, strictScope),
            headers: _driverBearerHeaders(),
            body: jsonEncode(payload),
          )
          .timeout(const Duration(seconds: 6));
      if (res.statusCode != 200) {
        throw Exception('HTTP ${res.statusCode}: ${res.body}');
      }
      final decoded = jsonDecode(res.body);
      if (decoded is! Map || decoded['ok'] != true) {
        throw Exception('Invalid direct trip stop response: ${res.body}');
      }
      _directTripStopWorkerOk = true;
      // STREET-RIDE-DURABLE-COMPLETION-2 + DIRECT-RIDE-FINALIZE-ACK-GATE-1:
      // preserve the full finalize acknowledgement. Cleared only when the
      // booking is authoritatively finalized; otherwise keep stopped/pending
      // recovery evidence (never invent a new key or booking).
      final stopResult = parseDirectRideStopResponse(decoded);
      final outcome = mapDirectRideStopOutcome(
        parsed: stopResult,
        transportSucceeded: true,
      );
      final ack = isDirectRideFinalizeAcknowledged(
        outcome: outcome,
        expectedBookingId: resolvedBookingId,
      );
      if (ack) {
        await _clearDirectTripSession();
      } else {
        await persistStopped(
          trackingStopState: kDirectTripTrackingStopCompleted,
          bookingFinalizeState: kDirectTripFinalizePending,
        );
      }
      // OFFLINE-STOP-CHIRON-ARRIVAL-DURABILITY-P0: mirror planned-stop client
      // drain. Booking finalize ack alone must not strand a PENDING/absent
      // Chiron ride_stop outbox — reconcile is idempotent and drains ARRIVAL.
      if (outcome.trackingTripStopped &&
          resolvedBookingId.isNotEmpty &&
          !outcome.complianceEmitApplied) {
        unawaited(
          _reconcileDirectBookingOnWorker(
            tripId: tripId,
            expectedBookingId: resolvedBookingId,
          ),
        );
      }
      return outcome;
    } catch (e) {
      _directTripStopWorkerOk = false;
      // Transport / unknown: do not assume the tracking trip is still active,
      // and never treat this as booking completion. Persist recovery identity
      // WITH frozen STOP totals so reconnect can replay `/trip/stop`.
      await persistStopped(
        trackingStopState: kDirectTripTrackingStopPending,
        bookingFinalizeState: kDirectTripFinalizePending,
      );
      debugPrint('[DIRECT_TRIP][STOP][WARN] outcome=unknown reason=$e');
      return DirectRideStopOutcome.unknown;
    }
  }

  // STREET-RIDE-DURABLE-COMPLETION-2 + OFFLINE-STOP-RIDE-DURABILITY-P0:
  // durable direct-trip session persistence + startup/reconnect recovery.
  Future<void> _persistDirectTripSession({
    required String localLifecycle,
    required String bookingFinalizeState,
    String? trackingStopState,
    String? stoppedAtIso,
    double? frozenKmTotal,
    int? frozenWaitSecondsTotal,
    double? frozenTotalEur,
    String? tripIdOverride,
    String? bookingIdOverride,
    String? directRideKeyOverride,
    String? startedAtIsoOverride,
  }) async {
    try {
      final scope = _complianceLedgerScopeForStop();
      if (scope == null) return;
      final key = (directRideKeyOverride ?? _directRideKey ?? '').trim();
      final tripId = (tripIdOverride ?? _activeDirectTripId ?? '').trim();
      if (key.isEmpty && tripId.isEmpty) return;
      final startedIso = (startedAtIsoOverride ?? '').trim().isNotEmpty
          ? startedAtIsoOverride!.trim()
          : (_trackingStartedAt ?? DateTime.now()).toUtc().toIso8601String();
      final session = DirectTripSession(
        directRideKey: key,
        tripId: tripId,
        bookingId: (bookingIdOverride ?? _activeDirectBookingId ?? '').trim(),
        startedAtIso: startedIso,
        localLifecycle: localLifecycle,
        bookingFinalizeState: bookingFinalizeState,
        tenantId: scope.tenantId,
        companyId: scope.companyId,
        driverId: kDriverId,
        stoppedAtIso: stoppedAtIso,
        frozenKmTotal: frozenKmTotal,
        frozenWaitSecondsTotal: frozenWaitSecondsTotal,
        frozenTotalEur: frozenTotalEur,
        trackingStopState: trackingStopState,
      );
      await _DirectTripSessionStore.save(
        session,
        tenantId: scope.tenantId,
        companyId: scope.companyId,
        driverId: kDriverId,
      );
    } catch (_) {
      // Best-effort only.
    }
  }

  Future<void> _clearDirectTripSession() async {
    try {
      final scope = _complianceLedgerScopeForStop();
      if (scope == null) return;
      await _DirectTripSessionStore.clear(
        tenantId: scope.tenantId,
        companyId: scope.companyId,
      );
      unawaited(_clearActiveRideDurableSnapshot(reason: 'direct_trip_cleared'));
    } catch (_) {
      // Best-effort only.
    }
  }

  // ACTIVE-RIDE-DURABLE-RESTORE-P0-7: disk snapshot for planned + street rides
  // so Google Maps / PiP process death can restore the cockpit after PIN.
  ActiveRideDurableSnapshot? _buildActiveRideDurableSnapshot({
    ExternalNavigationSession? externalSession,
  }) {
    if (!_liveRideActive) return null;
    final bookingId = (_activeBooking?.bookingId ??
            _activeDirectBookingId ??
            _directRideKey ??
            '')
        .trim();
    if (bookingId.isEmpty) return null;
    final street = _directRideActive || _activeBookingIsStreetDirect;
    final last = _lastPos;
    return ActiveRideDurableSnapshot(
      rideType: street ? 'street' : 'planned',
      bookingId: bookingId,
      parentBookingId: street
          ? (_directRideKey ?? bookingId)
          : (_activeBooking?.details['parent_booking_id']?.toString() ??
              _activeBooking?.details['parentBookingId']?.toString()),
      activeLegId: (_activeBooking?.legId ?? '').trim().isEmpty
          ? null
          : _activeBooking!.legId,
      tripId: street
          ? (_activeDirectTripId ?? '').trim()
          : (_activeTripId ?? '').trim(),
      lifecyclePhase: 'active',
      startedAt: (_trackingStartedAt ?? DateTime.now()).toUtc(),
      updatedAt: DateTime.now().toUtc(),
      lastLat: last?.latitude,
      lastLon: last?.longitude,
      trackedDistanceKm: _kmDriven.isFinite ? _kmDriven : null,
      waitingSeconds: _effectiveWaitElapsed.inSeconds,
      currentOrFixedFare: street
          ? (_liveMeterTotalEur.isFinite ? _liveMeterTotalEur : null)
          : _fixedBookingPriceEur,
      paymentState: null,
      finalizePending: false,
      externalNavSession: externalSession ?? _externalNavigationSession,
    );
  }

  Future<void> _persistActiveRideDurableSnapshot({
    String reason = 'tick',
    ExternalNavigationSession? externalSession,
  }) async {
    try {
      final scope = _complianceLedgerScopeForStop();
      if (scope == null) return;
      final snap = _buildActiveRideDurableSnapshot(
        externalSession: externalSession,
      );
      if (snap == null) return;
      await ActiveRideDurableSnapshotStore.save(
        tenantId: scope.tenantId,
        companyId: scope.companyId,
        snapshot: snap,
      );
      debugPrint(
        '[EXTERNAL_NAV] event=active_ride_durable_persisted '
        'reason=$reason rideType=${snap.rideType} booking=${snap.bookingId} '
        'trip=${snap.tripId ?? ""} external_nav='
        '${snap.externalNavSession != null}',
      );
    } catch (_) {
      // Best-effort only.
    }
  }

  Future<void> _clearActiveRideDurableSnapshot({
    String reason = 'clear',
  }) async {
    try {
      final scope = _complianceLedgerScopeForStop();
      if (scope == null) return;
      await ActiveRideDurableSnapshotStore.clear(
        tenantId: scope.tenantId,
        companyId: scope.companyId,
      );
      debugPrint(
        '[EXTERNAL_NAV] event=active_ride_durable_cleared reason=$reason',
      );
    } catch (_) {}
  }

  /// Restore planned/street cockpit from disk after process death during
  /// external navigation. Idempotent; never invents fare/distance.
  Future<void> _recoverActiveRideDurableSnapshot() async {
    try {
      final scope = _complianceLedgerScopeForStop();
      if (scope == null) return;
      if (_liveRideActive) {
        debugPrint(
          '[EXTERNAL_NAV] event=active_ride_restore_skipped '
          'reason=already_live',
        );
        return;
      }
      final snap = await ActiveRideDurableSnapshotStore.load(
        tenantId: scope.tenantId,
        companyId: scope.companyId,
      );
      if (snap == null || snap.bookingId.trim().isEmpty) return;
      if (snap.lifecyclePhase != 'active' && !snap.finalizePending) {
        await ActiveRideDurableSnapshotStore.clear(
          tenantId: scope.tenantId,
          companyId: scope.companyId,
        );
        return;
      }

      debugPrint(
        '[EXTERNAL_NAV] event=active_ride_restore_begin '
        'rideType=${snap.rideType} booking=${snap.bookingId} '
        'trip=${snap.tripId ?? ""} process_recreated=true '
        'session_present=true',
      );

      await _refreshBookings(
        force: true,
        trigger: 'active_ride_durable_restore',
      );
      if (!mounted || _liveRideActive) return;

      BookingItem? booking;
      for (final b in _bookings) {
        if (b.bookingId.trim() == snap.bookingId.trim()) {
          booking = b;
          break;
        }
      }
      booking ??= BookingItem(
        bookingId: snap.bookingId,
        sessionId: snap.isPlanned ? snap.tripId : null,
        status: 'IN_PROGRESS',
        price: snap.currentOrFixedFare,
        currency: 'EUR',
        details: <String, dynamic>{
          if ((snap.parentBookingId ?? '').trim().isNotEmpty)
            'parent_booking_id': snap.parentBookingId,
          if ((snap.activeLegId ?? '').trim().isNotEmpty)
            'leg_id': snap.activeLegId,
          if (snap.isStreet) 'ride_kind': 'street_direct',
          'restored_from_durable_snapshot': true,
        },
      );

      final startedAt = snap.startedAt.toLocal();
      final waitSec = snap.waitingSeconds ?? 0;
      final km = snap.trackedDistanceKm;
      final ext = snap.externalNavSession?.copyWith(pipActive: false);

      if (mounted) {
        setState(() {
          _activeBooking = booking;
          if (snap.isStreet) {
            _directRideActive = true;
            _activeTripId = null;
            _activeDirectTripId =
                (snap.tripId ?? '').trim().isEmpty ? null : snap.tripId;
            _activeDirectBookingId = snap.bookingId;
            _directRideKey =
                (snap.parentBookingId ?? snap.bookingId).trim();
            _directTripStartWorkerOk = true;
          } else {
            _directRideActive = false;
            _activeTripId = (snap.tripId ?? '').trim().isEmpty
                ? snap.bookingId
                : snap.tripId;
            _activeDirectTripId = null;
            _activeDirectBookingId = null;
            _directRideKey = null;
          }
          _routePhase = _RideRoutePhase.trip;
          _kmDriven = (km != null && km.isFinite && km >= 0) ? km : 0.0;
          _trackingStartedAt = startedAt;
          _waitElapsed = Duration(seconds: waitSec < 0 ? 0 : waitSec);
          _isWaiting = false;
          _waitStartedAt = null;
          _cameraMode = _CameraMode.follow;
          _hasSwitchedToFollow = true;
          _followCar = true;
          _externalNavigationSession = ext;
          _navigationGuidanceActive =
              !(ext?.nativeGuidanceSuppressed ?? false);
        });
      }

      _publishBearerBusyState();
      _setNavigationWakelock(true);
      await _ensureLocationPermission();
      if (_posSub == null) _startTrackingInternal();
      _startMeterTicker();
      if (snap.isPlanned) {
        await _hydrateActiveBookingDetails(snap.bookingId);
        await _hydrateActiveBookingPrice(snap.bookingId);
      }
      unawaited(_persistActiveRideDurableSnapshot(reason: 'restore_ack'));
      debugPrint(
        '[EXTERNAL_NAV] event=active_ride_restored '
        'rideType=${snap.rideType} booking=${snap.bookingId} '
        'km=${snap.trackedDistanceKm} wait_s=$waitSec '
        'fare=${snap.currentOrFixedFare} '
        'external_nav=${ext != null} lifecycle_resume_completed=true',
      );
    } catch (e) {
      debugPrint(
        '[EXTERNAL_NAV] event=active_ride_restore_failed err=${e.runtimeType}',
      );
    }
  }

  /// Idempotently retries a street/direct booking finalization from the
  /// persisted trip. Returns a structured [DirectRideReconcileOutcome]; local
  /// COMPLETED may proceed only when [DirectRideReconcileOutcome.isAcknowledged]
  /// is true (identity match + completed finalize state).
  Future<DirectRideReconcileOutcome> _reconcileDirectBookingOnWorker({
    required String tripId,
    required String expectedBookingId,
  }) async {
    final reqTrip = tripId.trim();
    final expBooking = expectedBookingId.trim();
    if (reqTrip.isEmpty || expBooking.isEmpty) {
      return DirectRideReconcileOutcome.unknown(
        requestedTripId: reqTrip,
        expectedBookingId: expBooking,
      );
    }
    try {
      final strictScope = _strictBookingScopeForMutation(
        action: 'reconcile_direct_booking',
        showUx: false,
      );
      if (strictScope == null) {
        return DirectRideReconcileOutcome.unknown(
          requestedTripId: reqTrip,
          expectedBookingId: expBooking,
        );
      }
      final res = await http
          .post(
            _uriWithScope(kWorkerBaseUrl, kReconcileDirectBookingPath, strictScope),
            headers: _driverBearerHeaders(),
            body: jsonEncode(<String, dynamic>{
              'trip_id': reqTrip,
              ...strictScope,
              ..._driverMutationActorFields(
                actorVehicleId: _directRideVehicleId(),
              ),
            }),
          )
          .timeout(const Duration(seconds: 6));
      Object? decoded;
      try {
        decoded = jsonDecode(res.body);
      } catch (_) {
        return DirectRideReconcileOutcome.unknown(
          requestedTripId: reqTrip,
          expectedBookingId: expBooking,
          httpStatus: res.statusCode,
        );
      }
      return mapDirectRideReconcileOutcome(
        decoded: decoded,
        httpStatus: res.statusCode,
        requestedTripId: reqTrip,
        expectedBookingId: expBooking,
        transportSucceeded: true,
      );
    } catch (_) {
      return DirectRideReconcileOutcome.unknown(
        requestedTripId: reqTrip,
        expectedBookingId: expBooking,
      );
    }
  }

  /// Startup / reconnect recovery: resolve any persisted direct-trip session.
  /// Non-blocking (invoked unawaited). Offline STOP freezes totals and may
  /// need a `/trip/stop` replay before reconcile can finalize the booking.
  Future<void> _recoverPendingDirectTripSession() async {
    try {
      final scope = _complianceLedgerScopeForStop();
      if (scope == null) return;
      // Do not interfere with a ride that is live right now.
      if (_directRideActive) return;
      final session = await _DirectTripSessionStore.load(
        tenantId: scope.tenantId,
        companyId: scope.companyId,
        driverId: kDriverId,
      );
      if (session == null) return;
      final action = directTripRecoveryAction(session);
      switch (action) {
        case DirectTripRecoveryAction.none:
          return;
        case DirectTripRecoveryAction.retryStop:
          await _attemptDirectStopReplayWithBackoff(session, scope);
          return;
        case DirectTripRecoveryAction.reconcilePending:
          await _attemptDirectReconcileWithBackoff(session, scope);
          return;
        case DirectTripRecoveryAction.resumeActive:
        case DirectTripRecoveryAction.abandon:
          // DIRECT-RIDE-STOP-RECOVERY-RACE-1 Commit 2: never blindly resume or
          // abandon an active session that still carries durable ids. Probe
          // server truth via idempotent reconcile (never `/trip/stop`) unless
          // the session already carries a frozen offline-STOP outbox.
          if (session.needsTrackingStopReplay) {
            await _attemptDirectStopReplayWithBackoff(session, scope);
            return;
          }
          if (directTripSessionHasProbeIdentity(session)) {
            await _probeAndRecoverActiveDirectSession(session, scope);
            return;
          }
          // Structurally unusable (missing trip/booking identity): only then
          // honor abandon. resumeActive without ids keeps the file untouched.
          if (action == DirectTripRecoveryAction.abandon) {
            await _DirectTripSessionStore.clear(
              tenantId: scope.tenantId,
              companyId: scope.companyId,
            );
            debugPrint(
              '[DIRECT_TRIP_RECOVERY_PROBE] lifecycle=${session.localLifecycle} '
              'category=unusable identity_match=false server_non_terminal=false '
              'booking_finalized=false action=clear attempt=0',
            );
          }
          return;
      }
    } catch (_) {
      // Best-effort recovery; remain pending + retryable on next launch.
    }
  }

  /// OFFLINE-STOP-RIDE-DURABILITY-P0: replay `/trip/stop` with frozen client
  /// totals, then reconcile booking finalize. Idempotent on the worker.
  Future<void> _attemptDirectStopReplayWithBackoff(
    DirectTripSession session,
    ({String tenantId, String companyId}) scope,
  ) async {
    if (!session.needsTrackingStopReplay && !session.hasFrozenStopTotals) {
      await _attemptDirectReconcileWithBackoff(session, scope);
      return;
    }
    const maxAttempts = 4;
    for (var attempt = 0; attempt < maxAttempts; attempt++) {
      final outcome = await _stopDirectTripSessionOnWorker(
        tripId: session.tripId,
        kmTotal: session.frozenKmTotal ?? 0,
        waitSecondsTotal: session.frozenWaitSecondsTotal ?? 0,
        clientStoppedAtIso: session.stoppedAtIso,
        bookingIdOverride: session.bookingId,
        directRideKeyOverride: session.directRideKey,
        startedAtIsoOverride: session.startedAtIso,
        frozenTotalEur: session.frozenTotalEur,
      );
      if (isDirectRideFinalizeAcknowledged(
        outcome: outcome,
        expectedBookingId: session.bookingId,
      )) {
        await _DirectTripSessionStore.clear(
          tenantId: scope.tenantId,
          companyId: scope.companyId,
        );
        _clearStaleInMemoryDirectIdentityIfMatching(session);
        debugPrint('[DIRECT_TRIP][RECOVERY] stop_replay=finalize_ok');
        // Drain Chiron ARRIVAL even when booking finalize already ack'd.
        if (!outcome.complianceEmitApplied &&
            session.bookingId.trim().isNotEmpty) {
          unawaited(
            _reconcileDirectBookingOnWorker(
              tripId: session.tripId,
              expectedBookingId: session.bookingId,
            ),
          );
        }
        unawaited(
          _refreshBookings(
            force: true,
            trigger: 'street_recovery_stop_replay_ok',
          ),
        );
        return;
      }
      if (outcome.trackingTripStopped) {
        // Stop landed; booking finalize still pending — drain via reconcile.
        final advanced = session.copyWith(
          trackingStopState: kDirectTripTrackingStopCompleted,
          bookingFinalizeState: kDirectTripFinalizePending,
        );
        await _DirectTripSessionStore.save(
          advanced,
          tenantId: scope.tenantId,
          companyId: scope.companyId,
          driverId: kDriverId,
        );
        await _attemptDirectReconcileWithBackoff(advanced, scope);
        return;
      }
      if (attempt < maxAttempts - 1) {
        await Future<void>.delayed(directReconcileBackoff(attempt));
      }
    }
    debugPrint(
      '[DIRECT_TRIP][RECOVERY] state=stop_replay_pending retryable=true',
    );
  }

  /// Server-truth probe for a persisted active (or stale-active) session.
  /// Never calls `/trip/stop`. Never restores meter/navigation.
  Future<void> _probeAndRecoverActiveDirectSession(
    DirectTripSession session,
    ({String tenantId, String companyId}) scope,
  ) async {
    final outcome = await _reconcileDirectBookingOnWorker(
      tripId: session.tripId,
      expectedBookingId: session.bookingId,
    );
    final probeAction = classifyDirectTripRecoveryProbe(
      session: session,
      outcome: outcome,
    );
    final identityMatch = (outcome.responseTripId ?? '').trim() ==
            session.tripId.trim() &&
        (outcome.responseBookingId ?? '').trim() == session.bookingId.trim();
    debugPrint(
      '[DIRECT_TRIP_RECOVERY_PROBE] lifecycle=${session.localLifecycle} '
      'category=${probeAction.name} identity_match=$identityMatch '
      'server_non_terminal=${outcome.isNonTerminal} '
      'booking_finalized=${outcome.bookingFinalized} '
      'action=${_directRecoveryProbeActionLabel(probeAction)} attempt=0',
    );

    switch (probeAction) {
      case DirectTripRecoveryProbeAction.clearAcknowledged:
        await _DirectTripSessionStore.clear(
          tenantId: scope.tenantId,
          companyId: scope.companyId,
        );
        _clearStaleInMemoryDirectIdentityIfMatching(session);
        unawaited(
          _refreshBookings(
            force: true,
            trigger: 'street_recovery_finalize_ok',
          ),
        );
        return;
      case DirectTripRecoveryProbeAction.retainServerActive:
        // ACTIVE-RIDE-DURABLE-RESTORE-P0-7: server still non-terminal — restore
        // cockpit from durable snapshot (meter/nav). Never `/trip/stop`.
        unawaited(_recoverActiveRideDurableSnapshot());
        return;
      case DirectTripRecoveryProbeAction.retainTransportUnknown:
      case DirectTripRecoveryProbeAction.retainIdentityMismatch:
        // Retain evidence; retry on next startup. Never abandon on unknown.
        return;
      case DirectTripRecoveryProbeAction.rewriteStoppedPending:
        final rewritten = session.copyWith(
          localLifecycle: kDirectTripLocalLifecycleStopped,
          bookingFinalizeState: kDirectTripFinalizePending,
        );
        // Persist active → stopped/pending atomically before reconcile loop.
        await _DirectTripSessionStore.save(
          rewritten,
          tenantId: scope.tenantId,
          companyId: scope.companyId,
          driverId: kDriverId,
        );
        await _attemptDirectReconcileWithBackoff(rewritten, scope);
        return;
    }
  }

  String _directRecoveryProbeActionLabel(DirectTripRecoveryProbeAction a) {
    switch (a) {
      case DirectTripRecoveryProbeAction.clearAcknowledged:
        return 'clear';
      case DirectTripRecoveryProbeAction.retainServerActive:
        return 'retain';
      case DirectTripRecoveryProbeAction.rewriteStoppedPending:
        return 'rewrite_pending';
      case DirectTripRecoveryProbeAction.retainTransportUnknown:
        return 'retry';
      case DirectTripRecoveryProbeAction.retainIdentityMismatch:
        return 'retain';
    }
  }

  void _clearStaleInMemoryDirectIdentityIfMatching(DirectTripSession session) {
    final trip = session.tripId.trim();
    final booking = session.bookingId.trim();
    final matchesTrip =
        trip.isNotEmpty && (_activeDirectTripId ?? '').trim() == trip;
    final matchesBooking =
        booking.isNotEmpty && (_activeDirectBookingId ?? '').trim() == booking;
    if (!matchesTrip && !matchesBooking) return;
    if (mounted) {
      setState(() {
        if (matchesTrip) _activeDirectTripId = null;
        if (matchesBooking) _activeDirectBookingId = null;
        if ((_directRideKey ?? '').trim() == session.directRideKey.trim()) {
          _directRideKey = null;
        }
        _directStopFinalizePending = false;
        _directRideActive = false;
      });
    } else {
      if (matchesTrip) _activeDirectTripId = null;
      if (matchesBooking) _activeDirectBookingId = null;
      if ((_directRideKey ?? '').trim() == session.directRideKey.trim()) {
        _directRideKey = null;
      }
      _directStopFinalizePending = false;
      _directRideActive = false;
    }
  }

  Future<void> _attemptDirectReconcileWithBackoff(
    DirectTripSession session,
    ({String tenantId, String companyId}) scope,
  ) async {
    const maxAttempts = 4;
    for (var attempt = 0; attempt < maxAttempts; attempt++) {
      final outcome = await _reconcileDirectBookingOnWorker(
        tripId: session.tripId,
        expectedBookingId: session.bookingId,
      );
      if (isDirectRideReconcileAcknowledged(outcome)) {
        await _DirectTripSessionStore.clear(
          tenantId: scope.tenantId,
          companyId: scope.companyId,
        );
        _clearStaleInMemoryDirectIdentityIfMatching(session);
        debugPrint('[DIRECT_TRIP][RECOVERY] reconciled=completed');
        unawaited(
          _refreshBookings(
            force: true,
            trigger: 'street_recovery_reconcile_ok',
          ),
        );
        return;
      }
      if (attempt < maxAttempts - 1) {
        await Future<void>.delayed(directReconcileBackoff(attempt));
      }
    }
    debugPrint('[DIRECT_TRIP][RECOVERY] state=pending retryable=true');
  }

  Future<bool> _recordPlannedTripStopOnWorker({
    required BookingItem booking,
    required double kmTotal,
    required int waitSecondsTotal,
    required DateTime? startedAt,
    required DateTime stoppedAt,
  }) async {
    // DIRECT-RIDE-PLANNED-STOP-GUARD-1 (defense in depth): mirror the
    // operational-leg planned-stop street guard. A street/direct booking's
    // physical ride is stored authoritatively via `/trip/stop` +
    // `finalize-direct`; a second `/trip/record-planned-stop` for the same
    // record would produce the €0.00 Outbound duplicate identity fork we've
    // already fixed for operational legs. This defensive guard ensures no
    // future caller can bypass the `_stopTrip` decision helper.
    if (isStreetDirectBooking(<String, dynamic>{
      ...booking.details,
      if (booking.bookingId.trim().isNotEmpty)
        'booking_id': booking.bookingId,
    })) {
      debugPrint(
        '[PLANNED_STOP_GUARD] action=skip source=streetRide '
        'reason=street_direct_uses_finalize_direct',
      );
      return false;
    }
    PlannedStopIntent? durableIntent;
    try {
      final strictScope = _strictBookingScopeForMutation(
        action: 'record_planned_trip_stop',
        showUx: false,
      );
      if (strictScope == null) return false;
      var bookingDetails = _plannedBookingDetailsPayload(booking);
      final authoritativeFields = await _fetchPaymentFieldsForHistory(
        booking.bookingId,
      );
      if (authoritativeFields.isNotEmpty) {
        bookingDetails = _mergeBusinessReferencesIntoSource(
          source: bookingDetails,
          authoritative: authoritativeFields,
          canonicalBookingId: booking.bookingId,
          tripId: null,
          sourceTag: 'planned_trip_stop_authoritative_fields',
        );
        bookingDetails.addAll(authoritativeFields);
        final existingBooking = bookingDetails['booking'];
        if (existingBooking is Map) {
          final mergedBooking = _mergeBusinessReferencesIntoSource(
            source: Map<String, dynamic>.from(existingBooking),
            authoritative: authoritativeFields,
            canonicalBookingId: booking.bookingId,
            tripId: null,
            sourceTag: 'planned_trip_stop_booking_nested',
          );
          if (authoritativeFields['payment_status'] != null) {
            mergedBooking['payment_status'] =
                authoritativeFields['payment_status'];
            mergedBooking['paymentStatus'] =
                authoritativeFields['payment_status'];
          }
          if (authoritativeFields['paid_at'] != null) {
            mergedBooking['paid_at'] = authoritativeFields['paid_at'];
            mergedBooking['paidAt'] = authoritativeFields['paid_at'];
          }
          if (authoritativeFields['payment_provider'] != null) {
            mergedBooking['payment_provider'] =
                authoritativeFields['payment_provider'];
            mergedBooking['paymentProvider'] =
                authoritativeFields['payment_provider'];
          }
          if (authoritativeFields['payment_id'] != null) {
            mergedBooking['payment_id'] = authoritativeFields['payment_id'];
            mergedBooking['paymentId'] = authoritativeFields['payment_id'];
          }
          bookingDetails['booking'] = mergedBooking;
        }
      }
      final legAmount = _driverDisplayPriceForBooking(booking);
      final price =
          legAmount ??
          (booking.isOperationalLeg
              ? null
              : (booking.price ??
                    BookingItem._toNumOrNull(
                      bookingDetails['booking_total_eur'],
                    )));
      final payload = <String, dynamic>{
        'booking_id': booking.bookingId,
        ...strictScope,
        'driver_id': kDriverId,
        'vehicle_id': _directRideVehicleId(),
        'origin': <String, dynamic>{
          'label': (booking.from ?? _receiptText('currentLocation')).toString(),
        },
        'destination': <String, dynamic>{
          'label': (booking.to ?? booking.from ?? booking.shortId).toString(),
          // The driver is physically at the drop-off when stopping a planned
          // ride. Booking records for this flow carry no drop-off coordinates,
          // so the live device GPS is the only trusted arrival coordinate
          // (Chiron aankomstpunt). Never send 0/0; omit when GPS is unavailable.
          if (_lastPos != null) 'lat': _lastPos!.latitude,
          if (_lastPos != null) 'lon': _lastPos!.longitude,
        },
        'booking_details': bookingDetails,
        if (startedAt != null)
          'started_at': startedAt.toUtc().toIso8601String(),
        'stopped_at': stoppedAt.toUtc().toIso8601String(),
        'km_total': kmTotal,
        'wait_seconds_total': waitSecondsTotal,
        if (price != null) 'total_eur': price.toDouble(),
        'currency': booking.currency ?? kDefaultCurrency,
        if (bookingDetails['payment_status'] != null)
          'payment_status': bookingDetails['payment_status'],
        if (bookingDetails['paymentStatus'] != null)
          'paymentStatus': bookingDetails['paymentStatus'],
        if (bookingDetails['paid_at'] != null)
          'paid_at': bookingDetails['paid_at'],
        if (bookingDetails['paidAt'] != null)
          'paidAt': bookingDetails['paidAt'],
        if (bookingDetails['payment_provider'] != null)
          'payment_provider': bookingDetails['payment_provider'],
        if (bookingDetails['paymentProvider'] != null)
          'paymentProvider': bookingDetails['paymentProvider'],
        if (bookingDetails['payment_id'] != null)
          'payment_id': bookingDetails['payment_id'],
        if (bookingDetails['paymentId'] != null)
          'paymentId': bookingDetails['paymentId'],
        if (bookingDetails['receipt_reference'] != null)
          'receipt_reference': bookingDetails['receipt_reference'],
        if (bookingDetails['planning_reference'] != null)
          'planning_reference': bookingDetails['planning_reference'],
        if (bookingDetails['public_booking_reference'] != null)
          'public_booking_reference':
              bookingDetails['public_booking_reference'],
        if (bookingDetails['booking_reference'] != null)
          'booking_reference': bookingDetails['booking_reference'],
        if (bookingDetails['public_reference'] != null)
          'public_reference': bookingDetails['public_reference'],
        ..._driverMutationActorFields(actorVehicleId: _directRideVehicleId()),
      };
      // PLANNED-STOP-HISTORY-DURABILITY-P0-8: the measured STOP payload becomes
      // durable BEFORE the booking can be projected COMPLETED. This request is
      // the only writer of the trip / trips_index / driver-history / Chiron
      // chain, and no server route can recreate a trip row that was never
      // written, so a request lost to poor network must leave behind a
      // replayable intent rather than a completed ride with no history.
      durableIntent = _buildPlannedStopIntent(booking: booking, payload: payload);
      _plannedStopIntentDurable =
          durableIntent != null &&
          await _PlannedStopIntentStore.save(durableIntent);

      final res = await http
          .post(
            _uriWithScope(
              kWorkerBaseUrl,
              kRecordPlannedTripStopPath,
              strictScope,
            ),
            headers: _driverBearerHeaders(),
            body: jsonEncode(payload),
          )
          .timeout(const Duration(seconds: 6));
      if (res.statusCode != 200) {
        throw Exception('HTTP ${res.statusCode}: ${res.body}');
      }
      // Chain confirmed materialized, so the intent has served its purpose.
      await _clearPlannedStopIntent(durableIntent);
      debugPrint('[PLANNED_TRIP][HISTORY][OK] booking=${booking.bookingId}');

      // RELEASE-P0-DURABLE-CHIRON-SYNC-FOR-PLANNED-RIDES-2026-07-31: inspect
      // the durable Chiron outbox state returned by the tracking worker. When
      // the fire-and-forget ride_stop emit stayed PENDING (or absent for
      // legacy responses), trigger a bounded in-session reconcile with the
      // same event_id — never blocks the stop UX, never regresses APPLIED,
      // never invents ids. Server-side pending stays durable regardless of
      // this call's outcome; startup + future retries will pick it up.
      Object? decoded;
      try {
        decoded = jsonDecode(res.body);
      } catch (_) {
        decoded = null;
      }
      final tripIdFromResp = decoded is Map
          ? (decoded['trip_id'] ?? decoded['tripId'] ?? '').toString().trim()
          : '';
      final emitStateRaw = decoded is Map
          ? (decoded['compliance_emit_state'] ??
                  decoded['complianceEmitState'] ??
                  '')
              .toString()
              .trim()
              .toLowerCase()
          : '';
      if (tripIdFromResp.isNotEmpty && emitStateRaw != 'applied') {
        unawaited(
          _reconcilePlannedTripStopOnWorker(
            tripId: tripIdFromResp,
            bookingId: booking.bookingId,
          ),
        );
      }
      return true;
    } catch (e) {
      debugPrint(
        '[PLANNED_TRIP][HISTORY][WARN] booking=${booking.bookingId} reason=$e',
      );
      if (durableIntent != null) {
        await _PlannedStopIntentStore.recordAttemptFailure(
          intent: durableIntent,
          error: '$e',
        );
      }
      return false;
    }
  }

  /// PLANNED-STOP-HISTORY-DURABILITY-P0-8: whether the current STOP managed to
  /// persist a durable, replayable planned STOP intent.
  ///
  /// This is the invariant-B proof consumed by [_completeStoppedBooking]: without
  /// either a confirmed chain or this flag, a terminal COMPLETED projection would
  /// lose the driven ride entirely.
  bool _plannedStopIntentDurable = false;

  /// PLANNED-STOP-HISTORY-DURABILITY-P0-8: builds the durable STOP intent for a
  /// planned ride from the exact payload measured at STOP time.
  ///
  /// The payload is stored verbatim so recovery replays real ride truth and never
  /// synthesizes distance, waiting time or stop timestamps. Returns null when the
  /// tenant/company scope cannot be resolved, because an unscoped intent could
  /// not be replayed safely on a shared device.
  PlannedStopIntent? _buildPlannedStopIntent({
    required BookingItem booking,
    required Map<String, dynamic> payload,
  }) {
    final scope = _complianceLedgerScopeForStop();
    if (scope == null) return null;
    if (booking.bookingId.trim().isEmpty) return null;
    return PlannedStopIntent.fromStopPayload(
      bookingId: booking.bookingId,
      tenantId: scope.tenantId,
      companyId: scope.companyId,
      driverId: kDriverId,
      payload: payload,
      nowUtc: DateTime.now().toUtc(),
      legId: booking.legId,
      rowKey: booking.rowKey,
      legType: booking.isOperationalLeg
          ? _operationalLegTypeToken(booking)
          : '',
    );
  }

  Future<void> _clearPlannedStopIntent(PlannedStopIntent? intent) async {
    if (intent == null) return;
    await _PlannedStopIntentStore.remove(
      tenantId: intent.tenantId,
      companyId: intent.companyId,
      intentId: intent.intentId,
    );
  }

  /// PLANNED-STOP-HISTORY-DURABILITY-P0-8: ensures a durable STOP intent exists
  /// for [booking] before its leg/booking is projected COMPLETED.
  ///
  /// Used by the leg-status path, which commits COMPLETED to the booking worker
  /// before the tracking chain runs. Returns true when an intent is on disk,
  /// which is the invariant-B proof the caller needs.
  ///
  /// An existing intent for the same deterministic id is kept as-is. The cockpit
  /// STOP records real measured distance and waiting time, while this leg-scoped
  /// payload carries zeros, so overwriting would replace measured ride truth with
  /// zeros.
  Future<bool> _ensurePlannedStopIntentDurable(BookingItem booking) async {
    try {
      final scope = _complianceLedgerScopeForStop();
      if (scope == null) return false;
      final intentId = plannedStopTripId(
        bookingId: booking.bookingId,
        legId: booking.legId,
        rowKey: booking.rowKey,
      );
      final existing = await _PlannedStopIntentStore.pending(
        tenantId: scope.tenantId,
        companyId: scope.companyId,
        driverId: kDriverId,
      );
      if (existing.any((e) => e.intentId == intentId)) {
        debugPrint(
          '[PLANNED_STOP_INTENT][ENSURE] action=keep_existing intent=$intentId',
        );
        return true;
      }
      final payload = _buildOperationalLegPlannedStopPayload(booking);
      if (payload == null) return false;
      final intent = _buildPlannedStopIntent(booking: booking, payload: payload);
      if (intent == null) return false;
      return await _PlannedStopIntentStore.save(intent);
    } catch (e) {
      debugPrint('[PLANNED_STOP_INTENT][ENSURE][WARN] reason=$e');
      return false;
    }
  }

  /// PLANNED-STOP-HISTORY-DURABILITY-P0-8: replays stranded planned STOP intents.
  ///
  /// Runs at driver-page init so a stop lost to poor network, an app kill or a
  /// process death still materializes its trip, `trips_index`, driver-history and
  /// Chiron rows. Replay is idempotent: the tracking worker derives the same
  /// deterministic `trip_id`, de-duplicates index entries, reuses the same
  /// deterministic Chiron `event_id` and never regresses APPLIED.
  Future<void> _drainPlannedStopIntents() async {
    try {
      final scope = _complianceLedgerScopeForStop();
      if (scope == null) return;
      final pending = await _PlannedStopIntentStore.pending(
        tenantId: scope.tenantId,
        companyId: scope.companyId,
        driverId: kDriverId,
      );
      if (pending.isEmpty) return;
      debugPrint(
        '[PLANNED_STOP_INTENT][DRAIN] pending=${pending.length} '
        'tenant=${_maskLocalScopeId(scope.tenantId)}',
      );
      for (final intent in pending) {
        if (!mounted) return;
        await _replayPlannedStopIntent(intent);
      }
    } catch (e) {
      debugPrint('[PLANNED_STOP_INTENT][DRAIN][WARN] reason=$e');
    }
  }

  /// Replays one durable intent verbatim. Clears it only on server confirmation.
  Future<bool> _replayPlannedStopIntent(PlannedStopIntent intent) async {
    try {
      final strictScope = _strictBookingScopeForMutation(
        action: 'replay_planned_stop_intent',
        showUx: false,
      );
      if (strictScope == null) return false;
      // Fail closed rather than replay another tenant/company's ride.
      final scopeTenant = (strictScope['tenant_id'] ?? '').trim();
      final scopeCompany = (strictScope['company_id'] ?? '').trim();
      if (scopeTenant.isNotEmpty && scopeTenant != intent.tenantId) return false;
      if (scopeCompany.isNotEmpty && scopeCompany != intent.companyId) {
        return false;
      }
      final res = await http
          .post(
            _uriWithScope(
              kWorkerBaseUrl,
              kRecordPlannedTripStopPath,
              strictScope,
            ),
            headers: _driverBearerHeaders(),
            body: jsonEncode(intent.payload),
          )
          .timeout(const Duration(seconds: 10));
      if (res.statusCode < 200 || res.statusCode >= 300) {
        throw Exception('HTTP ${res.statusCode}');
      }
      debugPrint(
        '[PLANNED_STOP_INTENT][REPLAY][OK] intent=${intent.intentId} '
        'booking=${intent.bookingId} attempts=${intent.attemptCount}',
      );
      await _clearPlannedStopIntent(intent);
      return true;
    } catch (e) {
      debugPrint(
        '[PLANNED_STOP_INTENT][REPLAY][WARN] intent=${intent.intentId} reason=$e',
      );
      await _PlannedStopIntentStore.recordAttemptFailure(
        intent: intent,
        error: '$e',
      );
      return false;
    }
  }

  /// RELEASE-P0-DURABLE-CHIRON-SYNC-FOR-PLANNED-RIDES-2026-07-31: idempotent
  /// planned Chiron retry. Fires `POST /trip/reconcile-planned-stop` with the
  /// authoritative trip_id captured from the record-planned-stop response so
  /// the tracking worker can retry the durable compliance_emit_* outbox row
  /// using the exact same deterministic event_id (never regresses APPLIED,
  /// never mutates trip status/totals, fails closed on tenant mismatch).
  /// Best-effort: server-side pending remains durable regardless of outcome.
  Future<void> _reconcilePlannedTripStopOnWorker({
    required String tripId,
    required String bookingId,
  }) async {
    final trip = tripId.trim();
    if (trip.isEmpty) return;
    try {
      final strictScope = _strictBookingScopeForMutation(
        action: 'reconcile_planned_stop',
        showUx: false,
      );
      if (strictScope == null) return;
      final res = await http
          .post(
            _uriWithScope(
              kWorkerBaseUrl,
              kReconcilePlannedStopPath,
              strictScope,
            ),
            headers: _driverBearerHeaders(),
            body: jsonEncode(<String, dynamic>{
              'trip_id': trip,
              if (bookingId.trim().isNotEmpty) 'booking_id': bookingId.trim(),
              ...strictScope,
              ..._driverMutationActorFields(
                actorVehicleId: _directRideVehicleId(),
              ),
            }),
          )
          .timeout(const Duration(seconds: 6));
      String reason = '-';
      String state = '-';
      try {
        final decoded = jsonDecode(res.body);
        if (decoded is Map) {
          reason = (decoded['reason'] ?? '-').toString();
          state = (decoded['compliance_emit_state'] ?? '-').toString();
        }
      } catch (_) {}
      debugPrint(
        '[PLANNED_TRIP][RECONCILE_STOP] trip=$trip booking=${bookingId.isEmpty ? '-' : bookingId} '
        'http=${res.statusCode} reason=$reason state=$state',
      );
    } catch (e) {
      debugPrint(
        '[PLANNED_TRIP][RECONCILE_STOP][WARN] trip=$trip booking=${bookingId.isEmpty ? '-' : bookingId} reason=$e',
      );
    }
  }

  /// RELEASE-P0-DURABLE-CHIRON-SYNC-FOR-PLANNED-RIDES-2026-07-31: idempotent
  /// planned ride_start Chiron retry. Fires
  /// `POST /track/session/reconcile-start` so the tracking worker can retry
  /// the durable compliance_emit_start_* outbox row on the session record.
  /// Never regresses APPLIED, never invents ids, never blocks the START UX.
  Future<void> _reconcilePlannedSessionStartOnWorker({
    required String sessionId,
  }) async {
    final session = sessionId.trim();
    if (session.isEmpty) return;
    try {
      final strictScope = _strictBookingScopeForMutation(
        action: 'reconcile_planned_start',
        showUx: false,
      );
      if (strictScope == null) return;
      final res = await http
          .post(
            _uriWithScope(
              kWorkerBaseUrl,
              kReconcilePlannedStartPath,
              strictScope,
            ),
            headers: _driverBearerHeaders(),
            body: jsonEncode(<String, dynamic>{
              'session_id': session,
              ...strictScope,
              ..._driverMutationActorFields(
                actorVehicleId: _directRideVehicleId(),
              ),
            }),
          )
          .timeout(const Duration(seconds: 6));
      String reason = '-';
      String state = '-';
      try {
        final decoded = jsonDecode(res.body);
        if (decoded is Map) {
          reason = (decoded['reason'] ?? '-').toString();
          state = (decoded['compliance_emit_start_state'] ?? '-').toString();
        }
      } catch (_) {}
      debugPrint(
        '[PLANNED_TRIP][RECONCILE_START] session=$session '
        'http=${res.statusCode} reason=$reason state=$state',
      );
    } catch (e) {
      debugPrint(
        '[PLANNED_TRIP][RECONCILE_START][WARN] session=$session reason=$e',
      );
    }
  }

  /// RELEASE-P0-CLOSE-PLANNED-CHIRON-DURABILITY-GAPS-2026-07-31: bounded,
  /// tenant/company-scoped startup recovery for planned ride_start /
  /// ride_stop Chiron events that stayed PENDING (e.g. an app-kill between
  /// the durable persist and the in-session immediate retry). Server-side
  /// enumerates the scoped indices, reuses the persisted deterministic
  /// event_ids and never re-emits APPLIED events. Client fires this once
  /// on driver-page init as a non-blocking best-effort call.
  Future<void> _recoverPlannedPendingOnWorker() async {
    try {
      final strictScope = _strictBookingScopeForMutation(
        action: 'recover_planned_pending',
        showUx: false,
      );
      if (strictScope == null) return;
      final res = await http
          .post(
            _uriWithScope(
              kWorkerBaseUrl,
              kRecoverPlannedPendingPath,
              strictScope,
            ),
            headers: _driverBearerHeaders(),
            body: jsonEncode(<String, dynamic>{
              'limit': 25,
              ...strictScope,
              ..._driverMutationActorFields(
                actorVehicleId: _directRideVehicleId(),
              ),
            }),
          )
          .timeout(const Duration(seconds: 8));
      int reconciledStops = 0;
      int reconciledStarts = 0;
      int stillPendingStops = 0;
      int stillPendingStarts = 0;
      try {
        final decoded = jsonDecode(res.body);
        if (decoded is Map) {
          reconciledStops =
              int.tryParse((decoded['reconciled_stops'] ?? 0).toString()) ?? 0;
          reconciledStarts =
              int.tryParse((decoded['reconciled_starts'] ?? 0).toString()) ??
                  0;
          stillPendingStops =
              int.tryParse((decoded['still_pending_stops'] ?? 0).toString()) ??
                  0;
          stillPendingStarts = int.tryParse(
                (decoded['still_pending_starts'] ?? 0).toString(),
              ) ??
              0;
        }
      } catch (_) {}
      debugPrint(
        '[PLANNED_TRIP][RECOVER_STARTUP] http=${res.statusCode} '
        'reconciled_stops=$reconciledStops reconciled_starts=$reconciledStarts '
        'still_pending_stops=$stillPendingStops still_pending_starts=$stillPendingStarts',
      );
    } catch (e) {
      debugPrint('[PLANNED_TRIP][RECOVER_STARTUP][WARN] reason=$e');
    }
  }

  String _complianceRideId({
    required String rideType,
    String? bookingId,
    String? tripId,
    required DateTime stoppedAt,
  }) {
    final seed = (bookingId ?? tripId ?? '').trim();
    final ts = stoppedAt.toUtc().millisecondsSinceEpoch;
    if (seed.isNotEmpty) return 'rlg_${rideType}_${seed}_$ts';
    return 'rlg_${rideType}_$ts';
  }

  String _complianceReceiptReference({
    String? bookingId,
    String? tripId,
    required String rideId,
  }) {
    final booking = (bookingId ?? '').trim();
    if (booking.isNotEmpty) return booking;
    final trip = (tripId ?? '').trim();
    if (trip.isNotEmpty) return 'TRIP-$trip';
    return rideId.trim();
  }

  String _complianceValidationState({
    required String rideType,
    required bool backendConfirmed,
    required String driverId,
    required String receiptReference,
    required DateTime? startedAt,
    required DateTime stoppedAt,
    String? bookingId,
  }) {
    if (driverId.trim().isEmpty ||
        driverId.trim() == kFallbackDriverTrackingId.trim()) {
      return 'blocked';
    }
    if (startedAt == null || startedAt.isAfter(stoppedAt)) return 'blocked';
    if (receiptReference.trim().isEmpty) return 'blocked';
    if (rideType == 'direct' && !backendConfirmed) return 'blocked';
    if (rideType == 'planned' && (bookingId ?? '').trim().isEmpty) {
      return 'incomplete';
    }
    return 'exportable';
  }

  String? _complianceText(dynamic value) {
    final s = value?.toString().trim();
    if (s == null || s.isEmpty || s.toLowerCase() == 'null') return null;
    return s;
  }

  String? _compliancePathText(Map<String, dynamic> root, String path) {
    dynamic cursor = root;
    for (final part in path.split('.')) {
      if (cursor is! Map) return null;
      cursor = cursor[part];
    }
    return _complianceText(cursor);
  }

  String? _firstComplianceText(List<dynamic> candidates) {
    for (final candidate in candidates) {
      final text = _complianceText(candidate);
      if (text != null) return text;
    }
    return null;
  }

  String _normalizeCompliancePaymentStatus(dynamic value) {
    final raw = _complianceText(value);
    if (raw == null) return 'unknown';
    final normalized = raw
        .toLowerCase()
        .replaceAll('-', '_')
        .replaceAll(' ', '_')
        .trim();
    switch (normalized) {
      case 'paid':
      case 'succeeded':
      case 'success':
      case 'completed':
      case 'settled':
      case 'confirmed':
        return 'paid';
      case 'pending':
      case 'open':
      case 'authorized':
      case 'authorised':
      case 'processing':
        return 'pending';
      case 'failed':
      case 'error':
      case 'declined':
        return 'failed';
      case 'cancelled':
      case 'canceled':
        return 'cancelled';
      case 'unpaid':
      case 'not_paid':
        return 'unpaid';
      case 'unknown':
        return 'unknown';
      default:
        return 'unknown';
    }
  }

  String _normalizeCompliancePaymentMethod(dynamic value) {
    final raw = _complianceText(value);
    if (raw == null) return 'unknown';
    final normalized = raw
        .toLowerCase()
        .replaceAll('-', '_')
        .replaceAll(' ', '_')
        .trim();
    switch (normalized) {
      case 'cash':
      case 'contant':
        return 'cash';
      case 'qr':
      case 'qr_code':
        return 'qr';
      case 'bancontact':
        return 'bancontact';
      case 'card':
      case 'terminal':
      case 'card_terminal':
        return 'card_terminal';
      case 'payment_link':
      case 'link':
      case 'online':
        return 'payment_link';
      case 'mollie':
        return 'mollie';
      case 'in_car':
      case 'unknown':
        return 'unknown';
      default:
        return 'unknown';
    }
  }

  Map<String, dynamic> _buildCompliancePaymentPayload({
    dynamic status,
    dynamic method,
    dynamic source,
    dynamic provider,
    dynamic paymentId,
    dynamic paidAtUtc,
  }) {
    final normalizedStatus = _normalizeCompliancePaymentStatus(status);
    final normalizedMethod = _normalizeCompliancePaymentMethod(method);
    final sourceText = _complianceText(source);
    final providerText = _complianceText(provider);
    final paymentIdText = _complianceText(paymentId);
    final paidAtText = _complianceText(paidAtUtc);
    final parsedPaidAt = paidAtText == null
        ? null
        : DateTime.tryParse(paidAtText);

    return <String, dynamic>{
      'status': normalizedStatus,
      if (normalizedMethod != 'unknown') 'method': normalizedMethod,
      if (sourceText != null) 'source': sourceText,
      if (providerText != null) 'provider': providerText,
      if (paymentIdText != null) 'payment_id': paymentIdText,
      if (parsedPaidAt != null)
        'paid_at_utc': parsedPaidAt.toUtc().toIso8601String()
      else if (paidAtText != null)
        'paid_at_utc': paidAtText,
    };
  }

  Map<String, dynamic> _buildCompliancePlannedLedgerRecord({
    required BookingItem booking,
    required DateTime? startedAt,
    required DateTime stoppedAt,
    required double kmTotal,
    required int waitSecondsTotal,
    required bool backendConfirmed,
  }) {
    final bookingId = booking.bookingId.trim();
    final driverId = kDriverId.trim();
    final vehicleId = _directRideVehicleId().trim();
    final rideId = _complianceRideId(
      rideType: 'planned',
      bookingId: bookingId,
      stoppedAt: stoppedAt,
    );
    final receiptReference = _complianceReceiptReference(
      bookingId: bookingId,
      rideId: rideId,
    );
    final total =
        _driverDisplayPriceForBooking(booking) ??
        (booking.isOperationalLeg ? null : booking.price?.toDouble());
    final details = booking.details;
    final plannedPaymentStatus = _firstComplianceText([
      details['payment_status'],
      details['paymentStatus'],
      _compliancePathText(details, 'booking.payment_status'),
      _compliancePathText(details, 'booking.paymentStatus'),
      _compliancePathText(details, 'mollie.status'),
      _compliancePathText(details, 'record.mollie.status'),
    ]);
    final plannedPaymentMethod = _firstComplianceText([
      details['payment_method'],
      details['paymentMethod'],
      _compliancePathText(details, 'booking.payment_method'),
      _compliancePathText(details, 'booking.paymentMethod'),
    ]);
    final plannedPaymentSource = _firstComplianceText([
      details['payment_source'],
      details['paymentSource'],
      _compliancePathText(details, 'booking.payment_source'),
      _compliancePathText(details, 'booking.paymentSource'),
    ]);
    final plannedPaymentProvider = _firstComplianceText([
      details['payment_provider'],
      details['paymentProvider'],
      _compliancePathText(details, 'booking.payment_provider'),
      _compliancePathText(details, 'booking.paymentProvider'),
    ]);
    final plannedPaymentId = _firstComplianceText([
      details['payment_id'],
      details['paymentId'],
      _compliancePathText(details, 'booking.payment_id'),
      _compliancePathText(details, 'booking.paymentId'),
    ]);
    final plannedPaidAt = _firstComplianceText([
      details['paid_at'],
      details['paidAt'],
      _compliancePathText(details, 'booking.paid_at'),
      _compliancePathText(details, 'booking.paidAt'),
    ]);
    final referenceMaps = _referenceLookupMaps(<Map<String, dynamic>>[details]);
    final planningReference = _pickReferenceAliasFromMaps(referenceMaps, const [
      ['planning_reference'],
      ['planningReference'],
    ]);
    final publicBookingReference = _pickReferenceAliasFromMaps(
      referenceMaps,
      const [
        ['public_booking_reference'],
        ['publicBookingReference'],
        ['booking_reference'],
        ['bookingReference'],
        ['public_reference'],
        ['publicReference'],
      ],
    );
    final bookingReference = _pickReferenceAliasFromMaps(referenceMaps, const [
      ['booking_reference'],
      ['bookingReference'],
    ]);
    final publicReference = _pickReferenceAliasFromMaps(referenceMaps, const [
      ['public_reference'],
      ['publicReference'],
    ]);
    final effectiveReceiptReference = _pickBusinessReference(
      rawSource: details,
      details: details,
      bookingId: bookingId,
      tripId: null,
      legacyFallback: receiptReference,
    );
    final validationState = _complianceValidationState(
      rideType: 'planned',
      backendConfirmed: backendConfirmed,
      driverId: driverId,
      receiptReference: effectiveReceiptReference,
      startedAt: startedAt,
      stoppedAt: stoppedAt,
      bookingId: bookingId,
    );
    final ledgerScope = _complianceLedgerScopeForStop();

    return <String, dynamic>{
      'ledger_version': '1.0',
      'ride_id': rideId,
      'ride_type': 'planned',
      'lifecycle_status': 'completed',
      'tenant_id': ledgerScope?.tenantId ?? '',
      'company_id': ledgerScope?.companyId ?? '',
      'driver_id': driverId,
      'vehicle_id': vehicleId,
      'booking_id': bookingId,
      'trip_id': null,
      'session_id': _activeTripId,
      'started_at_utc': startedAt?.toUtc().toIso8601String(),
      'ended_at_utc': stoppedAt.toUtc().toIso8601String(),
      'duration_seconds': startedAt == null
          ? null
          : stoppedAt.difference(startedAt).inSeconds,
      'pickup': <String, dynamic>{'label': (booking.from ?? '').trim()},
      'dropoff': <String, dynamic>{'label': (booking.to ?? '').trim()},
      'distance_km': kmTotal,
      'wait_seconds_total': waitSecondsTotal,
      'fare': <String, dynamic>{
        'total_eur': total,
        'currency': booking.currency ?? kDefaultCurrency,
      },
      'payment': _buildCompliancePaymentPayload(
        status: plannedPaymentStatus,
        method: plannedPaymentMethod,
        source: plannedPaymentSource,
        provider: plannedPaymentProvider,
        paymentId: plannedPaymentId,
        paidAtUtc: plannedPaidAt,
      ),
      'references': <String, dynamic>{
        'receipt_reference': effectiveReceiptReference,
        'planning_reference': planningReference,
        'public_booking_reference': publicBookingReference,
        'booking_reference': bookingReference,
        'public_reference': publicReference,
        'invoice_reference': null,
      },
      'provenance': <String, dynamic>{
        'backend_confirmed': backendConfirmed,
        'validation_state': validationState,
      },
      'created_at_utc': DateTime.now().toUtc().toIso8601String(),
      'finalized_at_utc': stoppedAt.toUtc().toIso8601String(),
    };
  }

