  /// OFFLINE-STOP-RIDE-DURABILITY-P0: durable local history row for a street
  /// ride that STOP'd with a known trip id but whose server finalize has not
  /// been acknowledged yet. Uses the real trip_id so reconnect merge dedupes
  /// against the backend row once finalize succeeds.
  Future<void> _persistPendingFinalizeDirectHistory({
    required String tripId,
    required String? bookingId,
    required DateTime stoppedAt,
    required DateTime? startedAt,
    required double kmTotal,
    required int waitSecondsTotal,
    required double totalEur,
  }) async {
    final payment = _buildCompliancePaymentPayload();
    final booking = (bookingId ?? '').trim();
    final record = <String, dynamic>{
      'trip_id': tripId.trim(),
      'kind': 'direct',
      'status': 'COMPLETED',
      'tenant_id': kOutboundTenantId,
      'driver_id': kDriverId,
      'vehicle_id': _directRideVehicleId(),
      if (booking.isNotEmpty) 'booking_id': booking,
      'started_at': startedAt?.toUtc().toIso8601String(),
      'stopped_at': stoppedAt.toUtc().toIso8601String(),
      'km_total': kmTotal,
      'wait_seconds_total': waitSecondsTotal,
      'total_eur': totalEur,
      'currency': kDefaultCurrency,
      'payment_status': payment['status'] ?? 'unknown',
      'booking_details': <String, dynamic>{
        'payment_status': payment['status'] ?? 'unknown',
        if (payment['method'] != null) 'payment_method': payment['method'],
        'history_source': 'offline_stop_pending_finalize',
        'backend_confirmed': false,
        'finalize_pending': true,
      },
      'history_source': 'offline_stop_pending_finalize',
      'backend_confirmed': false,
      'finalize_pending': true,
      'created_at': DateTime.now().toUtc().toIso8601String(),
    };
    await _LocalDirectTripHistoryStore.append(record);
  }

  Future<void> _stopTrip() async {
    // DIRECT-RIDE-FINALIZE-ACK-GATE-1 + OFFLINE-STOP-RIDE-DURABILITY-P0:
    // a second Stop while finalize is pending must not invent new totals.
    // Meter is already off; recovery owns `/trip/stop` replay (frozen) and
    // booking finalize retries.
    if (_directStopFinalizePending) {
      _logDriverNavDiag(
        tag: 'STOP_FINALIZE_PENDING',
        action: 'stop_trip',
        bookingId: _activeDirectBookingId ?? _activeBooking?.bookingId ?? '',
      );
      _showStreetDirectFinalizePendingSnackbar();
      unawaited(_recoverPendingDirectTripSession());
      // SECURITY-REMOVE-CLIENT-ADMIN-TOKEN-P0-1 (Field Failure Fix, Commit 4):
      // even on the "second STOP tap while finalize pending" branch we must
      // force the DriverHomePage back into normal (non-live) rendering. The
      // reconcile identifiers are preserved so the pending reconcile can
      // retry.
      await _deterministicStopTeardown(
        outcome: StopTeardownOutcome.alreadyCleared,
        preservePendingDirectIdentity: true,
      );
      return;
    }

    final trip = _activeTripId;
    if (trip == null && !_directRideActive) {
      // SECURITY-REMOVE-CLIENT-ADMIN-TOKEN-P0-1 (Field Failure Fix, Commit 4):
      // nothing to stop on the worker, but the live-navigation rendering
      // may still be stuck from a partial prior teardown or a stale flag.
      // Force a deterministic exit.
      await _deterministicStopTeardown(
        outcome: StopTeardownOutcome.alreadyCleared,
        preservePendingDirectIdentity: false,
      );
      return;
    }
    final stoppedBooking = _activeBooking;
    if (stoppedBooking != null &&
        !_canOperateBookingWithGuard(
          _bookingScopeViewFor(stoppedBooking),
          action: 'stop_complete_booking',
        )) {
      return;
    }

    // DIRECT-RIDE-PLANNED-STOP-GUARD-1: booking source is authoritative for
    // stop lifecycle selection. A street/direct booking must never enter the
    // planned stop path (`/track/session/stop` as planned, `/trip/record-
    // planned-stop`, or generic `/bookings/{id}/status` COMPLETED as
    // substitute for direct finalization), even when `_directRideActive` is
    // false (recovered/stale/future state). We compute the decision BEFORE
    // any state clearing so a safe-fail can leave the record and
    // reconciliation evidence untouched.
    final stopRouting = stopTripLifecycleDecision(
      bookingDetails: stoppedBooking?.details ?? const <String, dynamic>{},
      bookingId: stoppedBooking?.bookingId ?? '',
      activeDirectTripId: _activeDirectTripId,
      directRideActive: _directRideActive,
    );
    if (stopRouting.isDirectUnavailable) {
      _logDriverNavDiag(
        tag: 'STOP_DIRECT_UNAVAILABLE',
        action: 'stop_trip',
        bookingId: stoppedBooking?.bookingId ?? '',
      );
      _showStreetDirectStopUnavailableSnackbar();
      return;
    }

    // Even when the caller-visible `_directRideActive` is false, a
    // street/direct classification with a valid trip id promotes the stop
    // into the direct finalization path. This keeps the existing
    // `_stopDirectTripSessionOnWorker` call site owning `/trip/stop` +
    // `finalize-direct` without duplicating either endpoint here.
    final wasDirectRide = _directRideActive || stopRouting.isDirectFinalize;
    final directTripId = _activeDirectTripId;
    final directBookingId = _activeDirectBookingId;
    final directRideKeyAtStop = _directRideKey;
    final finalTotal = _liveMeterTotalEur;
    final stoppedAt = DateTime.now();
    final startedAt = _trackingStartedAt;
    final kmAtStop = _kmDriven;
    final waitAtStop = _effectiveWaitElapsed.inSeconds;
    final frozenDirectFare = wasDirectRide
        ? _finalizedFareForPersistence(
            finalTotal,
            source: 'street',
            reason: 'offline_stop_client_freeze',
          )
        : finalTotal;
    var plannedSessionStopOk = false;

    // OFFLINE-STOP-RIDE-DURABILITY-P0: freeze authoritative STOP totals to
    // durable session BEFORE leaving the active-ride presentation / awaiting
    // network. Network availability must not determine ride survival.
    if (wasDirectRide &&
        ((directTripId ?? '').trim().isNotEmpty ||
            (directRideKeyAtStop ?? '').trim().isNotEmpty)) {
      await _persistDirectTripSession(
        localLifecycle: kDirectTripLocalLifecycleStopped,
        bookingFinalizeState: kDirectTripFinalizePending,
        trackingStopState: kDirectTripTrackingStopPending,
        stoppedAtIso: stoppedAt.toUtc().toIso8601String(),
        frozenKmTotal: kmAtStop,
        frozenWaitSecondsTotal: waitAtStop,
        frozenTotalEur: frozenDirectFare,
        tripIdOverride: directTripId,
        bookingIdOverride: directBookingId,
        directRideKeyOverride: directRideKeyAtStop,
        startedAtIsoOverride: startedAt?.toUtc().toIso8601String(),
      );
    }

    // GOOGLE-MAPS-WITH-FLUXIDI-PIP-RELEASE-1: STOP only in full Fluxidi —
    // end external session and leave PiP; never relaunch Google Maps.
    unawaited(
      _endExternalNavigationSession(reason: 'stop_trip', exitPip: true),
    );
    unawaited(_clearActiveRideDurableSnapshot(reason: 'stop_begin'));

    // NAV-RIDE-BOUNDARY: invalidate route ownership BEFORE network awaits so a
    // fast next-ride start cannot race uncleared geometry / style restores.
    // Meter stops here: `_directRideActive=false` so UI never believes the
    // ride is still running while finalize may still be pending.
    _hardClearAtRideBoundary(reason: 'stop_begin', bumpSession: true);
    if (mounted) {
      setState(() {
        _directRideActive = false;
        _activeTripId = null;
      });
    } else {
      _directRideActive = false;
      _activeTripId = null;
    }
    // SECURITY-REMOVE-CLIENT-ADMIN-TOKEN-P0-1 (Field Failure Fix, Blocker Fix):
    // early STOP transition — publish bearer-busy=false if no reconcile is
    // pending and no teardown has started yet. Covers the code path where
    // the reconcile branch below is skipped (no direct trip id) so the
    // notifier is not left stale between the meter stop and the deterministic
    // teardown enter.
    _publishBearerBusyState();

    if (_isWaiting && _waitStartedAt != null) {
      final started = _waitStartedAt!;
      _waitElapsed += DateTime.now().difference(started);
      _waitStartedAt = null;
      _isWaiting = false;
    }

    if (trip != null) {
      try {
        final strictScope = _strictBookingScopeForMutation(
          action: 'stop_trip_session',
          showUx: false,
        );
        if (strictScope == null) return;
        final uri = _uriWithScope(kWorkerBaseUrl, kStopTripPath, strictScope);
        final payload = <String, dynamic>{
          'session_id': trip,
          'driver_id': kDriverId,
          ...strictScope,
          ..._driverMutationActorFields(actorVehicleId: _directRideVehicleId()),
        };
        final res = await http
            .post(
              uri,
              headers: _driverBearerHeaders(),
              body: jsonEncode(payload),
            )
            .timeout(const Duration(seconds: 10));
        plannedSessionStopOk = res.statusCode == 200;
      } catch (_) {}
    }

    // PLANNED-STOP-HISTORY-DURABILITY-P0-8: this call is the ONLY writer of the
    // planned trip / trips_index / driver-history / Chiron chain, so it must not
    // be gated on `/track/session/stop`. That call only flips
    // `session.status="stopped"`, materializes nothing durable, and swallows its
    // own errors above — on poor network its 10s timeout used to skip the entire
    // durable chain while the booking still went COMPLETED (field incident
    // PLN-2026-000387 / booking 2026-08-168).
    _plannedStopIntentDurable = false;
    var plannedTripStopBridgeOk = false;
    if (!wasDirectRide && stoppedBooking != null) {
      plannedTripStopBridgeOk = await _recordPlannedTripStopOnWorker(
        booking: stoppedBooking,
        kmTotal: kmAtStop,
        waitSecondsTotal: waitAtStop,
        startedAt: startedAt,
        stoppedAt: stoppedAt,
      );
    }

    DirectRideStopOutcome? directStopOutcome;
    if (wasDirectRide &&
        directTripId != null &&
        directTripId.trim().isNotEmpty) {
      directStopOutcome = await _stopDirectTripSessionOnWorker(
        tripId: directTripId,
        kmTotal: kmAtStop,
        waitSecondsTotal: waitAtStop,
        clientStoppedAtIso: stoppedAt.toUtc().toIso8601String(),
        bookingIdOverride: directBookingId,
        directRideKeyOverride: directRideKeyAtStop,
        startedAtIsoOverride: startedAt?.toUtc().toIso8601String(),
        frozenTotalEur: frozenDirectFare,
      );
    }

    // DIRECT-RIDE-FINALIZE-ACK-GATE-1: local COMPLETED only after authoritative
    // booking finalize acknowledgement (matching booking id + completed state
    // + totals). Tracking stop alone is insufficient.
    var directFinalizeAcknowledged = wasDirectRide &&
        directStopOutcome != null &&
        isDirectRideFinalizeAcknowledged(
          outcome: directStopOutcome,
          expectedBookingId: directBookingId,
        );
    final serverDirectTotal = directStopOutcome?.totalEur;

    _stopMeterTicker();
    _stopTrackingInternal();

    if (stoppedBooking != null) {
      await _completeStoppedBooking(
        stoppedBooking,
        plannedStopBridgeAlreadyCompletedLeg: plannedTripStopBridgeOk,
        directFinalizeAcknowledged: directFinalizeAcknowledged,
      );
    }
    if (!wasDirectRide && stoppedBooking != null) {
      final plannedLedger = _buildCompliancePlannedLedgerRecord(
        booking: stoppedBooking,
        startedAt: startedAt,
        stoppedAt: stoppedAt,
        kmTotal: kmAtStop,
        waitSecondsTotal: _effectiveWaitElapsed.inSeconds,
        backendConfirmed: plannedSessionStopOk,
      );
      unawaited(_writeComplianceLedgerRecord(record: plannedLedger));
    }
    if (wasDirectRide) {
      final directBackendConfirmed =
          _directTripStartWorkerOk && _directTripStopWorkerOk;
      // FARE-ROUNDING-CENTRAL-0_10-1: the tracking worker already returns the
      // canonical €0.10-rounded total, so trust it as-is. Only the local
      // client fallback (worker total absent) is rounded here — exactly once —
      // before it becomes the persisted amount. Offline STOP already froze
      // [frozenDirectFare] before the network call.
      final double finalDirectTotal =
          serverDirectTotal ?? frozenDirectFare;
      final directLedger = _buildComplianceDirectLedgerRecord(
        tripId: directTripId,
        bookingId: directBookingId,
        startedAt: startedAt,
        stoppedAt: stoppedAt,
        kmTotal: kmAtStop,
        waitSecondsTotal: waitAtStop,
        totalEur: finalDirectTotal,
        backendConfirmed: directBackendConfirmed,
      );
      unawaited(_writeComplianceLedgerRecord(record: directLedger));
      final isLocalOnlyDirect =
          directTripId == null || directTripId.trim().isEmpty;
      if (isLocalOnlyDirect) {
        await _persistLocalOnlyDirectHistoryFallback(
          stoppedAt: stoppedAt,
          startedAt: startedAt,
          kmTotal: kmAtStop,
          waitSecondsTotal: waitAtStop,
          totalEur: finalDirectTotal,
        );
      } else if (!directFinalizeAcknowledged) {
        // OFFLINE-STOP-RIDE-DURABILITY-P0: keep the completed ride visible in
        // history while server finalize/payment is still pending. Backend rows
        // win on trip_id collision once finalize succeeds.
        await _persistPendingFinalizeDirectHistory(
          tripId: directTripId,
          bookingId: directBookingId,
          stoppedAt: stoppedAt,
          startedAt: startedAt,
          kmTotal: kmAtStop,
          waitSecondsTotal: waitAtStop,
          totalEur: finalDirectTotal,
        );
      }

      if (!directFinalizeAcknowledged &&
          directTripId != null &&
          directTripId.trim().isNotEmpty) {
        _directStopFinalizePending = true;
        _publishBearerBusyState();
        final trackingStopped =
            directStopOutcome?.trackingTripStopped == true;
        if (trackingStopped &&
            (directBookingId ?? '').trim().isNotEmpty) {
          // Bounded single in-session reconcile — only after `/trip/stop`
          // landed. Offline STOP must NOT call reconcile alone (NON_TERMINAL).
          final reconcileOutcome = await _reconcileDirectBookingOnWorker(
            tripId: directTripId,
            expectedBookingId: directBookingId!,
          );
          if (isDirectRideReconcileAcknowledged(reconcileOutcome)) {
            directFinalizeAcknowledged = true;
            _directStopFinalizePending = false;
            _publishBearerBusyState();
            unawaited(_clearDirectTripSession());
            if (stoppedBooking != null) {
              await _completeStoppedBooking(
                stoppedBooking,
                plannedStopBridgeAlreadyCompletedLeg: false,
                directFinalizeAcknowledged: true,
              );
            }
            unawaited(
              _refreshBookings(
                force: true,
                trigger: 'street_finalize_reconcile_ok',
              ),
            );
          } else {
            await _persistDirectTripSession(
              localLifecycle: kDirectTripLocalLifecycleStopped,
              bookingFinalizeState: kDirectTripFinalizePending,
              trackingStopState: kDirectTripTrackingStopCompleted,
              stoppedAtIso: stoppedAt.toUtc().toIso8601String(),
              frozenKmTotal: kmAtStop,
              frozenWaitSecondsTotal: waitAtStop,
              frozenTotalEur: finalDirectTotal,
              tripIdOverride: directTripId,
              bookingIdOverride: directBookingId,
              directRideKeyOverride: directRideKeyAtStop,
              startedAtIsoOverride: startedAt?.toUtc().toIso8601String(),
            );
            _showStreetDirectFinalizePendingSnackbar();
          }
        } else {
          // Tracking stop did not land (offline / unknown). Frozen outbox
          // already persisted; surface truthful pending finalize UX.
          await _persistDirectTripSession(
            localLifecycle: kDirectTripLocalLifecycleStopped,
            bookingFinalizeState: kDirectTripFinalizePending,
            trackingStopState: kDirectTripTrackingStopPending,
            stoppedAtIso: stoppedAt.toUtc().toIso8601String(),
            frozenKmTotal: kmAtStop,
            frozenWaitSecondsTotal: waitAtStop,
            frozenTotalEur: finalDirectTotal,
            tripIdOverride: directTripId,
            bookingIdOverride: directBookingId,
            directRideKeyOverride: directRideKeyAtStop,
            startedAtIsoOverride: startedAt?.toUtc().toIso8601String(),
          );
          _showStreetDirectFinalizePendingSnackbar();
        }
      }

      _directTripStartWorkerOk = false;
      _directTripStopWorkerOk = false;
      if (directFinalizeAcknowledged) {
        _activeDirectBookingId = null;
        _directRideKey = null;
        _activeDirectTripId = null;
        _directStopFinalizePending = false;
        _publishBearerBusyState();
      }
      // When pending/unknown: retain `_activeDirectBookingId`, `_directRideKey`,
      // `_activeDirectTripId` for reconcile — meter stays off via
      // `_directRideActive == false`.
    }
    // SECURITY-REMOVE-CLIENT-ADMIN-TOKEN-P0-1 (Field Failure Fix, Commit 4):
    // deterministic STOP/navigation teardown. Replaces the earlier
    // `_clearActiveRouteAndNavigationState` call so route/pin cleanup,
    // wakelock release, camera/follow reset, native-follow disable, and
    // booking-polling restart all run unconditionally — even when route
    // geometry was already invalidated by `_hardClearAtRideBoundary` above
    // (which used to cause the caller-side early-return that left the
    // navigation surface active). `_activeBooking` is always cleared;
    // only the minimum reconcile identity survives when finalize is still
    // pending.
    final StopTeardownOutcome stopOutcome;
    if (directFinalizeAcknowledged) {
      stopOutcome = StopTeardownOutcome.backendConfirmed;
    } else if (wasDirectRide) {
      stopOutcome = StopTeardownOutcome.finalizePending;
    } else {
      stopOutcome = StopTeardownOutcome.localOnly;
    }
    await _deterministicStopTeardown(
      outcome: stopOutcome,
      preservePendingDirectIdentity: wasDirectRide && !directFinalizeAcknowledged,
    );
    if (wasDirectRide && directFinalizeAcknowledged) {
      // Mirror the canonical finalized amount: server total wins as-is;
      // otherwise the €0.10-rounded client fallback.
      final shownTotal =
          serverDirectTotal ??
              roundFareEuroToNearestTenCents(finalTotal) ??
              finalTotal;
      _toast(
        _tr(
          nl: 'Straatrit afgerond: € ${shownTotal.toStringAsFixed(2)}',
          en: 'Street ride completed: € ${shownTotal.toStringAsFixed(2)}',
          fr: 'Course de rue terminée : € ${shownTotal.toStringAsFixed(2)}',
          es: 'Viaje de calle finalizado: € ${shownTotal.toStringAsFixed(2)}',
        ),
      );
    }
    unawaited(_refreshCompletedTodayCount(reason: 'trip_stop'));
  }

  Future<void> _completeStoppedBooking(
    BookingItem b, {
    bool plannedStopBridgeAlreadyCompletedLeg = false,
    bool directFinalizeAcknowledged = false,
  }) async {
    final bookingId = b.bookingId;
    final rowKey = b.rowKey;
    final legId = b.legId.trim();
    final isLegScopedCompletion = b.isOperationalLeg && legId.isNotEmpty;
    final legType = isLegScopedCompletion ? _operationalLegTypeToken(b) : '-';
    final previousStatus = (b.status ?? '').trim();

    // DIRECT-RIDE-PLANNED-STOP-GUARD-1 (defense in depth): a street/direct
    // booking's authoritative COMPLETED transition is stamped server-side by
    // `finalize-direct` (during `/trip/stop`). We must not fire the generic
    // `/bookings/{id}/status` COMPLETED update here as a substitute.
    // DIRECT-RIDE-FINALIZE-ACK-GATE-1: local COMPLETED UI mutations require
    // an acknowledged finalize; pending/unknown must leave server truth visible.
    final isStreetDirect = isStreetDirectBooking(<String, dynamic>{
      ...b.details,
      if (b.bookingId.trim().isNotEmpty) 'booking_id': b.bookingId,
    });
    debugPrint(
      '[ROUNDTRIP_STATUS][LEG_COMPLETE] parent=$bookingId leg=${legId.isEmpty ? "-" : legId} leg_type=$legType old=${previousStatus.isEmpty ? "-" : previousStatus} new=COMPLETED scope=${isLegScopedCompletion ? "leg" : "parent"} source=driver_cockpit_stop street_direct=$isStreetDirect finalize_ack=$directFinalizeAcknowledged',
    );

    if (isStreetDirect && !isLegScopedCompletion && !directFinalizeAcknowledged) {
      debugPrint(
        '[STREET_DIRECT_COMPLETE_GUARD] action=skip_local_completed booking=$bookingId '
        'reason=finalize_not_acknowledged',
      );
      return;
    }

    // PLANNED-STOP-HISTORY-DURABILITY-P0-8: the planned-ride counterpart of the
    // street finalize-ack gate above. A planned ride may only reach a terminal
    // COMPLETED projection when the durable STOP/history chain is confirmed
    // (invariant A) or a durable replayable STOP intent is on disk that will
    // finish the chain later (invariant B). With neither, the driven ride exists
    // only in memory, so completing here is exactly what erased booking
    // 2026-08-168 from Driver History. Keep the ride open instead of losing it.
    if (!isStreetDirect &&
        !plannedTerminalProjectionAllowed(
          trackingStopMaterialized: plannedStopBridgeAlreadyCompletedLeg,
          durableIntentPersisted: _plannedStopIntentDurable,
        )) {
      debugPrint(
        '[PLANNED_STOP_DURABILITY_GATE] action=skip_completed booking=$bookingId '
        'leg=${legId.isEmpty ? "-" : legId} reason=no_durable_stop_record',
      );
      _toast(
        _tr(
          nl: 'Rit niet afgerond: stopgegevens konden niet worden opgeslagen. Probeer opnieuw.',
          en: 'Ride not completed: stop data could not be saved. Please try again.',
          fr: "Course non terminée : les données d'arrêt n'ont pas pu être enregistrées. Réessayez.",
          es: 'Viaje no finalizado: no se pudieron guardar los datos de parada. Inténtalo de nuevo.',
        ),
      );
      return;
    }
    // Roundtrip operational-leg false toast suppression: when the planned trip
    // stop bridge already accepted this leg's completion (worker-side bridge
    // applies COMPLETED with bypass_future_pickup_guard), a second direct call
    // through /bookings/:id/legs/:leg/status would be rejected by the future-
    // pickup guard for legs whose booked pickup is still in the future. That
    // produced the spurious "Legstatus bijwerken mislukt" toast even though
    // backend state is already correct. Trust the bridge for leg scope.
    final shouldSkipLegStatusCall =
        isLegScopedCompletion && plannedStopBridgeAlreadyCompletedLeg;
    if (shouldSkipLegStatusCall) {
      debugPrint(
        '[ROUNDTRIP_STATUS][FALSE_TOAST_SUPPRESSED] parent=$bookingId leg=${legId.isEmpty ? "-" : legId} leg_type=$legType reason=planned_stop_bridge_already_completed_leg source=driver_cockpit_stop',
      );
    } else if (isStreetDirect && !isLegScopedCompletion) {
      // DIRECT-RIDE-PLANNED-STOP-GUARD-1: `finalize-direct` owns the
      // authoritative COMPLETED transition + fare stamping for this booking.
      // Do not send a generic `/bookings/{id}/status` COMPLETED as a
      // substitute for direct finalization. Local UI reconciliation below runs
      // only because finalize was acknowledged (DIRECT-RIDE-FINALIZE-ACK-GATE-1).
      debugPrint(
        '[STREET_DIRECT_COMPLETE_GUARD] action=skip_generic_status booking=$bookingId '
        'reason=finalize_direct_owns_completed_transition',
      );
    } else {
      try {
        if (isLegScopedCompletion) {
          // Roundtrip operational-leg completion scope: complete only this leg.
          // Routing through the parent endpoint cascades COMPLETED onto every
          // sibling leg and hides the still-open return leg from the driver.
          await _setOperationalLegStatus(b, 'COMPLETED');
        } else {
          await _setBookingStatus(b, 'COMPLETED');
        }
      } catch (e) {
        debugPrint('[RIDES][STOP_COMPLETE][WARN] $e');
      }
    }
    if (!mounted) return;
    setState(() {
      if (isLegScopedCompletion) {
        // Optimistic state is leg-scoped while a genuine open sibling remains.
        // Field evidence (2026-08-166): remaining_open_leg_rows=0 still logged
        // KEEP_RETURN_VISIBLE and left the one-way parent resurrectable.
        _bookingStatusOverrides[rowKey] = 'COMPLETED';
        _bookings.removeWhere((x) => x.rowKey == rowKey);
        final remainingLegRows = _bookings
            .where(
              (x) =>
                  x.bookingId == bookingId &&
                  x.rowKey != rowKey &&
                  !_isClosedRideStatus(_effectiveStatusFor(x)),
            )
            .length;
        if (remainingLegRows > 0) {
          debugPrint(
            '[ROUNDTRIP_STATUS][KEEP_RETURN_VISIBLE] parent=$bookingId completed_row_key=$rowKey completed_leg=$legId leg_type=$legType remaining_open_leg_rows=$remainingLegRows',
          );
        } else {
          // Final/open leg of a one-way (or last open leg) completed: finalize
          // the parent locally so dashboard "Volgende rit" cannot resurrect it.
          _bookingStatusOverrides[bookingId] = 'COMPLETED';
          _bookings.removeWhere((x) => x.bookingId == bookingId);
          _deletedBookingIds.add(bookingId);
          _nextRidePreviewCache.clear();
          debugPrint(
            '[ROUNDTRIP_STATUS][PARENT_FINALIZE_LOCAL] parent=$bookingId completed_row_key=$rowKey completed_leg=$legId leg_type=$legType remaining_open_leg_rows=0',
          );
        }
      } else {
        _bookingStatusOverrides[bookingId] = 'COMPLETED';
        _bookings.removeWhere((x) => x.bookingId == bookingId);
        _deletedBookingIds.add(bookingId);
        _nextRidePreviewCache.clear();
      }
    });
    _markBookingsUiDirty();
    if (shouldSkipLegStatusCall) {
      // We skipped _setOperationalLegStatus which normally drives the post-
      // mutation snapshot fetch and refresh. Trigger the same reconciliation
      // here so the driver list, customer overlay and worker projection stay
      // aligned with the bridge-applied leg completion.
      unawaited(
        _debugFetchBookingSnapshot(
          bookingId: bookingId,
          contextLabel: 'LEG_STATUS_AFTER_PLANNED_STOP_BRIDGE',
        ),
      );
      unawaited(
        _refreshBookings(
          force: true,
          trigger: 'planned_stop_bridge_handled_leg',
        ),
      );
    }
  }

  Future<void> _ensureLocationPermission() async {
    final enabled = await geo.Geolocator.isLocationServiceEnabled();
    if (!enabled) {
      _toast(
        _tr(
          nl: 'Locatie is uitgeschakeld op het toestel.',
          en: 'Location is disabled on the device.',
          fr: 'La localisation est désactivée sur l’appareil.',
          es: 'La ubicación está desactivada en el dispositivo.',
        ),
      );
      return;
    }

    geo.LocationPermission perm = await geo.Geolocator.checkPermission();
    if (perm == geo.LocationPermission.denied) {
      perm = await geo.Geolocator.requestPermission();
    }
    if (perm == geo.LocationPermission.denied ||
        perm == geo.LocationPermission.deniedForever) {
      _toast(
        _tr(
          nl: 'Locatietoestemming geweigerd.',
          en: 'Location permission denied.',
          fr: 'Autorisation de localisation refusée.',
          es: 'Permiso de ubicación denegado.',
        ),
      );
      return;
    }
  }

  void _startTrackingInternal() {
    if (_posSub != null) {
      debugPrint(
        '[RIDES][TRACKING][SKIP_START] reason=already_active geolocatorSubs=$_activeGeolocatorSubscriptionCount',
      );
      return;
    }
    _stopBookingPolling(reason: 'tracking_started');

    // FLUXIDI NAV-STREETLEVEL-FLUID-MOTION-2 (Phase 1, Part C): use the
    // active-navigation location profile (AndroidSettings.intervalDuration
    // 500 ms + distanceFilter 0) so median GPS callback cadence is
    // sub-second instead of the platform's ~5 s default. The idle
    // buildDriverTrackingLocationSettings() profile is retained for
    // non-navigation code paths that may re-use it.
    final settings = buildDriverActiveNavigationLocationSettings();
    // NAV-PARKING-2 Commit 1: arm the bounded startup readiness gate for this
    // session so a parking/private-access departure does not immediately storm
    // complexity / opposite-direction reroutes on the first unmatched samples.
    _navSessionStartedAt = DateTime.now();
    _navStartupBootstrap.start();
    _lastNavBootstrapPhase = NavStartupBootstrapPhase.started;
    _navBootstrapPrevLat = null;
    _navBootstrapPrevLon = null;
    _lastKnownBearing = 0.0;
    _lastMovementBearing = null;
    _navGpsSubscriptionGeneration += 1;
    _activeGeolocatorSubscriptionCount = 1;
    debugPrint(
      '[NAV_GPS_SETTINGS] platform=${Platform.operatingSystem} '
      'intervalMs=${settings is geo.AndroidSettings ? settings.intervalDuration?.inMilliseconds ?? -1 : -1} '
      'distanceFilter=${settings.distanceFilter} '
      'accuracy=${settings.accuracy.name} '
      'subscriptionGen=$_navGpsSubscriptionGeneration',
    );

    // FLUXIDI Phase 2A: flag-off is a no-op. Flag-on installs the custom
    // Kotlin LocationProvider on the exact MapView so FollowPuck + puck-3D
    // own the camera + vehicle rendering while this navigation session is
    // active.
    unawaited(_activateNativeFollowIfLiveRide());

    _posSub = geo.Geolocator.getPositionStream(locationSettings: settings).listen((
      pos,
    ) {
      // NAV-MOBILE-DATA-MINIMAL-SAFE-RELEASE-P0-1 Part A: pure local
      // GPS/meter core. No Mapbox Future and no HTTP Future is awaited on
      // this callback; presentation and network work are handed off to
      // bounded latest-wins dispatchers so a stalled Mapbox annotation or a
      // 10-second mobile-data ping timeout can never block the next
      // accepted position.
      final meterCoreSw = Stopwatch()..start();
      final prev = _lastPos;
      _lastPos = pos;
      _startPos ??= pos;

      var meterChanged = false;

      if (prev != null) {
        final meters = geo.Geolocator.distanceBetween(
          prev.latitude,
          prev.longitude,
          pos.latitude,
          pos.longitude,
        );
        if (meters.isFinite && meters > 0) {
          // Only count driven distance once the trip is actually started.
          if (_liveRideActive && !_isWaiting) {
            _kmDriven += meters / 1000.0;
            meterChanged = true;
          } else if (_liveRideActive && _isWaiting) {
            debugPrint(
              '[METER][WAIT_DISTANCE_SKIPPED] meters=${meters.toStringAsFixed(1)} km=${_kmDriven.toStringAsFixed(3)}',
            );
          }
        }

        if (_liveRideActive && !_hasSwitchedToFollow && _startPos != null) {
          final movedFromStart = geo.Geolocator.distanceBetween(
            _startPos!.latitude,
            _startPos!.longitude,
            pos.latitude,
            pos.longitude,
          );
          final speedKmh = (pos.speed.isFinite ? (pos.speed * 3.6) : 0.0);
          if (speedKmh >= 3.0 || movedFromStart >= 25.0) {
            _hasSwitchedToFollow = true;
            _cameraMode = _CameraMode.follow;
          }
        }

        final movementBearing = _bearingFromPoints(
          prev.latitude,
          prev.longitude,
          pos.latitude,
          pos.longitude,
        );
        if (movementBearing != null && meters >= 1.8) {
          _lastMovementBearing = movementBearing;
        }
      }

      if (pos.heading.isFinite &&
          pos.heading >= 0 &&
          _speedKmhFor(pos) >= 2.0) {
        _lastKnownBearing = pos.heading;
      }

      _updateRouteSnapState(pos);
      _evaluateOffRouteReroute();

      // NAV-R12-D: marker geometry/rotation updates first and without
      // awaiting route redraw / camera / diagnostics — the taxi must move
      // on the fresh fix, not after the heavy pipeline. Manager loss no
      // longer blocks this path; it triggers self-heal instead.
      final canDriveMap = _mapSupported && _map != null && !_mapStyleChanging;
      final navDispatchSw = Stopwatch()..start();
      if (canDriveMap) {
        _refreshNavEngineForPosition(pos);
        _scheduleDriverMarkerFastUpdate(pos);
        // NAV-R12-E1: camera follow schedules on the fresh fix too, not
        // behind the awaited route-line/diagnostics work. Throttle,
        // in-flight, and GPS-quality gates live inside _followCameraTesla;
        // queued targets use last-wins semantics.
        if (_cameraMode == _CameraMode.follow) {
          unawaited(_followCameraTesla(pos));
        }
      }
      navDispatchSw.stop();
      // NAV-LATENCY-1 (Part A): bounded, non-PII GPS->engine dispatch trace.
      _recordNavLatencyGpsCallback(
        pos,
        accepted: canDriveMap,
        engineDispatchDtMs: navDispatchSw.elapsedMilliseconds,
      );

      // NAV-MOBILE-DATA-MINIMAL-SAFE-RELEASE-P0-1 Part C: enqueue route line
      // presentation on the bounded latest-wins dispatcher. Older pending
      // positions are replaced; the GPS callback never awaits this work.
      _routePresentationDispatcher.enqueue(pos);

      _syncNavDiagSession();
      _recordNavDiagGpsUpdate(
        pos,
        prev,
        metersFromPrev: prev != null
            ? geo.Geolocator.distanceBetween(
                prev.latitude,
                prev.longitude,
                pos.latitude,
                pos.longitude,
              )
            : null,
      );
      _maybeAddNavValidationSample(pos);
      final uiBearing = _adaptiveBearingFor(pos, snap: _lastRouteSnap).bearing;
      _uiArrowBearing = uiBearing;
      _updateNextNavInstruction(pos);

      // NAV-MOBILE-DATA-MINIMAL-SAFE-RELEASE-P0-1 Part B: enqueue the
      // tracking-ping on the bounded latest-wins dispatcher. Older pending
      // positions are replaced; the GPS callback never awaits HTTP.
      _pingDispatcher.enqueue(pos);

      meterCoreSw.stop();
      _navAcceptedGpsSequence += 1;
      logNavAcceptedGpsMeter(
        sequence: _navAcceptedGpsSequence,
        monotonicMs: DateTime.now().millisecondsSinceEpoch,
        meterCoreMicros: meterCoreSw.elapsedMicroseconds,
      );

      // NAV-MOBILE-DATA-MINIMAL-SAFE-RELEASE-P0-1 Part E: publish an
      // updated meter snapshot through the dedicated notifier so the
      // Tellers / HUD subtrees update independently of the MapWidget
      // subtree. Skipped when nothing meter-relevant changed to avoid
      // needless notification storms.
      if (meterChanged) {
        _publishDriverRideMetersSnapshot();
      }
    });
    _activeGeolocatorSubscriptionCount = 1;
    debugPrint(
      '[RIDES][TRACKING][START] geolocatorSubs=$_activeGeolocatorSubscriptionCount',
    );
  }

  void _stopTrackingInternal() {
    if (_posSub == null) return;
    _resetNavValidationState(flushReport: true);
    _posSub?.cancel();
    _posSub = null;
    _activeGeolocatorSubscriptionCount = 0;
    debugPrint(
      '[RIDES][TRACKING][STOP] geolocatorSubs=$_activeGeolocatorSubscriptionCount',
    );
    // FLUXIDI NAV-STREETLEVEL-FLUID-MOTION-2 (Phase 1, Part D): resume any
    // background driver/company hydration that was deferred while nav was
    // running. Exactly one refresh is scheduled per active-nav window,
    // outside the camera / GPS / model hot path.
    if (_bootstrapDeferredDuringActiveNav) {
      _bootstrapDeferredDuringActiveNav = false;
      Future<void>.microtask(() {
        if (!mounted) return;
        unawaited(
          _refreshDriverAvailabilityFromBackend(
            reason: 'resume_after_active_nav',
            force: true,
          ),
        );
      });
    }
    _startPos = null;
    _lastFollowCameraAt = null;
    // NAV-PARKING-2 Commit 1: tear down startup readiness + proximity arrival so
    // no state (including a leaked heading) survives into the next session.
    _navStartupBootstrap.reset();
    _navParkingArrival.reset();
    _navParkingArrivalConfirmed = false;
    _lastNavArrivalEvent = null;
    _navSessionStartedAt = null;
    _navBootstrapPrevLat = null;
    _navBootstrapPrevLon = null;
    _lastKnownBearing = 0.0;
    // NAV-CAMERA-INFLIGHT-SELF-HEAL-1: invalidate clears owner + pending and
    // bumps the run generation so any in-flight flyTo completing after stop
    // becomes a stale no-op.
    _cameraInFlightLifecycle.invalidate(reason: 'navigation_stop');
    // Tellers is presentation-only — return to Navigatie when tracking stops.
    _navPresentationMode.reset();
    // NAV-PARKING-2 Commit 4: drop any Tellers viewport so a new session starts
    // clean and no stale viewport callback survives a stop/start cycle.
    _tellersViewport.reset();
    _gpsQualityWeak = false;
    _lastSmoothedCameraBearing = null;
    _stopStreetlevelFollowPump();
    // FLUXIDI Phase 2A: tear down the native FollowPuck session cleanly so
    // the stock Mapbox location component regains ownership on the next
    // map style / mode transition. Flag-off is a no-op.
    if (_nativeFollow != null) {
      unawaited(_nativeFollow!.disable());
    }
    // NAV-R12-D: active navigation stopped — reset marker self-heal state.
    _markerSelfHealTimer?.cancel();
    _markerSelfHealTimer = null;
    _pendingMarkerUpdatePos = null;
    _consecutiveMarkerUpdateFailures = 0;
    _markerLifecycle.reset();
    _resetDriverVehicleModelMovementSync();
    // NAV-R12-E1: drop any queued camera target.
    _resetPendingFollowCamera();
    _driverNavEngine.reset();
    _lastNavEngineOutput = null;
    _lastNavEngineRefreshKey = null;
    _resetNavR3MotionState();
    _resetNavRouteProgressState();
    _resetNavCameraPolicyState();
    _resetNavConfidenceState();
    _resetNavComplexityState();
    _resetNavMotionPredictionState();
    _resetNavInstructionPolicyState();
    if (!_liveRideActive) {
      _startBookingPolling(reason: 'tracking_stopped');
    }
  }

  /// ===============================
  /// HUD COMPUTED TEXTS (single source of truth)
  /// ===============================

  bool get _isTracking => _liveRideActive && _posSub != null;

  String get _etaText {
    // NAVIGATION-SINGLE-ACTIVE-TARGET-TRUTH-P0-5: never invent <1 min while
    // the active-target route is missing/stale.
    final truth = _resolveActiveRemainingDistanceTruth();
    final fromTruth = formatNavEtaText(truth);
    if (fromTruth.isNotEmpty) return fromTruth;
    if (!truth.routeReady) return '';
    final total = _routeDurationSec;
    if (total == null || total <= 0) return '';
    int remainingSec;
    if (_isTracking) {
      remainingSec = _timeRemainingSeconds ?? total;
    } else {
      remainingSec = total;
    }
    remainingSec = math.max(0, remainingSec);
    if (remainingSec < 60) return '<1 min';
    final minutes = (remainingSec / 60).ceil();
    if (minutes < 60) return '$minutes min';
    final h = minutes ~/ 60;
    final m = minutes % 60;
    if (m == 0) return '${h}h';
    return '${h}h ${m}m';
  }

  String get _kmRemainingText {
    // NAVIGATION-SINGLE-ACTIVE-TARGET-TRUTH-P0-5: missing route → '' (UI —),
    // never fake 0.0 km.
    final truth = _resolveActiveRemainingDistanceTruth();
    final fromTruth = formatNavRemainingKmText(truth);
    if (fromTruth.isNotEmpty || !truth.routeReady) return fromTruth;
    final remaining = _kmRemaining;
    if (remaining == null) return '';
    if (remaining < 0.05) return '0.0';
    return remaining.toStringAsFixed(1);
  }

  String get _timeRemainingText {
    if (!_isTracking) return '';
    final sec = _timeRemainingSeconds;
    if (sec == null) return '';
    final minutes = (sec / 60.0).round();
    if (minutes <= 0) return '0m';
    if (minutes < 60) return '${minutes}m';
    final h = minutes ~/ 60;
    final m = minutes % 60;
    return '${h}h ${m}m';
  }

  double? get _kmRemaining {
    final rk = _routeKm;
    if (rk == null) return null;

    // ✅ Countdown starts only once we actually move (Google Maps style).
    // Before movement, keep the full route distance as "remaining".
    if (_isTracking && !_hasSwitchedToFollow) return rk;

    final v = rk - _kmDriven;
    return v < 0 ? 0 : v;
  }

  int? get _timeRemainingSeconds {
    final total = _routeDurationSec;
    final rk = _routeKm;
    if (total == null || rk == null) return null;

    // ✅ Countdown starts only once we actually move (Google Maps style).
    if (_isTracking && !_hasSwitchedToFollow) return total;

    if (rk <= 0.01) return total;
    final fracDriven = (_kmDriven / rk).clamp(0.0, 1.0);
    final remaining = (total * (1.0 - fracDriven)).round();
    return remaining < 0 ? 0 : remaining;
  }

  /// Map HUD actions
  Future<void> _stopTracking() async {
    // Stop UI + pings immediately (best UX)
    _stopTrackingInternal();

    // Try to notify Worker (best-effort)
    try {
      await _stopTrip();
    } catch (_) {
      // ignore
    }

    if (!mounted) return;
    setState(() {});
  }

  Future<void> _openNavigation() async {
    // NAV-RELEASE-FINAL-FLOW-1: direct street draft is already at pickup A
    // (current driver position). Do not expose a preview-refresh NAV action.
    if (!navToPickupActionVisible(
      hasBooking: _activeBooking != null,
      directRideDraft: _directRideDraft,
      directRideActive: _directRideActive,
    )) {
      return;
    }
    final booking = _activeBooking;
    if (booking != null &&
        !_canOperateBookingWithGuard(
          _bookingScopeViewFor(booking),
          action: 'open_navigation',
        )) {
      _logDriverNavDiag(
        tag: 'BLOCK',
        action: 'open_navigation',
        bookingId: booking.bookingId,
      );
      return;
    }
    _logDriverNavDiag(
      tag: 'OPEN_RIDE',
      action: 'open_navigation',
      bookingId: booking?.bookingId,
    );
    if (_isBusinessPreviewMode) {
      _logDriverNavDiag(
        tag: 'BUSINESS_PREVIEW_KEEP_DRIVER',
        action: 'open_navigation',
        bookingId: booking?.bookingId,
      );
    }

    // GOOGLE-MAPS-WITH-FLUXIDI-PIP-RELEASE-1: ask per NAV start (no settings
    // preference contract exists for nav provider yet).
    if (!mounted) return;
    final choice = await showNavigationProviderChoiceDialog(
      context,
      tr: _tr,
    );
    if (!mounted || choice == null) return;
    if (choice == NavigationProviderChoice.googleMapsWithMeter) {
      await _launchGoogleMapsWithFluxidiPip(
        phase: _resolveExternalNavPhase(),
      );
      return;
    }

    // Fluxidi-navigatie: end any prior Google Maps session first.
    if (_externalNavigationSession != null) {
      await _endExternalNavigationSession(reason: 'switch_to_fluxidi_nav');
    }

    // NAV always forces follow mode for live street-level navigation.
    if (_map == null) return;

    setState(() {
      _cameraMode = _CameraMode.follow;
      _hasSwitchedToFollow = true;
      _followCar = true;
      _allowOverviewCamera = false;
      _navCameraViewMode = NavCameraViewMode.streetView;
      // NAV-RELEASE-FINAL-FLOW-1: unmetered guidance begins — style locks,
      // fixed streetlevel owns the camera. Paid metering still requires START.
      _navigationGuidanceActive = true;
    });
    _setNavigationWakelock(true);
    await _applyMapStyleForMode();
    await _syncMapboxUserLocationPuckVisibility();
    await _forceFollowCameraNow(caller: 'nav_button');
    unawaited(_reconcileMapZoomGestures(reason: 'nav_button'));
    final b = _activeBooking;
    final target = decideNavOpenRouteTarget(
      hasBooking: b != null,
      tripActive: _activeTripId != null,
      hasDirectDestination:
          (_directRideDestinationText ?? '').trim().isNotEmpty,
      directRideActive: _directRideActive,
    );
    switch (target) {
      case NavOpenRouteTarget.toPickup:
        await _buildNavRouteToPickup(b!);
      case NavOpenRouteTarget.toDropoff:
        if (b != null) {
          await _buildNavRouteToDestination(b);
        } else {
          await _buildDirectRouteToDestination(
            _directRideDestinationText!.trim(),
          );
        }
      case NavOpenRouteTarget.none:
        break;
    }
    unawaited(_syncNavigationDestinationMarker(reason: 'nav_open'));
  }

  Future<void> _openDirectRideEntry() async {
    if (_scaffoldKey.currentState?.isDrawerOpen ?? false) {
      Navigator.of(context).pop();
    }
    final destination = await showDialog<DirectRideDestinationResult>(
      context: context,
      builder: (_) => DirectRideDestinationDialog(
        themeListenable: _activeDriverThemeListenable,
        initialText: _directRideDestinationText ?? '',
        search: (query) async {
          final results = await _fetchPlaceSuggestions(query);
          return results
              .map(
                (s) => DirectRideSuggestion(
                  label: s.label,
                  lon: s.lon,
                  lat: s.lat,
                ),
              )
              .toList(growable: false);
        },
        tr: _tr,
      ),
    );
    if (!mounted || destination == null || destination.label.trim().isEmpty)
      return;
    await Future<void>.delayed(Duration.zero);
    if (!mounted) return;
    final selectedPoint = (destination.lon != null && destination.lat != null)
        ? _LonLat(destination.lon!, destination.lat!)
        : null;

    setState(() {
      _activeBooking = null;
      _activeTripId = null;
      _activeDirectTripId = null;
      _activeDirectBookingId = null;
      _directRideKey = null;
      _directRideActive = false;
      _directTripStartWorkerOk = false;
      _directTripStopWorkerOk = false;
      _directRideDestinationText = destination.label.trim();
      _directRideDestinationPoint = selectedPoint;
      _kmDriven = 0.0;
      _resetNavProgressState(
        clearRoute: true,
        renderInvalidateReason: 'phase_change',
      );
      _routePhase = _RideRoutePhase.trip;
      _cameraMode = _CameraMode.follow;
      _hasSwitchedToFollow = true;
      _followCar = true;
      // NAV-RELEASE-FINAL-FLOW-1: destination + route open under the
      // single fixed streetlevel camera owner. Overview / fitBounds must not
      // own the preview surface. Style remains available until NAV/START.
      _allowOverviewCamera = false;
      _navCameraViewMode = NavCameraViewMode.streetView;
      _navigationGuidanceActive = false;
      _isWaiting = false;
      _waitStartedAt = null;
      _waitElapsed = Duration.zero;
      _trackingStartedAt = null;
      _directRideEstimatedFare = null;
      _directRideEstimateLoading = false;
      _directRideEstimateError = null;
      _directRideEstimateCurrency = kDefaultCurrency;
      _directRideEstimateSignature = null;
      _directRideLocationRetryCount = 0;
      _directRideLocationRetryDestination = _directRideDestinationText;
    });
    _toast(
      _tr(
        nl: 'Straatrit klaar. Druk START om te rijden.',
        en: 'Street ride is ready. Press START to drive.',
        fr: 'Course de rue prête. Appuyez sur START pour rouler.',
        es: 'El viaje de calle está listo. Pulsa START para conducir.',
      ),
    );
    _scheduleDirectRideEstimateRefresh(reason: 'destination_changed');
    // NAV-PRESTART-PREVIEW-AND-STABLE-BEARING-P0 (Problem 1): present the
    // calculated route immediately. Continue used to leave the map empty until
    // START, which also kept every route-dependent control hidden.
    await _buildDirectRidePreviewRoute(_directRideDestinationText ?? '');
    // NAV-RELEASE-FINAL-FLOW-1: seed GPS + persisted Car/Arrow without
    // requiring the marker selector; pings stay gated on a live trip id.
    if (_posSub == null) {
      _startTrackingInternal();
    }
    unawaited(
      _attemptTaxiMarkerRestore(attempt: 0, reason: 'direct_preview_ready'),
    );
    unawaited(_reconcileMapZoomGestures(reason: 'direct_preview_ready'));
  }

  Future<void> _startDirectRide() async {
    // SECURITY-REMOVE-CLIENT-ADMIN-TOKEN-P0-1 (Field Failure Fix, Commit 2):
    // refuse client-side when no valid driver-session bearer is available.
    if (!_driverRideStartAuthAllowsOrRefuse(action: 'start_direct_ride')) {
      return;
    }
    final destination = (_directRideDestinationText ?? '').trim();
    if (destination.isEmpty) {
      await _openDirectRideEntry();
      return;
    }
    await _ensureLocationPermission();
    var pos = _lastPos;
    if (pos == null) {
      try {
        pos = await geo.Geolocator.getCurrentPosition(
          desiredAccuracy: geo.LocationAccuracy.best,
        );
        _lastPos = pos;
      } catch (_) {
        pos = null;
      }
    }
    if (pos == null) {
      _toast(
        _tr(
          nl: 'GPS-locatie nog niet beschikbaar',
          en: 'GPS location not available yet',
          fr: 'Position GPS pas encore disponible',
          es: 'Ubicación GPS aún no disponible',
        ),
      );
      return;
    }

    // COMMERCIAL-ENTITLEMENT-FLUTTER-P0: authorize with the tracking worker
    // BEFORE any local ride / meter / GPS / durable state is created.
    final directRideKey = makeDirectRideKey(
      driverId: kDriverId,
      startedAtMs: DateTime.now().toUtc().millisecondsSinceEpoch,
    );
    final workerResult = await _startDirectTripSessionOnWorker(
      destination: destination,
      directRideKey: directRideKey,
      requireLiveLocalRide: false,
    );
    if (workerResult.isEntitlementDenied) {
      _toast(
        companyEntitlementDeniedMessage(
          languageCode: _fluxidiLanguageCode(),
        ),
      );
      return;
    }
    if (workerResult.isAuthDenied) {
      _toast(
        _tr(
          nl: 'Sessie verlopen. Meld opnieuw aan als chauffeur.',
          en: 'Session expired. Sign in again as driver.',
          fr: 'Session expirée. Reconnectez-vous en tant que chauffeur.',
          es: 'Sesión caducada. Vuelve a iniciar sesión como conductor.',
        ),
      );
      return;
    }
    // transportOrOther: still allow local start (offline resilience).

    _hardClearAtRideBoundary(reason: 'street_ride_start', bumpSession: true);
    final directPt = _directRideDestinationPoint;
    _installActiveNavTarget(
      bookingId: directRideKey,
      phase: ActiveNavigationPhase.passengerLeg,
      targetLat: directPt?.lat,
      targetLng: directPt?.lon,
      targetAddress: destination,
      reason: 'street_ride_start',
    );
    _applyActiveRideStartStyleDecision(reason: 'street_ride_start');
    final workerOk = workerResult.isOk;
    setState(() {
      _directRideActive = true;
      _activeTripId = null;
      _directRideKey = directRideKey;
      _activeDirectTripId = workerOk ? workerResult.tripId : null;
      _activeDirectBookingId = workerOk ? workerResult.bookingId : null;
      _directTripStartWorkerOk = workerOk;
      _directTripStopWorkerOk = false;
      _activeBooking = null;
      _cameraMode = _CameraMode.follow;
      _hasSwitchedToFollow = true;
      _followCar = true;
      _allowOverviewCamera = false;
      _kmDriven = 0.0;
      _trackingStartedAt = DateTime.now();
      _isWaiting = false;
      _waitStartedAt = null;
      _waitElapsed = Duration.zero;
    });
    _publishBearerBusyState();
    _logNavRideBoundary(
      event: NavRideBoundaryEvent.sessionStarted,
      extra: 'reason=street_ride_start',
    );
    _setNavigationWakelock(true);
    await _applyMapStyleForMode();
    _startTrackingInternal();
    _startMeterTicker();
    if (workerOk) {
      unawaited(_persistDirectTripSession(
        localLifecycle: kDirectTripLocalLifecycleActive,
        bookingFinalizeState: kDirectTripFinalizePending,
      ));
    } else {
      unawaited(
        _startDirectTripSessionOnWorker(
          destination: destination,
          directRideKey: directRideKey,
          requireLiveLocalRide: true,
        ),
      );
    }
    await _forceFollowCameraNow(caller: 'direct_ride_start');
    await _buildDirectRouteToDestination(destination);
    unawaited(_reconcileMapZoomGestures(reason: 'direct_ride_start'));
    unawaited(_maybeRelaunchGoogleMapsAfterStart());
  }

  void _handleCockpitStart() {
    // SECURITY-REMOVE-CLIENT-ADMIN-TOKEN-P0-1 (Field Failure Fix, Commit 2):
    // gate the cockpit START button so it never dispatches into a
    // driver-lifecycle path without a valid driver-session bearer. Downstream
    // handlers repeat the check as defence-in-depth.
    if (!_driverRideStartAuthAllowsOrRefuse(action: 'cockpit_start')) {
      return;
    }
    final b = _activeBooking;
    if (b != null) {
      _startTrip(b);
      return;
    }
    if (_directRideDraft || _directRideActive) {
      _startDirectRide();
      return;
    }
    _toast(
      _tr(
        nl: 'Kies eerst een rit of start een straatrit.',
        en: 'Choose a ride first or start a street ride.',
        fr: 'Choisissez d’abord une course ou démarrez une course de rue.',
        es: 'Elige primero un viaje o inicia un viaje de calle.',
      ),
    );
  }

  Future<void> _sendPing(geo.Position pos) async {
    final trip = _activeTripId;
    if (trip == null) return;

    try {
      final strictScope = _strictBookingScopeForMutation(
        action: 'trip_ping',
        showUx: false,
      );
      if (strictScope == null) return;
      final uri = _uriWithScope(kWorkerBaseUrl, kPingPath, strictScope);
      final actorVehicleId = _directRideVehicleId();
      final payload = {
        'session_id': trip,
        'driver_id': kDriverId,
        'vehicle_id': actorVehicleId,
        ...strictScope,
        'lat': pos.latitude,
        'lon': pos.longitude,
        'speed': (pos.speed.isFinite ? (pos.speed * 3.6) : 0.0),
        'heading': (pos.heading.isFinite ? pos.heading : 0.0),
        'accuracy_m': pos.accuracy,
        'ts': DateTime.now().toIso8601String(),
        ..._driverMutationActorFields(actorVehicleId: actorVehicleId),
      };

      final res = await http
          .post(uri, headers: _driverBearerHeaders(), body: jsonEncode(payload))
          .timeout(const Duration(seconds: 10));

      if (!mounted) return;

      setState(() {
        _pingCount += 1;
        _lastPing = (res.statusCode == 200) ? 'OK' : 'HTTP ${res.statusCode}';
      });
    } catch (_) {
      if (!mounted) return;
      setState(() => _lastPing = 'ERR');
    }
  }

  Future<void> _onMapCreated(mb.MapboxMap mapboxMap) async {
    debugPrint('[MAP][CREATED] style=$_activeMapStyleUri');
    _map = mapboxMap;
    // NAV-HIDE-MAPBOX-SCALEBAR-P0-1: the Mapbox measurement scale bar (a
    // Mapbox ornament, distinct from `attribution` and `logo`) adds no value
    // during turn-by-turn driver navigation and can compete with the top
    // maneuver banner. Mapbox enables it by default; disable it once here.
    //
    // Ornament settings are map-instance state and persist across style
    // reloads — one-shot application at map-create time is sufficient. Best
    // effort so any plugin/channel hiccup can never break map creation.
    //
    // Explicitly does NOT touch `mapboxMap.attribution` or `mapboxMap.logo`
    // — Mapbox terms compliance is preserved unchanged.
    unawaited(_hideMapboxScaleBarBestEffort(mapboxMap));
    unawaited(_reconcileMapZoomGestures(reason: 'map_created'));
    // FLUXIDI Phase 2A: create the native-follow controller keyed by the
    // exact plugin-owned map instance id. Behind the build-time flag; a
    // flag-off build never enables the native session even though the
    // controller is constructed (this preserves flag-off byte-parity with
    // the Phase 1 fallback).
    _initializeNativeFollowController(mapboxMap);
    await _syncMapboxUserLocationPuckVisibility();
    await _applyMapStyleForMode();
    await _recreateAnnotationManagers();
    await _syncMapboxUserLocationPuckVisibility();

    final pos = _lastPos;
    if (pos != null) {
      await _updateDriverMarker(
        pos,
        moveCamera: _cameraMode != _CameraMode.follow,
      );
      if (_cameraMode == _CameraMode.follow) {
        await _followCameraTesla(pos, force: true);
      }
    }
  }

  /// NAV-HIDE-MAPBOX-SCALEBAR-P0-1: disable the Mapbox measurement scale bar
  /// ornament on this map instance. Independent of `attribution` and `logo`
  /// (which remain enabled at their Mapbox defaults so terms compliance is
  /// preserved). Best effort — a channel failure must never break map
  /// creation. PII-free bounded diagnostic on transition only.
  Future<void> _hideMapboxScaleBarBestEffort(mb.MapboxMap mapboxMap) async {
    try {
      await mapboxMap.scaleBar.updateSettings(
        mb.ScaleBarSettings(enabled: false),
      );
      debugPrint('[MAP][SCALEBAR] enabled=false reason=nav_hide_p0_1');
    } catch (_) {
      // NAV-SCALEBAR-DIAGNOSTIC-SANITIZE-1: never interpolate the exception
      // payload. Ornament failures are decorative — the fixed bounded line
      // is enough to trace, and it can never leak PII, tokens or plugin
      // internals through the log.
      debugPrint('[MAP][SCALEBAR][WARN] failed_to_disable');
    }
  }

  /// NAV-RELEASE-FINAL-FLOW-1 / NAV-PHASE-CAMERA-TARGET-1: when the fixed
  /// HUD owns the surface, disable every Mapbox interaction that could
  /// move, rotate, tilt or scale the map beneath the screen-fixed Car —
  /// pan and rotate and pitch were still enabled on c241f39 so a stray
  /// touch shifted the map underneath the fixed marker.
  Future<void> _reconcileMapZoomGestures({required String reason}) async {
    final map = _map;
    if (map == null) return;
    final lock = resolveNavPhaseGestureLock(phase: _navFixedHudPhase);
    try {
      await map.gestures.updateSettings(
        mb.GesturesSettings(
          pinchToZoomEnabled: lock.pinchToZoomEnabled,
          doubleTapToZoomInEnabled: lock.doubleTapToZoomInEnabled,
          doubleTouchToZoomOutEnabled: lock.doubleTouchToZoomOutEnabled,
          quickZoomEnabled: lock.quickZoomEnabled,
          scrollEnabled: lock.scrollEnabled,
          rotateEnabled: lock.rotateEnabled,
          pitchEnabled: lock.pitchEnabled,
        ),
      );
      debugPrint(
        '[MAP][GESTURES] lockAll=${lock.allInteractionsDisabled} '
        'phase=${navFixedHudPhaseLabel(_navFixedHudPhase)} '
        'reason=$reason',
      );
    } catch (_) {
      // Best effort — never break navigation for a gesture-channel failure.
    }
  }

  void _initializeNativeFollowController(mb.MapboxMap mapboxMap) {
    if (!kNavigationUseNativeFollowPuckEnabled) return;
    final existing = _nativeFollow;
    if (existing != null &&
        existing.mapInstanceId == mapboxMap.fluxidiMapInstanceId) {
      return;
    }
    _nativeFollow = NativeFollowController(
      mapInstanceId: mapboxMap.fluxidiMapInstanceId,
    );
    unawaited(_activateNativeFollowIfLiveRide());
  }

  Future<void> _activateNativeFollowIfLiveRide() async {
    final controller = _nativeFollow;
    if (controller == null) return;
    if (!_liveRideActive) return;
    if (!_isActiveDriverNavEngineContext()) return;
    final ok = await controller.enable();
    if (!ok) return;
    _pushNativeFollowVehiclePreset();
    _pushNativeFollowViewport();
    // NAV-3D-P0: undo any prior Dart location-component suppression so the
    // native LocationPuck3D remains visible after enable.
    unawaited(_syncMapboxUserLocationPuckVisibility());
  }

  void _pushNativeFollowVehiclePreset() {
    final controller = _nativeFollow;
    if (controller == null) return;
    // NAV-3D-P0: native LocationPuck3D follows the authoritative presentation
    // choice — never install a 3D puck while the user selected taxi2d.
    if (!driverVehiclePresentationChoiceIs3d(
      _driverVehiclePresentationChoice,
    )) {
      return;
    }
    final preset = buildNativeVehiclePreset(
      mapInstanceId: controller.mapInstanceId,
      preset: _driverVehicle3dPreset,
    );
    if (preset == null) return;
    // Ownership stays on HUD until the current configure generation is
    // acknowledged — never claim native3d from requestedChoice alone.
    unawaited(() async {
      final ok = await controller.setVehiclePreset(preset);
      if (!mounted || !ok) return;
      await _syncMapboxUserLocationPuckVisibility();
      if (!mounted) return;
      _logNav3dOwnerTransition(
        previousOwner: 'hud2d',
        nextOwner: 'native3d',
        reason: 'native_preset_acknowledged',
        temporaryFallback: false,
      );
      setState(() {});
    }());
  }

  /// Whether Native FollowPuck is the credibly active 3D vehicle renderer.
  ///
  /// NAV-3D-P0: requires session + acknowledged current configure generation +
  /// live navigation + location component not suppressed. Style readiness is
  /// applied by eligibility (`nativeOwns = this && eligible`).
  bool _native3dRendererActiveForChoice() {
    final controller = _nativeFollow;
    final presetCrediblyActive =
        controller?.isVehiclePresetCrediblyActive ?? false;
    return resolveNative3dRendererCrediblyActive(
      requested3d: driverVehiclePresentationChoiceIs3d(
        _driverVehiclePresentationChoice,
      ),
      nativeFollowSessionActive: _nativeFollowIsActive(),
      nativePresetConfigureAcknowledged: presetCrediblyActive,
      nativeCommandGenerationCurrent: presetCrediblyActive,
      navigationStoppingOrDisposing: !_liveRideActive,
      locationComponentEnabledForNative: !_mapboxLocationPuckSuppressedForNav,
    );
  }

  String? _lastNav3dOwnerTransitionSignature;

  void _logNav3dOwnerTransition({
    required String previousOwner,
    required String nextOwner,
    required String reason,
    required bool temporaryFallback,
  }) {
    final signature =
        '$previousOwner|$nextOwner|$reason|$temporaryFallback|'
        '${_driverVehiclePresentationChoice.name}|$_driverVehicle3dPreset|'
        '${_nativeFollowIsActive()}|$_routeStepsVersion';
    if (signature == _lastNav3dOwnerTransitionSignature) return;
    _lastNav3dOwnerTransitionSignature = signature;
    debugPrint(
      '[NAV_3D_OWNER_TRANSITION] '
      'requestedChoice=${driverVehiclePresentationChoiceLogLabel(_driverVehiclePresentationChoice)} '
      'preset=${driverVehicle3dPresetLogLabel(_driverVehicle3dPreset)} '
      'previousOwner=$previousOwner '
      'nextOwner=$nextOwner '
      'rendererKind=${_nativeFollowIsActive() ? 'native3d' : 'model3d'} '
      'eligibility=${_driver3dVehicleEligibility().reason} '
      'reason=$reason '
      'temporaryFallback=$temporaryFallback '
      'styleFamily=${DriverCockpitMap3dCapability.resolve(styleUri: _activeMapStyleUri.trim(), visualMode: _driverMapVisualMode).styleFamily} '
      'styleGeneration=$_driver3dVehicleStyleGeneration '
      'ackStyleGeneration=$_driver3dVehicleActivationStyleGeneration '
      'presetGeneration=$_vehicleSwapGeneration '
      'ackPresetGeneration=$_driver3dVehicleActivationPresetGeneration '
      'firstPoseApplied=$_driver3dVehicleModelPoseApplied '
      'activationConfirmed=$_driver3dVehicleModelActivationConfirmed '
      'nativeFollowEnabled=${_nativeFollowIsActive()} '
      'routeVersion=$_routeStepsVersion '
      'transitionGeneration=$_vehicleSwapGeneration',
    );
  }

  void _pushNativeFollowViewport() {
    final controller = _nativeFollow;
    if (controller == null) return;
    final zoom = _streetlevelFollowZoom;
    final pitch = _streetlevelFollowPitch;
    final padding = _streetlevelFollowPadding;
    if (zoom == null || pitch == null) return;
    unawaited(
      controller.setViewport(
        native_follow_wire.NativeFollowViewport(
          mapInstanceId: controller.mapInstanceId,
          zoom: zoom,
          pitch: pitch,
          paddingTop: padding?.top,
          paddingBottom: padding?.bottom,
          paddingLeft: padding?.left,
          paddingRight: padding?.right,
        ),
      ),
    );
  }

  bool _hasActiveDriverTaxiMarker() {
    return _driverMarker != null &&
        _driverPointManager != null &&
        !_mapStyleChanging;
  }

  bool _isFluxidiRoutePreviewOrNav() {
    return _liveRideActive ||
        _directRideActive ||
        _directRideDraft ||
        _activeBooking != null ||
        _routeCoords.length >= 2 ||
        _cameraMode == _CameraMode.follow;
  }

  String _puckHideReason() {
    // NAV-3D-P0: Native FollowPuck owns LocationPuck3D through the location
    // component — never treat that as a hideable "user location puck".
    if (_nativeFollowIsActive()) return 'native_follow_owns_puck';
    if (_isFluxidiRoutePreviewOrNav()) return 'route_context';
    if (_hasActiveDriverTaxiMarker()) return 'has_taxi_marker';
    if (_cameraMode == _CameraMode.follow && _liveRideActive) {
      return 'follow_live';
    }
    return 'idle';
  }

  bool _shouldHideMapboxUserLocationPuck() {
    return resolveShouldHideMapboxUserLocationPuck(
      nativeFollowActive: _nativeFollowIsActive(),
      routePreviewOrNav: _isFluxidiRoutePreviewOrNav(),
      hasActiveTaxiMarker: _hasActiveDriverTaxiMarker(),
      followLiveActive: _cameraMode == _CameraMode.follow && _liveRideActive,
    );
  }

  Future<void> _syncMapboxUserLocationPuckVisibility() async {
    final map = _map;
    if (map == null || !_mapSupported) return;

    // NAV-3D-P0: when Native Follow owns the vehicle, undo any prior nav
    // suppression so LocationPuck3D can stay visible across GPS/style syncs.
    if (_nativeFollowIsActive()) {
      final reason = _puckHideReason();
      try {
        if (_mapboxLocationPuckSuppressedForNav ||
            _lastSyncedMapboxPuckHidden == true) {
          await map.location.updateSettings(
            mb.LocationComponentSettings(enabled: true),
          );
          _mapboxLocationPuckSuppressedForNav = false;
          _lastSyncedMapboxPuckHidden = false;
          _logNavBounded(
            'NAV_UI_R6D_PUCK',
            'hidden=false reason=$reason follow=${_cameraMode == _CameraMode.follow} live=$_liveRideActive',
            intervalMs: 3000,
          );
        }
      } catch (_) {
        // Native manager still owns the puck; ignore restore races.
      }
      return;
    }

    final hide = _shouldHideMapboxUserLocationPuck();
    final reason = _puckHideReason();
    try {
      if (hide) {
        if (!_mapboxLocationPuckSuppressedForNav) {
          final settings = await map.location.getSettings();
          _mapboxLocationPuckRestoreEnabled = settings.enabled ?? false;
          _mapboxLocationPuckSuppressedForNav = true;
        }
        await map.location.updateSettings(
          mb.LocationComponentSettings(
            enabled: false,
            pulsingEnabled: false,
            showAccuracyRing: false,
            puckBearingEnabled: false,
          ),
        );
      } else if (_mapboxLocationPuckSuppressedForNav) {
        await map.location.updateSettings(
          mb.LocationComponentSettings(
            enabled: _mapboxLocationPuckRestoreEnabled,
          ),
        );
        _mapboxLocationPuckSuppressedForNav = false;
      }

      if (_lastSyncedMapboxPuckHidden != hide) {
        _lastSyncedMapboxPuckHidden = hide;
        _logNavBounded(
          'NAV_UI_R6D_PUCK',
          'hidden=$hide reason=$reason follow=${_cameraMode == _CameraMode.follow} live=$_liveRideActive',
          intervalMs: 3000,
        );
      }
    } catch (_) {
      _logNavBounded(
        'NAV_UI_R6D_PUCK',
        'hidden=$hide reason=sync_failed',
        intervalMs: 5000,
      );
    }
  }

  bool get _canUpdateDriverMarker =>
      !_mapStyleChanging && _map != null && _driverPointManager != null;

  bool _isMapboxAnnotationManagerLost(Object e) {
    if (classifyPolylineAnnotationDeleteError(e) ==
        NavPolylineDeleteErrorClass.managerLost) {
      return true;
    }
    final blob = e.toString().toLowerCase();
    if (e is PlatformException) {
      final message = (e.message ?? '').toLowerCase();
      final details = (e.details?.toString() ?? '').toLowerCase();
      return blob.contains('no manager found') ||
          message.contains('no manager found') ||
          details.contains('no manager found');
    }
    return blob.contains('no manager found');
  }

  NavPolylineDeleteOwnership _captureRoutePolylineDeleteOwnership() {
    return NavPolylineDeleteOwnership(
      managerGeneration: _routeAnnotationGate.managerGeneration,
      renderEpoch: _routeRenderEpoch,
      sessionGeneration: _navigationSessionGeneration,
      styleGeneration: _styleRequestGeneration,
    );
  }

  /// NAV-ANNOTATION-LIFECYCLE-REPAIR-1: idempotent serialized polyline delete.
  /// Never throws. Never mutates `_routeLine*` (caller nulls refs first).
  Future<NavPolylineDeleteResult> _safeDeleteRoutePolyline(
    mb.PolylineAnnotation annotation, {
    required mb.PolylineAnnotationManager mgr,
    required NavPolylineDeleteOwnership ownership,
    required String reason,
  }) async {
    final id = annotation.id;
    logNavUiInputTiming(
      action: NavUiInputTimingAction.routeAnnotationDelete,
      phase: NavUiInputTimingPhase.deleteStart,
      managerGeneration: ownership.managerGeneration,
      renderEpoch: ownership.renderEpoch,
      sessionGeneration: ownership.sessionGeneration,
      styleGeneration: ownership.styleGeneration,
      reason: reason,
    );
    final startedAt = DateTime.now();
    final result = await _routePolylineDeleteCoordinator.delete(
      annotationId: id,
      ownership: ownership,
      currentManagerGeneration: () => _routeAnnotationGate.managerGeneration,
      currentRenderEpoch: () => _routeRenderEpoch,
      currentSessionGeneration: () => _navigationSessionGeneration,
      currentStyleGeneration: () => _styleRequestGeneration,
      nativeDelete: () => mgr.delete(annotation),
    );
    final durationMs =
        DateTime.now().difference(startedAt).inMilliseconds.clamp(0, 60000);
    // Safety: never clear current route handles from delete completion.
    assert(() {
      // ownershipStillCurrent false ⇒ must not mutate shared route refs.
      return true;
    }());
    if (result.outcome == NavPolylineDeleteOutcome.unexpectedFailure) {
      logNavUiInputTiming(
        action: NavUiInputTimingAction.routeAnnotationDelete,
        phase: NavUiInputTimingPhase.deleteFailed,
        managerGeneration: _routeAnnotationGate.managerGeneration,
        renderEpoch: _routeRenderEpoch,
        sessionGeneration: _navigationSessionGeneration,
        styleGeneration: _styleRequestGeneration,
        durationMs: durationMs,
        reason: result.errorToken ?? 'unexpected',
      );
      debugPrint(
        '[NAV_ANNOTATION_DELETE] outcome=unexpected_failure '
        'reason=${result.errorToken ?? 'unexpected'} '
        'managerGeneration=${_routeAnnotationGate.managerGeneration} '
        'renderEpoch=$_routeRenderEpoch '
        'sessionGeneration=$_navigationSessionGeneration '
        'styleGeneration=$_styleRequestGeneration',
      );
      unawaited(
        NavDiagnosticsRecorder.instance.recordException(
          context: 'route_polyline_delete_unexpected',
          error: StateError(result.errorToken ?? 'unexpected_failure'),
        ),
      );
    } else {
      final phase = result.outcome == NavPolylineDeleteOutcome.deleted
          ? NavUiInputTimingPhase.deleteCompleted
          : (result.outcome == NavPolylineDeleteOutcome.alreadyGone
                ? NavUiInputTimingPhase.deleteCompleted
                : NavUiInputTimingPhase.deleteCompleted);
      logNavUiInputTiming(
        action: NavUiInputTimingAction.routeAnnotationDelete,
        phase: phase,
        managerGeneration: _routeAnnotationGate.managerGeneration,
        renderEpoch: _routeRenderEpoch,
        sessionGeneration: _navigationSessionGeneration,
        styleGeneration: _styleRequestGeneration,
        durationMs: durationMs,
        reason: result.outcome.name,
      );
      if (result.outcome == NavPolylineDeleteOutcome.alreadyGone ||
          result.outcome == NavPolylineDeleteOutcome.staleSkipped) {
        debugPrint(
          '[NAV_ANNOTATION_DELETE] outcome=${result.outcome.name} '
          'reason=${result.errorToken ?? result.outcome.name} '
          'managerGeneration=${_routeAnnotationGate.managerGeneration} '
          'renderEpoch=$_routeRenderEpoch',
        );
      }
    }
    return result;
  }

  Future<void> _safeDeleteRoutePolylines(
    List<mb.PolylineAnnotation?> annotations, {
    required mb.PolylineAnnotationManager mgr,
    required String reason,
  }) async {
    final ownership = _captureRoutePolylineDeleteOwnership();
    for (final ann in annotations) {
      if (ann == null) continue;
      await _safeDeleteRoutePolyline(
        ann,
        mgr: mgr,
        ownership: ownership,
        reason: reason,
      );
    }
  }

  void _resetDriverMarkerOnNativeError(String reason) {
    debugPrint('[NAV_MARKER] manager_reset reason=$reason');
    unawaited(
      NavDiagnosticsRecorder.instance.recordException(
        context: 'marker_manager_reset',
        error: StateError(reason),
      ),
    );
    // NAV-3D-YELLOW-TAXI-FINAL-VISIBILITY-FIX-1: this reset can also fire on
    // repeated non-manager-lost errors while the native manager is still
    // alive. Dropping the Dart references without native cleanup leaks a
    // rendered taxi annotation that self-heal then duplicates. Best-effort
    // remove the old manager (and its annotations) before clearing.
    final staleManager = _driverPointManager;
    final map = _map;
    final ownership = _driverAnnotationGate.capture();
    _driverAnnotationGate.beginDrain();
    _driverPointManager = null;
    _driverMarker = null;
    _driverMarkerUsesTaxiAsset = false;
    if (staleManager != null) {
      unawaited(() async {
        final check = _driverAnnotationGate.allow(
          ownership,
          NavAnnotationOperationKind.dispose,
        );
        if (!check.allowed) {
          _logNavAnnotationManager(
            gate: _driverAnnotationGate,
            event: 'stale_operation_rejected',
            operation: NavAnnotationOperationKind.dispose,
            reason: check.reason,
          );
          return;
        }
        // Transactional barrier: wait for in-flight leased ops before removal.
        await _driverAnnotationGate.awaitDrained();
        try {
          if (map != null) {
            await map.annotations.removeAnnotationManager(staleManager);
          }
          // Disposal removes annotations — never deleteAll afterward.
        } catch (_) {}
        if (_driverAnnotationGate.markDisposed()) {
          _logNavAnnotationManager(
            gate: _driverAnnotationGate,
            event: 'disposed',
          );
        }
      }());
    } else {
      _driverAnnotationGate.markDisposed();
    }
    // NAV-R12-D: a lost manager must not stay lost until the next style
    // swap — mark degraded and schedule a bounded self-heal.
    _markerLifecycle.noteFailure(reason, DateTime.now());
    _scheduleMarkerSelfHeal(reason);
  }

  /// NAV-R12-D: bounded, PII-safe marker lifecycle diagnostics (no lat/lng).
  void _logNavR12Marker({
    required String event,
    String? markerSource,
    int? markerLagMs,
    String? selfHealReason,
    int? recreateAttempt,
  }) {
    final managerReady = _driverPointManager != null && !_mapStyleChanging;
    final signature =
        '$event|$managerReady|${_markerLifecycle.degraded}|'
        '${selfHealReason ?? ''}';
    final changed = signature != _lastNavR12MarkerSignature;
    _lastNavR12MarkerSignature = signature;
    _logNavBounded(
      'NAV_R12_MARKER',
      'markerUpdate=$event '
          'markerSource=${markerSource ?? 'na'} '
          'markerLagMs=${markerLagMs ?? -1} '
          'managerReady=$managerReady '
          'managerDegraded=${_markerLifecycle.degraded} '
          'updateInFlight=${_markerLifecycle.updateInFlight} '
          'pendingUpdate=${_markerLifecycle.pendingUpdate} '
          'selfHealScheduled=${_markerSelfHealTimer?.isActive ?? false} '
          'selfHealReason=${selfHealReason ?? _markerLifecycle.lastFailureReason} '
          'recreateAttempt=${recreateAttempt ?? _markerLifecycle.selfHealAttempts}',
      intervalMs: changed ? 1 : 2000,
    );
    if (changed && event.startsWith('self_heal')) {
      unawaited(
        NavDiagnosticsRecorder.instance.recordNavEngineEvent(
          tag: 'NAV_R12_MARKER',
          fields: <String, dynamic>{
            'event': event,
            'managerReady': managerReady,
            'managerDegraded': _markerLifecycle.degraded,
            'selfHealReason':
                selfHealReason ?? _markerLifecycle.lastFailureReason,
            'recreateAttempt':
                recreateAttempt ?? _markerLifecycle.selfHealAttempts,
          },
        ),
      );
    }
  }

  /// NAV-R12-D: schedule one self-heal attempt on the lifecycle backoff.
  /// Idempotent — an already-armed timer wins.
  void _scheduleMarkerSelfHeal(String reason) {
    if (!_mapSupported || !mounted) return;
    // EXTERNAL-NAV-RETURN-LIFECYCLE-P0-7: while Fluxidi PiP owns the surface,
    // never storm native annotation recreate (manager-missing fatal path).
    if (_externalNavigationSession?.pipActive == true) return;
    if (_markerSelfHealTimer?.isActive ?? false) return;
    final delay = _markerLifecycle.selfHealDelay(DateTime.now());
    _logNavR12Marker(event: 'self_heal_scheduled', selfHealReason: reason);
    _markerSelfHealTimer = Timer(delay, () {
      _markerSelfHealTimer = null;
      unawaited(_attemptMarkerSelfHeal(reason));
    });
  }

  /// NAV-R12-D: recreate the annotation manager and taxi marker after a
  /// native failure. Never throws; failure re-arms the backoff timer.
  Future<void> _attemptMarkerSelfHeal(String reason) async {
    if (!mounted) return;
    if (_map == null || _mapStyleChanging) {
      // Style swap has its own recreate/restore path; check back later.
      if (_markerLifecycle.degraded) _scheduleMarkerSelfHeal(reason);
      return;
    }
    if (!_markerLifecycle.degraded && _driverMarker != null) {
      return; // healed in the meantime (e.g. by a style-swap restore)
    }
    final attempt = _markerLifecycle.noteSelfHealAttemptStarted(DateTime.now());
    _logNavR12Marker(
      event: 'self_heal_attempt',
      selfHealReason: reason,
      recreateAttempt: attempt,
    );
    var success = false;
    try {
      if (_driverPointManager == null) {
        final mgr = await _map!.annotations.createPointAnnotationManager();
        await _configureDriverPointManagerForTaxiMarker(mgr);
        _driverPointManager = mgr;
        // NAV-ANNOTATION-MANAGER-TRANSACTIONAL-LIFECYCLE-2: a self-heal that
        // recreates the native manager MUST re-activate the executor,
        // otherwise the gate stays disposed and every leased marker update is
        // rejected (marker would never move again).
        _activateAnnotationGate(
          _driverAnnotationGate,
          event: 'activated_self_heal',
        );
      }
      success = await _attemptTaxiMarkerRestore(
        attempt: attempt,
        reason: 'self_heal_$reason',
      );
    } catch (_) {
      success = false;
    }
    if (success) {
      _markerLifecycle.noteSelfHealSucceeded(DateTime.now());
      _logNavR12Marker(
        event: 'self_heal_success',
        selfHealReason: reason,
        recreateAttempt: attempt,
      );
      await _syncMapboxUserLocationPuckVisibility();
    } else {
      _markerLifecycle.noteSelfHealFailed(reason, DateTime.now());
      _logNavR12Marker(
        event: 'self_heal_failed',
        selfHealReason: reason,
        recreateAttempt: attempt,
      );
      _scheduleMarkerSelfHeal(reason);
    }
  }

  /// NAV-R12-D: fast, coalesced marker update on a fresh GPS fix. Never
  /// blocks the caller; if a native update is already in flight the newest
  /// fix simply replaces the pending one (last-wins).
  void _scheduleDriverMarkerFastUpdate(geo.Position pos) {
    _pendingMarkerUpdatePos = pos;
    if (_driverPointManager == null &&
        !(_markerSelfHealTimer?.isActive ?? false) &&
        !_mapStyleChanging &&
        _map != null) {
      _markerLifecycle.noteFailure('manager_missing_on_fix', DateTime.now());
      _scheduleMarkerSelfHeal('manager_missing_on_fix');
    }
    if (!_markerLifecycle.beginUpdate(DateTime.now())) {
      _logNavR12Marker(event: 'skipped_in_flight');
      return;
    }
    unawaited(_runCoalescedMarkerUpdate());
  }

  Future<void> _runCoalescedMarkerUpdate() async {
    var runNext = true;
    while (runNext && mounted) {
      final pos = _pendingMarkerUpdatePos;
      var applied = false;
      if (pos != null) {
        try {
          applied = await _updateDriverMarker(pos);
        } catch (_) {
          applied = false;
        }
      }
      runNext = _markerLifecycle.finishUpdate(
        applied: applied,
        now: DateTime.now(),
      );
      if (runNext) {
        _markerLifecycle.beginUpdate(DateTime.now());
      }
    }
  }

  void _logNavAnnotationManager({
    required NavAnnotationManagerGate gate,
    required String event,
    NavAnnotationOperationKind? operation,
    NavAnnotationRejectReason? reason,
  }) {
    _logNavBounded(
      'NAV_ANNOTATION_MANAGER',
      gate.formatDiag(
        event: event,
        operation: operation,
        reason: reason,
        routeVersion: _routeStepsVersion,
      ),
      intervalMs: 1,
    );
  }

  /// NAV-ANNOTATION-MANAGER-TRANSACTIONAL-LIFECYCLE-2: bounded PII-free
  /// [NAV_ANNOTATION_TX] transaction event. Never includes coordinates or
  /// trip/customer identifiers.
  void _logNavAnnotationTx({
    required NavAnnotationManagerGate gate,
    required NavAnnotationTxEvent event,
    NavAnnotationOperationKind? operation,
    NavAnnotationRejectReason? reason,
  }) {
    _logNavBounded(
      'NAV_ANNOTATION_TX',
      'role=${gate.role.name} '
          'managerGeneration=${gate.managerGeneration} '
          'styleGeneration=${gate.styleGeneration} '
          'sessionGeneration=${gate.sessionGeneration} '
          'renderEpoch=${gate.renderEpoch} '
          'routeVersion=$_routeStepsVersion '
          'event=${navAnnotationTxEventLabel(event)}'
          '${operation != null ? ' operation=${operation.name}' : ''}'
          '${reason != null ? ' reason=${reason.name}' : ''}'
          ' inFlight=${navAnnotationCountBucket(gate.activeLeases)}',
      intervalMs: 1,
    );
  }

  /// Run [nativeOp] through the transactional executor for [gate]. Ownership is
  /// captured atomically (no await before the lease) so there is no
  /// check-then-act window: a draining/disposed/stale generation NEVER lets the
  /// native op cross the Flutter → native boundary, and while the lease is held
  /// disposal cannot remove the manager. Returns a stale result when rejected.
  Future<NavAnnotationRunResult<T>> _runAnnotationTx<T>({
    required NavAnnotationManagerGate gate,
    required NavAnnotationOperationKind kind,
    required Future<T> Function() nativeOp,
  }) async {
    final ownership = gate.capture();
    _logNavAnnotationTx(
      gate: gate,
      event: NavAnnotationTxEvent.queued,
      operation: kind,
    );
    try {
      final result = await gate.runGuarded<T>(
        ownership: ownership,
        kind: kind,
        nativeOp: () async {
          _logNavAnnotationTx(
            gate: gate,
            event: NavAnnotationTxEvent.leaseAcquired,
            operation: kind,
          );
          final value = await nativeOp();
          _logNavAnnotationTx(
            gate: gate,
            event: NavAnnotationTxEvent.nativeCompleted,
            operation: kind,
          );
          return value;
        },
      );
      if (!result.ran) {
        _logNavAnnotationTx(
          gate: gate,
          event: NavAnnotationTxEvent.staleBeforeStart,
          operation: kind,
          reason: result.rejectReason,
        );
      }
      return result;
    } catch (e, st) {
      // NAV-ANNOTATION-LIFECYCLE-REPAIR-1: delete/deleteAll must never escape
      // unhandled through DartMessenger (unawaited clear/replace paths).
      final isDelete = kind == NavAnnotationOperationKind.delete ||
          kind == NavAnnotationOperationKind.deleteAll;
      if (isDelete) {
        final stale = isStalePolylineAnnotationDeleteError(e);
        debugPrint(
          '[NAV_ANNOTATION_TX] role=${gate.role.name} '
          'event=${stale ? 'stale_delete_caught' : 'unexpected_delete_caught'} '
          'reason=${navPolylineDeleteErrorToken(e)} '
          'managerGeneration=${gate.managerGeneration} '
          'renderEpoch=$_routeRenderEpoch',
        );
        if (!stale) {
          unawaited(
            NavDiagnosticsRecorder.instance.recordException(
              context: 'annotation_delete_tx',
              error: e,
              stack: st,
            ),
          );
        }
        return NavAnnotationRunResult<T>.stale(
          stale
              ? NavAnnotationRejectReason.disposed
              : NavAnnotationRejectReason.notActive,
        );
      }
      rethrow;
    }
  }

  void _activateAnnotationGate(
    NavAnnotationManagerGate gate, {
    required String event,
  }) {
    gate.activate(
      styleGeneration: _styleRequestGeneration,
      sessionGeneration: _navigationSessionGeneration,
      renderEpoch: _routeRenderEpoch,
    );
    if (identical(gate, _routeAnnotationGate)) {
      _routePolylineDeleteCoordinator.onManagerActivated(
        gate.managerGeneration,
      );
    }
    _logNavAnnotationManager(gate: gate, event: event);
  }

  /// Drain every annotation-manager role so in-flight / queued native ops for
  /// the outgoing generation become no-ops before disposal. Style N+1 makes N
  /// stale immediately.
  void _beginDrainAllAnnotationManagers({required String reason}) {
    for (final gate in <NavAnnotationManagerGate>[
      _routeAnnotationGate,
      _pinsAnnotationGate,
      _destinationAnnotationGate,
      _driverAnnotationGate,
    ]) {
      if (gate.state == NavAnnotationManagerState.disposed) continue;
      gate.beginDrain();
      _logNavAnnotationManager(gate: gate, event: 'draining');
    }
    debugPrint('[NAV_ANNOTATION_MANAGER] event=drain_all reason=$reason');
  }

  /// NAV-STYLE-MANAGER-CRASH-TELLERS-MARKER-1: never issue per-annotation
  /// deletes after the manager is disposed — disposal itself removes native
  /// annotations. A follow-up deleteAll after removeAnnotationManager was a
  /// crash path ("No manager found with id: N").
  Future<void> _disposeDriverPointAnnotationManager() async {
    final map = _map;
    final mgr = _driverPointManager;
    final ownership = _driverAnnotationGate.capture();
    _driverAnnotationGate.beginDrain();
    _logNavAnnotationManager(gate: _driverAnnotationGate, event: 'draining');
    _driverPointManager = null;
    _driverMarker = null;
    _driverMarkerUsesTaxiAsset = false;
    if (mgr != null) {
      final disposeAllowed = _driverAnnotationGate.allow(
        ownership,
        NavAnnotationOperationKind.dispose,
      );
      if (disposeAllowed.allowed) {
        // Transactional barrier: block until every leased native op on this
        // generation has finished BEFORE removing the manager. This closes the
        // check-then-act window that let create/update reach a removed manager.
        if (_driverAnnotationGate.activeLeases > 0) {
          _logNavAnnotationManager(
            gate: _driverAnnotationGate,
            event: 'drain_waiting',
            operation: NavAnnotationOperationKind.dispose,
          );
        }
        await _driverAnnotationGate.awaitDrained();
        try {
          if (map != null) {
            await map.annotations.removeAnnotationManager(mgr);
            _logNavAnnotationManager(
              gate: _driverAnnotationGate,
              event: 'manager_removed',
              operation: NavAnnotationOperationKind.dispose,
            );
          }
          // Disposal removes annotations — do NOT call delete/deleteAll on the
          // disposed manager (native fatal on Android).
        } catch (_) {}
      } else {
        _logNavAnnotationManager(
          gate: _driverAnnotationGate,
          event: 'stale_operation_rejected',
          operation: NavAnnotationOperationKind.dispose,
          reason: disposeAllowed.reason,
        );
      }
    }
    if (_driverAnnotationGate.markDisposed()) {
      _logNavAnnotationManager(gate: _driverAnnotationGate, event: 'disposed');
    } else {
      _logNavAnnotationManager(
        gate: _driverAnnotationGate,
        event: 'duplicate_dispose_ignored',
      );
    }
    debugPrint('[NAV_MARKER] lifecycle=driver_manager_disposed');
  }

  /// NAV-R12-I-A / NAV-R13 + NAV-TELLERS-STREETLEVEL-SCREEN-UP-MARKER-1:
  /// pitch alignment is VIEWPORT so the sprite keeps its on-screen size
  /// under the pitched follow camera (field feedback NAV-R13).
  ///
  /// Rotation alignment is now selected by
  /// [_currentDriverMarkerRotationPolicy]:
  ///   * Streetlevel + owner == mapboxAnnotation → VIEWPORT (screen-up).
  ///     In Tellers Streetlevel the single Car/Arrow annotation stays
  ///     upright while the map/route rotate underneath.
  ///   * Otherwise → MAP (legacy taxi nose follows compass/road direction).
  /// Applies to the driver/taxi manager only; pins keep plugin defaults.
  Future<void> _configureDriverPointManagerForTaxiMarker(
    mb.PointAnnotationManager mgr,
  ) async {
    final policy = _currentDriverMarkerRotationPolicy();
    var event = 'manager_configured';
    String? failReason;
    try {
      await mgr.setIconRotationAlignment(
        _mapboxIconRotationAlignmentFor(policy),
      );
      await mgr.setIconPitchAlignment(mb.IconPitchAlignment.VIEWPORT);
    } catch (e) {
      event = 'manager_config_failed';
      failReason = e.runtimeType.toString();
    }
    _logNavBounded(
      'NAV_R13_MARKER_VISUAL',
      'markerUpdate=$event rotationAlignment=${policy.logLabel} '
          'pitchAlignment=viewport'
          '${failReason != null ? ' reason=$failReason' : ''}',
      intervalMs: 1,
    );
    unawaited(
      NavDiagnosticsRecorder.instance.recordNavEngineEvent(
        tag: 'NAV_R13_MARKER_VISUAL',
        fields: <String, dynamic>{
          'event': event,
          'rotationAlignment': policy.logLabel,
          'pitchAlignment': 'viewport',
          if (failReason != null) 'reason': failReason,
        },
      ),
    );
  }

  /// NAV-TELLERS-STREETLEVEL-SCREEN-UP-MARKER-1: resolve the current
  /// screen-up marker rotation policy from the live navigation state
  /// (presentation state, follow-live gating, Tellers activity).
  DriverMarkerRotationPolicy _currentDriverMarkerRotationPolicy() {
    final pres = _navigationPresentationStateFor(_navCameraViewMode);
    final owner = resolveDriverVehicleMarkerPresentationOwner(
      tellersActive: _navPresentationMode.isTellers,
      followLiveActive: _navFixedHudPresentationActive,
      showDriverHudOverlay: pres.showDriverHudOverlay,
    );
    return resolveDriverMarkerRotationPolicy(
      isStreetlevel: pres.useDriverCockpitCamera,
      owner: owner,
    );
  }

  /// NAV-TELLERS-STREETLEVEL-SCREEN-UP-MARKER-1: translate the pure policy
  /// alignment enum into the Mapbox `IconRotationAlignment` value.
  mb.IconRotationAlignment _mapboxIconRotationAlignmentFor(
    DriverMarkerRotationPolicy policy,
  ) {
    switch (policy.alignment) {
      case DriverMarkerRotationAlignment.map:
        return mb.IconRotationAlignment.MAP;
      case DriverMarkerRotationAlignment.viewport:
        return mb.IconRotationAlignment.VIEWPORT;
    }
  }

  /// NAV-TELLERS-STREETLEVEL-SCREEN-UP-MARKER-1: re-apply the current
  /// screen-up policy to the live driver point-annotation manager and
  /// marker. Called at every presentation-state transition (Tellers open /
  /// close, camera view mode change) and after style / manager restoration
  /// so the alignment matches the current owner without touching camera or
  /// pose logic.
  ///
  /// - Sets the manager `IconRotationAlignment` to the policy value.
  /// - If the policy forces `iconRotate = 0`, snaps the current marker's
  ///   `iconRotate` to 0 in one bounded native update, so the very next
  ///   frame is screen-up (no wait for the next GPS/route tick).
  Future<void> _reapplyDriverMarkerRotationPolicy({
    required String source,
  }) async {
    final mgr = _driverPointManager;
    if (mgr == null) return;
    final policy = _currentDriverMarkerRotationPolicy();
    try {
      await mgr.setIconRotationAlignment(
        _mapboxIconRotationAlignmentFor(policy),
      );
    } catch (e) {
      if (_isMapboxAnnotationManagerLost(e)) {
        _resetDriverMarkerOnNativeError('rotation_align_$source');
        return;
      }
    }
    _logNavBounded(
      'NAV_MARKER_ROTATION_POLICY',
      'source=$source alignment=${policy.logLabel}',
      intervalMs: 1,
    );
    if (!policy.forceIconRotateZero) return;
    final marker = _driverMarker;
    if (marker == null) return;
    if (!_canUpdateDriverMarker) return;
    final current = marker.iconRotate ?? 0.0;
    if (current.abs() < 0.001) return;
    if (!_driverAnnotationGate.tryAcquireLease(
      _driverAnnotationGate.capture(),
      NavAnnotationOperationKind.update,
    )) {
      return;
    }
    try {
      marker.iconRotate = 0.0;
      await mgr.update(marker);
    } catch (e) {
      if (_isMapboxAnnotationManagerLost(e)) {
        _resetDriverMarkerOnNativeError('rotation_snap_$source');
      }
    } finally {
      _driverAnnotationGate.releaseLease();
    }
  }

  // NAV-PARKING-2 Commit 2 + NAV-STYLE-MANAGER-CRASH-TELLERS-MARKER-1:
  // remove previous route/pins/destination managers before recreating them.
  // Drain first so any fire-and-forget delete/update captured against the old
  // generation becomes a no-op before removeAnnotationManager. Disposal itself
  // clears native annotations — never issue per-annotation deletes afterward.
  Future<void> _disposeRouteAndPinAnnotationManagers() async {
    final map = _map;
    final route = _routeLineManager;
    final pins = _pinsPointManager;
    final dest = _destinationMarkerManager;
    final routeOwn = _routeAnnotationGate.capture();
    final pinsOwn = _pinsAnnotationGate.capture();
    final destOwn = _destinationAnnotationGate.capture();
    _routeAnnotationGate.beginDrain();
    _pinsAnnotationGate.beginDrain();
    _destinationAnnotationGate.beginDrain();
    _logNavAnnotationManager(gate: _routeAnnotationGate, event: 'draining');
    _logNavAnnotationManager(gate: _pinsAnnotationGate, event: 'draining');
    _logNavAnnotationManager(
      gate: _destinationAnnotationGate,
      event: 'draining',
    );
    _routeLineManager = null;
    _routeLineOutline = null;
    _routeLine = null;
    _routeLineCompleted = null;
    _pinsPointManager = null;
    _pickupPin = null;
    _dropoffPin = null;
    _destinationMarkerManager = null;
    _destinationMarker = null;
    _lastDestinationMarkerSignature = null;
    if (map != null) {
      Future<void> disposeOne(
        mb.BaseAnnotationManager? mgr,
        NavAnnotationManagerGate gate,
        NavAnnotationOwnership ownership,
      ) async {
        if (mgr == null) return;
        final check = gate.allow(ownership, NavAnnotationOperationKind.dispose);
        if (!check.allowed) {
          _logNavAnnotationManager(
            gate: gate,
            event: 'stale_operation_rejected',
            operation: NavAnnotationOperationKind.dispose,
            reason: check.reason,
          );
          return;
        }
        // Transactional barrier: wait for every leased native op on this
        // generation to complete before removeAnnotationManager, so an
        // in-flight create/update/delete can never race manager removal.
        if (gate.activeLeases > 0) {
          _logNavAnnotationManager(
            gate: gate,
            event: 'drain_waiting',
            operation: NavAnnotationOperationKind.dispose,
          );
        }
        await gate.awaitDrained();
        try {
          await map.annotations.removeAnnotationManager(mgr);
          _logNavAnnotationManager(
            gate: gate,
            event: 'manager_removed',
            operation: NavAnnotationOperationKind.dispose,
          );
        } catch (_) {}
      }

      await disposeOne(route, _routeAnnotationGate, routeOwn);
      await disposeOne(pins, _pinsAnnotationGate, pinsOwn);
      await disposeOne(dest, _destinationAnnotationGate, destOwn);
    }
    for (final gate in <NavAnnotationManagerGate>[
      _routeAnnotationGate,
      _pinsAnnotationGate,
      _destinationAnnotationGate,
    ]) {
      if (gate.markDisposed()) {
        _logNavAnnotationManager(gate: gate, event: 'disposed');
      } else {
        _logNavAnnotationManager(
          gate: gate,
          event: 'duplicate_dispose_ignored',
        );
      }
    }
  }

  Future<void> _recreateAnnotationManagers() async {
    if (_map == null) return;
    await _syncMapboxUserLocationPuckVisibility();
    // Style replacement: drain all roles before disposing so stale queued
    // deletes cannot reach native after removeAnnotationManager.
    _beginDrainAllAnnotationManagers(reason: 'recreate');
    await _disposeDriverPointAnnotationManager();
    await _disposeRouteAndPinAnnotationManagers();
    _routeLineManager = await _map!.annotations
        .createPolylineAnnotationManager();
    _activateAnnotationGate(_routeAnnotationGate, event: 'activated');
    _pinsPointManager = await _map!.annotations.createPointAnnotationManager();
    _activateAnnotationGate(_pinsAnnotationGate, event: 'activated');
    _destinationMarkerManager = await _map!.annotations
        .createPointAnnotationManager();
    _activateAnnotationGate(_destinationAnnotationGate, event: 'activated');
    _destinationMarker = null;
    _lastDestinationMarkerSignature = null;
    final driverMgr = await _map!.annotations.createPointAnnotationManager();
    await _configureDriverPointManagerForTaxiMarker(driverMgr);
    _driverPointManager = driverMgr;
    _activateAnnotationGate(_driverAnnotationGate, event: 'activated');
    await _syncMapboxUserLocationPuckVisibility();
    await _ensureDriverVehicleModelLayer();
  }

  MapThemeMode _effectiveMapThemeFor(_CameraMode mode) {
    return _mapThemeOverride ??
        (mode == _CameraMode.follow ? MapThemeMode.light : MapThemeMode.dark);
  }

  String _styleForTheme(MapThemeMode theme) {
    return resolveDriverMapStyleUri(
      isLightTheme: theme == MapThemeMode.light,
      visualMode: _driverMapVisualMode,
      cockpit3dSceneActive: _isDriverCockpit3dSceneEligible(),
      cockpitVisualStyle: kNavigation3dCockpitSceneEnabled
          ? _driverCockpitMapVisualStyle
          : null,
      rejectedExperimentalUris: _rejectedCockpit3dStyleUris,
    );
  }

  bool _isDriverCockpit3dSceneEligible() {
    if (!kNavigation3dCockpitSceneEnabled) return false;
    // NAV-RELEASE-SIMPLE-STREETLEVEL-1: real 3D is active whenever the driver
    // selected the 3D style on a preview draft or live follow surface.
    // Previously preview required follow+live, so UI "3D" stayed visualMode=street.
    if (_driverCockpitMapVisualStyle == DriverCockpitMapVisualStyle.standard3d ||
        _driverMapVisualMode == DriverMapVisualMode.threeD) {
      return _directRideDraft ||
          (_cameraMode == _CameraMode.follow && _liveRideActive);
    }
    if (_cameraMode != _CameraMode.follow || !_liveRideActive) return false;
    return _navigationPresentationStateFor(
      _navCameraViewMode,
    ).useDriverCockpitCamera;
  }

  void _logNavPres3dStyleIfChanged({
    required String target,
    required String previous,
    required String result,
    String? reason,
  }) {
    if (!kNavigation3dCockpitSceneEnabled) return;
    final choice = driverCockpitMapVisualStyleLogLabel(
      _driverCockpitMapVisualStyle,
    );
    final signature = '$result|$choice|$target|$previous|${reason ?? ''}';
    if (signature == _lastNavPres3dStyleSignature) return;
    _lastNavPres3dStyleSignature = signature;
    _logNavBounded(
      'NAV_PRES_3D_STYLE',
      'enabled=true choice=$choice target=$target previous=$previous result=$result'
          '${reason != null ? ' reason=$reason' : ''}',
      intervalMs: 1200,
    );
  }

  String _styleForMode(_CameraMode mode) {
    return _styleForTheme(_effectiveMapThemeFor(mode));
  }

  Future<void> _applyMapStyleForMode() async {
    if (_map == null) return;
    final theme = _effectiveMapThemeFor(_cameraMode);
    final target = _styleForMode(_cameraMode);
    final previousStyle = _activeMapStyleUri;
    debugPrint(
      '[MAP][STYLE_REQ] theme=${theme == MapThemeMode.light ? 'light' : 'dark'} target=$target active=$_activeMapStyleUri pending=${_pendingMapStyleUri ?? ''}',
    );
    if (_activeMapStyleUri == target) {
      _logNavPres3dStyleIfChanged(
        target: target,
        previous: previousStyle,
        result: 'already',
      );
      debugPrint('[MAP][STYLE_SKIP] reason=already_active target=$target');
      await applyDriverMapVisualClarity(
        style: _map!.style,
        visualMode: _driverMapVisualMode,
      );
      return;
    }
    if (_pendingMapStyleUri == target) {
      debugPrint('[MAP][STYLE_SKIP] reason=in_flight target=$target');
      return;
    }
    _pendingMapStyleUri = target;
    _mapStyleChanging = true;
    // NAV-RIDE-BOUNDARY: style request N+1 makes N stale immediately.
    _styleRequestGeneration += 1;
    // NAV-STYLE-MANAGER-CRASH-TELLERS-MARKER-1: style N+1 drains every
    // annotation-manager generation immediately so queued deletes/updates for
    // N cannot reach native after the managers are removed.
    _beginDrainAllAnnotationManagers(reason: 'style_swap');
    // NAV-PRESTART-FIELD-BLOCKER-3 (Problem A): capture preview restore
    // eligibility so a style swap during pre-start preview may still redraw
    // the accepted route line + pins. Without this the style-restore gate
    // rejects every preview redraw because `_liveRideActive` is false.
    // NAV-PIP-PLANNED-COMPLETION-EVIDENCE-FIX-P0 (C): prepared_route booking
    // previews use `_fixedStreetLevelPreviewDraft` (active booking + street
    // draft). Restricting to `_directRideDraft` alone rejected style restore
    // with navigation_not_live while phase=prepared_route.
    final previewRestoreEligible =
        !_liveRideActive &&
        _fixedStreetLevelPreviewDraft &&
        _routeCoords.length >= 2;
    final styleOwnershipCapture = NavRouteOwnershipCapture(
      sessionGeneration: _navigationSessionGeneration,
      styleGeneration: _styleRequestGeneration,
      routeVersion: _routeStepsVersion,
      renderEpoch: _routeRenderEpoch,
      navigationLive: _liveRideActive,
      routeCoordCount: _routeCoords.length,
      previewRestoreEligible: previewRestoreEligible,
    );
    // Freeze geometry for this style owner — never read mutable coords later
    // from a stale callback.
    final frozenRouteCoords = List<_LonLat>.from(_routeCoords);
    // NAV-CAMERA-INFLIGHT-SELF-HEAL-1: style swap invalidates camera ownership
    // so a stale Mapbox completion cannot block the restored session.
    _cameraInFlightLifecycle.invalidate(reason: 'style_change');
    _resetPendingFollowCamera();
    debugPrint(
      '[NAV_MAPSTYLE] switching=${driverMapVisualModeLogLabel(_driverMapVisualMode)} target=$target',
    );
    debugPrint('[NAV_MARKER] paused_for_style_change');
    unawaited(
      NavDiagnosticsRecorder.instance.recordMapStyleChange(
        mode: driverMapVisualModeLogLabel(_driverMapVisualMode),
        phase: 'started',
      ),
    );
    var scheduleCockpit3dFallback = false;
    // NAV-LATENCY-1 (Part F): measure the style-swap startup hitch. The
    // redundant-reload guard above already prevents a reload when the target
    // style is already active, so this only fires on a genuine swap.
    final styleSw = Stopwatch()..start();
    var styleLoadedMs = 0;
    var visualsRestoredMs = 0;
    try {
      // NAV-UI-R6E: capture last taxi visual BEFORE the style swap and keep
      // the visible marker alive until the style itself replaces it; the
      // manager is disposed after setStyleURI so there is no early blank gap.
      _captureTaxiVisualSnapshotForStyleSwap();
      _driver3dVehicleStyleGeneration++;
      _cancelDriver3dActivationConfirmRetry();
      _driver3dVehicleAssetLifecycle.invalidateForStyleGeneration();
      _driverVehicleModelLayer.resetRegistration();
      _vehicleModelSyncLifecycle.clearMovementStateForStyleRestore(
        movementGeneration: 0,
      );
      _resetDriver3dVehicleModelVisualHandoff();
      _setVehicleMovementGeneration(0);
      debugPrint(
        '[MAP_THEME] selected=${theme == MapThemeMode.light ? 'light' : 'dark'} style=$target',
      );
      await _map!.style.setStyleURI(target);
      styleLoadedMs = styleSw.elapsedMilliseconds;
      _activeMapStyleUri = target;
      _logNavPres3dStyleIfChanged(
        target: target,
        previous: previousStyle,
        result: 'switch',
      );
      await _disposeDriverPointAnnotationManager();
      await applyDriverMapVisualClarity(
        style: _map!.style,
        visualMode: _driverMapVisualMode,
      );
      _logNavMapStyle(reason: 'style_applied');
      _mapRedrawCountThisMinute += 1;
      await _syncMapboxUserLocationPuckVisibility();
      await _recreateAnnotationManagers();
      _driverMarkerUsesTaxiAsset = false;
      _pickupPin = null;
      _dropoffPin = null;
      _destinationMarker = null;
      _lastDestinationMarkerSignature = null;
      _routeLine = null;
      _routeLineOutline = null;
      _routeLineCompleted = null;
      // Managers are ready again: unblock marker updates BEFORE the restore,
      // otherwise the restore is a no-op and the taxi vanishes until the next
      // GPS callback (NAV-UI-R6E root cause).
      _mapStyleChanging = false;
      final restore = await _restoreDriverVisualsAfterStyleChange(
        reason: 'style_swap',
        ownershipCapture: styleOwnershipCapture,
        frozenRouteCoords: frozenRouteCoords,
      );
      visualsRestoredMs = styleSw.elapsedMilliseconds;
      // NAV-R12-D: clear degraded state only once the marker actually
      // exists again after the style swap.
      if (restore.taxi && _driverMarker != null) {
        _markerLifecycle.noteSelfHealSucceeded(DateTime.now());
      }
      _scheduleTaxiMarkerRestoreRetries(reason: 'style_swap');
      await _syncMapboxUserLocationPuckVisibility();
      debugPrint(
        '[NAV_UI_R6D_STYLE_RESTORE] route=${restore.route} taxi=${restore.taxi} reason=style_swap',
      );
      await _ensureDriverVehicleModelLayer();
      logNav3dVehicleSync(
        phase: 'recovered_after_style_restore',
        generation: _vehicleMovementGeneration,
        preset: _driverVehicle3dPreset,
      );
      final pos = _lastPos;
      if (pos != null && _isDriver3dVehicleModelEffectivelyActive()) {
        final snap =
            _lastRouteSnap ??
            _snapToRoute(_LonLat(pos.longitude, pos.latitude));
        final visual = _resolveNavVisualForMarker(pos, snap);
        final markerDisplay = _driverMarkerDisplayFor(pos);
        unawaited(
          _syncDriverVehicleModelLayer(
            lon: visual.point.lon,
            lat: visual.point.lat,
            bearingDeg: visual.bearing,
            source: markerDisplay.source,
          ),
        );
      }
      debugPrint('[NAV_MARKER] recreated_after_style');
      unawaited(
        NavDiagnosticsRecorder.instance.recordMapStyleChange(
          mode: driverMapVisualModeLogLabel(_driverMapVisualMode),
          phase: 'completed',
        ),
      );
      debugPrint(
        '[MAP_THEME] redraw route=${restore.route} marker=${restore.taxi} pins=${_routeCoords.length >= 2}',
      );
      debugPrint('[MAP][STYLE_DONE] target=$target');
      unawaited(
        _applyMapboxTaxiMarkerPresentationOpacity(source: 'style_change'),
      );
      _scheduleCockpitCameraAfterStyleSwitch();
      // NAV-LATENCY-1 (Part F): bounded style-swap startup measurement.
      debugPrint(
        '[NAV_LATENCY_STYLE] target=$target '
        'styleLoadedMs=$styleLoadedMs '
        'routeRestored=${restore.route} '
        'markerRestored=${restore.taxi} '
        'visualsRestoredMs=$visualsRestoredMs '
        'cameraReadyMs=${styleSw.elapsedMilliseconds}',
      );
    } catch (e) {
      debugPrint('[MAP][STYLE_SKIP] reason=error target=$target error=$e');
      if (isExperimentalCockpit3dMapStyleUri(target)) {
        _rejectedCockpit3dStyleUris.add(target);
        _logNavPres3dStyleIfChanged(
          target: target,
          previous: previousStyle,
          result: 'failed',
          reason: 'setStyleURI_error',
        );
        final fallback = resolveDriverMapStyleUri(
          isLightTheme: theme == MapThemeMode.light,
          visualMode: _driverMapVisualMode,
          cockpit3dSceneActive: _isDriverCockpit3dSceneEligible(),
          cockpitVisualStyle: kNavigation3dCockpitSceneEnabled
              ? _driverCockpitMapVisualStyle
              : null,
          rejectedExperimentalUris: _rejectedCockpit3dStyleUris,
        );
        if (fallback != target && _activeMapStyleUri != fallback) {
          _logNavPres3dStyleIfChanged(
            target: fallback,
            previous: target,
            result: 'fallback',
            reason: 'experimental_unsupported',
          );
          scheduleCockpit3dFallback = true;
        }
      }
      unawaited(
        NavDiagnosticsRecorder.instance.recordMapStyleChange(
          mode: driverMapVisualModeLogLabel(_driverMapVisualMode),
          phase: 'failed',
          error: e.toString(),
        ),
      );
      unawaited(
        NavDiagnosticsRecorder.instance.recordException(
          context: 'map_style_change',
          error: e,
        ),
      );
    } finally {
      _mapStyleChanging = false;
      if (_pendingMapStyleUri == target) {
        _pendingMapStyleUri = null;
      }
    }
    // NAV-ANNOTATION-MANAGER-TRANSACTIONAL-LIFECYCLE-2 / Phase 6: a style tap
    // arrived while this swap was running — apply the latest requested style
    // exactly once now that the transaction has fully completed.
    if (_styleSwapRerunRequested && mounted) {
      _styleSwapRerunRequested = false;
      unawaited(
        _applyMapStyleForMode().then((_) {
          if (mounted) _scheduleCockpitCameraAfterStyleSwitch();
        }),
      );
    }
    if (scheduleCockpit3dFallback && mounted) {
      unawaited(_applyMapStyleForMode());
    }
  }

  Future<void> _setMapTheme(MapThemeMode theme) async {
    if (!mounted) return;
    if (kNavigation3dCockpitSceneEnabled) {
      await _setDriverCockpitMapVisualStyle(
        theme == MapThemeMode.light
            ? DriverCockpitMapVisualStyle.light
            : DriverCockpitMapVisualStyle.dark,
      );
      return;
    }
    setState(() => _mapThemeOverride = theme);
    await _applyMapStyleForMode();
  }

  Future<void> _setDriverCockpitMapVisualStyle(
    DriverCockpitMapVisualStyle style,
  ) async {
    if (!mounted) return;
    // NAV-ANNOTATION-MANAGER-TRANSACTIONAL-LIFECYCLE-2 / Phase 6: emergency
    // kill-switch — never swap style during a live ride when disabled.
    final decision = navStyleTapDecision(
      liveRideActive: _liveRideActive || _navigationGuidanceActive,
      styleTransactionRunning: _mapStyleChanging,
    );
    if (decision == NavStyleTapDecision.blocked) {
      _logNavMapStyle(reason: 'cockpit_style_choice_blocked_active_ride');
      return;
    }
    if (!_liveRideActive) _preStartStyleSelected = true;
    setState(() {
      _driverCockpitMapVisualStyle = style;
      switch (style) {
        case DriverCockpitMapVisualStyle.light:
          _mapThemeOverride = MapThemeMode.light;
          _driverMapVisualMode = DriverMapVisualMode.street;
        case DriverCockpitMapVisualStyle.dark:
          _mapThemeOverride = MapThemeMode.dark;
          _driverMapVisualMode = DriverMapVisualMode.street;
        case DriverCockpitMapVisualStyle.standard3d:
          // Real 3D presentation — never leave visualMode=street while UI says 3D.
          _driverMapVisualMode = DriverMapVisualMode.threeD;
        case DriverCockpitMapVisualStyle.satellite:
          _driverMapVisualMode = DriverMapVisualMode.satellite;
      }
    });
    _logNavMapStyle(reason: 'cockpit_style_choice');
    // Fail-safe: a swap is already running → coalesce. The state above already
    // reflects the latest tap, so the running swap's completion re-applies it
    // (latest-wins) instead of starting a second concurrent style swap.
    if (decision == NavStyleTapDecision.coalesce) {
      _styleSwapRerunRequested = true;
      _logNavMapStyle(reason: 'cockpit_style_choice_coalesced_busy');
      return;
    }
    await _applyMapStyleForMode();
    _scheduleCockpitCameraAfterStyleSwitch();
  }

  void _scheduleCockpitCameraAfterStyleSwitch() {
    // NAV-CAMERA-FIELD-REGRESSION-1: preview streetlevel never enters follow,
    // so the live-only gate below used to leave Mapbox's post-style-load
    // default camera (extreme zoom-out / horizon on 3D) in place. Re-apply
    // the cockpit profile exactly once after style ready.
    // NAV-RELEASE-FINAL-FLOW-1: booking preview drafts must restore the same
    // fixed streetlevel / zoom / anchor (not only street drafts).
    if (mayRestorePreviewCockpitCameraAfterStyleSwitch(
      hasPreviewDraft: _fixedStreetLevelPreviewDraft,
      selectedViewMode: _navPreviewViewModeToken(),
      liveRideActive: _liveRideActive,
    )) {
      unawaited(
        _applyPreviewStreetlevelCameraIfEligible(reason: 'style_switch'),
      );
      unawaited(_reconcileMapZoomGestures(reason: 'style_switch'));
      return;
    }
    if (_cameraMode != _CameraMode.follow || !_liveRideActive) return;
    if (!_navigationPresentationStateFor(
      _navCameraViewMode,
    ).useDriverCockpitCamera) {
      return;
    }
    final pos = _lastPos;
    if (pos == null) return;
    unawaited(
      _followCameraTesla(pos, force: true, cameraReason: 'style_switch'),
    );
    unawaited(_reconcileMapZoomGestures(reason: 'style_switch_live'));
  }

  String _driverCockpitMapVisualStyleLabel(DriverCockpitMapVisualStyle style) {
    switch (style) {
      case DriverCockpitMapVisualStyle.light:
        return _tr(nl: 'Licht', en: 'Light', fr: 'Clair', es: 'Claro');
      case DriverCockpitMapVisualStyle.dark:
        return _tr(nl: 'Donker', en: 'Dark', fr: 'Sombre', es: 'Oscuro');
      case DriverCockpitMapVisualStyle.standard3d:
        return _tr(nl: '3D', en: '3D', fr: '3D', es: '3D');
      case DriverCockpitMapVisualStyle.satellite:
        return _tr(
          nl: 'Satelliet',
          en: 'Satellite',
          fr: 'Satellite',
          es: 'Satélite',
        );
    }
  }

  IconData _driverCockpitMapVisualStyleIcon(DriverCockpitMapVisualStyle style) {
    switch (style) {
      case DriverCockpitMapVisualStyle.light:
        return Icons.light_mode_outlined;
      case DriverCockpitMapVisualStyle.dark:
        return Icons.dark_mode_outlined;
      case DriverCockpitMapVisualStyle.standard3d:
        // NAV-PRESTART-FIELD-BLOCKER-3 (Problem C + D): use a building icon
        // for 3D-buildings map style so it no longer collides with the cube
        // used by the camera-presentation preset chip.
        return Icons.apartment_outlined;
      case DriverCockpitMapVisualStyle.satellite:
        return Icons.satellite_alt_outlined;
    }
  }

  /// Restore route line + taxi marker immediately after a style change or
  /// annotation-manager recreation. Uses the last known visual position (nav
  /// interpolator, GPS, or route start) so the driver never sees a bare map
  /// while waiting 3–4 seconds for the next GPS callback.
  Future<({bool route, bool taxi})> _restoreDriverVisualsAfterStyleChange({
    required String reason,
    NavRouteOwnershipCapture? ownershipCapture,
    List<_LonLat>? frozenRouteCoords,
  }) async {
    var restoredRoute = false;
    // NAV-RIDE-BOUNDARY: restore only when the captured style/session/route
    // owners remain current. Prefer frozen geometry from the style request;
    // if route version advanced during the swap but session+style still match,
    // rebind to the active package coords once (not the stale frozen line).
    // NAV-PRESTART-FIELD-BLOCKER-3 (Problem A): mirror the capture's preview
    // eligibility so a preview-owned route is still restorable after a style
    // swap. The session / style / render-epoch / route-version guards remain
    // authoritative — this only widens the "must be live" gate.
    final previewRestoreEligibleNow =
        !_liveRideActive &&
        _fixedStreetLevelPreviewDraft &&
        _routeCoords.length >= 2;
    final capture =
        ownershipCapture ??
        NavRouteOwnershipCapture(
          sessionGeneration: _navigationSessionGeneration,
          styleGeneration: _styleRequestGeneration,
          routeVersion: _routeStepsVersion,
          renderEpoch: _routeRenderEpoch,
          navigationLive: _liveRideActive,
          routeCoordCount: _routeCoords.length,
          previewRestoreEligible: previewRestoreEligibleNow,
        );
    final currentSnapshot = NavRouteOwnershipSnapshot(
      sessionGeneration: _navigationSessionGeneration,
      styleGeneration: _styleRequestGeneration,
      routeVersion: _routeStepsVersion,
      renderEpoch: _routeRenderEpoch,
      navigationLive: _liveRideActive,
      activePackageSessionGeneration:
          _activeRouteRenderOwner?.sessionGeneration,
      activePackageRenderEpoch: _activeRouteRenderOwner?.renderEpoch,
      previewRestoreEligible: previewRestoreEligibleNow,
    );
    final decision = evaluateStyleRouteRestore(
      capture: capture,
      current: currentSnapshot,
    );
    // NAV-STYLE-MANAGER-CRASH-TELLERS-MARKER-1: restore only against the
    // current active manager generation — never the drained style-N manager.
    final routeGateOk = _routeAnnotationGate.isActive;
    final driverGateOk = _driverAnnotationGate.isActive;
    if (decision.allowed && routeGateOk) {
      _logNavAnnotationManager(
        gate: _routeAnnotationGate,
        event: 'restore_allowed',
        operation: NavAnnotationOperationKind.restore,
      );
    } else {
      _logNavAnnotationManager(
        gate: _routeAnnotationGate,
        event: 'restore_rejected',
        operation: NavAnnotationOperationKind.restore,
        reason: routeGateOk
            ? null
            : NavAnnotationRejectReason.notActive,
      );
    }
    if (driverGateOk) {
      _logNavAnnotationManager(
        gate: _driverAnnotationGate,
        event: 'restore_allowed',
        operation: NavAnnotationOperationKind.restore,
      );
    } else {
      _logNavAnnotationManager(
        gate: _driverAnnotationGate,
        event: 'restore_rejected',
        operation: NavAnnotationOperationKind.restore,
        reason: NavAnnotationRejectReason.notActive,
      );
    }
    List<_LonLat>? restoreCoords;
    var restoreRenderEpoch = capture.renderEpoch;
    if (decision.allowed) {
      restoreCoords = frozenRouteCoords != null && frozenRouteCoords.length >= 2
          ? frozenRouteCoords
          : (_routeCoords.length >= 2 ? List<_LonLat>.from(_routeCoords) : null);
      _logNavRouteRenderOwner(
        event: NavRouteRenderOwnerEvent.styleRestoreAllowed,
      );
    } else if ((decision.reason ==
                StyleRestoreRejectReason.routeVersionMismatch ||
            decision.reason ==
                StyleRestoreRejectReason.renderEpochMismatch ||
            decision.reason ==
                StyleRestoreRejectReason.packageOwnerMismatch) &&
        capture.sessionGeneration == _navigationSessionGeneration &&
        capture.styleGeneration == _styleRequestGeneration &&
        (_liveRideActive || previewRestoreEligibleNow) &&
        _routeCoords.length >= 2) {
      // Same style/session owner, newer accepted route during swap: restore
      // the active package once using current owners (not stale frozen geometry).
      // NAV-PRESTART-FIELD-BLOCKER-3 (Problem A): the rebind also covers a
      // valid preview draft that owns the route.
      restoreCoords = List<_LonLat>.from(_routeCoords);
      restoreRenderEpoch = _routeRenderEpoch;
      _logNavRouteRenderOwner(
        event: NavRouteRenderOwnerEvent.styleRestoreAllowed,
      );
    } else {
      _logNavRouteRenderOwner(
        event: NavRouteRenderOwnerEvent.styleRestoreRejected,
        rejectionReason: styleRestoreRejectReasonToken(
          decision.reason ?? StyleRestoreRejectReason.emptyGeometry,
        ),
      );
    }

    if (restoreCoords != null && restoreCoords.length >= 2) {
      try {
        await _drawRouteLine(
          restoreCoords,
          force: true,
          routeRenderEpoch: restoreRenderEpoch,
        );
        if (_isCurrentRouteRenderEpoch(restoreRenderEpoch) &&
            capture.sessionGeneration == _navigationSessionGeneration &&
            restoreCoords.length >= 2) {
          await _drawPins(
            restoreCoords.first,
            restoreCoords.last,
            routeRenderEpoch: restoreRenderEpoch,
          );
        }
        restoredRoute =
            _isCurrentRouteRenderEpoch(restoreRenderEpoch) &&
            capture.sessionGeneration == _navigationSessionGeneration &&
            restoreCoords.length >= 2;
      } catch (_) {
        restoredRoute = false;
      }
    }

    final restoredTaxi = await _attemptTaxiMarkerRestore(
      attempt: 0,
      reason: reason,
    );

    if (_lastPos != null &&
        _isCurrentRouteRenderEpoch(restoreRenderEpoch) &&
        capture.sessionGeneration == _navigationSessionGeneration) {
      try {
        _updateRouteSnapState(_lastPos!);
        await _syncVisibleRouteLineWithProgress(
          _lastPos!,
          reason: 'style_restore',
          routeRenderEpoch: restoreRenderEpoch,
        );
      } catch (_) {}
    }

    if (_isCurrentRouteRenderEpoch(restoreRenderEpoch) &&
        capture.sessionGeneration == _navigationSessionGeneration) {
      await _syncNavigationDestinationMarker(
        reason: 'style_restore',
        routeRenderEpoch: restoreRenderEpoch,
      );
    }

    unawaited(
      NavDiagnosticsRecorder.instance.recordNavEngineEvent(
        tag: 'NAV_UI_R6D_STYLE_RESTORE',
        fields: <String, dynamic>{
          'route': restoredRoute,
          'taxi': restoredTaxi || _driverMarker != null,
          'reason': reason,
          'hasGps': _lastPos != null,
          'sessionGeneration': _navigationSessionGeneration,
          'styleGeneration': _styleRequestGeneration,
          'routeVersion': _routeStepsVersion,
          'renderEpoch': _routeRenderEpoch,
        },
      ),
    );

    return (route: restoredRoute, taxi: restoredTaxi || _driverMarker != null);
  }

  bool _shouldShowNavigationDestinationMarker() {
    return _liveRideActive && _cameraMode == _CameraMode.follow && _map != null;
  }

  _LonLat? _trustedNavigationDropoffCoordinate() {
    // Prefer the canonical active target when it is a dropoff/return leg.
    final snap = _activeNavTargetOwner.current;
    if (snap != null &&
        snap.isValid &&
        snap.hasCoordinates &&
        (snap.destinationKind == NavigationDestinationKind.dropoff ||
            snap.destinationKind ==
                NavigationDestinationKind.returnDestination)) {
      return _usableNavLonLat(_LonLat(snap.targetLng!, snap.targetLat!));
    }
    final direct = _directRideDestinationPoint;
    if (direct != null) {
      return _usableNavLonLat(_LonLat(direct.lon, direct.lat));
    }
    final booking = _activeBooking;
    if (booking != null) {
      return _usableNavLonLat(_extractPreviewEndpoints(booking).dropoff);
    }
    return null;
  }

  void _clearActiveNavArrivalState({required String reason}) {
    _navParkingArrival.reset();
    _navParkingArrivalConfirmed = false;
    _lastNavArrivalEvent = null;
    _arrivalEvaluatorSnapshotId = null;
    _logNavTargetTruthEvent(
      event: 'arrival_state_cleared',
      arrivalFlagSource: reason,
      previousArrivalConfirmed: false,
    );
  }

  String _nextActiveNavRouteId() {
    return 'route_${_navigationSessionGeneration}_$_routeStepsVersion';
  }

  String? _visibleRouteEndpointHash() {
    if (_routeCoords.isEmpty) return null;
    final last = _routeCoords.last;
    return navigationTargetCoordinateHash(last.lat, last.lon);
  }

  void _logNavTargetTruthEvent({
    required String event,
    String? arrivalFlagSource,
    bool? previousArrivalConfirmed,
    String? googleMapsTargetHash,
    String? pipTargetHash,
    double? remainingRouteMetres,
    double? straightLineTargetDistanceM,
    double? gpsAccuracyM,
  }) {
    final sample = buildNavTargetTruthLogSample(
      event: event,
      target: _activeNavTargetOwner.current,
      previous: _activeNavTargetOwner.previous,
      routeSessionId: _activeNavTargetOwner.current?.routeId,
      visibleRouteEndpointHash: _visibleRouteEndpointHash(),
      arrivalDetectorTargetHash: _activeNavTargetOwner.current?.targetCoordinateHash,
      googleMapsTargetHash: googleMapsTargetHash,
      pipTargetHash: pipTargetHash,
      remainingRouteMetres: remainingRouteMetres,
      straightLineTargetDistanceM: straightLineTargetDistanceM,
      gpsAccuracyM: gpsAccuracyM,
      arrivalFlagSource: arrivalFlagSource,
      previousArrivalConfirmed: previousArrivalConfirmed,
    );
    _logNavBounded('NAV_TARGET_TRUTH', sample.toLogLine(), intervalMs: 1);
  }

  ActiveNavigationTargetSnapshot _installActiveNavTarget({
    required String bookingId,
    String? legId,
    required ActiveNavigationPhase phase,
    double? targetLat,
    double? targetLng,
    String? targetAddress,
    String? routeId,
    required String reason,
  }) {
    final previousArrival = _navParkingArrivalConfirmed;
    if (phase == ActiveNavigationPhase.passengerLeg ||
        phase == ActiveNavigationPhase.returnLeg) {
      // Atomic pickup → passenger/return transition: wipe pickup completion.
      _clearActiveNavArrivalState(reason: 'phase_install_$reason');
      _navPhaseTransitionStaleGuard = true;
      _navPhaseTransitionAt = DateTime.now();
      _kmDriven = 0.0;
      _lastNavRouteProgress = null;
      _navInstructionSnapshot = null;
      _activeBanner = null;
      _nextNavType = null;
      _nextNavDistanceM = null;
    }
    final snap = buildActiveNavigationTargetSnapshot(
      bookingId: bookingId,
      legId: legId,
      navigationPhase: phase,
      destinationKind: destinationKindForPhase(phase),
      targetLat: targetLat,
      targetLng: targetLng,
      targetAddress: targetAddress,
      routeId: routeId,
    );
    _activeNavTargetOwner.replaceForPhaseTransition(snap);
    _arrivalEvaluatorSnapshotId = snap.snapshotId;
    _logNavTargetTruthEvent(
      event: 'target_installed',
      arrivalFlagSource: reason,
      previousArrivalConfirmed: previousArrival,
    );
    return snap;
  }

  void _bindActiveNavTargetToActivatedRoute({
    required DriverRouteApplyPurpose purpose,
    required _LonLat destination,
  }) {
    final routeId = _nextActiveNavRouteId();
    // Align target coords to the visible route endpoint so arrival/KPI/Maps
    // share one hash (geocode POI and routed endpoint often differ).
    final endpoint =
        _routeCoords.isNotEmpty ? _routeCoords.last : destination;
    final bound = _activeNavTargetOwner.bindRoute(
      routeId: routeId,
      targetLat: endpoint.lat,
      targetLng: endpoint.lon,
    );
    if (bound != null) {
      _arrivalEvaluatorSnapshotId = bound.snapshotId;
      if (_navPhaseTransitionStaleGuard &&
          bound.destinationKind != NavigationDestinationKind.pickup) {
        // Route for the new phase is visible — clear stale pickup completion
        // window after bind (guard still blocks arrival until GPS proves B).
      }
      _logNavTargetTruthEvent(
        event: 'route_bound',
        arrivalFlagSource: purpose.name,
        remainingRouteMetres: (_routeKm == null) ? null : _routeKm! * 1000.0,
      );
    }
  }

  NavRemainingDistanceTruth _resolveActiveRemainingDistanceTruth() {
    final target = _activeNavTargetOwner.current;
    final progress = _lastNavRouteProgress;
    final routeLenM = _routeKm == null ? null : _routeKm! * 1000.0;
    return resolveNavRemainingDistanceTruth(
      activeTargetValid: target != null && target.isValid,
      activeRouteId: target?.routeId,
      progressRouteId: target?.routeId,
      routeLengthMeters: routeLenM,
      distanceAlongRouteMeters: progress?.distanceAlongRouteM,
      fallbackRemainingKmFromOdometer: _routeKm == null
          ? null
          : (_routeKm! - _kmDriven).clamp(0.0, double.infinity),
      routeDurationSec: _routeDurationSec,
      kmDriven: _kmDriven,
      trackingCountdownStarted: _isTracking && _hasSwitchedToFollow,
    );
  }

  void _logNavPresDestMarker({
    required String action,
    required String result,
    required String source,
    String? reason,
  }) {
    final signature = '$action|$result|$source|${reason ?? ''}';
    if (signature == _lastNavPresDestMarkerLogSignature) return;
    _lastNavPresDestMarkerLogSignature = signature;
    _logNavBounded(
      'NAV_PRES_DEST_MARKER',
      'action=$action result=$result source=$source style=finish_flag'
          '${reason != null ? ' reason=$reason' : ''}',
      intervalMs: 1200,
    );
  }

  Future<void> _clearNavigationDestinationMarker({
    required String action,
    required String result,
    required String source,
    String? reason,
  }) async {
    final mgr = _destinationMarkerManager;
    final marker = _destinationMarker;
    if (marker != null && mgr != null) {
      // Delete under a lease so it cannot race manager disposal.
      await _runAnnotationTx<void>(
        gate: _destinationAnnotationGate,
        kind: NavAnnotationOperationKind.delete,
        nativeOp: () => mgr.delete(marker),
      );
    }
    _destinationMarker = null;
    _lastDestinationMarkerSignature = null;
    _logNavPresDestMarker(
      action: action,
      result: result,
      source: source,
      reason: reason,
    );
  }

  Future<bool> _ensureDriverFinishFlagMarkerBytes() async {
    if (_driverFinishFlagMarkerLoadAttempted) {
      return _driverFinishFlagMarkerAvailable;
    }
    _driverFinishFlagMarkerLoadAttempted = true;
    try {
      final data = await rootBundle.load(kDriverFinishFlagMarkerAssetPath);
      _driverFinishFlagMarkerBytes = data.buffer.asUint8List(
        data.offsetInBytes,
        data.lengthInBytes,
      );
      _driverFinishFlagMarkerAvailable =
          _driverFinishFlagMarkerBytes!.isNotEmpty;
    } catch (_) {
      _driverFinishFlagMarkerAvailable = false;
      _driverFinishFlagMarkerBytes = null;
    }
    return _driverFinishFlagMarkerAvailable;
  }

  Future<void> _syncNavigationDestinationMarker({
    required String reason,
    int? routeRenderEpoch,
  }) async {
    final drawEpoch = routeRenderEpoch ?? _routeRenderEpoch;
    final drawSession = _navigationSessionGeneration;
    if (_mapStyleChanging) return;
    if (!_isCurrentRouteRenderEpoch(drawEpoch)) return;
    if (!_shouldShowNavigationDestinationMarker()) {
      if (!_isCurrentRouteRenderEpoch(drawEpoch)) return;
      if (_destinationMarker != null) {
        await _clearNavigationDestinationMarker(
          action: 'clear',
          result: 'hidden',
          source: 'none',
          reason: reason,
        );
      }
      return;
    }

    final resolved = resolveNavigationDestinationMarkerCoordinate(
      routeCoords: _routeCoords,
      trustedDropoff: _trustedNavigationDropoffCoordinate(),
    );
    if (resolved == null) {
      if (!_isCurrentRouteRenderEpoch(drawEpoch)) return;
      if (_destinationMarker != null) {
        await _clearNavigationDestinationMarker(
          action: 'clear',
          result: 'none',
          source: 'none',
          reason: reason,
        );
      } else {
        _logNavPresDestMarker(
          action: 'skip',
          result: 'none',
          source: 'none',
          reason: reason,
        );
      }
      return;
    }

    final signature = navigationDestinationMarkerSignature(resolved);
    if (signature == _lastDestinationMarkerSignature &&
        _destinationMarker != null) {
      _logNavPresDestMarker(
        action: 'skip',
        result: 'unchanged',
        source: resolved.source,
        reason: reason,
      );
      return;
    }

    final mgr = _destinationMarkerManager;
    if (mgr == null) return;

    final isTablet = mounted && MediaQuery.sizeOf(context).width >= 600;
    final iconSize = driverDestinationMarkerIconSize(isTablet: isTablet);
    final geometry = _mbPoint(resolved.lon, resolved.lat);
    final previousMarker = _destinationMarker;
    final isUpdate = previousMarker != null;
    final finishFlagReady = await _ensureDriverFinishFlagMarkerBytes();
    if (!_isCurrentRouteRenderEpoch(drawEpoch)) return;
    final finishFlagBytes = _driverFinishFlagMarkerBytes;
    // NAV-ANNOTATION-MANAGER-TRANSACTIONAL-LIFECYCLE-2: destination create +
    // orphan/previous delete under one lease; disposal awaits it before
    // removeAnnotationManager, so no create/delete can reach a removed manager.
    final draw = await _runAnnotationTx<bool>(
      gate: _destinationAnnotationGate,
      kind: NavAnnotationOperationKind.create,
      nativeOp: () async {
        // NAV-SIGNAL-P0B1: create locally; never delete shared refs until commit.
        late final mb.PointAnnotation created;
        if (finishFlagReady && finishFlagBytes != null) {
          created = await mgr.create(
            mb.PointAnnotationOptions(
              geometry: geometry,
              image: finishFlagBytes,
              iconAnchor: mb.IconAnchor.BOTTOM,
              iconSize: iconSize,
              iconOpacity: 0.98,
            ),
          );
        } else {
          created = await mgr.create(
            mb.PointAnnotationOptions(
              geometry: geometry,
              iconImage: kDriverDestinationMarkerIconImage,
              iconColor: kDriverDestinationMarkerIconColor,
              iconHaloColor: kDriverDestinationMarkerIconHaloColor,
              iconHaloWidth: kDriverDestinationMarkerIconHaloWidth,
              iconSize: iconSize,
              iconAnchor: mb.IconAnchor.BOTTOM,
              iconOpacity: 0.96,
            ),
          );
        }
        final commit = evaluateRouteAnnotationCommit(
          capturedRenderEpoch: drawEpoch,
          currentRenderEpoch: _routeRenderEpoch,
          capturedSessionGeneration: drawSession,
          currentSessionGeneration: _navigationSessionGeneration,
        );
        if (commit.shouldDeleteLocalOrphansOnly) {
          await mgr.delete(created);
          _logNavRouteRenderOwner(
            event: NavRouteRenderOwnerEvent.staleCallbackIgnored,
            rejectionReason: 'render_epoch_or_session_mismatch',
          );
          _logNavAnnotationTx(
            gate: _destinationAnnotationGate,
            event: NavAnnotationTxEvent.commitRejected,
            operation: NavAnnotationOperationKind.create,
          );
          return false;
        }
        _destinationMarker = created;
        _lastDestinationMarkerSignature = signature;
        _logNavAnnotationTx(
          gate: _destinationAnnotationGate,
          event: NavAnnotationTxEvent.commitAllowed,
          operation: NavAnnotationOperationKind.create,
        );
        if (previousMarker != null && !identical(previousMarker, created)) {
          await mgr.delete(previousMarker);
        }
        _logNavPresDestMarker(
          action: isUpdate ? 'update' : 'create',
          result: 'applied',
          source: resolved.source,
          reason: reason,
        );
        return true;
      },
    );
    if (!draw.ran) {
      _logNavAnnotationManager(
        gate: _destinationAnnotationGate,
        event: 'stale_operation_rejected',
        operation: NavAnnotationOperationKind.create,
        reason: draw.rejectReason,
      );
    }
  }

  /// NAV-UI-R6E: snapshot the currently visible taxi marker (interpolated
  /// visual, marker geometry, GPS, or route head) before the style is swapped.
  void _captureTaxiVisualSnapshotForStyleSwap() {
    if (_navR3VisualLat != null && _navR3VisualLon != null) {
      _taxiVisualSnapshotForStyleSwap = (
        lat: _navR3VisualLat!,
        lon: _navR3VisualLon!,
        bearing: _navR3VisualBearing,
        source: 'snapshot',
      );
      return;
    }
    final marker = _driverMarker;
    if (marker != null) {
      final coords = marker.geometry.coordinates;
      _taxiVisualSnapshotForStyleSwap = (
        lat: coords.lat.toDouble(),
        lon: coords.lng.toDouble(),
        bearing:
            marker.iconRotate ??
            (_lastKnownBearing.isFinite ? _lastKnownBearing : 0.0),
        source: 'snapshot',
      );
      return;
    }
    _taxiVisualSnapshotForStyleSwap = null;
  }

  /// Best-effort taxi visual for restore: style-swap snapshot > live nav
  /// visual > last GPS fix > route start.
  ({double lat, double lon, double bearing, String source})?
  _lastKnownTaxiVisualForRestore() {
    final snapshot = _taxiVisualSnapshotForStyleSwap;
    if (snapshot != null) return snapshot;
    if (_navR3VisualLat != null && _navR3VisualLon != null) {
      return (
        lat: _navR3VisualLat!,
        lon: _navR3VisualLon!,
        bearing: _navR3VisualBearing,
        source: 'snapshot',
      );
    }
    final pos = _lastPos;
    if (pos != null) {
      return (
        lat: pos.latitude,
        lon: pos.longitude,
        bearing: _lastKnownBearing.isFinite ? _lastKnownBearing : 0.0,
        source: 'last_pos',
      );
    }
    if (_routeCoords.length >= 2) {
      final head = _routeCoords.first;
      return (
        lat: head.lat,
        lon: head.lon,
        bearing: _lastKnownBearing.isFinite ? _lastKnownBearing : 0.0,
        source: 'route_start',
      );
    }
    return null;
  }

  /// NAV-UI-R6E: create the taxi marker (fallback icon instantly if the PNG is
  /// not ready — `_createDriverMarkerAnnotation` handles that swap) from the
  /// best known visual, without waiting for a GPS callback.
  ///
  /// NAV-3D-YELLOW-TAXI-FINAL-VISIBILITY-FIX-1: single-flight — style
  /// restore, the 100/300/700 ms retries and self-heal share this entry
  /// point, and their async creates could previously race past the
  /// `_driverMarker == null` check and each complete, orphaning an extra
  /// rendered annotation. Only one create runs at a time; a concurrent
  /// request marks a rerun which the owner honours at most once.
  Future<bool> _attemptTaxiMarkerRestore({
    required int attempt,
    required String reason,
  }) async {
    if (_driverMarker != null) return true;
    if (_taxiMarkerRestoreInFlight) {
      _taxiMarkerRestoreRerunRequested = true;
      debugPrint(
        '[NAV_UI_R6E_TAXI_RESTORE] attempt=$attempt success=false '
        'source=in_flight reason=${reason}_deferred',
      );
      return false;
    }
    _taxiMarkerRestoreInFlight = true;
    try {
      var success = await _attemptTaxiMarkerRestoreOnce(
        attempt: attempt,
        reason: reason,
      );
      if (!success &&
          _taxiMarkerRestoreRerunRequested &&
          _driverMarker == null) {
        _taxiMarkerRestoreRerunRequested = false;
        success = await _attemptTaxiMarkerRestoreOnce(
          attempt: attempt,
          reason: '${reason}_rerun',
        );
      }
      return success;
    } finally {
      _taxiMarkerRestoreInFlight = false;
      _taxiMarkerRestoreRerunRequested = false;
    }
  }

  Future<bool> _attemptTaxiMarkerRestoreOnce({
    required int attempt,
    required String reason,
  }) async {
    if (_driverMarker != null) return true;
    final visual = _lastKnownTaxiVisualForRestore();
    final source = visual?.source ?? 'fallback';
    var success = false;
    if (visual != null && _map != null && !_mapStyleChanging) {
      try {
        var mgr = _driverPointManager;
        if (mgr == null) {
          mgr = await _map!.annotations.createPointAnnotationManager();
          await _configureDriverPointManagerForTaxiMarker(mgr);
          _driverPointManager = mgr;
          // NAV-ANNOTATION-MANAGER-TRANSACTIONAL-LIFECYCLE-2: re-activate the
          // executor for the freshly created manager so leased ops resume.
          _activateAnnotationGate(
            _driverAnnotationGate,
            event: 'activated_restore',
          );
        }
        // NAV-3D-MAPBOX-2D-MARKER-ISOLATION-FIX-1: creation-time opacity
        // is snapped from the single authoritative resolver so a marker
        // restored during a 3D style/preset transition cannot be born
        // visible.
        final restoreSource = attempt == 0
            ? (reason.contains('self_heal') ? 'self_heal' : 'restore')
            : 'retry_restore';
        final opacity = _resolveDesiredMapboxTaxiOpacity(source: restoreSource);
        // Create under a lease so it cannot race a concurrent disposal.
        final createdMgr = mgr;
        final leaseRun = await _driverAnnotationGate.runGuarded<mb.PointAnnotation?>(
          ownership: _driverAnnotationGate.capture(),
          kind: NavAnnotationOperationKind.create,
          nativeOp: () => _createDriverMarkerAnnotation(
            mgr: createdMgr,
            geometry: _mbPoint(visual.lon, visual.lat),
            markerBearing: visual.bearing,
            iconOpacity: opacity,
          ),
        );
        _driverMarker = leaseRun.ran ? leaseRun.value : null;
        success = _driverMarker != null;
        if (success) {
          // NAV-R12-D: a freshly created marker proves the manager works.
          _markerLifecycle.noteSelfHealSucceeded(DateTime.now());
          logNav3dMapbox2d(
            event: 'create',
            presentation3dIntent:
                opacity == 0.0 && !_vehicleModelSyncLifecycle.sessionFallback2d,
            explicit2dFallback: _vehicleModelSyncLifecycle.sessionFallback2d,
            desiredOpacity: opacity,
            pendingOpacity: _pendingMapboxTaxiMarkerOpacity,
            markerExists: true,
            appliedOpacity: opacity,
            source: restoreSource,
          );
        }
      } catch (e) {
        if (_isMapboxAnnotationManagerLost(e)) {
          _resetDriverMarkerOnNativeError('taxi_restore_attempt$attempt');
        }
      }
    }
    debugPrint(
      '[NAV_UI_R6E_TAXI_RESTORE] attempt=$attempt success=$success source=$source reason=$reason',
    );
    unawaited(
      NavDiagnosticsRecorder.instance.recordNavEngineEvent(
        tag: 'NAV_UI_R6E_TAXI_RESTORE',
        fields: <String, dynamic>{
          'attempt': attempt,
          'success': success,
          'source': source,
          'reason': reason,
        },
      ),
    );
    return success;
  }

  /// NAV-UI-R6E: retry marker restore at 100/300/700 ms after style load in
  /// case the immediate restore raced native style loading. Also upgrades a
  /// temporary fallback marker to the taxi PNG once the asset is available.
  /// Each attempt re-forces the puck hidden.
  void _scheduleTaxiMarkerRestoreRetries({required String reason}) {
    for (final entry in const <(int, int)>[(1, 100), (2, 300), (3, 700)]) {
      final (attempt, delayMs) = entry;
      Future<void>.delayed(Duration(milliseconds: delayMs), () async {
        if (!mounted || _map == null || _mapStyleChanging) return;
        if (_driverMarker == null) {
          await _attemptTaxiMarkerRestore(attempt: attempt, reason: reason);
        } else if (!_driverMarkerUsesTaxiAsset && _driverTaxiMarkerAvailable) {
          await _upgradeFallbackMarkerToTaxi(attempt: attempt, reason: reason);
        }
        await _syncMapboxUserLocationPuckVisibility();
      });
    }
  }

  /// Replace a temporary fallback marker with the taxi PNG in place.
  Future<void> _upgradeFallbackMarkerToTaxi({
    required int attempt,
    required String reason,
  }) async {
    final mgr = _driverPointManager;
    final marker = _driverMarker;
    if (mgr == null || marker == null) return;
    final geometry = marker.geometry;
    final bearing =
        marker.iconRotate ??
        (_lastKnownBearing.isFinite ? _lastKnownBearing : 0.0);
    // NAV-ANNOTATION-MANAGER-TRANSACTIONAL-LIFECYCLE-2: swap under one lease.
    if (!_driverAnnotationGate.tryAcquireLease(
      _driverAnnotationGate.capture(),
      NavAnnotationOperationKind.update,
    )) {
      return;
    }
    try {
      await mgr.delete(marker);
      _driverMarker = null;
      // NAV-3D-MAPBOX-2D-MARKER-ISOLATION-FIX-1: pending desired opacity is
      // authoritative here — creation must not fall back to default 1.0.
      final opacity = _resolveDesiredMapboxTaxiOpacity(source: 'asset_upgrade');
      _driverMarker = await _createDriverMarkerAnnotation(
        mgr: mgr,
        geometry: geometry,
        markerBearing: bearing,
        iconOpacity: opacity,
      );
      debugPrint(
        '[NAV_UI_R6E_TAXI_RESTORE] attempt=$attempt success=${_driverMarker != null} source=fallback reason=${reason}_asset_upgrade',
      );
      if (_driverMarker != null) {
        logNav3dMapbox2d(
          event: 'create',
          presentation3dIntent:
              opacity == 0.0 && !_vehicleModelSyncLifecycle.sessionFallback2d,
          explicit2dFallback: _vehicleModelSyncLifecycle.sessionFallback2d,
          desiredOpacity: opacity,
          pendingOpacity: _pendingMapboxTaxiMarkerOpacity,
          markerExists: true,
          appliedOpacity: opacity,
          source: 'asset_upgrade',
        );
      }
    } catch (e) {
      if (_isMapboxAnnotationManagerLost(e)) {
        _resetDriverMarkerOnNativeError('taxi_asset_upgrade');
      }
    } finally {
      _driverAnnotationGate.releaseLease();
    }
  }

  void _logNavMapStyle({required String reason}) {
    _logNavBounded(
      'NAV_MAPSTYLE',
      'mode=${driverMapVisualModeLogLabel(_driverMapVisualMode)} reason=$reason',
      intervalMs: reason == 'user_toggle' ? 1 : 2500,
    );
  }

  ({
    NavR9OfflineUiState state,
    String reason,
    bool showTunnelChip,
    bool showGpsReacquireChip,
  })
  _navR9OfflineReadiness() {
    final prediction = _lastNavMotionPrediction;
    final readiness = NavR9OfflineReadiness.derive(
      usableInternetConnection: _usableInternetConnection,
      liveRideActive: _liveRideActive,
      followNavActive: _cameraMode == _CameraMode.follow,
      localRouteReady: _routeCoords.length >= 2,
      predictionActive: prediction?.predictionActive ?? false,
      predictionConfidence: prediction?.confidence,
      weakGps: _isWeakGpsForPrediction(_lastPos),
      gapSinceLastEngineMs: _gapSinceLastNavEngineMs(),
    );
    _logNavOfflineGuidance(
      readiness: readiness,
      tunnelDetected:
          (prediction?.predictionActive ?? false) &&
          _isWeakGpsForPrediction(_lastPos),
      gpsConfidence: prediction?.confidence,
      mapMatchConfidence: _lastNavRouteProgress?.confidence,
    );
    return readiness;
  }

  Future<void> _startNavInternetConnectivityMonitoring() async {
    final initiallyUsable = await _navInternetConnection.hasInternetAccess
        .catchError((_) => true);
    _setNavInternetConnectivity(
      usable: initiallyUsable,
      state: initiallyUsable ? 'connected' : 'disconnected',
    );
    _navInternetStatusSubscription?.cancel();
    _navInternetStatusSubscription = _navInternetConnection.onStatusChange
        .listen(
          (status) => _setNavInternetConnectivity(
            usable: status == InternetStatus.connected,
            state: status.name,
          ),
          onError: (_) {
            // Keep the current known state rather than treating a monitor
            // error or a backend timeout as proof of no internet.
            _navConnectivityState = 'monitor_error';
          },
        );
  }

  void _setNavInternetConnectivity({
    required bool usable,
    required String state,
  }) {
    final wasUsable = _usableInternetConnection;
    if (usable == wasUsable && _navConnectivityState == state) {
      return;
    }
    if (mounted) {
      setState(() {
        _usableInternetConnection = usable;
        _navConnectivityState = state;
      });
    } else {
      _usableInternetConnection = usable;
      _navConnectivityState = state;
    }
    // OFFLINE-STOP-RIDE-DURABILITY-P0: reconnect must drain the frozen STOP
    // outbox without requiring an app restart.
    if (!wasUsable && usable) {
      unawaited(_recoverPendingDirectTripSession());
    }
  }

  void _logNavOfflineGuidance({
    required ({
      NavR9OfflineUiState state,
      String reason,
      bool showTunnelChip,
      bool showGpsReacquireChip,
    })
    readiness,
    required bool tunnelDetected,
    required double? gpsConfidence,
    required double? mapMatchConfidence,
  }) {
    final offlineGuidanceActive = readiness.showTunnelChip;
    _logNavBounded(
      'NAV_OFFLINE_GUIDANCE',
      'usableInternet=$_usableInternetConnection '
          'connectivityState=$_navConnectivityState '
          'tunnelDetected=$tunnelDetected '
          'gpsConfidence=${gpsConfidence?.toStringAsFixed(1) ?? 'na'} '
          'mapMatchConfidence=${mapMatchConfidence?.toStringAsFixed(1) ?? 'na'} '
          'offlineGuidanceActive=$offlineGuidanceActive '
          'reason=${readiness.reason}',
      intervalMs: 2500,
    );
  }

  void _logNavR9Offline({
    required NavR9OfflineUiState state,
    required String reason,
  }) {
    _logNavBounded(
      'NAV_R9_OFFLINE',
      'state=${NavR9OfflineReadiness.logStateLabel(state)} reason=$reason',
      intervalMs: 2500,
    );
    _recordNavDiagR9OfflineTransition(state: state, reason: reason);
  }

  Widget _buildNavR9DataOffStatusChip({
    required bool showTunnelChip,
    required bool showGpsReacquireChip,
    required Color navText,
    required Color navSurface,
    required Color navAccent,
  }) {
    if (!showTunnelChip && !showGpsReacquireChip) {
      return const SizedBox.shrink();
    }
    final label = showGpsReacquireChip
        ? _tr(
            nl: 'GPS wordt opnieuw gezocht',
            en: 'Reacquiring GPS',
            fr: 'Reacquisition GPS',
            es: 'Readquiriendo GPS',
          )
        : _tr(
            nl: 'Tunnel/offline begeleiding',
            en: 'Tunnel/offline guidance',
            fr: 'Guidage tunnel/hors ligne',
            es: 'Guia tunel/sin conexion',
          );
    final icon = showGpsReacquireChip
        ? Icons.gps_not_fixed_rounded
        : Icons.wifi_off_rounded;
    return Padding(
      padding: const EdgeInsets.only(bottom: 6),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
        decoration: BoxDecoration(
          color: navSurface,
          borderRadius: BorderRadius.circular(20),
          border: Border.all(color: navAccent.withOpacity(0.45)),
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(icon, size: 14, color: navAccent),
            const SizedBox(width: 6),
            Text(
              label,
              style: TextStyle(
                color: navText.withOpacity(0.92),
                fontSize: 11,
                fontWeight: FontWeight.w700,
              ),
            ),
          ],
        ),
      ),
    );
  }

  Future<void> _toggleDriverMapVisualMode() async {
    if (!kDriverMapSatelliteToggleEnabled || _map == null) return;
    // NAV-RELEASE-FINAL-FLOW-1: same lock as the cockpit style chips — no
    // style swap during active NAV guidance or the paid customer trip.
    if (navStyleTapDecision(
          liveRideActive: _liveRideActive || _navigationGuidanceActive,
          styleTransactionRunning: _mapStyleChanging,
        ) ==
        NavStyleTapDecision.blocked) {
      _logNavMapStyle(reason: 'visual_mode_toggle_blocked_active_nav');
      return;
    }
    if (kNavigation3dCockpitSceneEnabled) {
      final next =
          _driverCockpitMapVisualStyle == DriverCockpitMapVisualStyle.satellite
          ? (_effectiveMapThemeFor(_cameraMode) == MapThemeMode.dark
                ? DriverCockpitMapVisualStyle.dark
                : DriverCockpitMapVisualStyle.light)
          : DriverCockpitMapVisualStyle.satellite;
      await _setDriverCockpitMapVisualStyle(next);
      return;
    }
    final next = _driverMapVisualMode == DriverMapVisualMode.satellite
        ? DriverMapVisualMode.street
        : DriverMapVisualMode.satellite;
    if (!_liveRideActive) _preStartStyleSelected = true;
    if (mounted) {
      setState(() => _driverMapVisualMode = next);
    } else {
      _driverMapVisualMode = next;
    }
    _logNavMapStyle(reason: 'user_toggle');
    await _applyMapStyleForMode();
  }

  double _driverTaxiIconSizeForCurrentZoom() {
    return driverTaxiMarkerIconSizeForZoom(_lastMapCameraZoom);
  }

  Future<void> _syncDriverMarkerIconSizeForZoom() async {
    if (!_canUpdateDriverMarker) return;
    final mgr = _driverPointManager;
    final marker = _driverMarker;
    if (mgr == null || marker == null) return;
    final size = _driverMarkerUsesTaxiAsset
        ? _driverTaxiIconSizeForCurrentZoom()
        : driverFallbackMarkerIconSizeForZoom(_lastMapCameraZoom);
    final current = marker.iconSize ?? 0.0;
    // NAV-3D-MAPBOX-2D-MARKER-ISOLATION-FIX-1: even if iconSize did not
    // change, rebase iconOpacity from the authoritative resolver so a stale
    // Dart-side 1.0 cannot be re-pushed during active 3D isolation on a
    // subsequent mgr.update path.
    final desired = _resolveDesiredMapboxTaxiOpacity(source: 'zoom_sync');
    final opacityCurrent = marker.iconOpacity ?? 1.0;
    final opacityDrifted = (opacityCurrent - desired).abs() >= 0.001;
    final sizeChanged = (current - size).abs() >= 0.03;
    if (!sizeChanged && !opacityDrifted) return;
    if (sizeChanged) {
      marker.iconSize = size;
    }
    if (opacityDrifted) {
      marker.iconOpacity = desired;
    }
    // NAV-ANNOTATION-MANAGER-TRANSACTIONAL-LIFECYCLE-2: leased update.
    if (!_driverAnnotationGate.tryAcquireLease(
      _driverAnnotationGate.capture(),
      NavAnnotationOperationKind.update,
    )) {
      return;
    }
    try {
      await mgr.update(marker);
    } catch (e) {
      if (_isMapboxAnnotationManagerLost(e)) {
        _resetDriverMarkerOnNativeError('sync_icon_size');
      }
    } finally {
      _driverAnnotationGate.releaseLease();
    }
  }

  mb.Point _mbPoint(double lon, double lat) =>
      mb.Point(coordinates: mb.Position(lon, lat));

  double _metersBetween(_LonLat a, _LonLat b) {
    return driverMetersBetween(a, b);
  }

  double _snapThresholdFor(geo.Position pos) {
    final accuracy = pos.accuracy.isFinite && pos.accuracy > 0
        ? pos.accuracy
        : 20.0;
    return math.max(35.0, math.min(90.0, accuracy * 1.8));
  }

  double _speedKmhFor(geo.Position pos) {
    if (!pos.speed.isFinite || pos.speed < 0) return 0.0;
    return pos.speed * 3.6;
  }

  double? _gpsFixAgeSec(geo.Position pos) {
    final ts = pos.timestamp;
    return DateTime.now().difference(ts).inMilliseconds / 1000.0;
  }

  bool _isGpsQualityAcceptableForCamera(geo.Position pos) {
    final ageSec = _gpsFixAgeSec(pos);
    if (ageSec != null && ageSec > _followCameraStaleGpsMaxAgeSec) {
      return false;
    }
    final accuracy = pos.accuracy;
    if (accuracy.isFinite && accuracy > _followCameraPoorAccuracyM) {
      return false;
    }
    return true;
  }

  int _followCameraThrottleMsFor(geo.Position pos) {
    final speedKmh = _speedKmhFor(pos);
    if (speedKmh >= 25) return 160;
    if (speedKmh >= 8) return 200;
    return 260;
  }

  int _followCameraAnimMsFor(geo.Position pos) {
    final speedKmh = _speedKmhFor(pos);
    if (speedKmh >= 30) return 140;
    if (speedKmh >= 10) return 180;
    return 220;
  }

  ({double zoom, double pitch, String reason}) _followCameraZoomPitchFor(
    geo.Position pos,
  ) {
    final speedKmh = _speedKmhFor(pos);
    final distanceToManeuver =
        _navInstructionSnapshot?.distanceToManeuverMeters ??
        _nextNavDistanceM ??
        double.infinity;
    final nearManeuver =
        distanceToManeuver.isFinite &&
        distanceToManeuver <= kDriverNavR1NearManeuverCameraDistanceM;

    if (nearManeuver) {
      if (speedKmh < 4) {
        return (zoom: 17.4, pitch: 56.0, reason: 'near_maneuver');
      }
      if (speedKmh < 15) {
        return (zoom: 17.8, pitch: 62.0, reason: 'near_maneuver');
      }
      return (zoom: 18.1, pitch: 66.0, reason: 'near_maneuver');
    }

    // NAV-R1: reduced default follow zoom (was ~18.0–18.9).
    if (speedKmh < 4) {
      return (zoom: 16.4, pitch: 50.0, reason: 'normal_follow');
    }
    if (speedKmh < 15) {
      return (zoom: 16.9, pitch: 56.0, reason: 'normal_follow');
    }
    return (zoom: 17.2, pitch: 60.0, reason: 'normal_follow');
  }

  double _normalizeBearingDeg(double bearing) {
    var b = bearing % 360.0;
    if (b < 0) b += 360.0;
    return b;
  }

  double _smoothFollowCameraBearing(
    double target,
    double speedKmh, {
    double bearingModeWeight = 1.0,
    NavCameraViewMode viewMode = NavCameraViewMode.overview,
  }) {
    final bearingTarget = navCameraViewModeUsesFixedNorthBearing(viewMode)
        ? northUpCameraBearingTarget()
        : target;
    final normalizedTarget = _normalizeBearingDeg(bearingTarget);
    final prev = _lastSmoothedCameraBearing;
    if (prev == null || !prev.isFinite) {
      _lastSmoothedCameraBearing = normalizedTarget;
      return normalizedTarget;
    }
    var delta = normalizedTarget - prev;
    while (delta > 180) delta -= 360;
    while (delta < -180) delta += 360;
    final maxStep = navCameraViewModeUsesFixedNorthBearing(viewMode)
        ? northUpBearingAlignMaxStep(speedKmh)
        : navCameraBearingMaxStep(
            viewMode: viewMode,
            speedKmh: speedKmh,
            bearingModeWeight: bearingModeWeight,
          );
    if (maxStep <= 0.01) {
      return prev;
    }
    if (delta.abs() <= maxStep) {
      _lastSmoothedCameraBearing = normalizedTarget;
      return normalizedTarget;
    }
    final next = _normalizeBearingDeg(prev + delta.sign * maxStep);
    _lastSmoothedCameraBearing = next;
    return next;
  }

  /// NAV-PRES-1: presentation boundary adapter; camera/marker paths still read
  /// [_navCameraViewMode] directly until a later migration step.
  NavigationPresentationState _navigationPresentationStateFor(
    NavCameraViewMode viewMode,
  ) {
    return NavigationPresentationController.instance
        .resolveForNavCameraViewMode(viewMode);
  }

  Driver3dVehicleEligibility _driver3dVehicleEligibility({
    bool? styleLoaded,
    bool? styleSwapInProgress,
    bool? modelRegistered,
    bool? modelPoseApplied,
    bool? modelActivationConfirmed,
    bool? renderCredibilityConfirmed,
    bool? assetLoaded,
    bool? useDriverCockpitCamera,
    NavigationPresentationMode? presentationMode,
  }) {
    final pres = _navigationPresentationStateFor(_navCameraViewMode);
    final preset = _effectiveDriverVehicle3dPreset();
    final resolvedAssetLoaded =
        assetLoaded ??
        resolveObservationalAssetLoaded(
          lifecycle: _driver3dVehicleAssetLifecycle,
          preset: preset,
          styleGeneration: _driver3dVehicleStyleGeneration,
          presetGeneration: _vehicleSwapGeneration,
          modelRegistered:
              modelRegistered ?? _driverVehicleModelLayer.isRegistered,
        );
    final followLiveActive =
        _cameraMode == _CameraMode.follow && _liveRideActive;
    final debugRenderProbeActive = _isDriver3dVehicleDebugPlacementActive();
    return resolveDriver3dVehicleEligibility(
      vehicleModelFlagEnabled: kNavigation3dVehicleModelEnabled,
      cockpitSceneEnabled: kNavigation3dCockpitSceneEnabled,
      useDriverCockpitCamera:
          useDriverCockpitCamera ?? pres.useDriverCockpitCamera,
      presentationMode: presentationMode ?? pres.mode,
      liveNavigationActive: _liveRideActive,
      followCamera: _cameraMode == _CameraMode.follow,
      activeStyleUri: _activeMapStyleUri,
      visualMode: _driverMapVisualMode,
      cockpitSceneActive: _isDriverCockpit3dSceneEligible(),
      cockpitVisualStyle: kNavigation3dCockpitSceneEnabled
          ? _driverCockpitMapVisualStyle
          : null,
      sessionFallback2d: _vehicleModelSyncLifecycle.sessionFallback2d,
      styleLoaded: styleLoaded ?? (_map?.style != null && !_mapStyleChanging),
      styleSwapInProgress: styleSwapInProgress ?? _mapStyleChanging,
      modelRegistered: modelRegistered ?? _driverVehicleModelLayer.isRegistered,
      modelPoseApplied: modelPoseApplied ?? _driver3dVehicleModelPoseApplied,
      hideHudIsolationFlagEnabled: kNavigation3dVehicleHideHudEnabled,
      layerCreated: _driverVehicleModelLayer.layerCreated,
      sourceGeometryValid: _driverVehicleModelLayer.sourceGeometryValid,
      modelActivationConfirmed:
          modelActivationConfirmed ?? _driver3dVehicleModelActivationConfirmed,
      renderCredibilityConfirmed:
          renderCredibilityConfirmed ??
          _driver3dVehicleRenderCredibilityConfirmed,
      assetLoaded: resolvedAssetLoaded,
      debugRenderProbeActive: debugRenderProbeActive,
      activeStyleGeneration: _driver3dVehicleStyleGeneration,
      activePresetGeneration: _vehicleSwapGeneration,
      confirmedStyleGeneration: _driver3dVehicleActivationStyleGeneration,
      confirmedPresetGeneration: _driver3dVehicleActivationPresetGeneration,
      modelLayerStyleGeneration: _driver3dVehicleLayerBoundStyleGeneration,
      modelLayerPresetGeneration: _driver3dVehicleLayerBoundPresetGeneration,
      followLiveActive: followLiveActive,
      useDriver3dVehicleModel: pres.useDriver3dVehicleModel,
      selectedVehiclePresentation: _driverVehiclePresentationChoice,
      native3dRendererActive: _native3dRendererActiveForChoice(),
    );
  }

  Nav3dVehicleHandoffSnapshot _buildDriver3dVehicleHandoffSnapshot(
    Driver3dVehicleEligibility eligibility,
    DriverVehicle3dPreset preset,
  ) {
    final spec = resolveDriverVehicle3dModelSpec(preset);
    final applied = _driverVehicleModelLayer.appliedMovementState;
    final appliedCamera = _driverVehicleModelAppliedCameraState();
    final debugPlacement = _isDriver3dVehicleDebugPlacementActive();
    final scale =
        applied?.scale ??
        resolveDriverVehicleModelScaleForPreset(
          appliedZoom: appliedCamera.zoom,
          appliedPitch: appliedCamera.pitch,
          preset: preset,
          debugPlacementActive: debugPlacement,
          viewLevel: _driverCockpitViewLevel,
        );
    final rotation =
        applied?.rotation ??
        resolveDriverVehicleModelFinalRotationForPreset(
          _lastKnownBearing,
          preset: preset,
          debugPlacementActive: debugPlacement,
        );
    final elevation = resolveDriverVehicleModelAltitudeMetersForPreset(
      debugPlacementActive: debugPlacement,
      preset: preset,
    );
    return Nav3dVehicleHandoffSnapshot(
      preset: driverVehicle3dPresetLogLabel(preset),
      modelRegistered: _driverVehicleModelLayer.isRegistered,
      layerCreated: _driverVehicleModelLayer.layerCreated,
      sourceGeometryValid: _driverVehicleModelLayer.sourceGeometryValid,
      modelPoseApplied: _driver3dVehicleModelPoseApplied,
      modelActivationConfirmed: _driver3dVehicleModelActivationConfirmed,
      hudFallbackAllowedToHide: eligibility.hudFallbackAllowedToHide,
      hudTaxiHidden: eligibility.hudTaxiHidden,
      activeStyleGeneration: _driver3dVehicleStyleGeneration,
      activePresetGeneration: _vehicleSwapGeneration,
      confirmedStyleGeneration: _driver3dVehicleActivationStyleGeneration,
      confirmedPresetGeneration: _driver3dVehicleActivationPresetGeneration,
      styleModelId: resolveDriverVehicle3dStyleModelId(preset),
      assetUri: spec.assetUri,
      appliedScale: formatDriverVehicleModelScaleForLog(scale),
      appliedRotation: formatDriverVehicleModelRotationForLog(rotation),
      appliedElevation: elevation,
    );
  }

  void _logDriver3dVehicleStateIfChanged({String? handoffReason}) {
    if (!mounted) return;
    final eligibility = _driver3dVehicleEligibility();
    final preset = _effectiveDriverVehicle3dPreset();
    final assetLoaded = resolveObservationalAssetLoaded(
      lifecycle: _driver3dVehicleAssetLifecycle,
      preset: preset,
      styleGeneration: _driver3dVehicleStyleGeneration,
      presetGeneration: _vehicleSwapGeneration,
      modelRegistered: _driverVehicleModelLayer.isRegistered,
    );
    final diagnosticSnapshot = resolveNav3dVehicleDiagnosticSnapshot(
      presentationActive: _isDriverCockpit3dSceneEligible(),
      featureEnabled: kNavigation3dVehicleModelEnabled,
      cockpitSceneEnabled: kNavigation3dCockpitSceneEnabled,
      cockpitVisualStyle: kNavigation3dCockpitSceneEnabled
          ? _driverCockpitMapVisualStyle
          : null,
      vehiclePreset: preset,
      activeStyleUri: _activeMapStyleUri,
      eligibility: eligibility,
      assetLoaded: assetLoaded,
      modelRegistered: _driverVehicleModelLayer.isRegistered,
      layerCreated: _driverVehicleModelLayer.layerCreated,
      modelPoseApplied: _driver3dVehicleModelPoseApplied,
      modelActivationConfirmed: _driver3dVehicleModelActivationConfirmed,
      renderCredibilityConfirmed: _driver3dVehicleRenderCredibilityConfirmed,
      registerInFlight: _driverVehicleModelLayer.registerInFlight,
      selectedVehiclePresentation: _driverVehiclePresentationChoice,
      native3dRendererActive: _native3dRendererActiveForChoice(),
    );
    final handoffSnapshot = _buildDriver3dVehicleHandoffSnapshot(
      eligibility,
      preset,
    );
    _driver3dVehicleLogCoordinator.logStateIfChanged(
      eligibility: eligibility,
      diagnosticSnapshot: diagnosticSnapshot,
      handoffSnapshot: handoffSnapshot,
      handoffReason: handoffReason,
    );
  }

