  // NAV-PRESTART-FIELD-BLOCKER-3 (Problem B + C): opaque token bridge for the
  // pre-start preview presentation decision. Keeps the decision module free
  // of the driver-page NavCameraViewMode enum.
  String _navPreviewViewModeToken() {
    switch (_navCameraViewMode) {
      case NavCameraViewMode.streetView:
        return NavPreviewViewModeTokens.streetView;
      case NavCameraViewMode.northUp:
        return NavPreviewViewModeTokens.northUp;
      case NavCameraViewMode.overview:
        return NavPreviewViewModeTokens.overview;
    }
  }

  /// NAV-PRESTART-FIELD-BLOCKER-3 (Problem B + C): applies the driver-cockpit
  /// camera profile during pre-start preview so streetlevel actually anchors
  /// the vehicle low above the KPI panel. Deliberately uses `_map.flyTo`
  /// directly instead of `_followCameraTesla` so the live follow guards
  /// (`follow + liveRideActive`) stay intact.
  Future<void> _applyPreviewStreetlevelCameraIfEligible({
    required String reason,
  }) async {
    if (!mounted) return;
    if (_map == null || !_mapSupported) return;
    if (_liveRideActive) return;
    if (_navCameraViewMode != NavCameraViewMode.streetView) return;
    // NAV-RELEASE-FINAL-FLOW-1: street draft OR prepared booking preview.
    if (!_fixedStreetLevelPreviewDraft) return;
    final pos = _lastPos;
    if (pos == null) return;
    // NAV-FIXED-HUD-PRESENTATION-1: route-up, never raw GPS course. At
    // standstill `pos.heading` is noise (or 0), which is exactly why the
    // prepared route did not extend toward the top of the screen.
    final routeUp = resolveNavFixedRouteUpBearing(
      routeTangentBearingDeg: navFirstMeaningfulRouteSegmentBearing(
        _routeCoords,
      ),
      seededRouteBearingDeg: _navStationaryBearingGate.acceptedBearing,
      gpsHeadingDeg: pos.heading.isFinite ? pos.heading : null,
    );
    // NAV-PHASE-CAMERA-TARGET-1: center on pickup A (prepared booking) or
    // the first route point (prepared street draft) rather than the raw
    // driver GPS. When the driver is not yet at A, targeting driver GPS put
    // the HUD off the route line and let the route point sideways.
    final target = _resolvePhaseCameraTargetForPreview(pos);
    if (!target.hasCoordinate) return;
    final width = MediaQuery.sizeOf(context).width;
    final height = MediaQuery.sizeOf(context).height;
    final safe = MediaQuery.of(context).padding;
    final orientation = MediaQuery.of(context).orientation;
    final isLandscape = orientation == Orientation.landscape;
    final screenClass = FluxidiBreakpoints.classifyDeviceSize(
      Size(width, height),
    );
    final bool isTablet =
        screenClass == FluxidiScreenClass.tablet ||
        screenClass == FluxidiScreenClass.desktop;
    final overrides = _driverCockpitCameraOverrides(
      policyZoom: _lastDriverCockpitAppliedZoom ??
          driverCockpitViewLevelTargetZoom(
            isTablet: isTablet,
            isLandscape: isLandscape,
            level: _driverCockpitViewLevel,
          ),
      policyPitch: _lastDriverCockpitAppliedPitch ??
          driverCockpitViewLevelTargetPitch(
            isTablet: isTablet,
            isLandscape: isLandscape,
            level: _driverCockpitViewLevel,
          ),
      isTablet: isTablet,
      isLandscape: isLandscape,
      safeTop: safe.top,
      safeBottom: safe.bottom,
      screenHeight: height,
      vehicleLat: target.lat,
      vehicleLon: target.lon,
      bearingDeg: routeUp.bearingDeg,
      speedKmh: 0.0,
      progress: null,
      directAdjust: true,
    );
    _commitDriverCockpitAppliedCamera(
      zoom: overrides.zoom,
      pitch: overrides.pitch,
    );
    final bearingDeg = routeUp.bearingDeg;
    try {
      await _map!.flyTo(
        mb.CameraOptions(
          center: _mbPoint(target.lon, target.lat),
          zoom: overrides.zoom,
          pitch: overrides.pitch,
          bearing: bearingDeg,
          padding: mb.MbxEdgeInsets(
            top: overrides.padding.top,
            left: overrides.padding.left,
            bottom: overrides.padding.bottom,
            right: overrides.padding.right,
          ),
        ),
        mb.MapAnimationOptions(duration: 650),
      );
      _logNavBounded(
        'NAV_PRESTART_PREVIEW',
        'event=streetlevel_camera_apply reason=$reason '
        'level=$_driverCockpitViewLevel '
        'zoom=${overrides.zoom.toStringAsFixed(2)} '
        'pitch=${overrides.pitch.toStringAsFixed(1)} '
        'bearing=${bearingDeg.toStringAsFixed(1)} '
        'bearingSource=${navFixedRouteUpBearingSourceLabel(routeUp.source)} '
        'targetSource=${navPhaseCameraTargetSourceLabel(target.source)} '
        'anchor=${overrides.anchorFraction.toStringAsFixed(3)}',
      );
    } catch (_) {
      // Transient Mapbox flyTo errors are retried by the next preview event.
    }
  }

  /// NAV-RELEASE-SIMPLE-STREETLEVEL-1: presentation toggle retired. Kept as a
  /// no-op so any stray call site cannot switch away from fixed streetlevel.
  Future<void> _setNavPreStartPresentation(
    NavPreviewPresentationMode mode,
  ) async {
    if (!mounted) return;
    if (_liveRideActive) return;
    if (_navCameraViewMode != NavCameraViewMode.streetView) {
      setState(() {
        _navCameraViewMode = NavCameraViewMode.streetView;
        _allowOverviewCamera = false;
      });
    }
    await _applyPreviewStreetlevelCameraIfEligible(
      reason: 'fixed_streetlevel_enforce',
    );
  }

  /// NAV-RELEASE-SIMPLE-STREETLEVEL-1: live view-mode cycling removed.
  void _toggleNavCameraViewMode() {
    if (_cameraMode != _CameraMode.follow || !_liveRideActive) return;
    if (_navCameraViewMode != NavCameraViewMode.streetView) {
      setState(() => _navCameraViewMode = NavCameraViewMode.streetView);
    }
    _allowOverviewCamera = false;
    final pos = _lastPos;
    if (pos != null) {
      unawaited(
        _followCameraTesla(pos, force: true, cameraReason: 'fixed_streetlevel'),
      );
    }
  }

  void _logNavR15CameraView({
    required NavCameraViewMode mode,
    required NavCameraViewMode previousMode,
    required String source,
  }) {
    final signature =
        '${navCameraViewModeLabel(mode)}|${navCameraViewModeLabel(previousMode)}|$source';
    if (signature == _lastNavR15ViewModeSignature) return;
    _lastNavR15ViewModeSignature = signature;
    _logNavBounded(
      'NAV_R15_CAMERA_VIEW',
      'mode=${navCameraViewModeLabel(mode)} '
          'previousMode=${navCameraViewModeLabel(previousMode)} '
          'source=$source',
    );
    unawaited(
      NavDiagnosticsRecorder.instance.recordNavEngineEvent(
        tag: 'NAV_R15_CAMERA_VIEW',
        fields: <String, dynamic>{
          'mode': navCameraViewModeLabel(mode),
          'previousMode': navCameraViewModeLabel(previousMode),
          'source': source,
        },
      ),
    );
  }

  void _logNavR15CameraBearing({
    required NavCameraViewMode mode,
    required double speedKmh,
    required String bearingSource,
    required double bearingWeight,
    required double bearingDeltaDeg,
    required double? routeConfidence,
  }) {
    final signature =
        '${navCameraViewModeLabel(mode)}|$bearingSource|'
        '${bearingWeight.toStringAsFixed(2)}|'
        '${navCameraBearingDeltaBucket(bearingDeltaDeg)}';
    if (signature == _lastNavR15BearingSignature) return;
    _lastNavR15BearingSignature = signature;
    final speedBucket = navCameraSpeedBucketForDiagnostics(speedKmh);
    final confidenceBucket = navCameraConfidenceBucketForDiagnostics(
      routeConfidence,
    );
    final deltaBucket = navCameraBearingDeltaBucket(bearingDeltaDeg);
    _logNavBounded(
      'NAV_R15_CAMERA_BEARING',
      'mode=${navCameraViewModeLabel(mode)} '
          'speedBucket=$speedBucket '
          'bearingSource=$bearingSource '
          'bearingWeight=${bearingWeight.toStringAsFixed(2)} '
          'deltaBucket=$deltaBucket '
          'confidenceBucket=$confidenceBucket',
      intervalMs: 1200,
    );
    unawaited(
      NavDiagnosticsRecorder.instance.recordNavEngineEvent(
        tag: 'NAV_R15_CAMERA_BEARING',
        fields: <String, dynamic>{
          'mode': navCameraViewModeLabel(mode),
          'speedBucket': speedBucket,
          'bearingSource': bearingSource,
          'bearingWeight': bearingWeight,
          'deltaBucket': deltaBucket,
          'confidenceBucket': confidenceBucket,
        },
      ),
    );
  }

  void _logNavBounded(String tag, String message, {int intervalMs = 900}) {
    final now = DateTime.now();
    final last = _lastNavDebugAt[tag];
    if (last != null && now.difference(last).inMilliseconds < intervalMs)
      return;
    _lastNavDebugAt[tag] = now;
    debugPrint('[$tag] $message');
  }

  /// NAV-CAMERA-INFLIGHT-SELF-HEAL-1: PII-free bounded diagnostic for the
  /// camera in-flight lifecycle. Rare phases (timeout/error/stale) always
  /// print; common phases (start/complete/cleared) are throttled per-phase
  /// so a fast follow-camera loop cannot flood logs.
  void _logNavCameraInFlight({
    required NavCameraInFlightPhase phase,
    required int generation,
    int? animMs,
    int? ageMs,
    bool hasPending = false,
    String? reason,
    String? commandKind,
    String? event,
  }) {
    final line = formatNavCameraInFlightDiagnostic(
      phase: phase,
      generation: generation,
      animMs: animMs,
      ageMs: ageMs,
      hasPending: hasPending,
      reason: reason,
      commandKind: commandKind,
      event: event,
    );
    switch (phase) {
      case NavCameraInFlightPhase.timeout:
      case NavCameraInFlightPhase.error:
      case NavCameraInFlightPhase.stale:
        debugPrint(line);
        return;
      case NavCameraInFlightPhase.start:
      case NavCameraInFlightPhase.complete:
      case NavCameraInFlightPhase.cleared:
        // Always emit anomaly/transition events; throttle routine GPS starts.
        if (event == NavCameraInFlightEvent.pendingReplaced.label ||
            event == NavCameraInFlightEvent.pendingReplayed.label ||
            event == NavCameraInFlightEvent.ownerInvalidated.label ||
            event == NavCameraInFlightEvent.commandTimedOut.label) {
          debugPrint(line);
          return;
        }
        final tag = 'NAV_CAMERA_INFLIGHT_${phase.label}';
        final now = DateTime.now();
        final last = _lastNavDebugAt[tag];
        if (last != null && now.difference(last).inMilliseconds < 800) {
          return;
        }
        _lastNavDebugAt[tag] = now;
        debugPrint(line);
        return;
    }
  }

  void _syncNavDiagSession() {
    if (_isActiveDriverNavEngineContext()) {
      unawaited(
        NavDiagnosticsRecorder.instance.beginSessionIfNeeded(
          trigger: 'follow_nav',
        ),
      );
    } else {
      unawaited(
        NavDiagnosticsRecorder.instance.endSessionIfActive(
          reason: 'nav_context_end',
        ),
      );
    }
  }

  void _recordNavDiagGpsUpdate(
    geo.Position pos,
    geo.Position? prev, {
    double? metersFromPrev,
  }) {
    if (!NavDiagnosticsRecorder.instance.hasActiveSession) return;
    final now = DateTime.now();
    final last = _lastNavDiagGpsAt;
    final dtMs = last == null ? 0 : now.difference(last).inMilliseconds;
    _lastNavDiagGpsAt = now;
    final distanceFromLastM =
        metersFromPrev != null && metersFromPrev.isFinite && metersFromPrev > 0
        ? metersFromPrev
        : null;
    unawaited(
      NavDiagnosticsRecorder.instance.recordGpsUpdate(
        dtMs: dtMs,
        speedKmh: _speedKmhFor(pos),
        accuracyM: pos.accuracy.isFinite && pos.accuracy > 0
            ? pos.accuracy
            : -1,
        heading: pos.heading.isFinite && pos.heading >= 0 ? pos.heading : null,
        distanceFromLastM: distanceFromLastM,
      ),
    );
  }

  DateTime? _lastNavLatencyGpsCallbackAt;

  String _navLatencyAccuracyBucket(double? m) {
    if (m == null || !m.isFinite || m <= 0) return 'unknown';
    if (m <= 8) return 'excellent';
    if (m <= 20) return 'good';
    if (m <= 40) return 'fair';
    return 'poor';
  }

  String _navLatencySpeedBucket(double kmh) {
    if (kmh < 3) return 'stationary';
    if (kmh < 20) return 'slow';
    if (kmh < 60) return 'urban';
    return 'fast';
  }

  /// NAV-LATENCY-1 (Part A): bounded, rate-limited GPS callback diagnostics and
  /// validation cadence feed. No coordinates are logged.
  void _recordNavLatencyGpsCallback(
    geo.Position pos, {
    required bool accepted,
    required int engineDispatchDtMs,
  }) {
    final now = DateTime.now();
    final last = _lastNavLatencyGpsCallbackAt;
    final callbackDtMs = last == null ? 0 : now.difference(last).inMilliseconds;
    _lastNavLatencyGpsCallbackAt = now;

    final sourceAgeMs = now
        .difference(pos.timestamp)
        .inMilliseconds
        .clamp(0, 600000);
    final accuracyM = pos.accuracy.isFinite && pos.accuracy > 0
        ? pos.accuracy
        : null;
    final speedKmh = _speedKmhFor(pos);

    var rejectReason = '';
    if (!accepted) {
      if (!_mapSupported || _map == null) {
        rejectReason = 'map_unavailable';
      } else if (_mapStyleChanging) {
        rejectReason = 'style_changing';
      } else {
        rejectReason = 'not_driving_map';
      }
    }

    if (_isActiveDriverNavEngineContext()) {
      _driverNavValidationEngine.noteCallbackIntervalMs(callbackDtMs);
      _driverNavValidationEngine.noteSourceAgeMs(sourceAgeMs);
      // NAV-STREETLEVEL-FLUID-MOTION-1: raw GPS cadence.
      if (callbackDtMs > 0) _navGpsCadence.add(callbackDtMs.toDouble());
    }

    // NAV-LATENCY-1 (Part B): a fresh live fix clears the waiting-for-fresh-fix
    // state so passive follow can resume from a live position.
    if (_navWaitingForFreshFix &&
        sourceAgeMs <= NavFreshStartGate.freshFollowMaxAgeMs) {
      _navWaitingForFreshFix = false;
      _logNavBounded(
        'NAV_FRESH_START',
        'action=fresh_fix_resumed sourceAgeMs=$sourceAgeMs',
        intervalMs: 1000,
      );
    }

    _logNavBounded(
      'NAV_LATENCY_GPS',
      'callbackDtMs=$callbackDtMs '
          'sourceAgeMs=$sourceAgeMs '
          'accuracyBucket=${_navLatencyAccuracyBucket(accuracyM)} '
          'speedBucket=${_navLatencySpeedBucket(speedKmh)} '
          'accepted=$accepted '
          'rejectReason=${rejectReason.isEmpty ? '-' : rejectReason} '
          'engineDispatchDtMs=$engineDispatchDtMs',
      intervalMs: 1000,
    );
  }

  void _recordNavDiagR9OfflineTransition({
    required NavR9OfflineUiState state,
    required String reason,
  }) {
    final prev = _lastNavDiagR9State;
    _lastNavDiagR9State = state;
    if (prev == state) return;
    final now = DateTime.now();
    if (state == NavR9OfflineUiState.prediction ||
        state == NavR9OfflineUiState.gpsReacquire) {
      _lastNavDiagR9EnteredAt = now;
      unawaited(
        NavDiagnosticsRecorder.instance.recordOfflineMode(
          transition: 'entered',
          reason: reason,
          state: NavR9OfflineReadiness.logStateLabel(state),
        ),
      );
      return;
    }
    if (prev == NavR9OfflineUiState.prediction ||
        prev == NavR9OfflineUiState.gpsReacquire) {
      final entered = _lastNavDiagR9EnteredAt;
      final durationMs = entered == null
          ? null
          : now.difference(entered).inMilliseconds;
      _lastNavDiagR9EnteredAt = null;
      unawaited(
        NavDiagnosticsRecorder.instance.recordOfflineMode(
          transition: 'exited',
          reason: reason,
          durationMs: durationMs,
          state: prev == null
              ? null
              : NavR9OfflineReadiness.logStateLabel(prev),
        ),
      );
    }
  }

  // NAV-TELLERS-POSE-ANCHOR-AND-DIAGNOSTICS-UI-1: the visible driver-facing
  // diagnostics chip was removed. This PII-safe export helper is intentionally
  // retained (not surfaced in the toolbar) so internal/support flows can still
  // share recorded sessions without re-introducing a navigation-toolbar button.
  // ignore: unused_element
  Future<void> _shareNavDiagnostics() async {
    try {
      final file = await NavDiagnosticsRecorder.instance.exportLatestSessions(
        count: 2,
        asText: false,
      );
      if (file == null) {
        _toast(
          _tr(
            nl: 'Geen navigatie-diagnose beschikbaar.',
            en: 'No navigation diagnostics available.',
            fr: 'Aucun diagnostic de navigation disponible.',
            es: 'No hay diagnostico de navegacion disponible.',
          ),
        );
        return;
      }
      await Share.shareXFiles(
        <XFile>[XFile(file.path)],
        subject: 'Fluxidi navigatie-diagnose',
        text: _tr(
          nl: 'Fluxidi navigatie-diagnose (geen PII).',
          en: 'Fluxidi navigation diagnostics (no PII).',
          fr: 'Diagnostic navigation Fluxidi (sans PII).',
          es: 'Diagnostico de navegacion Fluxidi (sin PII).',
        ),
      );
    } catch (e) {
      unawaited(
        NavDiagnosticsRecorder.instance.recordException(
          context: 'share_nav_diag',
          error: e,
        ),
      );
      _toast(
        _tr(
          nl: 'Diagnose delen mislukt.',
          en: 'Could not share diagnostics.',
          fr: 'Partage du diagnostic impossible.',
          es: 'No se pudo compartir el diagnostico.',
        ),
      );
    }
  }

  /// NAV-TELLERS-POSE-ANCHOR-AND-DIAGNOSTICS-UI-1: after the Tellers follow
  /// camera settles, project the authoritative navigation pose through Mapbox
  /// and emit a bounded, PII-free `[NAV_TELLERS_ANCHOR]` proof that the pose and
  /// the on-screen Car/Arrow anchor converge. Buckets only — never coordinates,
  /// addresses or GPS. Rate-limited and development-only.
  Future<void> _logNavTellersAnchorSettledIfActive() async {
    if (kReleaseMode) return;
    final geometry = _pendingTellersAnchorGeometry;
    final poseLat = _pendingTellersAnchorPoseLat;
    final poseLon = _pendingTellersAnchorPoseLon;
    if (geometry == null || poseLat == null || poseLon == null) return;
    if (!_navPresentationMode.isTellers) return;
    final map = _map;
    if (map == null) return;
    final now = DateTime.now();
    final last = _lastTellersAnchorDiagAt;
    if (last != null && now.difference(last).inMilliseconds < 2000) return;
    _lastTellersAnchorDiagAt = now;
    try {
      final screen = await map.pixelForCoordinate(_mbPoint(poseLon, poseLat));
      final projectedPose = Offset(screen.x.toDouble(), screen.y.toDouble());
      final line = formatNavTellersAnchorDiagnostic(
        viewportGeneration: _tellersViewport.generation,
        isLandscape: geometry.isLandscape,
        markerAnchor: geometry.markerAnchorGlobal,
        projectedPose: projectedPose,
        viewportSize: geometry.mapViewportSize,
      );
      _logNavBounded('NAV_TELLERS_ANCHOR', line, intervalMs: 2000);
      // NAV-TELLERS-ROTATION-COMPOSITION-AND-POSE-LOCK-1 (Commit 2): the pose
      // lock proof (device class + View level + alignment buckets). Marker
      // road-contact anchor == camera target anchor by construction, so
      // aligned=true confirms project(matchedPose) lands on the marker.
      //
      // NAV-TELLERS-ROUTE-CENTERLINE-LOCK-1: also project the matched-route
      // snap point (when captured on the same camera pass) so the diagnostic
      // additionally reports the marker↔route-centreline delta. Coarse
      // buckets only — no coordinates leak.
      Offset? projectedSnap;
      final snapLat = _pendingTellersSnappedRouteLat;
      final snapLon = _pendingTellersSnappedRouteLon;
      if (snapLat != null && snapLon != null) {
        try {
          final snapScreen =
              await map.pixelForCoordinate(_mbPoint(snapLon, snapLat));
          projectedSnap =
              Offset(snapScreen.x.toDouble(), snapScreen.y.toDouble());
        } catch (_) {
          projectedSnap = null;
        }
      }
      _logNavBounded(
        'NAV_TELLERS_POSE_LOCK',
        formatNavTellersPoseLockDiagnostic(
          viewportGeneration: _tellersViewport.generation,
          isLandscape: geometry.isLandscape,
          isTablet: geometry.isTablet,
          viewLevel: _driverCockpitViewLevel,
          markerAnchor: geometry.markerRoadContactAnchorGlobal,
          projectedPose: projectedPose,
          viewportSize: geometry.mapViewportSize,
          projectedSnappedRoute: projectedSnap,
          poseSource: _pendingTellersPoseSource,
        ),
        intervalMs: 2000,
      );
    } catch (_) {
      // Projection can throw during style/size transitions; never crash a
      // development diagnostic.
    }
  }

  ({double enterThresholdM, double exitThresholdM}) _matchThresholdsFor(
    geo.Position pos,
  ) {
    final base = _snapThresholdFor(pos);
    final speedKmh = _speedKmhFor(pos);
    final navAgeSec = _trackingStartedAt == null
        ? 999.0
        : DateTime.now().difference(_trackingStartedAt!).inMilliseconds /
              1000.0;
    final justStarted = navAgeSec <= 18.0;
    final movingFast = speedKmh >= 35.0;
    final enter = justStarted
        ? math.max(base, 70.0)
        : (movingFast ? math.max(base, 48.0) : base);
    final exit = enter + 18.0;
    return (enterThresholdM: enter, exitThresholdM: exit);
  }

  bool _isProgressPlausible(_RouteSnap snap, geo.Position pos) {
    final prev = _lastVisualProgressM;
    if (prev == null) return true;
    final speedKmh = _speedKmhFor(pos);
    final backwardToleranceM = speedKmh < 6.0 ? 35.0 : 22.0;
    if (snap.distanceAlongRouteM < prev - backwardToleranceM) {
      return false;
    }
    final maxForwardJumpM = math.max(70.0, speedKmh * 2.8 + 38.0);
    if (snap.distanceAlongRouteM > prev + maxForwardJumpM) {
      return false;
    }
    return true;
  }

  bool _canSnapToRoute(geo.Position pos, _RouteSnap? snap) {
    if (snap == null) return false;
    final thresholds = _matchThresholdsFor(pos);
    final threshold = _useMatchedVisual
        ? thresholds.exitThresholdM
        : thresholds.enterThresholdM;
    if (snap.distanceFromRouteM > threshold) return false;
    return _isProgressPlausible(snap, pos);
  }

  _RouteSnap? _snapToRouteOn(List<_LonLat> routeCoords, _LonLat raw) {
    return driverSnapToRouteOn(routeCoords, raw);
  }

  _RouteSnap? _snapToRoute(_LonLat raw) => _snapToRouteOn(_routeCoords, raw);

  double _distanceAlongRouteFor(_LonLat point) {
    return _snapToRoute(point)?.distanceAlongRouteM ?? 0.0;
  }

  double _distanceAlongRouteForCoords(
    List<_LonLat> routeCoords,
    _LonLat point,
  ) {
    return driverDistanceAlongRouteForCoords(routeCoords, point);
  }

  void _resetNavRouteProgressState() {
    _driverNavRouteProgress.reset();
    _lastNavRouteProgress = null;
    _navRouteProgressRouteFingerprint = null;
  }

  void _resetNavCameraPolicyState() {
    _driverNavCameraPolicy.reset();
    _lastNavCameraPolicy = null;
  }

  void _resetNavConfidenceState() {
    _driverNavConfidenceEngine.reset();
    _lastNavConfidence = null;
  }

  void _resetNavComplexityState() {
    _navComplexityGuard.reset();
    _lastNavCautionState = NavComplexityGuardState.inactive;
    _lastNavR14ComplexitySignature = null;
  }

  NavComplexityGuardInput _buildNavComplexityGuardInput(geo.Position pos) {
    final progress = _lastNavRouteProgress;
    final confidence = _lastNavConfidence;
    final prediction = _lastNavMotionPrediction;
    return NavComplexityGuardInput(
      timestamp: DateTime.now(),
      liveRideActive: _liveRideActive,
      followMode: _cameraMode == _CameraMode.follow,
      overallConfidence: confidence?.overallScore,
      trustInstruction: confidence?.trustInstruction ?? true,
      trustBearing: confidence?.trustBearing ?? true,
      snapDistanceM: progress?.snapDistanceM,
      offRouteLikely: progress?.offRouteLikely ?? _offRouteLikely,
      // Transport cleanup must not keep complexity in reroute warning state
      // after the accepted package already owns the new route version.
      // NAV-REROUTE-CURRENT-POSITION-HEADING-P0: coordinator suppresses
      // complexity churn while old guidance is invalidated / requesting.
      reroutePending:
          (_isRerouting && !_rerouteOwnershipAccepted) ||
          _navRerouteCoordinator.suppressComplexityCaution,
      headingDeltaDeg: progress?.headingDeltaDeg ?? _navHeadingDeltaDegFor(pos),
      predictionActive: prediction?.predictionActive ?? false,
      gapBridgeMs: _gapSinceLastNavEngineMs(),
      maneuverModifier: _nextNavModifier,
      instructionStepIndex: _nextStepIndex,
      speedKmh: _speedKmhFor(pos),
      distanceToManeuverM:
          _navInstructionSnapshot?.distanceToManeuverMeters ??
          _nextNavDistanceM,
      maneuverType: _nextNavType,
      routeVersion: _routeStepsVersion,
    );
  }

  // NAV-PARKING-2 Commit 1: update the bounded startup-readiness gate and the
  // destination-proximity arrival evaluator for this fix. Runs before the
  // complexity/reroute decisions consume `_navStartupBootstrap.ready` and
  // `_navParkingArrivalConfirmed`. Pure engines do the deciding; this method
  // only feeds them live evidence and records PII-free diagnostics.
  void _updateNavStartupAndArrival(geo.Position pos) {
    final startedAt = _navSessionStartedAt;
    final elapsedMs = startedAt == null
        ? 0
        : DateTime.now().difference(startedAt).inMilliseconds;
    final progress = _lastNavRouteProgress;
    final speedKmh = _speedKmhFor(pos);
    final fixAgeMs = DateTime.now()
        .difference(pos.timestamp)
        .inMilliseconds
        .abs();
    final coherent = _navBootstrapPositionCoherent(pos);
    final routeEntry =
        (progress?.forwardProgress ?? false) &&
        (progress?.snapDistanceM ?? 1e9) <= 30.0;
    final bootstrapResult = _navStartupBootstrap.evaluate(
      NavStartupBootstrapSample(
        elapsedSinceStartMs: elapsedMs,
        hasActiveSessionRoute: _routeCoords.isNotEmpty,
        gpsFixAgeMs: fixAgeMs,
        gpsAccuracyM: pos.accuracy,
        speedKmh: speedKmh,
        hasUsableCourse: pos.heading.isFinite && pos.heading >= 0 &&
            speedKmh >= 6.0,
        mapMatched: _useMatchedVisual,
        routeEntryProgressing: routeEntry,
        coherentWithPreviousSample: coherent,
      ),
    );
    if (bootstrapResult.changed || bootstrapResult.phase != _lastNavBootstrapPhase) {
      _lastNavBootstrapPhase = bootstrapResult.phase;
      _logNavBounded(
        'NAV_STARTUP_BOOTSTRAP',
        'phase=${bootstrapResult.phase.label} ready=${bootstrapResult.ready}',
        intervalMs: 1,
      );
    }
    _navBootstrapPrevLat = pos.latitude;
    _navBootstrapPrevLon = pos.longitude;

    // Destination-proximity arrival only with active target + known route.
    // NAVIGATION-ARRIVAL-STATE-RESET-P0-5: never treat missing route as 0 m.
    final target = _activeNavTargetOwner.current;
    final dropoff = _trustedNavigationDropoffCoordinate();
    if (_liveRideActive &&
        _routeCoords.isNotEmpty &&
        dropoff != null &&
        target != null &&
        target.isValid) {
      final toOriginal = geo.Geolocator.distanceBetween(
        pos.latitude,
        pos.longitude,
        dropoff.lat,
        dropoff.lon,
      );
      final endpoint = _routeCoords.last;
      final toEndpoint = geo.Geolocator.distanceBetween(
        pos.latitude,
        pos.longitude,
        endpoint.lat,
        endpoint.lon,
      );
      final truth = _resolveActiveRemainingDistanceTruth();
      final remainingKnown = truth.routeReady && truth.remainingMeters != null;
      final remainingM = truth.remainingMeters;
      if (!remainingKnown) {
        _logNavTargetTruthEvent(
          event: 'arrival_eval_skipped',
          arrivalFlagSource: 'remaining_unknown',
          straightLineTargetDistanceM: toOriginal,
          gpsAccuracyM: pos.accuracy,
        );
        return;
      }
      final arrivalResult = _navParkingArrival.evaluate(
        NavParkingArrivalInput(
          timestampMs: DateTime.now().millisecondsSinceEpoch,
          distanceToOriginalDestinationM: toOriginal,
          distanceToRouteEndpointM: toEndpoint,
          remainingRouteM: remainingM!,
          gpsAccuracyM: pos.accuracy,
          speedKmh: speedKmh,
          progressingTowardDestination: progress?.forwardProgress ?? false,
        ),
      );
      final event = arrivalResult.event;
      if (event != null && event != _lastNavArrivalEvent) {
        _lastNavArrivalEvent = event;
        _logNavBounded(
          'NAV_ARRIVAL',
          'event=${event.label} dwellMs=${arrivalResult.dwellMs}',
          intervalMs: 1,
        );
      }
      // After toPickup→passengerLeg, block arrival while still far from B so a
      // leftover "pickup bereikt" completion cannot become "bestemming B".
      final phaseStaleCompletion = _navPhaseTransitionStaleGuard &&
          toOriginal > 80.0;
      final guard = evaluateNavArrivalTruth(
        NavArrivalTruthInput(
          activeTarget: target,
          arrivalEvaluatorSnapshotId:
              _arrivalEvaluatorSnapshotId ?? target.snapshotId,
          visibleRouteId: target.routeId,
          visibleRouteEndpointHash: _visibleRouteEndpointHash(),
          gpsFixValid: pos.accuracy.isFinite,
          gpsAccuracyM: pos.accuracy,
          distanceToTargetM: toOriginal,
          arrivalThresholdM: 45.0,
          dwellOrConsecutiveFixesSatisfied:
              arrivalResult.arrived || _navParkingArrival.confirmed,
          remainingRouteM: remainingM,
          remainingRouteKnown: remainingKnown,
          straightLineTargetDistanceM: toOriginal,
          phaseJustChangedWithStaleCompletion: phaseStaleCompletion,
          parkingEvaluatorArrived: arrivalResult.arrived,
        ),
      );
      if (!guard.allowArrival) {
        if (guard.logEvent == 'target_mismatch' ||
            guard.rejectReason ==
                NavArrivalTruthRejectReason.targetEndpointMismatch) {
          _logNavTargetTruthEvent(
            event: 'target_mismatch',
            arrivalFlagSource: guard.logEvent,
            remainingRouteMetres: remainingM,
            straightLineTargetDistanceM: toOriginal,
            gpsAccuracyM: pos.accuracy,
          );
        }
        return;
      }
      if (arrivalResult.arrived && !_navParkingArrivalConfirmed) {
        _navPhaseTransitionStaleGuard = false;
        logNavUiInputTiming(
          action: NavUiInputTimingAction.terPlaatse,
          phase: NavUiInputTimingPhase.inputReceived,
          managerGeneration: _routeAnnotationGate.managerGeneration,
          renderEpoch: _routeRenderEpoch,
          sessionGeneration: _navigationSessionGeneration,
          styleGeneration: _styleRequestGeneration,
          reason: 'parking_arrival',
        );
        _navParkingArrivalConfirmed = true;
        _activeLaneGuidance = null;
        _resetNavComplexityState();
        _logNavTargetTruthEvent(
          event: 'arrival_confirmed',
          arrivalFlagSource: 'parking_proximity',
          remainingRouteMetres: remainingM,
          straightLineTargetDistanceM: toOriginal,
          gpsAccuracyM: pos.accuracy,
        );
        logNavUiInputTiming(
          action: NavUiInputTimingAction.terPlaatse,
          phase: NavUiInputTimingPhase.completed,
          managerGeneration: _routeAnnotationGate.managerGeneration,
          renderEpoch: _routeRenderEpoch,
          sessionGeneration: _navigationSessionGeneration,
          styleGeneration: _styleRequestGeneration,
          reason: 'parking_arrival_confirmed',
        );
      }
    }
  }


  bool _navBootstrapPositionCoherent(geo.Position pos) {
    final lat = _navBootstrapPrevLat;
    final lon = _navBootstrapPrevLon;
    if (lat == null || lon == null) return false;
    final d = geo.Geolocator.distanceBetween(lat, lon, pos.latitude, pos.longitude);
    // Reject teleports/large GPS jumps; a coherent sample is spatially close.
    return d.isFinite && d <= 120.0;
  }

  void _updateNavComplexityForPosition(geo.Position pos) {
    if (!_isActiveDriverNavEngineContext()) {
      final wasShowing = _lastNavCautionState.active;
      _resetNavComplexityState();
      if (wasShowing && mounted) setState(() {});
      return;
    }
    _updateNavStartupAndArrival(pos);
    // During the bounded startup bootstrap, expected startup uncertainty (first
    // unmatched parking samples, stale/stationary heading) must not surface as
    // a "complex road situation". Once destination-proximity arrival is
    // authoritative, contradictory complexity is likewise withheld. This gates
    // evaluation only — the guard's scoring/activation logic is unchanged.
    if (!_navStartupBootstrap.ready || _navParkingArrivalConfirmed) {
      final wasShowing = _lastNavCautionState.active;
      _resetNavComplexityState();
      if (wasShowing && mounted) setState(() {});
      return;
    }
    final input = _buildNavComplexityGuardInput(pos);
    final prevShowing = _lastNavCautionState.active;
    final state = _navComplexityGuard.update(input);
    _lastNavCautionState = state;
    _logNavR14Complexity(state, input: input);
    if (!prevShowing && state.active) {
      unawaited(_exportNavComplexityIntelligenceEvent(state, input));
    }
    if (prevShowing != state.active && mounted) {
      setState(() {});
    }
  }

  Future<void> _exportNavComplexityIntelligenceEvent(
    NavComplexityGuardState state,
    NavComplexityGuardInput input,
  ) async {
    final event = NavComplexityIntelligenceBuilder.fromGuardContext(
      state: state,
      input: input,
      diagnosticsSessionId: NavDiagnosticsRecorder.instance.activeSessionId,
    );
    await _navComplexityIntelligenceExporter.exportEvent(
      event,
      recordLocally: (payload) => NavDiagnosticsRecorder.instance
          .recordNavComplexityIntelligenceEvent(payload),
    );
  }

  void _logNavR14Complexity(
    NavComplexityGuardState state, {
    required NavComplexityGuardInput input,
  }) {
    final confidence = _lastNavConfidence;
    final snapBucket = NavComplexityGuard.snapDistanceBucket(
      input.snapDistanceM,
    );
    final confidenceBucket = NavComplexityGuard.confidenceBucket(
      input.overallConfidence,
    );
    final signature =
        '${state.active}|${state.reasonCode}|${state.signalCount}|'
        '$confidenceBucket|$snapBucket|${state.predictionRepeated}';
    final changed = signature != _lastNavR14ComplexitySignature;
    _lastNavR14ComplexitySignature = signature;
    _logNavBounded(
      'NAV_R14_COMPLEXITY',
      'active=${state.active} '
          'severity=${state.severity.name} '
          'reason=${state.reasonCode} '
          'confidenceBucket=$confidenceBucket '
          'snapDistBucket=$snapBucket '
          'predictionRepeated=${state.predictionRepeated} '
          'trustBearing=${input.trustBearing} '
          'trustInstruction=${input.trustInstruction}',
      intervalMs: changed ? 1 : 3000,
    );
    logNavComplexityDecision(state.decision);
    if (changed) {
      unawaited(
        NavDiagnosticsRecorder.instance.recordNavEngineEvent(
          tag: 'NAV_R14_COMPLEXITY',
          fields: <String, dynamic>{
            'active': state.active,
            'severity': state.severity.name,
            'reason': state.reasonCode,
            'confidenceBucket': confidenceBucket,
            'snapDistBucket': snapBucket,
            'predictionRepeated': state.predictionRepeated,
            'trustBearing': input.trustBearing,
            'trustInstruction': input.trustInstruction,
            'signals': state.signalCount,
          },
        ),
      );
    }
  }

  void _resetNavMotionPredictionState() {
    _driverNavMotionPrediction.reset();
    _lastNavMotionPrediction = null;
  }

  void _resetNavInstructionPolicyState() {
    _driverNavInstructionPolicy.reset();
  }

  int _gapSinceLastNavEngineMs() {
    final output = _lastNavEngineOutput;
    if (output == null) return 0;
    return DateTime.now()
        .difference(output.timestamp)
        .inMilliseconds
        .clamp(0, 600000);
  }

  double? _navHeadingDeltaDegFor(geo.Position pos) {
    final rawHeading = pos.heading.isFinite && pos.heading >= 0
        ? pos.heading
        : null;
    if (rawHeading == null) return null;
    final progress = _lastNavRouteProgress;
    final routeBearing =
        _routeBearingFromProgress(progress) ??
        _routeBearingAtSnap(_lastRouteSnap);
    if (routeBearing == null || !routeBearing.isFinite) return null;
    var delta = (rawHeading - routeBearing) % 360.0;
    if (delta > 180.0) delta -= 360.0;
    if (delta < -180.0) delta += 360.0;
    return delta.abs();
  }

  NavConfidenceInput _buildNavConfidenceInput(geo.Position pos) {
    final progress = _lastNavRouteProgress;
    return NavConfidenceInput(
      timestamp: pos.timestamp,
      gpsAccuracyM: pos.accuracy.isFinite && pos.accuracy > 0
          ? pos.accuracy
          : null,
      speedKmh: _speedKmhFor(pos),
      routeConfidence: progress?.confidence,
      snapDistanceM: progress?.snapDistanceM,
      hasReliableSnap: progress?.hasReliableSnap ?? false,
      offRouteLikely: progress?.offRouteLikely ?? _offRouteLikely,
      forwardProgress: progress?.forwardProgress ?? true,
      headingDeltaDeg: _navHeadingDeltaDegFor(pos),
      liveRideActive: _liveRideActive,
    );
  }

  void _updateNavConfidenceForPosition(geo.Position pos) {
    if (!_isActiveDriverNavEngineContext()) {
      _lastNavConfidence = null;
      return;
    }
    try {
      final output = _driverNavConfidenceEngine.update(
        _buildNavConfidenceInput(pos),
      );
      _lastNavConfidence = output;
      _logNavBounded(
        'NAV_R6_CONFIDENCE',
        'overall=${output.overallScore.round()} '
            'gps=${output.gpsScore.round()} '
            'route=${output.routeScore.round()} '
            'heading=${output.headingScore.round()} '
            'motion=${output.motionScore.round()} '
            'camera=${output.cameraScore.round()} '
            'instruction=${output.instructionScore.round()} '
            'trustSnap=${output.trustRouteSnap} '
            'trustBearing=${output.trustBearing} '
            'trustInstruction=${output.trustInstruction} '
            'reason=${output.reason}',
        intervalMs: 1500,
      );
      unawaited(
        NavDiagnosticsRecorder.instance.recordNavEngineEvent(
          tag: 'NAV_R6_CONFIDENCE',
          fields: <String, dynamic>{
            'overall': output.overallScore.round(),
            'gps': output.gpsScore.round(),
            'route': output.routeScore.round(),
            'heading': output.headingScore.round(),
            'motion': output.motionScore.round(),
            'camera': output.cameraScore.round(),
            'instruction': output.instructionScore.round(),
            'trustSnap': output.trustRouteSnap,
            'trustBearing': output.trustBearing,
            'trustInstruction': output.trustInstruction,
            'reason': output.reason,
          },
        ),
      );
    } catch (_) {
      _lastNavConfidence = null;
    }
    _updateNavComplexityForPosition(pos);
  }

  NavCameraPolicyInput _buildNavCameraPolicyInput(
    geo.Position pos, {
    required bool manualRecenter,
  }) {
    final distanceToManeuver =
        _navInstructionSnapshot?.distanceToManeuverMeters ?? _nextNavDistanceM;
    final nearManeuver =
        distanceToManeuver != null &&
        distanceToManeuver.isFinite &&
        distanceToManeuver <= kDriverNavR1NearManeuverCameraDistanceM;
    final progress = _lastNavRouteProgress;
    final confidence = _lastNavConfidence;
    final activeNav = _isActiveDriverNavEngineContext();
    final hasReliableSnap = activeNav && confidence != null
        ? confidence.trustRouteSnap
        : (progress?.hasReliableSnap ?? _useMatchedVisual);
    return NavCameraPolicyInput(
      timestamp: DateTime.now(),
      // NAV-FIXED-HUD-PRESENTATION-1: the follow camera is the single camera
      // owner for every phase that shows a prepared or driven route, not just
      // the metered ride. Gating on `_liveRideActive` alone made a prepared
      // booking and NAV-to-pickup resolve `follow=false reason=inactive`, so
      // the map never rotated to route-up underneath the fixed HUD.
      liveRideActive: _navFixedHudPresentationActive,
      cameraFollowMode: _cameraMode == _CameraMode.follow,
      manualRecenter: manualRecenter,
      speedKmh: _speedKmhFor(pos),
      accuracyM: pos.accuracy.isFinite && pos.accuracy > 0
          ? pos.accuracy
          : null,
      routeConfidence: progress?.confidence,
      offRouteLikely: progress?.offRouteLikely ?? _offRouteLikely,
      // NAV-R12-H: adaptation signals widen the zoom context.
      routeDeviationLikely: progress?.routeDeviationLikely ?? false,
      oppositeDirectionLikely: progress?.oppositeDirectionLikely ?? false,
      backwardProgressLikely: progress?.backwardProgressLikely ?? false,
      reroutePending: _isRerouting,
      distanceToManeuverM: distanceToManeuver,
      nearManeuver: nearManeuver,
      waitingMode: _isWaiting,
      hasReliableSnap: hasReliableSnap,
      // NAV-FIXED-HUD-PRESENTATION-1: overview here forced the fixed-north
      // bearing branch of the smoother, which is the "north-up / stale map
      // angle" the field test saw on prepared routes.
      viewMode: _navFixedHudPresentationActive
          ? _navCameraViewMode
          : NavCameraViewMode.overview,
    );
  }

  ({
    bool shouldFollow,
    double zoom,
    double tilt,
    double bearingModeWeight,
    String reason,
  })
  _resolveNavCameraPolicy(geo.Position pos, {required bool manualRecenter}) {
    final input = _buildNavCameraPolicyInput(
      pos,
      manualRecenter: manualRecenter,
    );
    try {
      final output = _driverNavCameraPolicy.update(input);
      _lastNavCameraPolicy = output;
      var shouldFollow = output.shouldFollow;
      var zoom = output.zoom;
      var tilt = output.tilt;
      var bearingModeWeight = output.bearingModeWeight;
      var reason = output.reason;
      final confidence = _lastNavConfidence;
      if (confidence != null && _isActiveDriverNavEngineContext()) {
        if (!confidence.allowCameraAggression && !manualRecenter) {
          // NAV-R12-H: lower clamp follows the wider dynamic zoom range.
          zoom = (zoom - 0.35).clamp(
            DriverNavCameraPolicy.minZoom,
            DriverNavCameraPolicy.maxZoom,
          );
          tilt = (tilt - 2.0).clamp(44.0, 66.0);
          bearingModeWeight =
              (bearingModeWeight * (confidence.trustBearing ? 0.65 : 0.35))
                  .clamp(0.1, 1.0);
          reason = '${reason}_r6_cautious';
        }
        if (confidence.cameraScore < 45.0 && !manualRecenter) {
          shouldFollow = false;
          reason = 'r6_low_camera_confidence';
        }
      }
      _logNavBounded(
        'NAV_R5_CAMERA_POLICY',
        'zoom=${zoom.toStringAsFixed(1)} '
            'targetZoom=${output.targetZoom.toStringAsFixed(1)} '
            'zoomReason=${output.zoomReason} '
            'tilt=${tilt.toStringAsFixed(1)} '
            'follow=$shouldFollow reason=$reason',
        intervalMs: 2000,
      );
      unawaited(
        NavDiagnosticsRecorder.instance.recordNavEngineEvent(
          tag: 'NAV_R5_CAMERA_POLICY',
          fields: <String, dynamic>{
            'zoom': zoom,
            'targetZoom': output.targetZoom,
            'zoomReason': output.zoomReason,
            'tilt': tilt,
            'follow': shouldFollow,
            'reason': reason,
          },
        ),
      );
      return (
        shouldFollow: shouldFollow,
        zoom: zoom,
        tilt: tilt,
        bearingModeWeight: bearingModeWeight,
        reason: reason,
      );
    } catch (_) {
      final fallback = _followCameraZoomPitchFor(pos);
      return (
        shouldFollow: true,
        zoom: fallback.zoom,
        tilt: fallback.pitch,
        bearingModeWeight: 1.0,
        reason: fallback.reason,
      );
    }
  }

  int _navRouteProgressRouteFingerprintFor() {
    if (_routeCoords.length < 2) return 0;
    final first = _routeCoords.first;
    final last = _routeCoords.last;
    return Object.hash(
      _routeCoords.length,
      first.lat,
      first.lon,
      last.lat,
      last.lon,
    );
  }

  void _ensureNavRouteProgressRouteFresh() {
    final fingerprint = _navRouteProgressRouteFingerprintFor();
    if (fingerprint != _navRouteProgressRouteFingerprint) {
      _navRouteProgressRouteFingerprint = fingerprint;
      _driverNavRouteProgress.reset();
      _lastNavRouteProgress = null;
      _resetNavCameraPolicyState();
      _resetNavConfidenceState();
      _resetNavMotionPredictionState();
      _resetNavInstructionPolicyState();
    }
  }

  List<NavRoutePoint> _navRoutePointsFromCoords() {
    return _routeCoords
        .map((p) => NavRoutePoint(latitude: p.lat, longitude: p.lon))
        .toList(growable: false);
  }

  NavRouteProgressOutput? _updateNavRouteProgressForPosition(geo.Position pos) {
    if (!_isActiveDriverNavEngineContext()) {
      return null;
    }
    if (_routeCoords.length < 2) {
      return null;
    }

    _ensureNavRouteProgressRouteFresh();
    try {
      final output = _driverNavRouteProgress.update(
        NavRouteProgressInput(
          timestamp: pos.timestamp,
          rawLatitude: pos.latitude,
          rawLongitude: pos.longitude,
          rawHeading: pos.heading.isFinite && pos.heading >= 0
              ? pos.heading
              : null,
          speedKmh: _speedKmhFor(pos),
          accuracyM: pos.accuracy.isFinite && pos.accuracy > 0
              ? pos.accuracy
              : null,
          routePoints: _navRoutePointsFromCoords(),
        ),
      );
      _lastNavRouteProgress = output;
      _logNavBounded(
        'NAV_R4_PROGRESS',
        'segment=${output.segmentIndex ?? -1} '
            'confidence=${output.confidence.round()} '
            'snapDistM=${output.snapDistanceM.toStringAsFixed(1)} '
            'forward=${output.forwardProgress} '
            'offRoute=${output.offRouteLikely} '
            'reason=${output.reason}',
        intervalMs: 1500,
      );
      unawaited(
        NavDiagnosticsRecorder.instance.recordNavEngineEvent(
          tag: 'NAV_R4_PROGRESS',
          fields: <String, dynamic>{
            'segment': output.segmentIndex ?? -1,
            'confidence': output.confidence.round(),
            'snapDistM': output.snapDistanceM,
            'forward': output.forwardProgress,
            'offRoute': output.offRouteLikely,
            'reason': output.reason,
          },
        ),
      );
      return output;
    } catch (_) {
      _lastNavRouteProgress = null;
      return null;
    }
  }

  _RouteSnap? _routeSnapFromProgressOrFallback(_LonLat rawPoint) {
    final progress = _lastNavRouteProgress;
    if (_isActiveDriverNavEngineContext() &&
        progress != null &&
        progress.snappedLatitude != null &&
        progress.snappedLongitude != null &&
        progress.segmentIndex != null) {
      return DriverRouteSnap(
        point: _LonLat(progress.snappedLongitude!, progress.snappedLatitude!),
        distanceFromRouteM: progress.snapDistanceM,
        distanceAlongRouteM: progress.distanceAlongRouteM ?? 0.0,
        segmentIndex: progress.segmentIndex!,
        segmentT: 0.0,
      );
    }
    return _snapToRoute(rawPoint);
  }

  /// NAV-OS-R2: forward-looking route bearing from progress. Walks the
  /// polyline ahead of the snapped point, so it can never return a
  /// previous/backward segment bearing.
  double? _routeBearingFromProgress(NavRouteProgressOutput? progress) {
    if (progress == null ||
        progress.segmentIndex == null ||
        _routeCoords.length < 2) {
      return null;
    }
    final i = progress.segmentIndex!.clamp(0, _routeCoords.length - 2);
    final speedKmh = _lastPos != null ? _speedKmhFor(_lastPos!) : 0.0;
    final lookaheadM = (speedKmh / 3.6 * 1.2).clamp(8.0, 30.0);
    return driverForwardRouteBearing(
      _routeCoords,
      segmentIndex: i,
      snappedLat: progress.snappedLatitude ?? _routeCoords[i].lat,
      snappedLon: progress.snappedLongitude ?? _routeCoords[i].lon,
      lookaheadM: lookaheadM,
    );
  }

  /// NAV-OS-R2: forward route bearing with an anti-reverse guard. If the
  /// candidate bearing is ~180° off the movement/GPS direction (snap landed on
  /// an anti-parallel segment), it looks further ahead along the route; if
  /// that still disagrees, returns null so callers fall back to GPS heading.
  double? _resolveForwardRouteBearing(geo.Position pos, {_RouteSnap? snap}) {
    final progress = _lastNavRouteProgress;

    double? bearingAt(double lookaheadM) {
      if (_routeCoords.length < 2) return null;
      if (progress != null && progress.segmentIndex != null) {
        final i = progress.segmentIndex!.clamp(0, _routeCoords.length - 2);
        return driverForwardRouteBearing(
          _routeCoords,
          segmentIndex: i,
          snappedLat: progress.snappedLatitude ?? _routeCoords[i].lat,
          snappedLon: progress.snappedLongitude ?? _routeCoords[i].lon,
          lookaheadM: lookaheadM,
        );
      }
      if (snap != null) {
        return driverForwardRouteBearing(
          _routeCoords,
          segmentIndex: snap.segmentIndex,
          snappedLat: snap.point.lat,
          snappedLon: snap.point.lon,
          lookaheadM: lookaheadM,
        );
      }
      return null;
    }

    final speedKmh = _speedKmhFor(pos);
    final baseLookaheadM = (speedKmh / 3.6 * 1.2).clamp(8.0, 30.0);
    var bearing = bearingAt(baseLookaheadM);
    var reversedGuard = false;
    final gpsHeading = pos.heading.isFinite && pos.heading >= 0
        ? pos.heading
        : null;
    final reference = speedKmh >= 6.0
        ? (_lastMovementBearing ?? gpsHeading)
        : null;
    double? delta;
    if (bearing != null && reference != null) {
      delta = NavBearingSmoother.bearingDelta(reference, bearing);
      if (delta.abs() > 150.0) {
        reversedGuard = true;
        // Prefer the next forward segment further along the route.
        final ahead = bearingAt(baseLookaheadM + 35.0);
        final aheadDelta = ahead == null
            ? null
            : NavBearingSmoother.bearingDelta(reference, ahead);
        if (ahead != null && aheadDelta != null && aheadDelta.abs() <= 150.0) {
          bearing = ahead;
          delta = aheadDelta;
        } else {
          bearing = null;
        }
      }
    }
    _lastR2ReversedGuard = reversedGuard;
    _lastR2BearingDeltaDeg = delta;
    return bearing;
  }

  static String _r2BearingSourceLabel(String source) {
    if (source == 'route' || source.startsWith('route_segment')) {
      return 'forward_route';
    }
    if (source == 'gps' || source == 'gps_heading' || source == 'movement') {
      return 'gps';
    }
    if (source == 'last' || source.startsWith('last_stable')) return 'hold';
    return 'fallback';
  }

  static String _navR11SourceFromEngine(String engineSource) {
    if (engineSource.startsWith('route_segment')) return 'route';
    if (engineSource == 'gps_heading' || engineSource == 'movement') {
      return 'gps';
    }
    if (engineSource.startsWith('last_stable')) return 'last';
    return 'fallback';
  }

  bool _routeProgressMatchedVisual(NavRouteProgressOutput? progress) {
    return progress != null &&
        progress.hasReliableSnap &&
        progress.forwardProgress &&
        !progress.offRouteLikely;
  }

  void _updateRouteSnapState(geo.Position pos) {
    final rawPoint = _LonLat(pos.longitude, pos.latitude);
    final progress = _updateNavRouteProgressForPosition(pos);
    _updateNavConfidenceForPosition(pos);
    final snap = _routeSnapFromProgressOrFallback(rawPoint);
    _lastRouteSnap = snap;
    final bool canUseMatched =
        _isActiveDriverNavEngineContext() && progress != null
        ? _routeProgressMatchedVisual(progress) &&
              (_lastNavConfidence?.trustRouteSnap ?? true)
        : _canSnapToRoute(pos, snap);
    if (canUseMatched) {
      _matchEnterHits += 1;
      _matchExitHits = 0;
      if (!_useMatchedVisual && _matchEnterHits >= 2) {
        _useMatchedVisual = true;
      }
    } else {
      _matchExitHits += 1;
      _matchEnterHits = 0;
      if (_useMatchedVisual && _matchExitHits >= 2) {
        _useMatchedVisual = false;
      }
    }
    if (_useMatchedVisual && snap != null) {
      _lastVisualProgressM = snap.distanceAlongRouteM;
    }

    final offRouteThreshold = math.max(70.0, _snapThresholdFor(pos) + 25.0);
    final snapDistance =
        snap?.distanceFromRouteM ?? progress?.snapDistanceM ?? double.infinity;
    final progressForDecision =
        progress ??
        NavRouteProgressOutput(
          hasReliableSnap: false,
          snapDistanceM: snapDistance.isFinite ? snapDistance : double.infinity,
          confidence: 0,
          forwardProgress: true,
          offRouteLikely:
              snapDistance.isFinite && snapDistance > offRouteThreshold,
          reason: 'legacy_snap',
        );
    // FLUXIDI NAV-STREETLEVEL-FLUID-MOTION-2 (Phase 1, Part F): feed the
    // post-reroute stabilisation gate with this sample. Only in-generation
    // samples with a reliable snap count toward the >=2 fresh-samples
    // requirement; the gate silently no-ops outside the stabilisation
    // window.
    _rerouteStabilization.observeSample(
      routeGeneration: _routeStepsVersion,
      snapDistanceM: snapDistance,
      hasReliableSnap: progress?.hasReliableSnap ?? false,
    );
    _lastRerouteDecision = _rerouteDecision.update(
      NavRerouteDecisionTickInput(
        progress: progressForDecision,
        snapDistanceM: snapDistance.isFinite ? snapDistance : double.infinity,
        speedKmh: _speedKmhFor(pos),
        offRouteThresholdM: offRouteThreshold,
        useProgressOffRouteHits:
            _isActiveDriverNavEngineContext() && progress != null,
        now: DateTime.now(),
        lastRerouteAt: _lastRerouteAt,
        lastRerouteSuccessAt: _lastRerouteSuccessAt,
        lastRerouteFailureAt: _lastRerouteFailureAt,
        routeAcceptedAt: _routeAcceptedAt,
        accuracyM: pos.accuracy.isFinite ? pos.accuracy : null,
        distanceToManeuverM:
            _navInstructionSnapshot?.distanceToManeuverMeters ??
            _nextNavDistanceM,
        lastRerouteFailed: _lastRerouteFailed,
        allowReroutePhase: _reroutePhaseAllowed(),
        liveRideActive: _liveRideActive,
        isWaiting: _isWaiting,
        isRerouting: _isRerouting,
        hasRoute: _routeCoords.length >= 2,
        routeVersion: _routeStepsVersion,
      ),
    );
    final decision = _lastRerouteDecision!;
    _logNavRerouteCandidateAndTransition(
      pos: pos,
      progress: progress,
      snapDistance: snapDistance.isFinite ? snapDistance : double.infinity,
      decision: decision,
    );
    if (decision.eligible) {
      _rerouteDecisionEligibleAt ??= DateTime.now();
      _offRouteRerouteDebounceStartedAt ??= _rerouteDecisionEligibleAt;
    } else if (!decision.offRouteLikely) {
      _rerouteDecisionEligibleAt = null;
    }
    _offRouteHitCount = decision.offRouteHitCount;
    _offRouteReason = decision.offRouteReason;
    final offRoute = decision.offRouteLikely;
    final oppositeDirection = progress?.oppositeDirectionLikely ?? false;
    final backwardProgress = progress?.backwardProgressLikely ?? false;
    final routeDeviation = progress?.routeDeviationLikely ?? false;
    if (offRoute != _offRouteLikely) {
      _offRouteLikely = offRoute;
      if (!offRoute) {
        _offRouteRerouteDebounceStartedAt = null;
      }
      // NAV-CAMERA-ZERO-OLD-ROUTE-HOLD-P0: old-route tangent loses camera
      // authority immediately when deviation flips on — do not wait for
      // confirmed reroute.
      if (offRoute) {
        _updateNavCameraBearingOwner(
          reason: 'off_route_flip',
          forceInvalidatePassive: true,
        );
      } else {
        _updateNavCameraBearingOwner(reason: 'off_route_cleared');
      }
      // NAV-R12-B: rebuild immediately so the route-adaptation banner state
      // shows on the same fix, not only once a route fetch starts.
      if (mounted) setState(() {});
    }
    _logNavR12RouteDeviation(
      pos: pos,
      progress: progress,
      snapDistance: snapDistance.isFinite ? snapDistance : double.infinity,
      routeDeviation: routeDeviation,
      oppositeDirection: oppositeDirection,
      backwardProgress: backwardProgress,
    );
    _logNavR17RerouteDecision(
      pos: pos,
      progress: progress,
      snapDistance: snapDistance.isFinite ? snapDistance : double.infinity,
      decision: decision,
    );

    final displayPoint = (_useMatchedVisual && snap != null)
        ? snap.point
        : rawPoint;
    _lastMarkerLagM = geo.Geolocator.distanceBetween(
      rawPoint.lat,
      rawPoint.lon,
      displayPoint.lat,
      displayPoint.lon,
    );

    _logNavBounded(
      'NAV_MATCH',
      'rawLat=${rawPoint.lat.toStringAsFixed(6)} rawLon=${rawPoint.lon.toStringAsFixed(6)} '
          'snapDistM=${snapDistance.isFinite ? snapDistance.toStringAsFixed(1) : 'inf'} '
          'gpsAccuracyM=${(pos.accuracy.isFinite ? pos.accuracy : -1).toStringAsFixed(1)} '
          'useMatchedVisual=$_useMatchedVisual reason=${canUseMatched ? 'confidence_ok' : 'confidence_low'}',
    );
  }

  bool _reroutePhaseAllowed() {
    if (_routePhase == _RideRoutePhase.toPickup) {
      return _activeBooking != null && _activeTripId == null;
    }
    if (_routePhase == _RideRoutePhase.trip) {
      final booking = _activeBooking;
      if (booking != null && _activeTripId != null) return true;
      if (_directRideActive &&
          (_directRideDestinationText ?? '').trim().isNotEmpty) {
        return true;
      }
    }
    return false;
  }

  void _logNavR17RerouteDecision({
    required geo.Position pos,
    required NavRouteProgressOutput? progress,
    required double snapDistance,
    required NavRerouteDecisionTickOutput decision,
  }) {
    final signature =
        '${decision.offRouteReason}|${decision.eligible}|'
        '${decision.cooldownActive}|${decision.movementOk}|'
        '${decision.samplesOffRoute}|${decision.shouldTrigger}|'
        '${decision.cooldownKind}|${decision.blockedReason}|'
        '${decision.strongSampleCount}|${decision.wrongStreetSampleCount}|'
        '${decision.wrongStreetFastPath}|${decision.fastPathEligible}';
    if (signature == _lastNavR17RerouteSignature) return;
    _lastNavR17RerouteSignature = signature;
    final headingDelta = progress?.headingDeltaDeg;
    final accuracyM = pos.accuracy.isFinite ? pos.accuracy : null;
    _logNavBounded(
      'NAV_R17_REROUTE_DECISION',
      'reason=${decision.offRouteReason} '
          'headingDeltaBucket=${navRerouteHeadingDeltaBucket(headingDelta)} '
          'routeDistanceBucket=${navRerouteDistanceBucket(snapDistance)} '
          'snapDistanceBucket=${navRerouteDistanceBucket(snapDistance)} '
          'accuracyBucket=${navRerouteAccuracyBucket(accuracyM)} '
          'samplesOffRoute=${decision.samplesOffRoute} '
          'strongSampleCount=${decision.strongSampleCount} '
          'wrongStreetSampleCount=${decision.wrongStreetSampleCount} '
          'wrongStreetFastPath=${decision.wrongStreetFastPath} '
          'firstStrongEvidenceAgeMs=${decision.firstStrongEvidenceAgeMs ?? -1} '
          'strongEvidenceDurationMs=${decision.strongEvidenceDurationMs ?? -1} '
          'movementBucket=${navRerouteMovementBucket(_speedKmhFor(pos))} '
          'usableSampleStreak=${decision.samplesOffRoute} '
          'eligible=${decision.eligible} '
          'cooldown=${decision.cooldownActive} '
          'cooldownKind=${navRerouteCooldownKindToken(decision.cooldownKind)} '
          'cooldownRemainingMs=${decision.cooldownRemainingMs} '
          'fastPathEligible=${decision.fastPathEligible} '
          'blockedReason=${decision.blockedReason} '
          'requestInFlight=${decision.requestInFlight} '
          'routeVersion=${decision.routeVersion}',
      intervalMs: 1200,
    );
    unawaited(
      NavDiagnosticsRecorder.instance.recordNavEngineEvent(
        tag: 'NAV_R17_REROUTE_DECISION',
        fields: <String, dynamic>{
          'reason': decision.offRouteReason,
          'headingDeltaBucket': navRerouteHeadingDeltaBucket(headingDelta),
          'routeDistanceBucket': navRerouteDistanceBucket(snapDistance),
          'snapDistanceBucket': navRerouteDistanceBucket(snapDistance),
          'accuracyBucket': navRerouteAccuracyBucket(accuracyM),
          'samplesOffRoute': decision.samplesOffRoute,
          'strongSampleCount': decision.strongSampleCount,
          'wrongStreetSampleCount': decision.wrongStreetSampleCount,
          'wrongStreetFastPath': decision.wrongStreetFastPath,
          'firstStrongEvidenceAgeMs': decision.firstStrongEvidenceAgeMs ?? -1,
          'strongEvidenceDurationMs': decision.strongEvidenceDurationMs ?? -1,
          'movementBucket': navRerouteMovementBucket(_speedKmhFor(pos)),
          'usableSampleStreak': decision.samplesOffRoute,
          'eligible': decision.eligible,
          'cooldown': decision.cooldownActive,
          'cooldownKind': navRerouteCooldownKindToken(decision.cooldownKind),
          'cooldownRemainingMs': decision.cooldownRemainingMs,
          'fastPathEligible': decision.fastPathEligible,
          'blockedReason': decision.blockedReason,
          'requestInFlight': decision.requestInFlight,
          'routeVersion': decision.routeVersion,
        },
      ),
    );
  }

  void _logNavR17RerouteApply({
    required String result,
    required String reason,
    required bool routeReplaced,
  }) {
    _logNavBounded(
      'NAV_R17_REROUTE_APPLY',
      'result=$result reason=$reason routeReplaced=$routeReplaced',
    );
    unawaited(
      NavDiagnosticsRecorder.instance.recordNavEngineEvent(
        tag: 'NAV_R17_REROUTE_APPLY',
        fields: <String, dynamic>{
          'result': result,
          'reason': reason,
          'routeReplaced': routeReplaced,
        },
      ),
    );
  }

  /// NAV-LATENCY-1 (Part E): bounded, PII-safe reroute timing chain. Reroutes
  /// are infrequent events, so each phase is emitted once (no coordinates).
  void _logNavRerouteCandidateAndTransition({
    required geo.Position pos,
    required NavRouteProgressOutput? progress,
    required double snapDistance,
    required NavRerouteDecisionTickOutput decision,
  }) {
    final now = DateTime.now();
    final suspected = decision.strongMismatchSuspected ||
        (progress?.strongMismatchSuspected ?? false);
    final confirmed = decision.strongMismatchConfirmed || decision.offRouteLikely;
    if (suspected) {
      final firstSuspect = _rerouteSuspectedAt == null;
      _rerouteSuspectedAt ??= now;
      if (firstSuspect) {
        _updateNavCameraBearingOwner(
          reason: 'deviation_suspected',
          forceInvalidatePassive: true,
        );
      }
    } else if (!confirmed) {
      _rerouteSuspectedAt = null;
      _rerouteConfirmedAt = null;
    }
    if (confirmed) {
      final firstConfirm = _rerouteConfirmedAt == null;
      _rerouteConfirmedAt ??= now;
      if (firstConfirm) {
        _updateNavCameraBearingOwner(
          reason: 'deviation_confirmed',
          forceInvalidatePassive: true,
        );
      }
    }
    if (decision.shouldTrigger) {
      _rerouteTriggerAt ??= now;
    }
    final headingDelta = progress?.headingDeltaDeg;
    final accuracyM = pos.accuracy.isFinite ? pos.accuracy : null;
    final growStreak = progress?.strongMismatchSampleCount ??
        decision.wrongStreetSampleCount;
    final candidateSig =
        '${decision.offRouteReason}|$suspected|$confirmed|'
        '${decision.samplesOffRoute}|${navRerouteDistanceBucket(snapDistance)}|'
        '${navRerouteHeadingDeltaBucket(headingDelta)}';
    if (candidateSig != _lastNavRerouteCandidateSignature) {
      _lastNavRerouteCandidateSignature = candidateSig;
      _logNavBounded(
        'NAV_REROUTE_CANDIDATE',
        'reason=${decision.offRouteReason} '
            'speedBucket=${navRerouteMovementBucket(_speedKmhFor(pos))} '
            'accuracyBucket=${navRerouteAccuracyBucket(accuracyM)} '
            'snapDistanceBucket=${navRerouteDistanceBucket(snapDistance)} '
            'snapGrowthSamples=$growStreak '
            'headingDeltaBucket=${navRerouteHeadingDeltaBucket(headingDelta)} '
            'forwardProgress=${progress?.forwardProgress ?? true} '
            'consecutiveSamples=${decision.samplesOffRoute} '
            'suspected=$suspected confirmed=$confirmed',
        intervalMs: 800,
      );
    }
    if (suspected || confirmed || decision.shouldTrigger || decision.eligible) {
      _logNavBounded(
        'NAV_REROUTE_TRANSITION',
        'suspectedAgeMs=${_rerouteSuspectedAt == null ? -1 : now.difference(_rerouteSuspectedAt!).inMilliseconds} '
            'confirmedAgeMs=${_rerouteConfirmedAt == null ? -1 : now.difference(_rerouteConfirmedAt!).inMilliseconds} '
            'triggerAgeMs=${_rerouteTriggerAt == null ? -1 : now.difference(_rerouteTriggerAt!).inMilliseconds} '
            'requestStartedAgeMs=${_rerouteRequestStartedAt == null ? -1 : now.difference(_rerouteRequestStartedAt!).inMilliseconds} '
            'debounceMs=${decision.debounceRequired.inMilliseconds} '
            'blockedReason=${decision.blockedReason} '
            'shouldTrigger=${decision.shouldTrigger} '
            'eligible=${decision.eligible}',
        intervalMs: 800,
      );
    }
  }

  void _logNavRerouteBannerDiag({
    required String state,
    required String reason,
  }) {
    final sig = '$state|$reason|$_routeStepsVersion';
    if (sig == _lastNavRerouteBannerSignature) return;
    _lastNavRerouteBannerSignature = sig;
    _logNavBounded(
      'NAV_REROUTE_BANNER',
      'bannerState=$state reason=$reason '
          'staleSuppressed=${state == 'suppressed_stale' || state == 'route_adaptation'} '
          'adaptationShown=${state == 'route_adaptation'} '
          'ownershipAccepted=$_rerouteOwnershipAccepted '
          'routeVersion=$_routeStepsVersion',
      intervalMs: 1,
    );
  }

  void _logNavLatencyReroute({
    required String phase,
    required String reason,
    int? elapsedFromCandidateMs,
    int? requestDurationMs,
    int? parseDurationMs,
    int? renderDurationMs,
    int? totalDurationMs,
    int? oldRouteVersion,
    int? newRouteVersion,
  }) {
    final b = StringBuffer('[NAV_LATENCY_REROUTE] phase=$phase reason=$reason');
    if (elapsedFromCandidateMs != null) {
      b.write(' elapsedFromCandidateMs=$elapsedFromCandidateMs');
    }
    if (requestDurationMs != null)
      b.write(' requestDurationMs=$requestDurationMs');
    if (parseDurationMs != null) b.write(' parseDurationMs=$parseDurationMs');
    if (renderDurationMs != null)
      b.write(' renderDurationMs=$renderDurationMs');
    if (totalDurationMs != null) b.write(' totalDurationMs=$totalDurationMs');
    if (oldRouteVersion != null) b.write(' oldRouteVersion=$oldRouteVersion');
    if (newRouteVersion != null) b.write(' newRouteVersion=$newRouteVersion');
    debugPrint(b.toString());
    unawaited(
      NavDiagnosticsRecorder.instance.recordNavEngineEvent(
        tag: 'NAV_LATENCY_REROUTE',
        fields: <String, dynamic>{
          'phase': phase,
          'reason': reason,
          if (elapsedFromCandidateMs != null)
            'elapsedFromCandidateMs': elapsedFromCandidateMs,
          if (requestDurationMs != null) 'requestDurationMs': requestDurationMs,
          if (parseDurationMs != null) 'parseDurationMs': parseDurationMs,
          if (renderDurationMs != null) 'renderDurationMs': renderDurationMs,
          if (totalDurationMs != null) 'totalDurationMs': totalDurationMs,
          if (oldRouteVersion != null) 'oldRouteVersion': oldRouteVersion,
          if (newRouteVersion != null) 'newRouteVersion': newRouteVersion,
        },
      ),
    );
  }

  /// NAV-R12-B: bounded, PII-safe route-deviation diagnostics (no lat/lng).
  void _logNavR12RouteDeviation({
    required geo.Position pos,
    required NavRouteProgressOutput? progress,
    required double snapDistance,
    required bool routeDeviation,
    required bool oppositeDirection,
    required bool backwardProgress,
  }) {
    final rerouteEligible = _canAttemptOffRouteReroute();
    final signature =
        '$_offRouteReason|$routeDeviation|$oppositeDirection|'
        '$backwardProgress|$_offRouteLikely|$rerouteEligible';
    final changed = signature != _lastNavR12OffRouteSignature;
    _lastNavR12OffRouteSignature = signature;
    final headingDelta = progress?.headingDeltaDeg;
    _logNavBounded(
      'NAV_R12_ROUTE_DEVIATION',
      'reason=$_offRouteReason '
          'speedKmh=${_speedKmhFor(pos).toStringAsFixed(1)} '
          'snapDistM=${snapDistance.isFinite ? snapDistance.toStringAsFixed(1) : 'inf'} '
          'headingDeltaDeg=${headingDelta?.toStringAsFixed(0) ?? 'na'} '
          'routeDeviationLikely=$routeDeviation '
          'oppositeDirectionLikely=$oppositeDirection '
          'backwardProgressLikely=$backwardProgress '
          'offRouteLikely=$_offRouteLikely '
          'rerouteEligible=$rerouteEligible',
      intervalMs: changed ? 1 : 2000,
    );
    if (changed) {
      unawaited(
        NavDiagnosticsRecorder.instance.recordNavEngineEvent(
          tag: 'NAV_R12_ROUTE_DEVIATION',
          fields: <String, dynamic>{
            'reason': _offRouteReason,
            'speedKmh': _speedKmhFor(pos).round(),
            'snapDistM': snapDistance.isFinite ? snapDistance.round() : -1,
            'headingDeltaDeg': headingDelta?.round() ?? -1,
            'routeDeviationLikely': routeDeviation,
            'oppositeDirectionLikely': oppositeDirection,
            'backwardProgressLikely': backwardProgress,
            'offRouteLikely': _offRouteLikely,
            'rerouteEligible': rerouteEligible,
          },
        ),
      );
    }
  }

  bool _isRouteDeviationOffRouteReason() {
    return navRerouteIsRouteDeviationReason(_offRouteReason);
  }

  Duration _rerouteCooldownFor() {
    return navRerouteCooldownFor(
      offRouteReason: _offRouteReason,
      lastRerouteFailed: _lastRerouteFailed,
    );
  }

  bool _canAttemptOffRouteReroute() {
    return _lastRerouteDecision?.eligible ?? false;
  }

  void _evaluateOffRouteReroute() {
    if (_lastRerouteDecision?.shouldTrigger != true) return;
    final reason = _isRouteDeviationOffRouteReason()
        ? _offRouteReason
        : 'off_route';
    // NAV-PARKING-2 Commit 1: once bounded destination-proximity arrival is
    // authoritative, suppress contradictory close-destination rerouting.
    if (_navParkingArrivalConfirmed) {
      _logNavBounded(
        'NAV_ARRIVAL',
        'event=close_destination_reroute_suppressed reason=$reason',
        intervalMs: 1500,
      );
      return;
    }
    // NAV-PARKING-2 Commit 1: during the bounded startup bootstrap (departing a
    // parking lot / private access road), the first unmatched samples and a
    // stale/stationary heading must not storm opposite-direction / wrong-street
    // reroutes. Genuine severe deviations resume once readiness is confirmed.
    if (!_navStartupBootstrap.ready) {
      _logNavBounded(
        'NAV_STARTUP_BOOTSTRAP',
        'phase=${_navStartupBootstrap.phase.label} reroute_suppressed reason=$reason',
        intervalMs: 1500,
      );
      return;
    }
    // FLUXIDI NAV-STREETLEVEL-FLUID-MOTION-2 (Phase 1, Part F): block
    // opposite-direction / backward-progress reroutes during the post-
    // reroute stabilisation window (needs >=2 fresh in-generation samples
    // OR 8 s cooldown). Severe deviations bypass the gate immediately. The
    // gate is a no-op outside the window.
    //
    // NAV-REROUTE-P0: confirmed wrong-street / junction-exit must not wait
    // on this opposite-direction thrash gate — request start stays in the
    // same location-processing cycle as shouldTrigger=true.
    final isOppositeOrBacktrack = reason == 'opposite_direction' ||
        reason == 'opposite_direction_strong' ||
        reason == 'backward_progress';
    if (isOppositeOrBacktrack) {
      final snapDistance =
          _lastRouteSnap?.distanceFromRouteM ??
          _lastNavRouteProgress?.snapDistanceM ??
          double.infinity;
      final speedKmh = _lastPos != null ? _speedKmhFor(_lastPos!) : 0.0;
      final allow = _rerouteStabilization.allowOppositeDirectionReroute(
        now: DateTime.now(),
        snapDistanceM: snapDistance,
        oppositeStrong: reason == 'opposite_direction_strong',
        speedKmh: speedKmh,
        currentRouteGeneration: _routeStepsVersion,
      );
      if (!allow) {
        _logNavBounded(
          'NAV_REROUTE_STAB',
          'gate=block reason=$reason freshSamples=${_rerouteStabilization.freshSamplesCollected} '
              'requiredSamples=${NavRerouteStabilization.freshSamplesRequired} '
              'currentRouteGeneration=$_routeStepsVersion '
              'postRerouteRouteGeneration=${_rerouteStabilization.postRerouteRouteGeneration} '
              'snapDistanceM=${snapDistance.isFinite ? snapDistance.toStringAsFixed(1) : 'inf'} '
              'speedKmh=${speedKmh.toStringAsFixed(1)}',
          intervalMs: 1500,
        );
        return;
      }
    }
    unawaited(_triggerOffRouteReroute(reason: reason));
  }

  void _resetOffRouteStateAfterReroute() {
    _rerouteDecision.noteRerouteApplied(DateTime.now());
    // FLUXIDI NAV-STREETLEVEL-FLUID-MOTION-2 (Phase 1, Part F): latch the
    // post-reroute stabilisation window against the *new* route generation
    // and reset the streetlevel bearing controller so old-route heading
    // evidence cannot bias the next pump ticks.
    _rerouteStabilization.noteRerouteApplied(
      newRouteGeneration: _routeStepsVersion,
      now: DateTime.now(),
    );
    // RELEASE-P0: do NOT wipe apply-time forward ownership established in
    // `_tryActivatePreparedDriverRoute`. Clearing matched visual / snap /
    // trim / bearing seed here caused briefly-correct-then-behind: the first
    // draw looked right, then this finally-block restored old ownership.
    final preserveApplyOwnership = _rerouteApplyForwardOwnershipActive;
    if (!preserveApplyOwnership) {
      _streetlevelBearingController.reset();
      _navStationaryBearingGate.reset();
      _navBearingAnchorLat = null;
      _navBearingAnchorLon = null;
      _useMatchedVisual = false;
      _lastVisualProgressM = null;
      _lastRouteSnap = null;
      _routeLineProgressTrimmed = false;
      _lastRouteLineTrimProgressM = 0.0;
      _lastRouteLineTrimAt = null;
    } else {
      // Keep snap/trim/matched visual. Re-seed bearing from the *new* forward
      // segment so a prior streetlevel reset cannot restore diagonal bearing.
      _streetlevelBearingController.reset();
      final seedBearing =
          navFirstMeaningfulRouteSegmentBearing(_routeCoords);
      if (seedBearing != null) {
        final seeded = _navStationaryBearingGate.seedInitialRouteBearing(
          routeTangentBearingDeg: seedBearing,
          routeSegmentIndex: 0,
        );
        if (seeded != null) {
          _navBearingAnchorLat = _lastPos?.latitude;
          _navBearingAnchorLon = _lastPos?.longitude;
          _logNavBounded(
            'NAV_BEARING_SEED',
            'reason=reroute_reset_preserve bearing=${seeded.toStringAsFixed(1)} '
                'source=forward_segment',
            intervalMs: 1000,
          );
        }
      }
      _logNavBounded(
        'NAV_R17_REROUTE_APPLY',
        'result=preserve_apply_ownership gen=$_routeStepsVersion '
            'trimmed=$_routeLineProgressTrimmed matched=$_useMatchedVisual',
        intervalMs: 500,
      );
    }
    _streetlevelFollowPump.setExpectedRouteGeneration(_routeStepsVersion);
    // FLUXIDI Phase 2A: advance the native-side route generation so any
    // in-flight pose belonging to the old route is rejected by the custom
    // LocationProvider gating.
    _nativeFollow?.noteRouteGenerationApplied(_routeStepsVersion);
    _lastRerouteDecision = null;
    _offRouteHitCount = 0;
    _offRouteLikely = false;
    _offRouteReason = 'none';
    _offRouteRerouteDebounceStartedAt = null;
    _matchEnterHits = 0;
    _matchExitHits = 0;
  }

  String _reroutePhaseLabel() {
    return _routePhase == _RideRoutePhase.toPickup ? 'toPickup' : 'toDropoff';
  }

  NavRerouteRequestOrigin? _navRerouteOriginFromLastPos() {
    final pos = _lastPos;
    if (pos == null) return null;
    final heading = pos.heading.isFinite && pos.heading >= 0
        ? pos.heading
        : (_lastMovementBearing ?? 0.0);
    final snap = _lastRouteSnap;
    final matchedOk =
        snap != null &&
        (_lastNavRouteProgress?.confidence ?? 0) >= 55 &&
        !_offRouteLikely;
    return NavRerouteRequestOrigin(
      latitude: pos.latitude,
      longitude: pos.longitude,
      headingDeg: heading,
      mapMatchedLatitude: matchedOk ? snap.point.lat : null,
      mapMatchedLongitude: matchedOk ? snap.point.lon : null,
      accuracyM: pos.accuracy.isFinite ? pos.accuracy : null,
      speedKmh: _speedKmhFor(pos),
    );
  }

  NavRerouteDestination? _navRerouteDestinationFromActiveRoute() {
    if (_routeCoords.length < 2) return null;
    final last = _routeCoords.last;
    return NavRerouteDestination(latitude: last.lat, longitude: last.lon);
  }

  void _invalidateOldRouteGuidanceForReroute({required String reason}) {
    // Release old maneuver guidance immediately after confirm — do not keep
    // navigating along the obsolete route while the request is in flight.
    _activeBanner = null;
    _activeLaneGuidance = null;
    _nextNavInstruction = null;
    _nextNavStreet = null;
    _nextNavDistanceM = null;
    _nextNavType = null;
    _nextNavModifier = null;
    _navInstructionSnapshot = NavInstructionSnapshot.none;
    _useMatchedVisual = false;
    _logNavBounded(
      'NAV_REROUTE_COORD',
      'event=old_guidance_invalidated reason=$reason '
          '${_navRerouteCoordinator.latency.toDiagLine(
            navigationSessionGeneration:
                _navRerouteCoordinator.navigationSessionGeneration,
            rerouteGeneration: _navRerouteCoordinator.rerouteGeneration,
            routeVersion: _routeStepsVersion,
          )}',
      intervalMs: 400,
    );
  }

  Future<void> _triggerOffRouteReroute({
    required String reason,
    bool forceFollowUp = false,
  }) async {
    final origin = _navRerouteOriginFromLastPos();
    final dest = _navRerouteDestinationFromActiveRoute();
    if (origin == null || dest == null) {
      _logNavR17RerouteApply(
        result: 'skipped',
        reason: 'missing_origin_or_destination',
        routeReplaced: false,
      );
      return;
    }

    if (_isRerouting) {
      // Latest-wins: invalidate any in-flight package via a new generation and
      // queue one follow-up using the latest real position after clear.
      _routeRequestGeneration.begin();
      _pendingRerouteAfterInFlight = true;
      _pendingRerouteReason = reason;
      _navRerouteCoordinator.confirmOffRoute(
        reason: reason,
        origin: origin,
        dest: dest,
      );
      _invalidateOldRouteGuidanceForReroute(reason: reason);
      _logNavBounded(
        'NAV_R17_REROUTE_APPLY',
        'result=supersede_inflight reason=$reason gen=${_routeRequestGeneration.latest} '
            'rerouteGen=${_navRerouteCoordinator.rerouteGeneration}',
        intervalMs: 800,
      );
      return;
    }
    if (!forceFollowUp && !(_lastRerouteDecision?.eligible ?? false)) {
      _logNavR17RerouteApply(
        result: 'skipped',
        reason: reason,
        routeReplaced: false,
      );
      return;
    }

    final rerouteGen = _navRerouteCoordinator.confirmOffRoute(
      reason: reason,
      origin: origin,
      dest: dest,
    );
    _activeRerouteRequestGeneration = rerouteGen;
    _invalidateOldRouteGuidanceForReroute(reason: reason);
    _navRerouteCoordinator.beginRequest(
      expectedGeneration: rerouteGen,
      origin: origin,
    );

    _isRerouting = true;
    _pendingRerouteAfterInFlight = false;
    _pendingRerouteReason = null;
    _rerouteOwnershipAccepted = false;
    _rerouteReason = reason;
    _lastRerouteAt = DateTime.now();
    _rerouteRequestStartedAt = _lastRerouteAt;
    // NAV-CAMERA-ZERO-OLD-ROUTE-HOLD-P0: travel direction owns bearing for
    // the entire pending window; supersede any old-route passive follow.
    _updateNavCameraBearingOwner(
      reason: 'reroute_pending',
      forceInvalidatePassive: true,
    );
    _reroutePackagePreparedAt = null;
    // NAV-LATENCY-1 (Part E): capture the deviation-candidate anchor and the
    // pre-reroute route version before they are reset, for atomic-handoff
    // timing on the next field test. No coordinates are emitted.
    final rerouteCandidateAt =
        _rerouteDecisionEligibleAt ?? _offRouteRerouteDebounceStartedAt;
    final oldRouteVersion = _routeStepsVersion;
    _offRouteRerouteDebounceStartedAt = null;
    final phaseLabel = _reroutePhaseLabel();
    final rerouteStartedAt = DateTime.now();
    final elapsedFromCandidateMs = rerouteCandidateAt == null
        ? null
        : rerouteStartedAt.difference(rerouteCandidateAt).inMilliseconds;
    _logNavR17RerouteApply(
      result: 'started',
      reason: reason,
      routeReplaced: false,
    );
    if (elapsedFromCandidateMs != null) {
      _logNavBounded(
        'NAV_R17_REROUTE_APPLY',
        'decisionEligibleToRequestStartMs=$elapsedFromCandidateMs '
            'reason=$reason routeVersion=$oldRouteVersion',
      );
    }
    _logNavLatencyReroute(
      phase: 'decision_eligible',
      reason: reason,
      elapsedFromCandidateMs: elapsedFromCandidateMs,
      oldRouteVersion: oldRouteVersion,
    );
    _logNavLatencyReroute(
      phase: 'request_started',
      reason: reason,
      elapsedFromCandidateMs: elapsedFromCandidateMs,
      oldRouteVersion: oldRouteVersion,
    );
    debugPrint('[NAV_REROUTE] phase=$phaseLabel reason=$reason start=1');
    unawaited(
      NavDiagnosticsRecorder.instance.recordRerouteEvent(
        offRoute: _offRouteLikely,
        triggerReason: reason,
        phase: phaseLabel,
      ),
    );
    if (kDebugMode) {
      debugPrint('[NAV_REROUTE] ui=loading reason=rerouting');
    }
    if (mounted) setState(() {});

    var ok = false;
    try {
      if (_routePhase == _RideRoutePhase.toPickup) {
        final booking = _activeBooking;
        if (booking != null) {
          // NAV-SIGNAL-P0B: success is activation, not leftover prior coords.
          ok = await _buildNavRouteToPickup(booking);
        }
      } else {
        final booking = _activeBooking;
        if (booking != null && _activeTripId != null) {
          ok = await _buildNavRouteToDestination(booking);
        } else if (_directRideActive) {
          final destination = (_directRideDestinationText ?? '').trim();
          if (destination.isNotEmpty) {
            ok = await _buildDirectRouteToDestination(destination);
          }
        }
      }
    } catch (_) {
      ok = false;
    } finally {
      final totalDurationMs = DateTime.now()
          .difference(rerouteStartedAt)
          .inMilliseconds;
      if (ok) {
        _resetOffRouteStateAfterReroute();
        _logNavR17RerouteApply(
          result: 'success',
          reason: reason,
          routeReplaced: true,
        );
        final candidateToAppliedMs = _rerouteSuspectedAt == null
            ? totalDurationMs
            : DateTime.now().difference(_rerouteSuspectedAt!).inMilliseconds;
        _logNavBounded(
          'NAV_REROUTE_RESULT',
          'requestGeneration=${_routeRequestGeneration.latest} '
              'requestDurationMs=$totalDurationMs '
              'staleRejected=0 '
              'parseApplyDurationMs=$totalDurationMs '
              'candidateToAppliedMs=$candidateToAppliedMs '
              'result=success reason=$reason '
              'oldRouteVersion=$oldRouteVersion '
              'newRouteVersion=$_routeStepsVersion',
        );
        _logNavLatencyReroute(
          phase: 'route_applied',
          reason: reason,
          requestDurationMs: totalDurationMs,
          totalDurationMs: totalDurationMs,
          oldRouteVersion: oldRouteVersion,
          newRouteVersion: _routeStepsVersion,
        );
        _logNavLatencyReroute(
          phase: 'camera_handoff_complete',
          reason: reason,
          totalDurationMs: totalDurationMs,
          oldRouteVersion: oldRouteVersion,
          newRouteVersion: _routeStepsVersion,
        );
      } else {
        _logNavR17RerouteApply(
          result: 'failed',
          reason: reason,
          routeReplaced: false,
        );
        _logNavLatencyReroute(
          phase: 'route_apply_failed',
          reason: reason,
          totalDurationMs: totalDurationMs,
          oldRouteVersion: oldRouteVersion,
          newRouteVersion: _routeStepsVersion,
        );
      }
      // NAV-R10 (Part G): a reroute was actually observed this session.
      _driverNavValidationEngine.noteRerouteObserved(success: ok);
      // NAV-R12-B: failed reroutes retry on a short backoff instead of the
      // full cooldown (see _rerouteCooldownFor).
      _lastRerouteFailed = !ok;
      if (ok) {
        _lastRerouteSuccessAt ??= DateTime.now();
        final acceptedAt = _routeAcceptedAt;
        final requestStarted = _rerouteRequestStartedAt;
        if (acceptedAt != null && requestStarted != null) {
          _logNavBounded(
            'NAV_R17_REROUTE_APPLY',
            'routeAcceptedToTransportCompleteMs='
                '${DateTime.now().difference(acceptedAt).inMilliseconds} '
                'requestStartToPackagePreparedMs='
                '${(_reroutePackagePreparedAt ?? acceptedAt).difference(requestStarted).inMilliseconds} '
                'packagePreparedToRouteAcceptedMs='
                '${acceptedAt.difference(_reroutePackagePreparedAt ?? acceptedAt).inMilliseconds}',
          );
        }
      } else {
        _lastRerouteFailureAt = DateTime.now();
        _rerouteOwnershipAccepted = false;
      }
      _isRerouting = false;
      _rerouteOwnershipAccepted = false;
      _rerouteReason = null;
      _rerouteDecisionEligibleAt = null;
      if (_pendingRerouteAfterInFlight) {
        final followUp = (_pendingRerouteReason ?? reason).trim();
        _pendingRerouteAfterInFlight = false;
        _pendingRerouteReason = null;
        if (followUp.isNotEmpty) {
          // Short yield so the next tick can refresh GPS + decision state.
          unawaited(
            Future<void>.delayed(const Duration(milliseconds: 200), () {
              if (!mounted) return;
              unawaited(
                _triggerOffRouteReroute(
                  reason: followUp,
                  forceFollowUp: true,
                ),
              );
            }),
          );
        }
      }
      _logNavBounded(
        'NAV_R17_REROUTE_APPLY',
        'result=in_flight_cleared ok=${ok ? 1 : 0} reason=$reason',
      );
      debugPrint(
        '[NAV_REROUTE] phase=$phaseLabel reason=$reason result=${ok ? 'ok' : 'fail'}',
      );
      unawaited(
        NavDiagnosticsRecorder.instance.recordRerouteEvent(
          offRoute: _offRouteLikely,
          triggerReason: reason,
          durationMs: DateTime.now()
              .difference(rerouteStartedAt)
              .inMilliseconds,
          success: ok,
          phase: phaseLabel,
        ),
      );
      if (!ok) {
        // FLUXIDI-EXTERNAL-NAV-FALLBACK-POPUP-LOOP-P0-1: never auto-recommend
        // Waze/Google on reroute failure. Fluxidi keeps the prior route and
        // retries in-app; external maps stay behind the manual More actions.
        _maybeAutoPromptExternalNavFallback(
          reason: 'reroute_failed',
          failureIsTerminal: false,
          transientNavigationSignal: true,
        );
      }
      if (mounted) setState(() {});
    }
  }

  _LonLat _displayRoutePointFor(geo.Position pos) {
    final snap =
        _lastRouteSnap ?? _snapToRoute(_LonLat(pos.longitude, pos.latitude));
    if (_useMatchedVisual && snap != null) return snap.point;
    return _LonLat(pos.longitude, pos.latitude);
  }

  ({_LonLat point, String source, double? snapDistM}) _driverMarkerDisplayFor(
    geo.Position pos,
  ) {
    final raw = _LonLat(pos.longitude, pos.latitude);
    final snap = _lastRouteSnap ?? _snapToRoute(raw);
    final activeNav =
        _cameraMode == _CameraMode.follow &&
        _liveRideActive &&
        _routeCoords.length >= 2;

    if (activeNav) {
      final progress = _lastNavRouteProgress;
      final confidence = _lastNavConfidence;
      if (_routeProgressMatchedVisual(progress) &&
          (confidence?.trustRouteSnap ?? true) &&
          progress!.snappedLatitude != null &&
          progress.snappedLongitude != null) {
        return (
          point: _LonLat(progress.snappedLongitude!, progress.snappedLatitude!),
          source: 'route_snap',
          snapDistM: progress.snapDistanceM,
        );
      }
      if (progress?.offRouteLikely == true) {
        return (
          point: raw,
          source: 'raw',
          snapDistM: progress?.snapDistanceM ?? snap?.distanceFromRouteM,
        );
      }
    }

    if (!activeNav) {
      if (_useMatchedVisual && snap != null) {
        return (
          point: snap.point,
          source: 'route_snap',
          snapDistM: snap.distanceFromRouteM,
        );
      }
      return (
        point: raw,
        source: 'fallback',
        snapDistM: snap?.distanceFromRouteM,
      );
    }

    if (snap == null) {
      return (point: raw, source: 'raw', snapDistM: null);
    }

    if (_offRouteLikely) {
      return (point: raw, source: 'raw', snapDistM: snap.distanceFromRouteM);
    }

    final markerSnapThresholdM = math.max(45.0, _snapThresholdFor(pos));
    if (snap.distanceFromRouteM <= markerSnapThresholdM) {
      return (
        point: snap.point,
        source: 'route_snap',
        snapDistM: snap.distanceFromRouteM,
      );
    }

    return (point: raw, source: 'raw', snapDistM: snap.distanceFromRouteM);
  }

  double? _effectiveRouteProgressM(geo.Position pos) {
    final progress = _lastNavRouteProgress;
    if (_isActiveDriverNavEngineContext() &&
        _routeProgressMatchedVisual(progress) &&
        progress?.distanceAlongRouteM != null) {
      return progress!.distanceAlongRouteM;
    }
    final snap =
        _lastRouteSnap ?? _snapToRoute(_LonLat(pos.longitude, pos.latitude));
    if (_useMatchedVisual && snap != null) return snap.distanceAlongRouteM;
    return null;
  }

  List<_LonLat> _routeCoordsFromSnap(_RouteSnap snap) {
    return driverRouteCoordsFromSnap(_routeCoords, snap);
  }

  Future<void> _syncVisibleRouteLineWithProgress(
    geo.Position pos, {
    String reason = 'progress_update',
    bool force = false,
    int? routeRenderEpoch,
  }) async {
    final drawEpoch = routeRenderEpoch ?? _routeRenderEpoch;
    if (_routeCoords.length < 2 || _routeLineManager == null) return;
    if (!_isCurrentRouteRenderEpoch(drawEpoch)) return;
    final snap =
        _lastRouteSnap ?? _snapToRoute(_LonLat(pos.longitude, pos.latitude));
    final progressM = _effectiveRouteProgressM(pos);

    if (_cameraMode != _CameraMode.follow || !_liveRideActive) {
      if (_routeLineProgressTrimmed) {
        _routeLineProgressTrimmed = false;
        _lastRouteLineTrimProgressM = 0.0;
        await _drawRouteLine(
          _routeCoords,
          force: true,
          routeRenderEpoch: drawEpoch,
        );
        _logNavBounded(
          'NAV_OS_R2_ROUTE_PROGRESS_LINE',
          'completedM=0 remainingM=${driverRouteLengthMeters(_routeCoords).toStringAsFixed(0)} reason=reset_full',
        );
      }
      return;
    }

    if (!_useMatchedVisual || snap == null || progressM == null) {
      if (_routeLineProgressTrimmed) {
        _routeLineProgressTrimmed = false;
        _lastRouteLineTrimProgressM = 0.0;
        await _drawRouteLine(
          _routeCoords,
          force: true,
          routeRenderEpoch: drawEpoch,
        );
        _logNavBounded(
          'NAV_OS_R2_ROUTE_PROGRESS_LINE',
          'completedM=0 remainingM=${driverRouteLengthMeters(_routeCoords).toStringAsFixed(0)} reason=reset_no_snap',
        );
      }
      _logNavBounded(
        'NAV_PROGRESS',
        'progressM=-1 routeLineTrimmed=false markerLagM=${_lastMarkerLagM.toStringAsFixed(1)}',
      );
      return;
    }

    // NAV-OS-R2 + presentation smoothness: coalesce GPS-driven trim writes.
    final now = DateTime.now();
    final deltaM = (progressM - _lastRouteLineTrimProgressM).abs();
    final msSinceLast = _lastRouteLineTrimAt == null
        ? 999999
        : now.difference(_lastRouteLineTrimAt!).inMilliseconds;
    final writeDecision = decideNavRouteLineProgressWrite(
      capturedRenderEpoch: drawEpoch,
      currentRenderEpoch: _routeRenderEpoch,
      hasActiveLineAnnotations: _routeLine != null && _routeLineOutline != null,
      forceRecreate: force && !_routeLineProgressTrimmed,
      sameRouteVersion: true,
      progressDeltaM: deltaM,
      msSinceLastWrite: msSinceLast,
    );
    if (writeDecision.kind == NavRouteLineProgressWriteKind.skip && !force) {
      _logNavBounded(
        'NAV_PROGRESS',
        'progressM=${progressM.toStringAsFixed(1)} routeLineTrimmed=true '
            'markerLagM=${_lastMarkerLagM.toStringAsFixed(1)} '
            'write=skip reason=${writeDecision.reason}',
      );
      return;
    }

    // NAV-OS-R2: split geometry — muted grey behind the taxi, blue ahead.
    var remaining = _routeCoordsFromSnap(snap);
    final completed = driverRouteCoordsUpToSnap(_routeCoords, snap);
    final cockpitLeadInActive = _navigationPresentationStateFor(
      _navCameraViewMode,
    ).useDriverCockpitCamera;
    final leadInM = cockpitLeadInActive
        ? driverCockpitRouteVisualLeadInMeters(_driverCockpitViewLevel)
        : 0.0;
    if (cockpitLeadInActive && leadInM > 0) {
      remaining = driverRouteCoordsWithCockpitVisualLeadIn(
        routeCoords: _routeCoords,
        snap: snap,
        leadInM: leadInM,
      );
      _logNavPresRouteLeadin(
        level: _driverCockpitViewLevel,
        leadInM: leadInM,
        points: remaining.length,
        result: 'applied',
        reason: reason,
      );
    } else {
      _logNavPresRouteLeadin(
        level: _driverCockpitViewLevel,
        leadInM: 0,
        points: remaining.length,
        result: 'skipped',
        reason: cockpitLeadInActive ? 'lead_in_zero' : 'not_cockpit',
      );
    }
    if (remaining.length >= 2) {
      if (!_isCurrentRouteRenderEpoch(drawEpoch)) return;
      _routeLineProgressTrimmed = true;
      _lastRouteLineTrimProgressM = progressM;
      _lastRouteLineTrimAt = now;
      final preferUpdate =
          writeDecision.kind == NavRouteLineProgressWriteKind.updateInPlace ||
          (force &&
              _routeLine != null &&
              _routeLineOutline != null &&
              writeDecision.kind != NavRouteLineProgressWriteKind.recreate);
      await _drawRouteLine(
        remaining,
        force: !preferUpdate,
        completedCoords: completed,
        routeRenderEpoch: drawEpoch,
        preferInPlaceUpdate: preferUpdate,
      );
      final totalM = driverRouteLengthMeters(_routeCoords);
      final remainingM = (totalM - progressM).clamp(0.0, totalM);
      _logNavBounded(
        'NAV_OS_R2_ROUTE_PROGRESS_LINE',
        'completedM=${progressM.toStringAsFixed(0)} '
            'remainingM=${remainingM.toStringAsFixed(0)} reason=$reason',
      );
    }
    _logNavBounded(
      'NAV_PROGRESS',
      'progressM=${progressM.toStringAsFixed(1)} routeLineTrimmed=${remaining.length >= 2} markerLagM=${_lastMarkerLagM.toStringAsFixed(1)}',
    );
  }

  double? _routeBearingAtSnap(_RouteSnap? snap) {
    return driverRouteBearingAtSnap(_routeCoords, snap);
  }

  bool _isActiveDriverNavEngineContext() {
    return _cameraMode == _CameraMode.follow &&
        _liveRideActive &&
        _routeCoords.length >= 2;
  }

  NavEngineInput _buildNavEngineInput(geo.Position pos, _RouteSnap? snap) {
    final markerDisplay = _driverMarkerDisplayFor(pos);
    final progress = _lastNavRouteProgress;
    final confidence = _lastNavConfidence;
    final activeNav = _isActiveDriverNavEngineContext();
    final progressReliable = activeNav && progress != null
        ? progress.hasReliableSnap
        : markerDisplay.source == 'route_snap';
    final hasReliableSnap =
        progressReliable &&
        (!activeNav || confidence == null || confidence.trustRouteSnap);
    final snappedLat = hasReliableSnap
        ? (progress?.snappedLatitude ?? snap?.point.lat)
        : null;
    final snappedLon = hasReliableSnap
        ? (progress?.snappedLongitude ?? snap?.point.lon)
        : null;
    final routeBearing = _resolveForwardRouteBearing(pos, snap: snap);
    return NavEngineInput(
      timestamp: DateTime.now(),
      rawLatitude: pos.latitude,
      rawLongitude: pos.longitude,
      snappedLatitude: snappedLat,
      snappedLongitude: snappedLon,
      hasReliableSnap: hasReliableSnap,
      rawHeading: pos.heading.isFinite && pos.heading >= 0 ? pos.heading : null,
      routeBearing: routeBearing,
      speedKmh: _speedKmhFor(pos),
      accuracyM: pos.accuracy.isFinite && pos.accuracy > 0
          ? pos.accuracy
          : null,
      cameraFollowMode: _cameraMode == _CameraMode.follow,
      liveRideActive: _liveRideActive,
      movementBearing: _lastMovementBearing,
      offRouteLikely: progress?.offRouteLikely ?? _offRouteLikely,
      trustBearing: confidence?.trustBearing ?? true,
      routeConfidence: progress?.confidence ?? confidence?.routeScore,
      routeDeviationLikely: progress?.routeDeviationLikely ?? false,
      oppositeDirectionLikely: progress?.oppositeDirectionLikely ?? false,
      backwardProgressLikely: progress?.backwardProgressLikely ?? false,
      headingDeltaDeg: progress?.headingDeltaDeg,
      forwardProgress: progress?.forwardProgress ?? true,
    );
  }

  String _navEngineRefreshKeyFor(geo.Position pos) {
    return '${pos.timestamp.millisecondsSinceEpoch}|'
        '${pos.latitude.toStringAsFixed(6)}|'
        '${pos.longitude.toStringAsFixed(6)}';
  }

  void _refreshNavEngineForPosition(geo.Position pos) {
    final key = _navEngineRefreshKeyFor(pos);
    if (_lastNavEngineRefreshKey == key) return;
    _lastNavEngineRefreshKey = key;

    if (!_isActiveDriverNavEngineContext()) {
      _driverNavEngine.reset();
      _lastNavEngineOutput = null;
      _resetNavR3MotionState();
      _resetNavMotionPredictionState();
      _lastNavConfidence = null;
      return;
    }

    final snap =
        _lastRouteSnap ?? _snapToRoute(_LonLat(pos.longitude, pos.latitude));
    final priorOutput = _lastNavEngineOutput;
    final fromVisual = _navR3CaptureVisual(priorOutput);
    try {
      final output = _driverNavEngine.update(_buildNavEngineInput(pos, snap));
      _lastNavEngineOutput = output;
      _applyNavEngineMotionTarget(
        output,
        fromVisual: fromVisual,
        priorOutput: priorOutput,
      );
      final progress = _lastNavRouteProgress;
      _driverNavMotionPrediction.noteEngineUpdate(
        timestamp: output.timestamp,
        displayLatitude: output.displayLatitude,
        displayLongitude: output.displayLongitude,
        bearing: output.bearing,
        trustRouteSnap:
            _lastNavConfidence?.trustRouteSnap ??
            progress?.hasReliableSnap ??
            false,
      );
      _lastNavMotionPrediction = null;
      _startNavMotionTimerIfNeeded();
      _logNavBounded(
        'NAV_ENGINE_OUT',
        'source=${output.markerSource} animate=${output.shouldAnimateMarker} '
            'bearing=${output.bearing.toStringAsFixed(1)} '
            'bearingSource=${_driverNavEngine.lastBearingSource} '
            'speedKmh=${output.speedKmh?.toStringAsFixed(1) ?? 'na'} '
            'accuracyM=${output.accuracyM?.toStringAsFixed(1) ?? 'na'} '
            'cameraReason=${output.cameraReason}',
        intervalMs: 2000,
      );
      _logNavBounded(
        'NAV_OS_R2_BEARING',
        'source=${_r2BearingSourceLabel(_driverNavEngine.lastBearingSource)} '
            'delta=${_lastR2BearingDeltaDeg?.toStringAsFixed(1) ?? 'na'} '
            'reversedGuard=$_lastR2ReversedGuard',
        intervalMs: 2000,
      );
      _logNavR11Bearing(
        source: _navR11SourceFromEngine(_driverNavEngine.lastBearingSource),
        speedKmh: output.speedKmh ?? 0.0,
        accuracyM: output.accuracyM,
        confidence:
            _lastNavRouteProgress?.confidence ?? _lastNavConfidence?.routeScore,
        deltaDeg: priorOutput != null
            ? NavBearingSmoother.bearingDelta(
                priorOutput.bearing,
                output.bearing,
              )
            : null,
        appliedDeg: output.bearing,
        reason: _driverNavEngine.lastBearingReason,
        headingDeltaDeg: _lastNavRouteProgress?.headingDeltaDeg,
        routeDeviationLikely:
            _lastNavRouteProgress?.routeDeviationLikely ?? false,
        oppositeDirectionLikely:
            _lastNavRouteProgress?.oppositeDirectionLikely ?? false,
        backwardProgressLikely:
            _lastNavRouteProgress?.backwardProgressLikely ?? false,
        offRouteLikely:
            _lastNavRouteProgress?.offRouteLikely ?? _offRouteLikely,
        routeBearingAllowed: _driverNavEngine.lastRouteBearingAllowed,
      );
      unawaited(
        NavDiagnosticsRecorder.instance.recordNavEngineEvent(
          tag: 'NAV_ENGINE_OUT',
          fields: <String, dynamic>{
            'source': output.markerSource,
            'animate': output.shouldAnimateMarker,
            'bearing': output.bearing.round(),
            'bearingSource': _driverNavEngine.lastBearingSource,
            'speedKmh': output.speedKmh?.round(),
            'accuracyM': output.accuracyM?.round(),
            'cameraReason': output.cameraReason,
          },
        ),
      );
    } catch (_) {
      _driverNavEngine.reset();
      _lastNavEngineOutput = null;
      _resetNavR3MotionState();
    }
  }

  void _logNavR3Motion({
    required String state,
    required int durationMs,
    required double progress,
    required bool animate,
  }) {
    _logNavBounded(
      'NAV_R3_MOTION',
      'state=$state durationMs=$durationMs '
          'progress=${progress.toStringAsFixed(2)} animate=$animate',
      intervalMs: state == 'tick' ? 1200 : 1,
    );
  }

  void _stopNavR3MotionTimer() {
    _navR3MotionTimer?.cancel();
    _navR3MotionTimer = null;
  }

  void _resetNavR3MotionState() {
    _stopNavR3MotionTimer();
    if (_navR3MotionActive || _navR3VisualLat != null) {
      _logNavR3Motion(
        state: 'reset',
        durationMs: 0,
        progress: 0.0,
        animate: false,
      );
    }
    _navR3MotionActive = false;
    _navR3VisualLat = null;
    _navR3VisualLon = null;
    _navR3VisualBearing = 0.0;
    _navR3AnimStartedAt = null;
    _navR3AnimDuration = const Duration(milliseconds: 1000);
    _lastNavMotionPrediction = null;
    // NAV-STREETLEVEL-REALTIME-FOLLOW-PIPELINE-1: producer stopped -> stop the
    // camera follow consumer so it never runs from a dead pose stream.
    _stopStreetlevelFollowPump();
  }

  bool _isWeakGpsForPrediction(geo.Position? pos) {
    if (pos == null) return true;
    if (!_isGpsQualityAcceptableForCamera(pos)) return true;
    final accuracy = pos.accuracy;
    return accuracy.isFinite && accuracy > 28.0;
  }

  NavMotionPredictionInput _buildNavMotionPredictionInput() {
    final output = _lastNavEngineOutput!;
    final confidence = _lastNavConfidence;
    final progress = _lastNavRouteProgress;
    final pos = _lastPos;
    final trustRouteSnap = confidence?.trustRouteSnap ?? false;
    final trustBearing = confidence?.trustBearing ?? false;
    return NavMotionPredictionInput(
      timestamp: DateTime.now(),
      lastDisplayLatitude: _navR3VisualLat ?? output.displayLatitude,
      lastDisplayLongitude: _navR3VisualLon ?? output.displayLongitude,
      lastReliableLatitude: trustRouteSnap
          ? (progress?.snappedLatitude ?? output.displayLatitude)
          : null,
      lastReliableLongitude: trustRouteSnap
          ? (progress?.snappedLongitude ?? output.displayLongitude)
          : null,
      bearing: _navR3VisualBearing,
      speedKmh: output.speedKmh ?? (pos != null ? _speedKmhFor(pos) : null),
      routeBearing:
          _routeBearingFromProgress(progress) ??
          _routeBearingAtSnap(_lastRouteSnap),
      trustRouteSnap: trustRouteSnap,
      trustBearing: trustBearing,
      offRouteLikely: progress?.offRouteLikely ?? _offRouteLikely,
      gpsAccuracyM:
          output.accuracyM ??
          (pos != null && pos.accuracy.isFinite && pos.accuracy > 0
              ? pos.accuracy
              : null),
      liveRideActive: _liveRideActive,
      gapSinceLastEngineMs: _gapSinceLastNavEngineMs(),
      weakGps: _isWeakGpsForPrediction(pos),
    );
  }

  NavMotionPredictionOutput? _updateNavMotionPrediction() {
    if (!_isActiveDriverNavEngineContext() || _lastNavEngineOutput == null) {
      _lastNavMotionPrediction = null;
      return null;
    }
    try {
      final result = _driverNavMotionPrediction.update(
        _buildNavMotionPredictionInput(),
      );
      // NAV-R10 (Part G): count each distinct gap_exceeded episode once, with
      // the gap duration, so validation scoring can penalise stalled sessions.
      if (result.reason == 'gap_exceeded' &&
          _lastNavPredictionReason != 'gap_exceeded') {
        _driverNavValidationEngine.notePredictionGapExceeded(
          _gapSinceLastNavEngineMs(),
        );
      }
      _lastNavPredictionReason = result.reason;
      _lastNavMotionPrediction = result;
      _logNavBounded(
        'NAV_R7_PREDICTION',
        'active=${result.predictionActive} '
            'durationMs=${_gapSinceLastNavEngineMs()} '
            'confidence=${result.confidence.round()} '
            'reason=${result.reason}',
        intervalMs: 1200,
      );
      unawaited(
        NavDiagnosticsRecorder.instance.recordNavEngineEvent(
          tag: 'NAV_R7_PREDICTION',
          fields: <String, dynamic>{
            'active': result.predictionActive,
            'durationMs': _gapSinceLastNavEngineMs(),
            'confidence': result.confidence.round(),
            'reason': result.reason,
          },
        ),
      );
      return result;
    } catch (_) {
      _lastNavMotionPrediction = null;
      return null;
    }
  }

  void _startNavMotionTimerIfNeeded() {
    if (!_isActiveDriverNavEngineContext()) return;
    if (_navR3MotionTimer != null) return;
    // NAV-STREETLEVEL-FLUID-MOTION-1: produce the visual pose at frame cadence
    // (~60 fps) so forward motion is reconstructed between GPS fixes rather
    // than stepping at raw GPS cadence. The R3 interpolation + prediction are
    // time-based, so a faster tick yields smoother motion, not faster motion.
    _navR3MotionTimer = Timer.periodic(
      const Duration(milliseconds: kNavStreetlevelFrameTickMs),
      (_) {
        _navR3MotionTick();
      },
    );
  }

  ({double lat, double lon, double bearing})? _navR3CaptureVisual(
    NavEngineOutput? priorOutput,
  ) {
    if (_navR3VisualLat != null && _navR3VisualLon != null) {
      return (
        lat: _navR3VisualLat!,
        lon: _navR3VisualLon!,
        bearing: _navR3VisualBearing,
      );
    }
    if (priorOutput != null) {
      return (
        lat: priorOutput.displayLatitude,
        lon: priorOutput.displayLongitude,
        bearing: priorOutput.bearing,
      );
    }
    return null;
  }

  Duration _navR3DurationFor(
    NavEngineOutput output,
    NavEngineOutput? priorOutput,
  ) {
    var intervalMs = 800;
    if (priorOutput != null) {
      intervalMs = output.timestamp
          .difference(priorOutput.timestamp)
          .inMilliseconds;
    }
    intervalMs = intervalMs.clamp(280, 3200);
    final intervalT = (intervalMs - 280) / 2920.0;
    var durationMs = (360 + intervalT * 420).round();
    final speed = output.speedKmh ?? 0.0;
    if (speed > 50) {
      durationMs -= 180;
    } else if (speed > 35) {
      durationMs -= 130;
    } else if (speed > 20) {
      durationMs -= 70;
    }
    if (speed < 8) durationMs += 90;
    return Duration(milliseconds: durationMs.clamp(320, 820));
  }

  static double _shortestBearingDelta(double from, double to) {
    var delta = (to - from) % 360.0;
    if (delta > 180.0) delta -= 360.0;
    if (delta < -180.0) delta += 360.0;
    return delta;
  }

  static double _lerpBearingShortest(double from, double to, double t) {
    final delta = _shortestBearingDelta(from, to);
    var bearing = from + delta * t;
    bearing %= 360.0;
    if (bearing < 0) bearing += 360.0;
    return bearing;
  }

  void _applyNavEngineMotionTarget(
    NavEngineOutput output, {
    required ({double lat, double lon, double bearing})? fromVisual,
    required NavEngineOutput? priorOutput,
  }) {
    if (!_isActiveDriverNavEngineContext()) {
      _resetNavR3MotionState();
      return;
    }

    final toLat = output.displayLatitude;
    final toLon = output.displayLongitude;
    final speed = output.speedKmh ?? 0.0;
    final fromLat = fromVisual?.lat ?? toLat;
    final fromLon = fromVisual?.lon ?? toLon;
    final fromBearing = fromVisual?.bearing ?? output.bearing;
    final toBearing = speed < 3.0 ? fromBearing : output.bearing;

    // NAV-STREETLEVEL-FLUID-MOTION-1: engine-anchor cadence (interval between
    // successive engine outputs feeding the visual pose).
    if (priorOutput != null) {
      final anchorDtMs = output.timestamp
          .difference(priorOutput.timestamp)
          .inMilliseconds;
      if (anchorDtMs > 0) _navAnchorCadence.add(anchorDtMs.toDouble());
    }

    // NAV-STREETLEVEL-FLUID-MOTION-1: distance between the currently displayed
    // pose and the fresh anchor decides the correction blend. An irreconcilable
    // jump (e.g. GPS teleport / snap to a far road) hard-resets instead of
    // smearing the vehicle across the map for a full blend window.
    final correctionM = _metersBetween(
      _LonLat(fromLon, fromLat),
      _LonLat(toLon, toLat),
    );
    if (output.shouldAnimateMarker &&
        NavStreetlevelCorrectionPolicy.requiresHardReset(correctionM)) {
      _navR3VisualLat = toLat;
      _navR3VisualLon = toLon;
      _navR3VisualBearing = toBearing;
      _navR3MotionActive = false;
      _navR3AnimStartedAt = null;
      _stopNavR3MotionTimer();
      _logNavR3Motion(
        state: 'hard_reset',
        durationMs: 0,
        progress: 1.0,
        animate: false,
      );
      _startNavMotionTimerIfNeeded();
      return;
    }

    if (output.shouldAnimateMarker && priorOutput != null) {
      final intervalMs = output.timestamp
          .difference(priorOutput.timestamp)
          .inMilliseconds;
      if (intervalMs < 480 && speed > 28) {
        _navR3VisualLat = toLat;
        _navR3VisualLon = toLon;
        _navR3VisualBearing = toBearing;
        _navR3MotionActive = false;
        _navR3AnimStartedAt = null;
        _stopNavR3MotionTimer();
        _logNavR3Motion(
          state: 'fast_snap',
          durationMs: 0,
          progress: 1.0,
          animate: false,
        );
        _startNavMotionTimerIfNeeded();
        return;
      }
    }

    if (!output.shouldAnimateMarker) {
      _navR3VisualLat = toLat;
      _navR3VisualLon = toLon;
      _navR3VisualBearing = toBearing;
      _navR3MotionActive = false;
      _navR3AnimStartedAt = null;
      _stopNavR3MotionTimer();
      _logNavR3Motion(
        state: 'jump',
        durationMs: 0,
        progress: 1.0,
        animate: false,
      );
      _startNavMotionTimerIfNeeded();
      return;
    }

    _navR3FromLat = fromLat;
    _navR3FromLon = fromLon;
    _navR3ToLat = toLat;
    _navR3ToLon = toLon;
    _navR3FromBearing = fromBearing;
    _navR3ToBearing = toBearing;
    _navR3VisualLat = fromLat;
    _navR3VisualLon = fromLon;
    _navR3VisualBearing = fromBearing;
    _navR3AnimStartedAt = DateTime.now();
    // NAV-STREETLEVEL-FLUID-MOTION-1: bound the correction blend to spec —
    // normal (<=15 m) corrections resolve within ~250–500 ms, large/off-route
    // ones use a bounded recovery window — so the vehicle never stays visibly
    // on the wrong road through a long slow smear. At typical GPS cadence the
    // interval-derived base duration is already below these caps.
    final baseDuration = _navR3DurationFor(output, priorOutput);
    final correctionCapMs = NavStreetlevelCorrectionPolicy.maxBlendMsFor(
      correctionM,
    );
    _navR3AnimDuration = baseDuration.inMilliseconds > correctionCapMs
        ? Duration(milliseconds: correctionCapMs)
        : baseDuration;
    _navR3MotionActive = true;
    _logNavR3Motion(
      state: 'start',
      durationMs: _navR3AnimDuration.inMilliseconds,
      progress: 0.0,
      animate: true,
    );
    _startNavMotionTimerIfNeeded();
  }

  void _startNavR3MotionTimer() {
    _startNavMotionTimerIfNeeded();
  }

  double _navR3MotionProgress() {
    final startedAt = _navR3AnimStartedAt;
    if (!_navR3MotionActive || startedAt == null) return 1.0;
    final durationMs = _navR3AnimDuration.inMilliseconds;
    if (durationMs <= 0) return 1.0;
    final elapsedMs = DateTime.now().difference(startedAt).inMilliseconds;
    return (elapsedMs / durationMs).clamp(0.0, 1.0);
  }

  ({double lat, double lon, double bearing}) _navR3InterpolatedVisual(
    NavEngineOutput output,
  ) {
    if (!_navR3MotionActive) {
      if (_navR3VisualLat != null && _navR3VisualLon != null) {
        return (
          lat: _navR3VisualLat!,
          lon: _navR3VisualLon!,
          bearing: _navR3VisualBearing,
        );
      }
      return (
        lat: output.displayLatitude,
        lon: output.displayLongitude,
        bearing: output.bearing,
      );
    }

    final progress = _navR3MotionProgress();
    final t = progress;
    final lat = _navR3FromLat + (_navR3ToLat - _navR3FromLat) * t;
    final lon = _navR3FromLon + (_navR3ToLon - _navR3FromLon) * t;
    final speed = output.speedKmh ?? 0.0;
    final bearing = speed < 3.0
        ? _navR3FromBearing
        : _lerpBearingShortest(_navR3FromBearing, _navR3ToBearing, t);
    return (lat: lat, lon: lon, bearing: bearing);
  }

  void _navR3MotionTick() {
    if (!mounted) {
      _resetNavR3MotionState();
      _resetNavMotionPredictionState();
      return;
    }
    if (!_isActiveDriverNavEngineContext() ||
        _map == null ||
        _mapStyleChanging ||
        _driverPointManager == null ||
        _driverMarker == null) {
      _resetNavR3MotionState();
      _resetNavMotionPredictionState();
      return;
    }

    final output = _lastNavEngineOutput;
    if (output == null) {
      _resetNavR3MotionState();
      _resetNavMotionPredictionState();
      return;
    }

    if (_navR3MotionActive) {
      final progress = _navR3MotionProgress();
      final visual = _navR3InterpolatedVisual(output);
      _navR3VisualLat = visual.lat;
      _navR3VisualLon = visual.lon;
      _navR3VisualBearing = visual.bearing;
      _logNavR3Motion(
        state: 'tick',
        durationMs: _navR3AnimDuration.inMilliseconds,
        progress: progress,
        animate: true,
      );
      unawaited(
        _applyDriverMarkerVisualOnly(visual.lat, visual.lon, visual.bearing),
      );
      if (progress < 1.0) return;

      _navR3VisualLat = _navR3ToLat;
      _navR3VisualLon = _navR3ToLon;
      _navR3VisualBearing = _navR3ToBearing;
      _navR3MotionActive = false;
      _navR3AnimStartedAt = null;
    }

    final prediction = _updateNavMotionPrediction();
    if (prediction?.predictionActive == true) {
      _navR3VisualLat = prediction!.predictedLatitude;
      _navR3VisualLon = prediction.predictedLongitude;
      _navR3VisualBearing = prediction.predictedBearing;
      unawaited(
        _applyDriverMarkerVisualOnly(
          prediction.predictedLatitude,
          prediction.predictedLongitude,
          prediction.predictedBearing,
        ),
      );
      return;
    }

    _lastNavMotionPrediction = null;
    final gapMs = _gapSinceLastNavEngineMs();
    final weakGps = _isWeakGpsForPrediction(_lastPos);
    if (gapMs < 450 && !weakGps) {
      _stopNavR3MotionTimer();
    }
  }

  Future<void> _applyDriverMarkerVisualOnly(
    double lat,
    double lon,
    double bearing, {
    String source = 'route_snap',
  }) async {
    // NAV-STREETLEVEL-REALTIME-FOLLOW-PIPELINE-1: the marker visual is the
    // authoritative live pose producer. Publish it (gated to streetlevel
    // follow) so the bounded camera pump consumes the same pose generation.
    _publishStreetlevelFollowPose(lat, lon, bearing);
    if (!_canUpdateDriverMarker) return;
    final mgr = _driverPointManager;
    final marker = _driverMarker;
    if (mgr == null || marker == null) return;
    // NAV-STREETLEVEL-FLUID-MOTION-1: at frame cadence (~60 fps) the native
    // marker update must not back up. Coalesce: skip while a previous update is
    // still in flight — the next free frame applies the newest lat/lon, so the
    // marker never trails the camera by more than a frame and never queues.
    if (_driverMarkerVisualUpdateInFlight) return;
    // NAV-ANNOTATION-MANAGER-TRANSACTIONAL-LIFECYCLE-2: even the 60 fps visual
    // update must hold a lease — a draining/disposed generation rejects it so
    // the native update never reaches a removed manager.
    if (!_driverAnnotationGate.tryAcquireLease(
      _driverAnnotationGate.capture(),
      NavAnnotationOperationKind.update,
    )) {
      return;
    }
    _driverMarkerVisualUpdateInFlight = true;
    final p = _mbPoint(lon, lat);
    marker.geometry = p;
    // NAV-TELLERS-STREETLEVEL-SCREEN-UP-MARKER-1: in Tellers Streetlevel
    // (Mapbox-owner + streetlevel view) the marker is viewport-fixed and
    // its iconRotate is forced to 0 — the pose bearing rotates the map
    // underneath, never the marker itself. Outside that case the
    // authoritative pose bearing passes through unchanged.
    marker.iconRotate =
        _currentDriverMarkerRotationPolicy().iconRotateFor(bearing);
    // NAV-3D-MAPBOX-2D-MARKER-ISOLATION-FIX-1: rebase opacity from the
    // authoritative resolver every visual update so route_snap paths
    // never re-push a stale 1.0 during active 3D isolation.
    marker.iconOpacity = _resolveDesiredMapboxTaxiOpacity(
      source: 'visual_sync',
    );
    try {
      await mgr.update(marker);
    } catch (e) {
      if (_isMapboxAnnotationManagerLost(e)) {
        _resetDriverMarkerOnNativeError('visual_only_update');
      }
    } finally {
      _driverAnnotationGate.releaseLease();
      _driverMarkerVisualUpdateInFlight = false;
    }
    unawaited(
      _syncDriverVehicleModelLayer(
        lon: lon,
        lat: lat,
        bearingDeg: bearing,
        source: source,
      ),
    );
  }

  ({_LonLat point, double bearing}) _resolveNavVisualForLiveNav(
    geo.Position pos,
    _RouteSnap? snap, {
    bool allowPrediction = true,
  }) {
    final output = _lastNavEngineOutput;
    if (output != null && _isActiveDriverNavEngineContext()) {
      if (_navR3MotionActive) {
        final visual = _navR3InterpolatedVisual(output);
        _navR3VisualLat = visual.lat;
        _navR3VisualLon = visual.lon;
        _navR3VisualBearing = visual.bearing;
        return (
          point: _LonLat(visual.lon, visual.lat),
          bearing: visual.bearing,
        );
      }
      final prediction = _lastNavMotionPrediction;
      if (allowPrediction &&
          prediction != null &&
          prediction.predictionActive) {
        _navR3VisualLat = prediction.predictedLatitude;
        _navR3VisualLon = prediction.predictedLongitude;
        _navR3VisualBearing = prediction.predictedBearing;
        return (
          point: _LonLat(
            prediction.predictedLongitude,
            prediction.predictedLatitude,
          ),
          bearing: prediction.predictedBearing,
        );
      }
      final visual = _navR3InterpolatedVisual(output);
      _navR3VisualLat = visual.lat;
      _navR3VisualLon = visual.lon;
      _navR3VisualBearing = visual.bearing;
      return (point: _LonLat(visual.lon, visual.lat), bearing: visual.bearing);
    }
    final markerDisplay = _driverMarkerDisplayFor(pos);
    return (point: markerDisplay.point, bearing: _markerBearingFor(pos, snap));
  }

  ({_LonLat point, double bearing}) _resolveNavVisualForMarker(
    geo.Position pos,
    _RouteSnap? snap,
  ) {
    return _resolveNavVisualForLiveNav(pos, snap);
  }

  Future<bool> _ensureDriverTaxiMarkerBytes() async {
    if (_driverTaxiMarkerLoadAttempted) return _driverTaxiMarkerAvailable;
    _driverTaxiMarkerLoadAttempted = true;
    try {
      final data = await rootBundle.load(kDriverTaxiMarkerAssetPath);
      _driverTaxiMarkerBytes = data.buffer.asUint8List(
        data.offsetInBytes,
        data.lengthInBytes,
      );
      _driverTaxiMarkerAvailable = _driverTaxiMarkerBytes!.isNotEmpty;
      if (_driverTaxiMarkerAvailable) {
        debugPrint('[NAV_MARKER] taxi_asset=loaded');
      }
    } catch (_) {
      _driverTaxiMarkerAvailable = false;
      _driverTaxiMarkerBytes = null;
      debugPrint('[NAV_MARKER] taxi_asset=missing');
    }
    return _driverTaxiMarkerAvailable;
  }

  /// NAV-TELLERS-MARKER-CHOICE-APPLY-1: lazily rasterise the Arrow glyph into
  /// PNG bytes (cached). Rendered at the taxi asset's native resolution so the
  /// same Mapbox iconSize keeps the Car/Arrow on-screen footprint identical.
  Future<Uint8List?> _ensureDriverArrowMarkerBytes() async {
    if (_driverArrowMarkerLoadAttempted) return _driverArrowMarkerBytes;
    _driverArrowMarkerLoadAttempted = true;
    try {
      _driverArrowMarkerBytes =
          await renderNavigationDriverArrowMarkerPngBytes();
      if (_driverArrowMarkerBytes != null &&
          _driverArrowMarkerBytes!.isNotEmpty) {
        debugPrint('[NAV_MARKER] arrow_asset=rendered');
      } else {
        _driverArrowMarkerBytes = null;
        debugPrint('[NAV_MARKER] arrow_asset=empty');
      }
    } catch (_) {
      _driverArrowMarkerBytes = null;
      debugPrint('[NAV_MARKER] arrow_asset=failed');
    }
    return _driverArrowMarkerBytes;
  }

  /// NAV-TELLERS-MARKER-CHOICE-APPLY-1: resolve the image bytes for the CURRENT
  /// [_driverNavigationMarkerChoice]. Arrow → rasterised arrow glyph; Car (or
  /// any Arrow rasterisation failure) → taxi PNG. Distinct byte sources mean
  /// Car and Arrow never share a stale cached icon.
  Future<({Uint8List? bytes, bool isArrow})>
      _resolveDriverMarkerImageBytesForChoice() async {
    if (_driverNavigationMarkerChoice == DriverNavigationMarkerChoice.arrow) {
      final arrow = await _ensureDriverArrowMarkerBytes();
      final arrowAvailable = arrow != null && arrow.isNotEmpty;
      final source = driverNavigationMarkerIconSourceFor(
        _driverNavigationMarkerChoice,
        arrowAvailable: arrowAvailable,
      );
      if (source == DriverNavigationMarkerIconSource.arrowGlyph) {
        return (bytes: arrow, isArrow: true);
      }
    }
    final taxiReady = await _ensureDriverTaxiMarkerBytes();
    return (
      bytes: taxiReady ? _driverTaxiMarkerBytes : null,
      isArrow: false,
    );
  }

  /// NAV-TELLERS-MARKER-CHOICE-APPLY-1: immediately apply the selected marker
  /// choice to the EXISTING single Mapbox annotation. Mapbox cannot safely swap
  /// an annotation's bitmap image in place, so — mirroring the existing asset-
  /// swap path — this deletes the one annotation and creates exactly one
  /// replacement under the same annotation lifecycle gate, preserving pose,
  /// bearing, size and opacity. If there is no live annotation yet, or the gate
  /// is busy, the next [_updateDriverMarker] reconciles via the applied-choice
  /// mismatch. Never creates a second annotation or a Flutter overlay.
  Future<void> _applyDriverMarkerChoiceToAnnotation() async {
    final mgr = _driverPointManager;
    final marker = _driverMarker;
    // NAV-RELEASE-FINAL-FLOW-1: if the persisted Car/Arrow has no annotation
    // yet (preview never waited for selector interaction), bootstrap it from
    // the restore path instead of silently no-oping.
    if (mgr == null || marker == null) {
      unawaited(
        _attemptTaxiMarkerRestore(
          attempt: 0,
          reason: 'marker_choice_bootstrap',
        ),
      );
      return;
    }
    if (!_canUpdateDriverMarker) return;
    if (!driverNavigationMarkerNeedsIconSwap(
      applied: _driverMarkerAppliedChoice,
      selected: _driverNavigationMarkerChoice,
    )) {
      return;
    }
    // Warm the target bytes before touching native so the recreate cannot lose
    // the marker to a slow first rasterisation.
    await _resolveDriverMarkerImageBytesForChoice();
    if (_driverPointManager != mgr || _driverMarker != marker) return;
    final geometry = marker.geometry;
    final bearing = marker.iconRotate ?? 0.0;
    final opacity = _resolveDesiredMapboxTaxiOpacity(source: 'marker_choice');
    if (!_driverAnnotationGate.tryAcquireLease(
      _driverAnnotationGate.capture(),
      NavAnnotationOperationKind.update,
    )) {
      return;
    }
    try {
      try {
        await mgr.deleteAll();
      } catch (e) {
        if (_isMapboxAnnotationManagerLost(e)) {
          _resetDriverMarkerOnNativeError('marker_choice_delete');
          return;
        }
      }
      _driverMarker = null;
      try {
        _driverMarker = await _createDriverMarkerAnnotation(
          mgr: mgr,
          geometry: geometry,
          markerBearing: bearing,
          iconOpacity: opacity,
        );
      } catch (e) {
        _noteMarkerUpdateFailure('marker_choice_recreate', e);
      }
    } finally {
      _driverAnnotationGate.releaseLease();
    }
    await _syncDriverMarkerIconSizeForZoom();
  }

  double _markerBearingFor(geo.Position pos, _RouteSnap? snap) {
    final speedKmh = _speedKmhFor(pos);
    final meta = _adaptiveBearingFor(pos, snap: snap);
    final confidence = _lastNavConfidence;
    var bearingWeight = 1.0;
    if (confidence != null) {
      bearingWeight = confidence.trustBearing ? 0.9 : 0.45;
      if (_lastNavRouteProgress?.offRouteLikely ?? _offRouteLikely) {
        bearingWeight *= 0.35;
      } else if (confidence.routeScore < 55.0) {
        bearingWeight *= 0.65;
      }
    }
    return _smoothFollowCameraBearing(
      meta.bearing,
      speedKmh,
      bearingModeWeight: bearingWeight,
    );
  }

  Future<mb.PointAnnotation?> _createDriverMarkerAnnotation({
    required mb.PointAnnotationManager mgr,
    required mb.Point geometry,
    required double markerBearing,
    double iconOpacity = 1.0,
  }) async {
    // NAV-TELLERS-MARKER-CHOICE-APPLY-1: the single Mapbox annotation renders
    // the selected Car (taxi PNG) or Arrow (rasterised glyph) bitmap. Both are
    // zoom-scaled with the same taxi iconSize calibration so switching never
    // changes marker size, and _driverMarkerAppliedChoice records the live
    // choice for idempotent selector re-application.
    //
    // NAV-TELLERS-STREETLEVEL-SCREEN-UP-MARKER-1: creation-time iconRotate is
    // routed through the current policy — in Tellers Streetlevel this snaps
    // to 0 so the freshly created Car/Arrow is born upright and the
    // map/route rotate underneath. Outside that case the pose bearing is
    // preserved unchanged.
    final policy = _currentDriverMarkerRotationPolicy();
    final effectiveIconRotate = policy.iconRotateFor(markerBearing);
    final resolved = await _resolveDriverMarkerImageBytesForChoice();
    final imageBytes = resolved.bytes;
    if (imageBytes != null && imageBytes.isNotEmpty) {
      try {
        final marker = await mgr.create(
          mb.PointAnnotationOptions(
            geometry: geometry,
            image: imageBytes,
            iconAnchor: mb.IconAnchor.CENTER,
            iconSize: _driverTaxiIconSizeForCurrentZoom(),
            iconRotate: effectiveIconRotate,
            iconOpacity: iconOpacity,
          ),
        );
        _driverMarkerUsesTaxiAsset = true;
        _driverMarkerIcon =
            resolved.isArrow ? 'fluxidi-driver-arrow' : 'fluxidi-driver-taxi';
        _driverMarkerAppliedChoice = _driverNavigationMarkerChoice;
        debugPrint('[NAV_MARKER] mode=${resolved.isArrow ? 'arrow' : 'taxi'}');
        return marker;
      } catch (_) {
        debugPrint('[NAV_MARKER] mode=custom_fallback_triangle');
      }
    }

    _driverMarkerUsesTaxiAsset = false;
    _driverMarkerAppliedChoice = _driverNavigationMarkerChoice;
    try {
      _driverMarkerIcon = 'triangle-15';
      return await mgr.create(
        mb.PointAnnotationOptions(
          geometry: geometry,
          iconImage: _driverMarkerIcon,
          iconColor: 0xFFFFD21F,
          iconSize: driverFallbackMarkerIconSizeForZoom(_lastMapCameraZoom),
          iconRotate: effectiveIconRotate,
          iconOpacity: iconOpacity,
        ),
      );
    } catch (_) {
      _driverMarkerIcon = 'marker-15';
      return await mgr.create(
        mb.PointAnnotationOptions(
          geometry: geometry,
          iconImage: _driverMarkerIcon,
          iconColor: 0xFFFFD21F,
          iconSize: driverFallbackMarkerIconSizeForZoom(_lastMapCameraZoom),
          iconRotate: effectiveIconRotate,
          iconOpacity: iconOpacity,
        ),
      );
    }
  }

  /// Returns true when the native marker create/update was applied.
  Future<bool> _updateDriverMarker(
    geo.Position pos, {
    bool moveCamera = false,
  }) async {
    if (!_canUpdateDriverMarker) {
      _logNavR12Marker(event: 'skipped_not_ready');
      return false;
    }
    final mgr = _driverPointManager;
    if (mgr == null) return false;

    final snap =
        _lastRouteSnap ?? _snapToRoute(_LonLat(pos.longitude, pos.latitude));
    _refreshNavEngineForPosition(pos);
    final visual = _resolveNavVisualForMarker(pos, snap);
    if (_lastNavEngineOutput == null) {
      final markerDisplay = _driverMarkerDisplayFor(pos);
      _logNavBounded(
        'NAV_MARKER',
        'source=${markerDisplay.source} snapDistM=${markerDisplay.snapDistM?.round() ?? -1}',
      );
    }
    // NAV-TELLERS-SINGLE-MAP-MARKER-OWNER-1: in Tellers the ONE Mapbox
    // annotation is the visible vehicle marker AND the same authoritative
    // pose (matched snap when reliable — see NAV-TELLERS-ROUTE-CENTERLINE-
    // LOCK-1) the follow camera projects at the Tellers marker anchor. Pin
    // the annotation geometry to that pose so the single marker stays on
    // the polyline centreline. Ordinary Navigation keeps the existing visual
    // (prediction/interpolation/raw) — unchanged.
    var markerLat = visual.point.lat;
    var markerLon = visual.point.lon;
    if (_navPresentationMode.isTellers) {
      final progress = _lastNavRouteProgress;
      final confidence = _lastNavConfidence;
      final tellersPose = resolveTellersAuthoritativePose(
        TellersAuthoritativePoseInput(
          visualLat: visual.point.lat,
          visualLon: visual.point.lon,
          snappedLat: progress?.snappedLatitude,
          snappedLon: progress?.snappedLongitude,
          hasReliableMatchedSnap: _routeProgressMatchedVisual(progress),
          trustRouteSnap: confidence?.trustRouteSnap ?? true,
          offRouteLikely: progress?.offRouteLikely ?? _offRouteLikely,
        ),
      );
      markerLat = tellersPose.lat;
      markerLon = tellersPose.lon;
    }
    final p = _mbPoint(markerLon, markerLat);
    final markerBearing = visual.bearing;
    // Fresh GPS-driven visual supersedes any pre-style-swap snapshot.
    _taxiVisualSnapshotForStyleSwap = null;
    final taxiReady = await _ensureDriverTaxiMarkerBytes();
    if (!_canUpdateDriverMarker || _driverPointManager != mgr) return false;
    final wantsTaxi = taxiReady && _driverTaxiMarkerBytes != null;
    // NAV-TELLERS-MARKER-CHOICE-APPLY-1: a genuine Car/Arrow change means the
    // live annotation renders the wrong bitmap; force one delete+recreate
    // (Mapbox cannot swap an annotation image in place) so the next GPS fix
    // reconciles even if the immediate selector apply lost the gate race.
    final markerChoiceChanged = driverNavigationMarkerNeedsIconSwap(
      applied: _driverMarkerAppliedChoice,
      selected: _driverNavigationMarkerChoice,
    );

    // NAV-ANNOTATION-MANAGER-TRANSACTIONAL-LIFECYCLE-2: hold a lease for the
    // whole delete/deleteAll/create/update sequence. A draining/disposed
    // driver generation rejects the lease (no native op crosses the boundary);
    // while held, disposal awaits before removeAnnotationManager.
    if (!_driverAnnotationGate.tryAcquireLease(
      _driverAnnotationGate.capture(),
      NavAnnotationOperationKind.update,
    )) {
      _logNavAnnotationManager(
        gate: _driverAnnotationGate,
        event: 'stale_operation_rejected',
        operation: NavAnnotationOperationKind.update,
        reason: _driverAnnotationGate
            .allow(
              _driverAnnotationGate.capture(),
              NavAnnotationOperationKind.update,
            )
            .reason,
      );
      return false;
    }
    try {
      if (_driverMarker != null &&
          (_driverMarkerUsesTaxiAsset != wantsTaxi || markerChoiceChanged)) {
        try {
          await mgr.delete(_driverMarker!);
        } catch (e) {
          if (_isMapboxAnnotationManagerLost(e)) {
            _resetDriverMarkerOnNativeError('delete_for_asset_swap');
            return false;
          }
        }
        _driverMarker = null;
      }

      if (_driverMarker == null) {
        try {
          await mgr.deleteAll();
        } catch (e) {
          if (_isMapboxAnnotationManagerLost(e)) {
            _resetDriverMarkerOnNativeError('delete_all_before_create');
            return false;
          }
        }
        try {
          // NAV-3D-MAPBOX-2D-MARKER-ISOLATION-FIX-1: creation-time opacity
          // is snapped from the authoritative resolver — never default 1.0.
          final createOpacity = _resolveDesiredMapboxTaxiOpacity(
            source: 'create',
          );
          _driverMarker = await _createDriverMarkerAnnotation(
            mgr: mgr,
            geometry: p,
            markerBearing: markerBearing,
            iconOpacity: createOpacity,
          );
          if (_driverMarker != null) {
            logNav3dMapbox2d(
              event: 'create',
              presentation3dIntent:
                  createOpacity == 0.0 &&
                  !_vehicleModelSyncLifecycle.sessionFallback2d,
              explicit2dFallback: _vehicleModelSyncLifecycle.sessionFallback2d,
              desiredOpacity: createOpacity,
              pendingOpacity: _pendingMapboxTaxiMarkerOpacity,
              markerExists: true,
              appliedOpacity: createOpacity,
              source: 'create',
            );
          }
        } catch (e) {
          _noteMarkerUpdateFailure('create_marker', e);
          return false;
        }
      } else {
        try {
          // NAV-3D-MAPBOX-2D-MARKER-ISOLATION-FIX-1: geometry updates must
          // never re-push a stale Dart-side iconOpacity to native — always
          // rebase opacity on the authoritative pending desired value first.
          // NAV-TELLERS-STREETLEVEL-SCREEN-UP-MARKER-1: in Tellers
          // Streetlevel iconRotate is snapped to 0; the map/route rotate
          // underneath so the Car/Arrow nose stays at physical screen top.
          _driverMarker!.geometry = p;
          _driverMarker!.iconRotate = _currentDriverMarkerRotationPolicy()
              .iconRotateFor(markerBearing);
          _driverMarker!.iconOpacity = _resolveDesiredMapboxTaxiOpacity(
            source: 'visual_sync',
          );
          await mgr.update(_driverMarker!);
        } catch (e) {
          _noteMarkerUpdateFailure('update_marker', e);
          return false;
        }
      }
    } finally {
      _driverAnnotationGate.releaseLease();
    }
    _consecutiveMarkerUpdateFailures = 0;
    // NAV-R12-D: icon-size/puck sync are non-critical extra native round
    // trips — throttle them off the per-fix hot path.
    final auxNow = DateTime.now();
    if (_lastMarkerAuxSyncAt == null ||
        auxNow.difference(_lastMarkerAuxSyncAt!).inMilliseconds >= 1500) {
      _lastMarkerAuxSyncAt = auxNow;
      await _syncDriverMarkerIconSizeForZoom();
      await _syncMapboxUserLocationPuckVisibility();
    }

    final markerDisplay = _driverMarkerDisplayFor(pos);
    final markerNow = DateTime.now();
    final markerLagMs = _lastNavDiagMarkerAt == null
        ? null
        : markerNow.difference(_lastNavDiagMarkerAt!).inMilliseconds;
    _lastNavDiagMarkerAt = markerNow;
    if (markerLagMs != null && _isActiveDriverNavEngineContext()) {
      _driverNavValidationEngine.noteMarkerLagMs(markerLagMs);
    }
    final String bearingSource;
    final double? bearingDeltaDeg;
    if (_isActiveDriverNavEngineContext() && _lastNavEngineOutput != null) {
      bearingSource = _driverNavEngine.lastBearingSource;
      bearingDeltaDeg = pos.heading.isFinite && pos.heading >= 0
          ? NavBearingSmoother.bearingDelta(pos.heading, markerBearing)
          : null;
    } else {
      final meta = _adaptiveBearingFor(pos, snap: snap);
      bearingSource = meta.source;
      bearingDeltaDeg = meta.bearingDeltaDeg;
    }
    unawaited(
      NavDiagnosticsRecorder.instance.recordMarkerUpdate(
        source: markerDisplay.source,
        snapDistM: markerDisplay.snapDistM,
        bearing: markerBearing,
        markerLagMs: markerLagMs,
        bearingSource: bearingSource,
        bearingDeltaDeg: bearingDeltaDeg,
      ),
    );
    _logNavR12Marker(
      event: 'applied',
      markerSource: markerDisplay.source,
      markerLagMs: markerLagMs,
    );

    // NAV-TELLERS-SINGLE-MAP-MARKER-OWNER-1: bounded PII-free invariant proof.
    // Exactly one visible vehicle-marker owner. No coordinates or trip ids.
    // NAV-FIXED-HUD-PRESENTATION-1: the owner used to be hardcoded to
    // `mapbox`, so the field log could not distinguish "the HUD owns and the
    // annotation is hidden" from "the annotation is the visible marker". It
    // now reports the resolved owner and the route phase.
    final markerOwner = resolveDriverVehicleMarkerPresentationOwner(
      tellersActive: _navPresentationMode.isTellers,
      followLiveActive: _navFixedHudPresentationActive,
      showDriverHudOverlay: _navigationPresentationStateFor(
        _navCameraViewMode,
      ).showDriverHudOverlay,
    );
    _logNavBounded(
      'NAV_MARKER_OWNER',
      'mode=${_navPresentationMode.isTellers ? 'tellers' : 'navigation'} '
          'phase=${navFixedHudPhaseLabel(_navFixedHudPhase)} '
          'owner=${driverVehicleMarkerPresentationOwnerLabel(markerOwner)} '
          'visible_owner_count=1 '
          'marker=${_driverNavigationMarkerChoice == DriverNavigationMarkerChoice.arrow ? 'arrow' : 'car'}',
      intervalMs: 3000,
    );

    unawaited(
      _syncDriverVehicleModelLayer(
        lon: visual.point.lon,
        lat: visual.point.lat,
        bearingDeg: markerBearing,
        source: markerDisplay.source,
      ),
    );

    if (moveCamera && _cameraMode != _CameraMode.follow) {
      await _map?.flyTo(
        mb.CameraOptions(center: p, zoom: 13.5),
        mb.MapAnimationOptions(duration: 700),
      );
    }
    return true;
  }

  /// NAV-R12-D: marker create/update exception handling — a lost manager
  /// resets immediately; other native errors degrade after two consecutive
  /// failures (stale/detached annotation) so self-heal can recreate.
  void _noteMarkerUpdateFailure(String reason, Object e) {
    _logNavR12Marker(event: 'failed_$reason');
    if (_isMapboxAnnotationManagerLost(e)) {
      _resetDriverMarkerOnNativeError(reason);
      return;
    }
    _consecutiveMarkerUpdateFailures += 1;
    if (_consecutiveMarkerUpdateFailures >= 2) {
      _consecutiveMarkerUpdateFailures = 0;
      _resetDriverMarkerOnNativeError('${reason}_repeated');
    }
  }

  void _recordNavDiagCameraUpdate({
    required bool follow,
    String? skippedReason,
    double? zoom,
    double? tilt,
    double? bearing,
  }) {
    if (!NavDiagnosticsRecorder.instance.hasActiveSession) return;
    unawaited(
      NavDiagnosticsRecorder.instance.recordCameraUpdate(
        follow: follow,
        skippedReason: skippedReason,
        zoom: zoom,
        tilt: tilt,
        bearing: bearing,
      ),
    );
  }

  /// NAV-R12-E1: bounded, PII-safe camera decision diagnostics (no lat/lng).
  void _logNavR12Camera({
    required String animation,
    String? targetSource,
    String? skipReason,
    int? targetAgeMs,
  }) {
    final progress = _lastNavRouteProgress;
    final cameraPolicy = _lastNavCameraPolicy;
    final maneuverDistanceM =
        _navInstructionSnapshot?.distanceToManeuverMeters ?? _nextNavDistanceM;
    final signature =
        '$animation|${targetSource ?? ''}|${skipReason ?? ''}|'
        '${cameraPolicy?.zoomReason ?? ''}|'
        '${progress?.routeDeviationLikely ?? false}|'
        '${progress?.offRouteLikely ?? _offRouteLikely}';
    final changed = signature != _lastNavR12CameraSignature;
    _lastNavR12CameraSignature = signature;
    _logNavBounded(
      'NAV_R12_CAMERA',
      'cameraAnimation=$animation '
          'cameraTargetSource=${targetSource ?? 'na'} '
          'cameraSkippedReason=${skipReason ?? 'none'} '
          'zoom=${cameraPolicy?.zoom.toStringAsFixed(1) ?? 'na'} '
          'targetZoom=${cameraPolicy?.targetZoom.toStringAsFixed(1) ?? 'na'} '
          'zoomReason=${cameraPolicy?.zoomReason ?? 'na'} '
          'tilt=${cameraPolicy?.tilt.toStringAsFixed(1) ?? 'na'} '
          'speedKmh=${_lastPos != null ? _speedKmhFor(_lastPos!).toStringAsFixed(1) : 'na'} '
          'maneuverDistanceM=${maneuverDistanceM?.round() ?? -1} '
          'routeDeviationLikely=${progress?.routeDeviationLikely ?? false} '
          'oppositeDirectionLikely=${progress?.oppositeDirectionLikely ?? false} '
          'backwardProgressLikely=${progress?.backwardProgressLikely ?? false} '
          'offRouteLikely=${progress?.offRouteLikely ?? _offRouteLikely} '
          'reroutePending=$_isRerouting '
          'predictionActive=${_lastNavMotionPrediction?.predictionActive ?? false} '
          'targetAgeMs=${targetAgeMs ?? -1} '
          'followMode=${_cameraMode == _CameraMode.follow} '
          'animationInFlight=$_followCameraInFlight '
          'pendingCameraUpdate=${_pendingFollowCameraPos != null}',
      intervalMs: changed ? 1 : 2000,
    );
  }

  /// NAV-R12-E1 / NAV-CAMERA-INFLIGHT-SELF-HEAL-1: remember the newest camera
  /// target (last-wins) instead of dropping the fix when the camera is
  /// throttled or animating. Never builds an unbounded queue.
  void _queuePendingFollowCamera(
    geo.Position pos, {
    required String skipReason,
    int? retryDelayMs,
  }) {
    final replaced = _pendingFollowCameraPos != null;
    _pendingFollowCameraPos = pos;
    _cameraInFlightLifecycle.setPending(
      NavCameraCommandKind.pendingReplay,
      pos,
    );
    _logNavR12Camera(animation: 'queued_latest', skipReason: skipReason);
    if (replaced) {
      _logNavCameraInFlight(
        phase: NavCameraInFlightPhase.start,
        generation: _cameraInFlightLifecycle.currentGeneration,
        hasPending: true,
        reason: skipReason,
        commandKind: NavCameraCommandKind.pendingReplay.label,
        event: NavCameraInFlightEvent.pendingReplaced.label,
      );
    }
    if (retryDelayMs != null) {
      _armPendingFollowCameraTimer(retryDelayMs);
    }
  }

  void _armPendingFollowCameraTimer(int delayMs) {
    if (_pendingFollowCameraTimer?.isActive ?? false) return;
    _pendingFollowCameraTimer = Timer(
      Duration(milliseconds: delayMs.clamp(16, 1000)),
      () {
        _pendingFollowCameraTimer = null;
        _runPendingFollowCamera();
      },
    );
  }

  void _runPendingFollowCamera() {
    final pos = _pendingFollowCameraPos;
    _pendingFollowCameraPos = null;
    _cameraInFlightLifecycle.takePending(reportReplay: pos != null);
    if (pos == null || !mounted) return;
    // Manual pan/zoom wins: no forced recenter outside follow mode.
    if (_cameraMode != _CameraMode.follow) return;
    if (_map == null || _mapStyleChanging || _posSub == null) return;
    _logNavR12Camera(animation: 'applied_pending');
    _logNavCameraInFlight(
      phase: NavCameraInFlightPhase.start,
      generation: _cameraInFlightLifecycle.currentGeneration,
      reason: 'pending_latest',
      commandKind: NavCameraCommandKind.pendingReplay.label,
      event: NavCameraInFlightEvent.pendingReplayed.label,
    );
    unawaited(_followCameraTesla(pos, cameraReason: 'pending_latest'));
  }

  void _resetPendingFollowCamera() {
    _pendingFollowCameraTimer?.cancel();
    _pendingFollowCameraTimer = null;
    _pendingFollowCameraPos = null;
    _cameraInFlightLifecycle.clearPending();
  }

  // NAV-STREETLEVEL-REALTIME-FOLLOW-PIPELINE-1: eligibility for the bounded
  // real-time follow pump (cockpit streetlevel follow only). When eligible the
  // pump owns camera writes and the heavy per-fix flyTo is skipped.
  bool _streetlevelFollowPumpEligible() {
    // FLUXIDI Phase 2A: when native FollowPuck is active, Mapbox owns the
    // camera. The Dart pump becomes ineligible so zero passive Dart camera
    // writes reach the platform channel. Flag-off behavior is unchanged.
    if (_nativeFollowIsActive()) return false;
    if (_cameraMode != _CameraMode.follow) return false;
    if (!_liveRideActive) return false;
    if (!_isActiveDriverNavEngineContext()) return false;
    if (_map == null || _mapStyleChanging) return false;
    final navPresentation = _navigationPresentationStateFor(_navCameraViewMode);
    if (!navPresentation.useDriverCockpitCamera) return false;
    return driverCockpitStreetlevelBearingLockActive(_driverCockpitViewLevel);
  }

  /// FLUXIDI Phase 2A: single-source ownership gate. Returns `true` only when
  /// the build-time flag [kNavigationUseNativeFollowPuckEnabled] is on AND the
  /// Dart-side [NativeFollowController] has an active session (native
  /// LocationProvider installed on the exact MapView, FollowPuck owning the
  /// camera, LocationPuck3D rendering the vehicle). Every passive Dart
  /// writer defers to this gate.
  bool _nativeFollowIsActive() {
    if (!kNavigationUseNativeFollowPuckEnabled) return false;
    final controller = _nativeFollow;
    if (controller == null) return false;
    return controller.isSessionActive;
  }

  /// Forwards one authoritative pose to the native FollowPuck bridge. The
  /// controller enforces rate limiting (5-10 Hz), single-in-flight,
  /// generation guard and latest-wins coalescing. No queue is retained
  /// anywhere on the Dart side.
  void _submitPoseToNativeFollow(double lat, double lon, double bearing) {
    final controller = _nativeFollow;
    if (controller == null) return;
    final pos = _lastPos;
    final speedMps = pos?.speed ?? 0.0;
    final accuracyM = pos?.accuracy ?? 0.0;
    final nowMs = DateTime.now().millisecondsSinceEpoch;
    unawaited(
      controller.submitPose(
        latitude: lat,
        longitude: lon,
        courseDegrees: bearing,
        speedMetersPerSecond: speedMps.isFinite && speedMps > 0
            ? speedMps
            : 0.0,
        horizontalAccuracyMeters: accuracyM.isFinite && accuracyM > 0
            ? accuracyM
            : 0.0,
        timestampMillis: nowMs,
        routeGeneration: _routeStepsVersion,
      ),
    );
  }

  /// Producer hook: publishes the latest authoritative visual pose (the exact
  /// pose the 2D marker / 3D model just rendered) to the bounded camera pump so
  /// the camera consumes the same pose generation as the vehicle (PART A / G).
  void _publishStreetlevelFollowPose(double lat, double lon, double bearing) {
    // FLUXIDI Phase 2A: when native FollowPuck is active, forward the same
    // authoritative pose to the native custom LocationProvider at bounded
    // 5-10 Hz. The Dart pump is intentionally left OFF (see the
    // _nativeFollowIsActive guard in _streetlevelFollowPumpEligible()) so the
    // native FollowPuckViewportState owns the camera continuously.
    if (_nativeFollowIsActive()) {
      _submitPoseToNativeFollow(lat, lon, bearing);
      _stopStreetlevelFollowPump();
      return;
    }
    if (!_streetlevelFollowPumpEligible()) {
      _stopStreetlevelFollowPump();
      return;
    }
    _streetlevelPoseGeneration += 1;
    _streetlevelVehicleGeneration = _streetlevelPoseGeneration;
    final nowMs = DateTime.now().millisecondsSinceEpoch;
    // NAV-STREETLEVEL-FLUID-MOTION-1: visual-pose cadence (frame-driven).
    if (_lastPosePublishAtMs != null) {
      _navPoseCadence.add((nowMs - _lastPosePublishAtMs!).toDouble());
    }
    _lastPosePublishAtMs = nowMs;
    final owner = _resolveNavCameraBearingOwnerNow();
    _streetlevelFollowPump.submit(
      NavStreetlevelPose(
        lat: lat,
        lon: lon,
        bearingDeg: bearing,
        headingDeg: bearing,
        timestampMs: nowMs,
        routeGeneration: _routeStepsVersion,
        poseGeneration: _streetlevelPoseGeneration,
        renderEpoch: _routeRenderEpoch,
        ownerMode: navCameraBearingOwnerLabel(owner),
      ),
    );
    _ensureStreetlevelFollowPumpRunning();
  }

  void _ensureStreetlevelFollowPumpRunning() {
    if (_streetlevelFollowPumpTimer != null) return;
    // FLUXIDI NAV-STREETLEVEL-FLUID-MOTION-2 (Phase 1 fallback, Part A):
    // self-rescheduling single-shot pump driven by the adaptive cadence
    // controller. Replaces the previous 16 ms Timer.periodic + setCamera
    // flood; runs at 6-10 Hz and adapts on measured apply-latency /
    // frame-stats health. The primitive stays `setCamera` (instant, no
    // animation) so no repeated `easeTo` / `flyTo` restarts are involved.
    _scheduleNextStreetlevelFollowPumpTick();
    _registerNavFrameTimings();
  }

  void _scheduleNextStreetlevelFollowPumpTick() {
    if (!mounted || !_streetlevelFollowPumpEligible()) {
      _streetlevelFollowPumpTimer = null;
      return;
    }
    _streetlevelFollowPumpTimer = Timer(
      Duration(milliseconds: _navAdaptiveCadence.currentTickMs()),
      () {
        _streetlevelFollowPumpTimer = null;
        _streetlevelFollowPumpTick();
        _scheduleNextStreetlevelFollowPumpTick();
      },
    );
  }

  void _stopStreetlevelFollowPump() {
    _streetlevelFollowPumpTimer?.cancel();
    _streetlevelFollowPumpTimer = null;
    _streetlevelFollowPump.reset();
    _streetlevelBearingController.reset();
    _navStationaryBearingGate.reset();
    _navCameraBearingOwner = NavCameraBearingOwner.reliableRoute;
    _navCameraNewRouteBlendUntil = null;
    _navCameraLastBearingSource = 'held';
    _navBearingAnchorLat = null;
    _navBearingAnchorLon = null;
    _lastStreetlevelPumpCameraAt = null;
    _driverMarkerVisualUpdateInFlight = false;
    _unregisterNavFrameTimings();
    _lastPosePublishAtMs = null;
    _navPoseCadence.reset();
    _navCameraApplyCadence.reset();
    _navFrameCadence.reset();
    _navUiBuildStats.reset();
    _navRasterStats.reset();
    // FLUXIDI NAV-STREETLEVEL-FLUID-MOTION-2 (Phase 1 fallback): reset the
    // adaptive cadence so a new follow session starts at max Hz.
    _navAdaptiveCadence.reset();
  }

  /// NAV-STREETLEVEL-FLUID-MOTION-1: subscribe to Flutter engine frame timings
  /// so the rendered-frame, UI-build and raster (render-thread) cadences can be
  /// distinguished from the GPS / anchor / pose / camera-apply cadences.
  void _registerNavFrameTimings() {
    if (_navFrameTimingsRegistered) return;
    _navFrameTimingsRegistered = true;
    _navFrameTimingsCallback = (List<FrameTiming> timings) {
      for (final t in timings) {
        _navFrameCadence.add(t.totalSpan.inMicroseconds / 1000.0);
        _navUiBuildStats.add(t.buildDuration.inMicroseconds / 1000.0);
        _navRasterStats.add(t.rasterDuration.inMicroseconds / 1000.0);
      }
    };
    WidgetsBinding.instance.addTimingsCallback(_navFrameTimingsCallback!);
  }

  void _unregisterNavFrameTimings() {
    final cb = _navFrameTimingsCallback;
    if (cb != null) {
      WidgetsBinding.instance.removeTimingsCallback(cb);
    }
    _navFrameTimingsCallback = null;
    _navFrameTimingsRegistered = false;
  }

  /// Emits the bounded five-cadence budget line at most every 2 s.
  void _maybeEmitNavCadenceDiag(int nowMs) {
    if (_lastCadenceDiagAtMs != null && nowMs - _lastCadenceDiagAtMs! < 2000) {
      return;
    }
    _lastCadenceDiagAtMs = nowMs;
    debugPrint(
      formatNavCadenceDiag(
        gpsMedianMs: _navGpsCadence.medianMs,
        anchorMedianMs: _navAnchorCadence.medianMs,
        poseMedianMs: _navPoseCadence.medianMs,
        cameraApplyMedianMs: _navCameraApplyCadence.medianMs,
        frameMedianMs: _navFrameCadence.medianMs,
        frameP95Ms: _navFrameCadence.p95Ms,
        frameFreezesOver100: _navFrameCadence.freezesOver(100.0),
        uiBuildMedianMs: _navUiBuildStats.medianMs,
        rasterMedianMs: _navRasterStats.medianMs,
      ),
    );
  }

  /// Consumer: one bounded camera update per tick, newest pose wins, a single
  /// update in flight. Finite periodic timer — no recursion, no microtask
  /// chain, no queue of stale camera targets.
  void _streetlevelFollowPumpTick() {
    if (!mounted || !_streetlevelFollowPumpEligible()) {
      _stopStreetlevelFollowPump();
      return;
    }
    // PART C single-owner: a forced legacy camera move (manual recenter, view
    // +/-, style restore, nav start) temporarily owns the camera. The passive
    // pump yields so two Mapbox animations never run at the same time.
    if (_followCameraInFlight) {
      _logNavLatencyCamera(owner: 'legacy_forced', skipReason: 'legacy_owns');
      return;
    }
    final zoom = _streetlevelFollowZoom;
    final pitch = _streetlevelFollowPitch;
    final padding = _streetlevelFollowPadding;
    // Wait for the first full per-fix computation to seed zoom/pitch/padding.
    if (zoom == null || pitch == null || padding == null) return;
    final pose = _streetlevelFollowPump.acquire();
    if (pose == null) return;
    // NAV-CAMERA-ZERO-OLD-ROUTE-HOLD-P0: never let routeVersion N / epoch N
    // commit after N+1 is active (belt-and-braces over pump acquire).
    final commit = decideNavCameraCommandCommit(
      candidate: NavCameraCommandToken(
        routeVersion: pose.routeGeneration,
        ownerMode: navCameraBearingOwnerFromLabel(pose.ownerMode) ??
            NavCameraBearingOwner.reliableRoute,
        poseGeneration: pose.poseGeneration,
        renderEpoch: pose.renderEpoch,
        targetTimestampMs: pose.timestampMs,
        targetBearingDeg: pose.bearingDeg,
        bearingSource: pose.ownerMode,
      ),
      activeRouteVersion: _routeStepsVersion,
      activeRenderEpoch: _routeRenderEpoch,
      lastCommittedPoseGeneration: _streetlevelCameraGeneration,
      activeOwner: _navCameraBearingOwner,
    );
    if (!commit.accept) {
      _streetlevelFollowPump.complete();
      _logNavBounded(
        'NAV_CAMERA_OWNER',
        formatNavCameraOwnerDiag(
          fromOwner: _navCameraBearingOwner,
          toOwner: _navCameraBearingOwner,
          reason: commit.reason,
          routeVersion: pose.routeGeneration,
          bearingSource: pose.ownerMode,
          targetBearing: pose.bearingDeg,
          appliedBearing:
              _streetlevelBearingController.appliedBearing ?? pose.bearingDeg,
          angularDelta: 0,
          targetAgeMs:
              DateTime.now().millisecondsSinceEpoch - pose.timestampMs,
          staleCommandCancelled: commit.staleCommandCancelled,
        ).replaceFirst('[NAV_CAMERA_OWNER] ', ''),
        intervalMs: 1,
      );
      return;
    }
    unawaited(_applyStreetlevelPumpCamera(pose, zoom, pitch, padding));
  }

  int? _lastNavLatencyCameraDiagAtMs;

  /// NAV-LATENCY-1 (Part C): bounded single-owner camera trace (max 1/s).
  void _logNavLatencyCamera({
    required String owner,
    int targetGeneration = 0,
    int appliedGeneration = 0,
    int targetAgeMs = 0,
    int requestToApplyMs = 0,
    int applyIntervalMs = 0,
    bool animationInFlight = false,
    String skipReason = '',
  }) {
    final nowMs = DateTime.now().millisecondsSinceEpoch;
    if (_lastNavLatencyCameraDiagAtMs != null &&
        nowMs - _lastNavLatencyCameraDiagAtMs! < 1000) {
      return;
    }
    _lastNavLatencyCameraDiagAtMs = nowMs;
    debugPrint(
      formatNavLatencyCameraDiag(
        owner: owner,
        targetGeneration: targetGeneration,
        appliedGeneration: appliedGeneration,
        targetAgeMs: targetAgeMs,
        requestToApplyMs: requestToApplyMs,
        applyIntervalMs: applyIntervalMs,
        animationInFlight: animationInFlight,
        coalescedCount: _streetlevelFollowPump.coalescedCount,
        droppedCount: _streetlevelFollowPump.droppedStaleTargets,
        skipReason: skipReason,
      ),
    );
  }

  /// NAV-PRESTART-PREVIEW-AND-STABLE-BEARING-P0 (Problem 2): fixes the initial
  /// Street Level bearing from the first meaningful segment of the accepted
  /// route. Called on route activation, i.e. before any movement exists.
  void _seedNavStationaryBearingFromRoute({required String reason}) {
    if (_routeCoords.length < 2) return;
    final seeded = _navStationaryBearingGate.seedInitialRouteBearing(
      routeTangentBearingDeg: navFirstMeaningfulRouteSegmentBearing(
        _routeCoords,
      ),
      routeSegmentIndex: 0,
    );
    if (seeded == null) return;
    _navBearingAnchorLat = _lastPos?.latitude;
    _navBearingAnchorLon = _lastPos?.longitude;
    _streetlevelBearingController.reset();
    _logNavBounded(
      'NAV_BEARING_SEED',
      'reason=$reason bearing=${seeded.toStringAsFixed(1)} '
      'source=${navBearingSourceLabel(NavBearingSource.initialRouteSegment)}',
      intervalMs: 1000,
    );
  }

  /// NAV-CAMERA-ZERO-OLD-ROUTE-HOLD-P0: resolve + publish owner transitions.
  NavCameraBearingOwner _resolveNavCameraBearingOwnerNow() {
    final progress = _lastNavRouteProgress;
    final deviationSuspected = _offRouteLikely ||
        _rerouteSuspectedAt != null ||
        (progress?.strongMismatchSuspected ?? false) ||
        (progress?.routeDeviationLikely ?? false) ||
        (progress?.oppositeDirectionLikely ?? false);
    final reroutePending = _isRerouting && !_rerouteOwnershipAccepted;
    final newRouteBlendActive = _navCameraNewRouteBlendUntil != null &&
        DateTime.now().isBefore(_navCameraNewRouteBlendUntil!);
    if (_navCameraNewRouteBlendUntil != null && !newRouteBlendActive) {
      _navCameraNewRouteBlendUntil = null;
    }
    final routeMatchReliable = !_offRouteLikely &&
        (_useMatchedVisual || (progress?.forwardProgress ?? true)) &&
        !reroutePending;
    return resolveNavCameraBearingOwner(
      deviationSuspected: deviationSuspected && !newRouteBlendActive,
      reroutePending: reroutePending,
      newRouteBlendActive: newRouteBlendActive,
      routeMatchReliable: routeMatchReliable,
    );
  }

  void _updateNavCameraBearingOwner({
    required String reason,
    bool forceInvalidatePassive = false,
  }) {
    final next = _resolveNavCameraBearingOwnerNow();
    final from = _navCameraBearingOwner;
    if (from == next && !forceInvalidatePassive) return;
    _navCameraBearingOwner = next;
    if (forceInvalidatePassive ||
        (from != next &&
            (next == NavCameraBearingOwner.deviationSuspected ||
                next == NavCameraBearingOwner.reroutePending ||
                next == NavCameraBearingOwner.newRouteAccepted))) {
      // Supersede old-route passive-follow / flyTo so stale completions cannot
      // commit after ownership advanced.
      _cameraInFlightLifecycle.invalidate(reason: 'camera_owner_$reason');
    }
    final applied = _streetlevelBearingController.appliedBearing ??
        _navStationaryBearingGate.acceptedBearing ??
        0.0;
    final target = _streetlevelBearingController.lastTargetDeg;
    _logNavBounded(
      'NAV_CAMERA_OWNER',
      formatNavCameraOwnerDiag(
        fromOwner: from,
        toOwner: next,
        reason: reason,
        routeVersion: _routeStepsVersion,
        bearingSource: _navCameraLastBearingSource,
        targetBearing: target,
        appliedBearing: applied,
        angularDelta: navBearingShortestDelta(applied, target),
        targetAgeMs: 0,
        staleCommandCancelled:
            _streetlevelFollowPump.staleCommandCancelled > 0,
      ).replaceFirst('[NAV_CAMERA_OWNER] ', ''),
      intervalMs: 1,
    );
  }

  /// NAV-PRESTART-PREVIEW-AND-STABLE-BEARING-P0 (Problem 2): resolves the
  /// bearing the Street Level camera is allowed to aim at.
  ///
  /// The pose bearing arrives from the vehicle-visual pipeline, which re-derives
  /// a heading on every GPS fix. While the vehicle is stationary that value
  /// wanders (re-snapped route tangent near the origin, plus raw course noise),
  /// so it must not become a camera target. The gate holds the last reliable
  /// bearing until movement is trustworthy; only then does the smoother below
  /// see a moving target.
  ///
  /// NAV-CAMERA-ZERO-OLD-ROUTE-HOLD-P0: when deviation is suspected or a
  /// reroute is pending, route tangent loses authority immediately and the
  /// predicted/interpolated travel pose owns bearing between GPS samples.
  double _stabilizeStreetlevelCameraBearing({
    required double poseBearingDeg,
    required double speedKmh,
    required double dtMs,
  }) {
    final owner = _resolveNavCameraBearingOwnerNow();
    if (owner != _navCameraBearingOwner) {
      _updateNavCameraBearingOwner(reason: 'owner_resolve');
    }
    final allowTangent = navCameraRouteTangentAllowed(owner);
    final travelAuthority = navCameraTravelAuthority(owner);
    final pos = _lastPos;
    double? displacementM;
    if (pos != null &&
        _navBearingAnchorLat != null &&
        _navBearingAnchorLon != null) {
      displacementM = _metersBetween(
        _LonLat(_navBearingAnchorLon!, _navBearingAnchorLat!),
        _LonLat(pos.longitude, pos.latitude),
      );
    }
    final progress = _lastNavRouteProgress;
    final decision = _navStationaryBearingGate.resolve(
      NavStationaryBearingInput(
        speedKmh: speedKmh,
        routeTangentBearingDeg: allowTangent
            ? (pos == null
                  ? _routeBearingFromProgress(progress)
                  : _resolveForwardRouteBearing(pos))
            : null,
        routeSegmentIndex: progress?.segmentIndex,
        gpsHeadingDeg: pos != null && pos.heading.isFinite && pos.heading >= 0
            ? pos.heading
            : null,
        movementBearingDeg: _lastMovementBearing,
        travelBearingDeg: poseBearingDeg,
        displacementM: displacementM,
        accuracyM: pos != null && pos.accuracy.isFinite && pos.accuracy > 0
            ? pos.accuracy
            : null,
        dtMs: dtMs,
        allowRouteTangent: allowTangent,
        travelAuthority: travelAuthority,
        maxRotationRateDegPerSec: travelAuthority
            ? kNavCameraTravelMaxRotationRateDegPerSec
            : kNavBearingMaxRotationRateDegPerSec,
      ),
    );
    _navCameraLastBearingSource = navBearingSourceLabel(decision.source);
    if (!decision.held && pos != null) {
      _navBearingAnchorLat = pos.latitude;
      _navBearingAnchorLon = pos.longitude;
    }
    if (decision.held) {
      _logNavBounded(
        'NAV_BEARING_HOLD',
        formatNavStationaryBearingDiag(
          decision: decision,
          speedKmh: speedKmh,
          segmentIndex: progress?.segmentIndex,
        ),
        intervalMs: 2000,
      );
      // Nothing reliable yet: keep the pose bearing rather than snapping the
      // camera to an arbitrary 0 degrees.
      if (_navStationaryBearingGate.acceptedBearing == null) {
        return poseBearingDeg;
      }
    }
    return decision.bearingDeg;
  }

  Future<void> _applyStreetlevelPumpCamera(
    NavStreetlevelPose pose,
    double zoom,
    double pitch,
    mb.MbxEdgeInsets padding,
  ) async {
    final speedKmh = _lastPos != null ? _speedKmhFor(_lastPos!) : 0.0;
    final now = DateTime.now();
    final intervalMs = _lastStreetlevelPumpCameraAt == null
        ? 0
        : now.difference(_lastStreetlevelPumpCameraAt!).inMilliseconds;
    final dtMs = intervalMs <= 0
        ? _navAdaptiveCadence.currentTickMs().toDouble()
        : intervalMs.toDouble();
    final targetBearing = _stabilizeStreetlevelCameraBearing(
      poseBearingDeg: pose.bearingDeg,
      speedKmh: speedKmh,
      dtMs: dtMs,
    );
    // FLUXIDI NAV-STREETLEVEL-FLUID-MOTION-2 (Phase 1 fallback): drive
    // bearing at the actual measured camera-apply interval so angular
    // velocity stays cadence-independent when the adaptive controller
    // dynamically steps between 6 Hz and 10 Hz. First tick uses the
    // adaptive controller's current target as the reference dt so the
    // warm-up frame is not biased by the 16 ms pose-interpolator constant.
    final travelAuthority = navCameraTravelAuthority(
      _resolveNavCameraBearingOwnerNow(),
    );
    final appliedBearing = _streetlevelBearingController.follow(
      targetBearingDeg: targetBearing,
      speedKmh: speedKmh,
      dtMs: dtMs,
      travelAuthority: travelAuthority,
    );
    _lastStreetlevelPumpCameraAt = now;
    _streetlevelCameraGeneration = pose.poseGeneration;
    final nowMs = now.millisecondsSinceEpoch;
    // NAV-STREETLEVEL-FLUID-MOTION-1: camera-apply cadence + five-cadence line.
    if (intervalMs > 0) _navCameraApplyCadence.add(intervalMs.toDouble());
    _maybeEmitNavCadenceDiag(nowMs);
    // NAV-LATENCY-1 (Part C): bounded single-owner camera trace.
    _logNavLatencyCamera(
      owner: 'streetlevel_pump',
      targetGeneration: _streetlevelPoseGeneration,
      appliedGeneration: pose.poseGeneration,
      targetAgeMs: nowMs - pose.timestampMs,
      requestToApplyMs: nowMs - pose.timestampMs,
      applyIntervalMs: intervalMs,
      animationInFlight: _streetlevelFollowPump.inFlight,
    );
    if (_lastStreetlevelFollowDiagAtMs == null ||
        nowMs - _lastStreetlevelFollowDiagAtMs! >= 1000) {
      _lastStreetlevelFollowDiagAtMs = nowMs;
      debugPrint(
        formatNavStreetlevelFollowDiag(
          poseGeneration: pose.poseGeneration,
          cameraGeneration: _streetlevelCameraGeneration,
          vehicleGeneration: _streetlevelVehicleGeneration,
          poseAgeMs: nowMs - pose.timestampMs,
          cameraUpdateIntervalMs: intervalMs,
          bearingTarget: targetBearing,
          bearingApplied: appliedBearing,
          bearingDelta: _streetlevelBearingController.lastAppliedDeltaDeg,
          cameraInFlight: _streetlevelFollowPump.inFlight,
          droppedStaleTargets: _streetlevelFollowPump.droppedStaleTargets,
          reason: 'pump_apply',
        ),
      );
    }
    // FLUXIDI NAV-STREETLEVEL-FLUID-MOTION-2 (Phase 1 fallback, Part A): the
    // primitive stays `setCamera` (instant, no animation) so consecutive
    // writes never restart an eased animation. The adaptive cadence
    // controller determines HOW OFTEN we get here (6-10 Hz), driven by the
    // measured apply-latency + frame health below.
    final applyStart = Stopwatch()..start();
    try {
      await _map?.setCamera(
        mb.CameraOptions(
          center: _mbPoint(pose.lon, pose.lat),
          zoom: zoom,
          bearing: appliedBearing,
          pitch: pitch,
          padding: padding,
        ),
      );
    } catch (_) {
      // Swallow transient camera errors; the next pose retries.
    } finally {
      applyStart.stop();
      _navAdaptiveCadence.observe(
        applyLatencyMs: applyStart.elapsedMilliseconds.toDouble(),
        frameP95Ms: _navFrameCadence.p95Ms,
        freezesOver100: _navFrameCadence.freezesOver(100.0),
      );
      _streetlevelFollowPump.complete();
    }
  }

  Future<void> _followCameraTesla(
    geo.Position pos, {
    bool force = false,
    String cameraReason = 'normal_follow',
    int? viewZoomGeneration,
  }) async {
    // NAV-ORIENTATION-VIEWPORT-STABILITY-P0-1: capture the current viewport
    // epoch at entry. Any camera write, cached padding update or pending
    // Tellers anchor commit must be dropped if the epoch has advanced by the
    // time we reach it — a portrait ↔ landscape flip must never let an
    // in-flight pre-rotation follow pass write stale padding or fire a stale
    // flyTo into the newly-laid-out viewport.
    final navViewportEpochAtStart = _navViewportEpoch;
    // FLUXIDI Phase 2A: hard-gate every passive path. When native FollowPuck
    // owns the camera, the only legitimate passive writer is the native
    // custom LocationProvider — Dart contributes zero setCamera/easeTo/flyTo
    // calls. Explicit one-shot temporary owners (style_switch, view_mode,
    // pending_latest) are allowed via the `force: true` branch below, gated
    // by a bounded diagnostic counter so the acceptance criterion "passive
    // Dart camera calls == 0" is provable.
    if (_nativeFollowIsActive()) {
      if (!force) {
        _navValidationPendingCameraSkipReason = 'native_follow_owns';
        _recordNavDiagCameraUpdate(
          follow: false,
          skippedReason: 'native_follow_owns',
        );
        return;
      }
      // Explicit temporary owner. Latch native side, count the passive call
      // for hard-acceptance diagnostics, and let the caller do its one-shot
      // Mapbox action; a follow-up transitionToFollowPuck() returns
      // ownership to native.
      _nativeFollowPassiveCameraCallsCount += 1;
      unawaited(_nativeFollow!.setOwner(NativeFollowOwnerState.temporary));
    }
    if (_mapStyleChanging) {
      _navValidationPendingCameraSkipReason = 'style_changing';
      _recordNavDiagCameraUpdate(
        follow: false,
        skippedReason: 'style_changing',
      );
      return;
    }
    if (!force &&
        cameraReason == 'normal_follow' &&
        _driverCockpitViewZoomLifecycle.blocksPassiveFollow(DateTime.now())) {
      _navValidationPendingCameraSkipReason = 'manual_view_zoom';
      _recordNavDiagCameraUpdate(
        follow: false,
        skippedReason: 'manual_view_zoom',
      );
      _queuePendingFollowCamera(pos, skipReason: 'manual_view_zoom');
      return;
    }
    _navValidationPendingCameraFollowed = false;
    _navValidationPendingCameraSkipReason = null;

    final manualRecenter = force || cameraReason == 'manual_recenter';
    final policy = _resolveNavCameraPolicy(pos, manualRecenter: manualRecenter);
    if (!policy.shouldFollow && !manualRecenter) {
      _navValidationPendingCameraSkipReason = policy.reason;
      _logNavBounded(
        'NAV_R5_CAMERA_POLICY',
        'zoom=${policy.zoom.toStringAsFixed(1)} '
            'tilt=${policy.tilt.toStringAsFixed(1)} '
            'follow=false reason=${policy.reason}',
        intervalMs: 2000,
      );
      _recordNavDiagCameraUpdate(
        follow: false,
        skippedReason: policy.reason,
        zoom: policy.zoom,
        tilt: policy.tilt,
      );
      return;
    }

    if (!force && !_isGpsQualityAcceptableForCamera(pos)) {
      _gpsQualityWeak = true;
      _navValidationPendingCameraSkipReason = 'gps_weak';
      final ageSec = _gpsFixAgeSec(pos);
      final acc = pos.accuracy.isFinite ? pos.accuracy : -1.0;
      _logNavBounded(
        'NAV_GPS',
        'cameraSkip=1 ageSec=${ageSec?.toStringAsFixed(1) ?? 'na'} accuracyM=${acc.toStringAsFixed(1)}',
      );
      _recordNavDiagCameraUpdate(
        follow: false,
        skippedReason: 'gps_weak',
        zoom: policy.zoom,
        tilt: policy.tilt,
      );
      return;
    }
    _gpsQualityWeak = false;

    // NAV-STREETLEVEL-REALTIME-FOLLOW-PIPELINE-1: when the real-time follow
    // pump owns camera writes, this per-fix pass only refreshes the cached
    // zoom/pitch/padding — it must not run the legacy throttle/in-flight/flyTo
    // path (the pump handles cadence and one-in-flight).
    final streetlevelPump = _streetlevelFollowPumpEligible();

    final now = DateTime.now();
    final last = _lastFollowCameraAt;
    final throttleMs = _followCameraThrottleMsFor(pos);
    if (!force &&
        !streetlevelPump &&
        last != null &&
        now.difference(last).inMilliseconds < throttleMs) {
      _navValidationPendingCameraSkipReason = 'throttled';
      _recordNavDiagCameraUpdate(
        follow: false,
        skippedReason: 'throttled',
        zoom: policy.zoom,
        tilt: policy.tilt,
      );
      // NAV-R12-E1: last-wins — retry with the newest target once the
      // throttle window has passed instead of dropping this fix.
      final elapsedMs = now.difference(last).inMilliseconds;
      _queuePendingFollowCamera(
        pos,
        skipReason: 'throttled',
        retryDelayMs: throttleMs - elapsedMs + 8,
      );
      return;
    }
    if (!force && !streetlevelPump && _followCameraInFlight) {
      _navValidationPendingCameraSkipReason = 'in_flight';
      _recordNavDiagCameraUpdate(
        follow: false,
        skippedReason: 'in_flight',
        zoom: policy.zoom,
        tilt: policy.tilt,
      );
      // NAV-R12-E1: the running animation's completion applies this target.
      _queuePendingFollowCamera(pos, skipReason: 'in_flight');
      return;
    }
    if (cameraReason == 'cockpit_adjust' &&
        viewZoomGeneration != null &&
        _driverCockpitViewZoomLifecycle.shouldIgnoreStaleCamera(
          viewZoomGeneration,
        )) {
      return;
    }
    _lastFollowCameraAt = now;
    // NAV-CAMERA-INFLIGHT-SELF-HEAL-1: begin() sets in-flight and hands out
    // a monotonic generation. The OUTER try/finally below guarantees that
    // no matter what happens in the ~275 lines of synchronous work OR the
    // Mapbox flyTo await, the in-flight flag is cleared (or explicitly kept
    // owned by a newer run via `tryClear`'s stale check). User commands
    // (View +/-, recenter, view_mode) supersede a passive owner immediately.
    final commandKind = navCameraCommandKindFromReason(cameraReason);
    final provisionalAnimMs = cameraReason == 'cockpit_adjust'
        ? resolveDriverCockpitViewZoomAnimationMs(
            isTablet: MediaQuery.sizeOf(context).width >= 600,
            manualViewAdjust: true,
          )
        : (force ? 220 : _followCameraAnimMsFor(pos));
    final runGen = _cameraInFlightLifecycle.begin(
      kind: commandKind,
      expectedDuration: Duration(milliseconds: provisionalAnimMs),
    );
    if (runGen == null) {
      _navValidationPendingCameraSkipReason = 'lifecycle_disposed';
      _recordNavDiagCameraUpdate(
        follow: false,
        skippedReason: 'lifecycle_disposed',
        zoom: policy.zoom,
        tilt: policy.tilt,
      );
      return;
    }
    final runStartAt = DateTime.now();
    final startGpsAgeSec = _gpsFixAgeSec(pos);
    _logNavCameraInFlight(
      phase: NavCameraInFlightPhase.start,
      generation: runGen,
      animMs: provisionalAnimMs,
      ageMs: startGpsAgeSec != null ? (startGpsAgeSec * 1000).round() : null,
      reason: cameraReason,
      commandKind: commandKind.label,
      event: NavCameraInFlightEvent.commandStarted.label,
    );
    var flyToAnimMs = 0;
    int elapsedMsFromStart() =>
        DateTime.now().difference(runStartAt).inMilliseconds;
    try {
    final snap =
        _lastRouteSnap ?? _snapToRoute(_LonLat(pos.longitude, pos.latitude));
    final speedKmh = _speedKmhFor(pos);

    // NAV-R12-E1: pure target decision — deviation prefers the freshest
    // raw/live position, prediction only when confident and fresh.
    final progress = _lastNavRouteProgress;
    final strongMismatchSuspected =
        (progress?.strongMismatchSuspected ?? false) ||
        (_lastRerouteDecision?.strongMismatchSuspected ?? false);
    final targetDecision = NavCameraTargetPolicy.resolve(
      NavCameraTargetInput(
        followMode: _cameraMode == _CameraMode.follow,
        manualRecenter: manualRecenter,
        routeDeviationLikely: progress?.routeDeviationLikely ?? false,
        oppositeDirectionLikely: progress?.oppositeDirectionLikely ?? false,
        backwardProgressLikely: progress?.backwardProgressLikely ?? false,
        offRouteLikely: progress?.offRouteLikely ?? _offRouteLikely,
        strongMismatchSuspected: strongMismatchSuspected,
        hasReliableSnap: progress?.hasReliableSnap ?? false,
        predictionActive: _lastNavMotionPrediction?.predictionActive ?? false,
        predictionAgeMs: _gapSinceLastNavEngineMs(),
        cameraScore: _lastNavConfidence?.cameraScore ?? 0.0,
      ),
    );
    if (targetDecision.source == NavCameraTargetSource.skipped) {
      // NAV-CAMERA-INFLIGHT-SELF-HEAL-1: outer finally clears in-flight.
      _navValidationPendingCameraSkipReason = targetDecision.reason;
      _logNavR12Camera(
        animation: 'skipped_manual',
        targetSource: targetDecision.sourceLabel,
        skipReason: targetDecision.reason,
      );
      _recordNavDiagCameraUpdate(
        follow: false,
        skippedReason: targetDecision.reason,
        zoom: policy.zoom,
        tilt: policy.tilt,
      );
      return;
    }
    var visual =
        _isActiveDriverNavEngineContext() && _lastNavEngineOutput != null
        ? _resolveNavVisualForLiveNav(
            pos,
            snap,
            allowPrediction:
                targetDecision.source == NavCameraTargetSource.prediction,
          )
        : (
            point: _displayRoutePointFor(pos),
            bearing: _adaptiveBearingFor(pos, snap: snap).bearing,
          );
    if (targetDecision.forceRawTarget) {
      // Route is adapting: aim at the live driver position, keep the
      // already-resolved display bearing (NAV-R12-C output).
      visual = (
        point: _LonLat(pos.longitude, pos.latitude),
        bearing: visual.bearing,
      );
    }
    final viewMode = _navCameraViewMode;
    final navPresentation = _navigationPresentationStateFor(viewMode);
    final instantCockpitBearing =
        force &&
        (cameraReason == 'cockpit_adjust' || cameraReason == 'style_switch');
    final prevBearing = _lastSmoothedCameraBearing;
    late final double rawBearingTarget;
    late final double heading;
    late final String bearingSource;
    if (_cameraMode == _CameraMode.follow &&
        _liveRideActive &&
        navPresentation.useDriverCockpitCamera) {
      // During mismatch / force-raw, planned-route tangent must not own
      // heading-up — follow actual travel evidence until the new route applies.
      final bearingOffRoute = (progress?.offRouteLikely ?? _offRouteLikely) ||
          targetDecision.forceRawTarget ||
          strongMismatchSuspected;
      final routeLocked = resolveDriverRouteBearing(
        DriverRouteBearingInput(
          routeCoords: _routeCoords,
          segmentIndex: progress?.segmentIndex,
          snappedLat: progress?.snappedLatitude,
          snappedLon: progress?.snappedLongitude,
          hasReliableSnap: bearingOffRoute
              ? false
              : (progress?.hasReliableSnap ?? false),
          gpsHeadingDeg: pos.heading.isFinite && pos.heading >= 0
              ? pos.heading
              : null,
          previousBearingDeg: prevBearing,
          routeConfidence: progress?.confidence,
          offRouteLikely: bearingOffRoute,
          forwardProgress: progress?.forwardProgress ?? true,
          speedKmh: speedKmh,
          maxStepDeg: instantCockpitBearing
              ? 0.0
              : driverRouteBearingMaxStep(speedKmh: speedKmh),
        ),
      );
      final bearingLock = applyDriverCockpitStreetlevelBearingLock(
        DriverCockpitStreetlevelBearingLockInput(
          routeBearing: routeLocked,
          viewLevel: _driverCockpitViewLevel,
          speedKmh: speedKmh,
          gpsHeadingDeg: pos.heading.isFinite && pos.heading >= 0
              ? pos.heading
              : null,
          gpsAccuracyM: pos.accuracy.isFinite && pos.accuracy > 0
              ? pos.accuracy
              : null,
          previousAppliedBearingDeg: prevBearing,
          instantApply: instantCockpitBearing,
        ),
      );
      heading = bearingLock.appliedBearing;
      rawBearingTarget = bearingLock.targetBearing;
      bearingSource = bearingLock.mode == 'route_tangent'
          ? 'applied_route_tangent'
          : bearingLock.mode;
      _lastSmoothedCameraBearing = heading;
      _logNavPresBearing(
        output: routeLocked,
        viewLevel: _driverCockpitViewLevel,
      );
      _logNavPresBearingLock(
        level: _driverCockpitViewLevel,
        speedKmh: speedKmh,
        output: bearingLock,
      );
    } else {
      rawBearingTarget = visual.bearing;
      heading = _smoothFollowCameraBearing(
        rawBearingTarget,
        speedKmh,
        bearingModeWeight: policy.bearingModeWeight,
        viewMode: viewMode,
      );
      bearingSource = _isActiveDriverNavEngineContext()
          ? _driverNavEngine.lastBearingSource
          : _adaptiveBearingFor(pos, snap: snap).source;
    }
    var bearingDeltaDeg = 0.0;
    if (prevBearing != null && prevBearing.isFinite) {
      var delta = rawBearingTarget - prevBearing;
      while (delta > 180) delta -= 360;
      while (delta < -180) delta += 360;
      bearingDeltaDeg = delta;
    }
    _logNavR15CameraBearing(
      mode: viewMode,
      speedKmh: speedKmh,
      bearingSource: bearingSource,
      bearingWeight: navPresentation.useDriverCockpitCamera
          ? 1.0
          : policy.bearingModeWeight,
      bearingDeltaDeg: bearingDeltaDeg,
      routeConfidence: progress?.confidence,
    );
    final p = _mbPoint(visual.point.lon, visual.point.lat);
    var cameraCenter = p;
    final resolvedReason = manualRecenter ? 'manual_recenter' : policy.reason;
    var cameraZoom = policy.zoom;
    var cameraPitch = policy.tilt;
    final isLandscape =
        MediaQuery.of(context).orientation == Orientation.landscape;
    final safeTop = MediaQuery.of(context).padding.top;
    final safeBottom = MediaQuery.of(context).padding.bottom;
    var viewPadding = navCameraViewPadding(
      mode: viewMode,
      isLandscape: isLandscape,
      safeTop: safeTop,
      safeBottom: safeBottom,
    );
    // NAV-PHASE-CAMERA-TARGET-1: prepared route, NAV-to-pickup A and the
    // active customer ride must all resolve through the same fixed L7 cockpit
    // profile. The former `_liveRideActive` gate here let the prepared and
    // toPickup phases fall through to the raw policy zoom (~17.0-17.6 street-
    // view tuned), which is exactly what the tablet field failure recorded on
    // manual recenter ([NAV_R1_CAMERA] zoom=17.6 reason=manual_recenter).
    if (_cameraMode == _CameraMode.follow &&
        _navFixedHudPresentationActive &&
        navPresentation.useDriverCockpitCamera) {
      final isTablet = MediaQuery.sizeOf(context).width >= 600;
      final directAdjust = force && cameraReason == 'cockpit_adjust';
      // NAV-PHASE-CAMERA-TARGET-1 (Correction 1): in the prepared-route
      // phase the camera must stay pinned on the A→B route start across
      // every subsequent GPS fix. Without this override, later
      // `_followCameraTesla` calls resolved `visual.point` from the driver
      // GPS (via `_displayRoutePointFor`) and re-centered the map on the
      // driver, moving the HUD nose off the route origin. Route the target
      // through the same phase resolver used by the initial preview apply.
      final phasePreviewTarget =
          _navFixedHudPhase == NavFixedHudPhase.preparedRoute
              ? _resolvePhaseCameraTargetForPreview(pos)
              : null;
      final effectiveVehicleLat =
          phasePreviewTarget?.hasCoordinate == true
              ? phasePreviewTarget!.lat
              : visual.point.lat;
      final effectiveVehicleLon =
          phasePreviewTarget?.hasCoordinate == true
              ? phasePreviewTarget!.lon
              : visual.point.lon;
      final cockpit = _driverCockpitCameraOverrides(
        policyZoom: cameraZoom,
        policyPitch: cameraPitch,
        isTablet: isTablet,
        isLandscape: isLandscape,
        safeTop: safeTop,
        safeBottom: safeBottom,
        screenHeight: MediaQuery.sizeOf(context).height,
        vehicleLat: effectiveVehicleLat,
        vehicleLon: effectiveVehicleLon,
        bearingDeg: heading,
        speedKmh: speedKmh,
        progress: progress,
        directAdjust: directAdjust,
        forceVehicleCenter: targetDecision.forceRawTarget ||
            strongMismatchSuspected ||
            // Prepared preview keeps phase target; never force-raw there.
            (_navFixedHudPhase != NavFixedHudPhase.preparedRoute &&
                (progress?.routeDeviationLikely ?? false)),
      );
      cameraZoom = cockpit.zoom;
      cameraPitch = cockpit.pitch;
      viewPadding = cockpit.padding;
      if (cockpit.centerLat != null && cockpit.centerLon != null) {
        cameraCenter = _mbPoint(cockpit.centerLon!, cockpit.centerLat!);
      } else if (phasePreviewTarget?.hasCoordinate == true) {
        cameraCenter =
            _mbPoint(phasePreviewTarget!.lon, phasePreviewTarget.lat);
      }
      _commitDriverCockpitAppliedCamera(zoom: cameraZoom, pitch: cameraPitch);
      if (_isDriver3dVehicleModelEffectivelyActive()) {
        _requestDriverVehicleModelMovementSync(
          lon: visual.point.lon,
          lat: visual.point.lat,
          bearingDeg: heading,
          source: 'camera_scale_$cameraReason',
        );
      }
      _logNavPresCameraAnchorDeferred();
      _logNavPresCamera(
        zoom: cameraZoom,
        pitch: cameraPitch,
        bearing: heading,
        anchorFraction: cockpit.anchorFraction,
        centerMode: cockpit.centerMode,
        reason: cockpit.reason,
      );
      _logNavPresRouteAlign(
        vehicleLat: visual.point.lat,
        vehicleLon: visual.point.lon,
        progress: progress,
        leadInM: driverCockpitRouteVisualLeadInMeters(_driverCockpitViewLevel),
        hudSize: driverCockpitFixedHudIconSize(isTablet: isTablet),
        anchor: cockpit.anchorFraction,
      );
      if (instantCockpitBearing) {
        _logNavPresCameraLevel(
          level: _driverCockpitViewLevel,
          zoom: cameraZoom,
          pitch: cameraPitch,
          bearingSource: bearingSource,
          result: 'applied',
        );
      }
    }
    // NAV-TELLERS-COMPOSITION-CORRECTION-1: while Tellers is presented, bias the
    // follow camera into the dedicated live-navigation window (right column in
    // landscape, centre band in portrait) via padding only. View level, zoom,
    // pitch and normal (non-Tellers) follow behaviour are unchanged.
    if (_navPresentationMode.isTellers) {
      // NAV-TELLERS-EXACT-LIVE-VIEWPORT-1 / NAV-TELLERS-POSE-ANCHOR-AND-
      // DIAGNOSTICS-UI-1: resolve the single authoritative Tellers geometry the
      // chrome/aperture/marker all use, then wire BOTH the camera target and
      // padding from it so the authoritative navigation pose projects onto the
      // exact on-screen marker anchor (project(pose) == markerAnchorGlobal).
      final tellersSize = MediaQuery.sizeOf(context);
      final tellersPad = MediaQuery.paddingOf(context);
      // NAV-TELLERS-ROTATION-COMPOSITION-AND-POSE-LOCK-1 (Commit 2): classify
      // form factor by the SHORTEST side, identical to the Tellers marker
      // widget (build() line — FluxidiBreakpoints.classifyDeviceSize). Using
      // `width >= 600` here promoted a phone in landscape (width ≥ 600) to
      // tablet, so the camera resolved a DIFFERENT liveWindowRect/markerAnchor
      // than the marker widget — the multi-pixel displacement seen in the field
      // that Centreren could not correct. Both must resolve the SAME geometry so
      // project(matchedPose) == markerRoadContactAnchorGlobal.
      final tellersClass = FluxidiBreakpoints.classifyDeviceSize(tellersSize);
      final tellersIsTablet = tellersClass == FluxidiScreenClass.tablet ||
          tellersClass == FluxidiScreenClass.desktop;
      final tellersGeometry = DriverTellersLayoutGeometry.resolve(
        viewportSize: tellersSize,
        safeTop: tellersPad.top,
        safeBottom: tellersPad.bottom,
        safeLeft: tellersPad.left,
        safeRight: tellersPad.right,
        isLandscape: isLandscape,
        isTablet: tellersIsTablet,
      );
      viewPadding = tellersGeometry.cameraPadding;
      // NAV-TELLERS-ROUTE-CENTERLINE-LOCK-1: resolve the single authoritative
      // Tellers pose. When the snap engine + confidence engine agree on a
      // trustworthy, on-route snap, the camera + pose-lock target follow the
      // same snapped point that owns the visible remaining-route START. Under
      // any deviation / off-route / no-snap signal, retain the existing visual
      // (prediction / interpolation / raw) pose so recovery UX is unchanged.
      final tellersProgress = _lastNavRouteProgress;
      final tellersConfidence = _lastNavConfidence;
      final tellersInput = TellersAuthoritativePoseInput(
        visualLat: visual.point.lat,
        visualLon: visual.point.lon,
        snappedLat: tellersProgress?.snappedLatitude,
        snappedLon: tellersProgress?.snappedLongitude,
        hasReliableMatchedSnap: _routeProgressMatchedVisual(tellersProgress),
        trustRouteSnap: tellersConfidence?.trustRouteSnap ?? true,
        offRouteLikely:
            tellersProgress?.offRouteLikely ?? _offRouteLikely,
      );
      final tellersPose = resolveTellersAuthoritativePose(tellersInput);
      final tellersCenterPoint =
          _mbPoint(tellersPose.lon, tellersPose.lat);
      // Center on the SAME authoritative pose the visible route trim owns
      // (matched snap when reliable; visual otherwise) so the padded focal
      // point places that pose directly beneath the Car/Arrow marker AND
      // over the polyline centreline.
      cameraCenter = tellersCenterPoint;
      // NAV-ORIENTATION-VIEWPORT-STABILITY-P0-1: only publish pending Tellers
      // anchor state when the viewport epoch is still current. A stale pass
      // must never resurrect a previous-epoch anchor over the newly settled
      // viewport.
      if (_navViewportEpoch == navViewportEpochAtStart) {
        _pendingTellersAnchorGeometry = tellersGeometry;
        _pendingTellersAnchorPoseLat = tellersPose.lat;
        _pendingTellersAnchorPoseLon = tellersPose.lon;
        _pendingTellersPoseSource = tellersPose.source;
        if (tellersInput.hasReliableMatchedSnap &&
            tellersInput.trustRouteSnap &&
            !tellersInput.offRouteLikely &&
            tellersProgress?.snappedLatitude != null &&
            tellersProgress?.snappedLongitude != null) {
          _pendingTellersSnappedRouteLat = tellersProgress!.snappedLatitude;
          _pendingTellersSnappedRouteLon = tellersProgress.snappedLongitude;
        } else {
          _pendingTellersSnappedRouteLat = null;
          _pendingTellersSnappedRouteLon = null;
        }
      }
    } else {
      _pendingTellersAnchorGeometry = null;
      _pendingTellersSnappedRouteLat = null;
      _pendingTellersSnappedRouteLon = null;
      _pendingTellersPoseSource = null;
    }
    _lastMapCameraZoom = cameraZoom;
    unawaited(_syncDriverMarkerIconSizeForZoom());
    // NAV-STREETLEVEL-REALTIME-FOLLOW-PIPELINE-1: refresh the pump's cached
    // zoom/pitch/padding from this full per-fix computation. For passive
    // follow, hand camera writes to the pump and skip the heavy flyTo here so
    // there is a single continuous camera driver. Forced/manual camera moves
    // still apply immediately below.
    if (streetlevelPump) {
      // NAV-ORIENTATION-VIEWPORT-STABILITY-P0-1: reject the pump-cache write
      // when the viewport epoch has advanced since we entered this pass.
      // Reseeding padding from a stale pass would immediately restart the
      // pump with previous-orientation padding — precisely the "old
      // landscape padding into portrait" failure mode this commit removes.
      if (_navViewportEpoch != navViewportEpochAtStart) {
        _navValidationPendingCameraSkipReason = 'viewport_epoch_stale';
        _recordNavDiagCameraUpdate(
          follow: false,
          skippedReason: 'viewport_epoch_stale',
        );
        return;
      }
      _streetlevelFollowZoom = cameraZoom;
      _streetlevelFollowPitch = cameraPitch;
      _streetlevelFollowPadding = mb.MbxEdgeInsets(
        top: viewPadding.top,
        left: viewPadding.left,
        bottom: viewPadding.bottom,
        right: viewPadding.right,
      );
      _ensureStreetlevelFollowPumpRunning();
      if (!force) {
        // NAV-CAMERA-INFLIGHT-SELF-HEAL-1: outer finally clears in-flight.
        _navValidationPendingCameraFollowed = true;
        _navValidationPendingCameraSkipReason = null;
        _recordNavDiagCameraUpdate(
          follow: true,
          zoom: cameraZoom,
          tilt: cameraPitch,
          bearing: _streetlevelBearingController.appliedBearing ?? heading,
        );
        return;
      }
    }
    _logNavBounded(
      'NAV_R1_CAMERA',
      'zoom=${cameraZoom.toStringAsFixed(1)} reason=$resolvedReason',
      intervalMs: 2500,
    );
    final isTablet = MediaQuery.sizeOf(context).width >= 600;
    final animMs = cameraReason == 'cockpit_adjust'
        ? resolveDriverCockpitViewZoomAnimationMs(
            isTablet: isTablet,
            manualViewAdjust: true,
          )
        : (force ? 220 : _followCameraAnimMsFor(pos));
    flyToAnimMs = animMs;
    final fixAgeSec = _gpsFixAgeSec(pos);
    _logNavR12Camera(
      animation: 'started',
      targetSource: targetDecision.sourceLabel,
      targetAgeMs: fixAgeSec != null ? (fixAgeSec * 1000).round() : null,
    );

    // NAV-ORIENTATION-VIEWPORT-STABILITY-P0-1: drop the flyTo when the
    // viewport epoch has advanced since this pass began — the padding and
    // center were computed against the previous-epoch viewport and applying
    // them now would flash the wrong aperture into the new orientation
    // until the subsequent pass corrects. The scheduled post-layout reseed
    // (owner: 'viewport_reseed') supplies a fresh forced flyTo once the new
    // viewport has settled.
    if (_navViewportEpoch != navViewportEpochAtStart) {
      _navValidationPendingCameraSkipReason = 'viewport_epoch_stale';
      _recordNavDiagCameraUpdate(
        follow: false,
        skippedReason: 'viewport_epoch_stale',
      );
      return;
    }
    // NAV-CAMERA-INFLIGHT-SELF-HEAL-1: bounded timeout around Mapbox flyTo.
    // A never-completing Mapbox Future used to leave `_followCameraInFlight`
    // stuck true for ~38 s in the field test. The outer try/finally guarantees
    // clear on every outcome; the .timeout() guarantees the await returns.
    final flyToFuture = _map?.flyTo(
      mb.CameraOptions(
        center: cameraCenter,
        zoom: cameraZoom,
        bearing: heading,
        pitch: cameraPitch,
        padding: mb.MbxEdgeInsets(
          top: viewPadding.top,
          left: viewPadding.left,
          bottom: viewPadding.bottom,
          right: viewPadding.right,
        ),
      ),
      mb.MapAnimationOptions(duration: animMs),
    );
    if (flyToFuture == null) {
      _logNavCameraInFlight(
        phase: NavCameraInFlightPhase.complete,
        generation: runGen,
        animMs: animMs,
        ageMs: elapsedMsFromStart(),
        reason: 'no_map',
        commandKind: commandKind.label,
        event: NavCameraInFlightEvent.commandCompleted.label,
      );
      return;
    }
    try {
      await flyToFuture.timeout(computeNavCameraInFlightTimeout(animMs));
      _logNavCameraInFlight(
        phase: NavCameraInFlightPhase.complete,
        generation: runGen,
        animMs: animMs,
        ageMs: elapsedMsFromStart(),
        commandKind: commandKind.label,
        event: NavCameraInFlightEvent.commandCompleted.label,
      );
      _navValidationPendingCameraFollowed = true;
      _navValidationPendingCameraSkipReason = null;
      _recordNavDiagCameraUpdate(
        follow: true,
        zoom: cameraZoom,
        tilt: cameraPitch,
        bearing: heading,
      );
      unawaited(_logNavTellersAnchorSettledIfActive());
    } on TimeoutException {
      _logNavCameraInFlight(
        phase: NavCameraInFlightPhase.timeout,
        generation: runGen,
        animMs: animMs,
        ageMs: elapsedMsFromStart(),
        reason: 'flyTo_no_completion',
        commandKind: commandKind.label,
        event: NavCameraInFlightEvent.commandTimedOut.label,
      );
    } catch (_) {
      _logNavCameraInFlight(
        phase: NavCameraInFlightPhase.error,
        generation: runGen,
        animMs: animMs,
        ageMs: elapsedMsFromStart(),
        reason: 'async_throw',
        commandKind: commandKind.label,
        event: NavCameraInFlightEvent.commandFailed.label,
      );
    }
    } catch (_) {
      // NAV-CAMERA-INFLIGHT-SELF-HEAL-1: synchronous throw somewhere in the
      // ~275 lines of prep between begin() and flyTo. The outer finally will
      // still clear the in-flight flag and re-schedule pending updates.
      _logNavCameraInFlight(
        phase: NavCameraInFlightPhase.error,
        generation: runGen,
        animMs: flyToAnimMs > 0 ? flyToAnimMs : null,
        ageMs: elapsedMsFromStart(),
        reason: 'sync_throw',
        commandKind: commandKind.label,
        event: NavCameraInFlightEvent.commandFailed.label,
      );
    } finally {
      // NAV-CAMERA-INFLIGHT-SELF-HEAL-1: single-point in-flight release.
      // `tryClear` returns false when a newer camera run already owns the
      // state — in that case we do NOT touch pending/flags (the newer run's
      // own finally will handle it).
      final hasPending = _pendingFollowCameraPos != null;
      if (_cameraInFlightLifecycle.tryClear(runGen)) {
        _logNavCameraInFlight(
          phase: NavCameraInFlightPhase.cleared,
          generation: runGen,
          animMs: flyToAnimMs > 0 ? flyToAnimMs : null,
          ageMs: elapsedMsFromStart(),
          hasPending: hasPending,
          commandKind: commandKind.label,
        );
        // NAV-R12-E1: apply the newest queued target within ~1 frame now
        // that the animation is done (or was timed out / errored). Throttle
        // inside _followCameraTesla still applies.
        if (hasPending && mounted) {
          _armPendingFollowCameraTimer(16);
        }
      } else {
        _logNavCameraInFlight(
          phase: NavCameraInFlightPhase.stale,
          generation: runGen,
          animMs: flyToAnimMs > 0 ? flyToAnimMs : null,
          ageMs: elapsedMsFromStart(),
          reason: 'newer_run_owns',
          commandKind: commandKind.label,
          event: NavCameraInFlightEvent.staleCompletionIgnored.label,
        );
      }
    }
  }

  /// NAV-R12-E2: true while the banner may not confidently show an
  /// old-route maneuver (deviation signals from NAV-R12-B or reroute in
  /// flight). Mirrors NavInstructionPolicyInput.routeAdaptationActive.
  bool _navRouteAdaptationActive() {
    final progress = _lastNavRouteProgress;
    final decision = _lastRerouteDecision;
    return _isRerouting ||
        (progress?.offRouteLikely ?? _offRouteLikely) ||
        (progress?.routeDeviationLikely ?? false) ||
        (progress?.oppositeDirectionLikely ?? false) ||
        (progress?.backwardProgressLikely ?? false) ||
        (progress?.strongMismatchSuspected ?? false) ||
        (decision?.strongMismatchSuspected ?? false);
  }

  /// NAV-R12-E2: bounded, PII-safe banner decision diagnostics (no lat/lng).
  void _logNavR12Banner({required String state, required String reason}) {
    final progress = _lastNavRouteProgress;
    final signature = '$state|$reason|$_routeStepsVersion|$_nextStepIndex';
    final changed = signature != _lastNavR12BannerSignature;
    _lastNavR12BannerSignature = signature;
    _logNavBounded(
      'NAV_R12_BANNER',
      'bannerState=$state '
          'reason=$reason '
          'instructionIndex=$_nextStepIndex '
          'routeDeviationLikely=${progress?.routeDeviationLikely ?? false} '
          'oppositeDirectionLikely=${progress?.oppositeDirectionLikely ?? false} '
          'backwardProgressLikely=${progress?.backwardProgressLikely ?? false} '
          'offRouteLikely=${progress?.offRouteLikely ?? _offRouteLikely} '
          'reroutePending=$_isRerouting '
          'routeReliable=${progress?.hasReliableSnap ?? _useMatchedVisual} '
          'maneuverType=${(_nextNavType ?? '').isEmpty ? 'na' : _nextNavType} '
          'routeVersion=$_routeStepsVersion',
      intervalMs: changed ? 1 : 2000,
    );
    if (changed) {
      _logNavRerouteBannerDiag(state: state, reason: reason);
    }
  }

  void _updateNextNavInstruction(geo.Position pos) {
    // GOOGLE-MAPS-WITH-FLUXIDI-PIP-RELEASE-1: while Google Maps owns guidance,
    // suppress Fluxidi maneuver banners / stale instruction ownership. GPS,
    // fare, wait and trip timers keep updating elsewhere.
    //
    // GOOGLE-MAPS-NAV-RETURN-SIGNAGE-RESTORE-P1: do NOT wipe the current
    // maneuver snapshot / owner progress while suppressed — clearing those
    // fields left NAV FLX without DriverTurnInstructionBanner after return.
    if (shouldSuppressNativeGuidance(_externalNavigationSession)) {
      assert(!shouldClearManeuverPresentationWhileSuppressed());
      return;
    }
    // NAV-REROUTE-CURRENT-POSITION-HEADING-P0: after confirmed deviation, do
    // not keep advancing old-route maneuvers while recalculating.
    if (_navRerouteCoordinator.freezeOldRouteProgress &&
        !_rerouteOwnershipAccepted) {
      final deadEndText = _navRerouteCoordinator.deadEndUturnInstruction(
        currentHeadingDeg: pos.heading.isFinite && pos.heading >= 0
            ? pos.heading
            : (_lastMovementBearing ?? 0.0),
        tr: _tr,
      );
      if (deadEndText != null) {
        _nextNavInstruction = deadEndText;
        _nextNavType = 'turn';
        _nextNavModifier = 'uturn';
      } else {
        _activeBanner = null;
        _activeLaneGuidance = null;
        _nextNavInstruction = null;
        _nextNavStreet = null;
        _nextNavDistanceM = null;
        _nextNavType = null;
        _nextNavModifier = null;
        _navInstructionSnapshot = NavInstructionSnapshot.none;
      }
      return;
    }
    // Stable dead-end U-turn while still plunging into the cul-de-sac.
    final deadEndHold = _navRerouteCoordinator.deadEndUturnInstruction(
      currentHeadingDeg: pos.heading.isFinite && pos.heading >= 0
          ? pos.heading
          : (_lastMovementBearing ?? 0.0),
      tr: _tr,
    );
    if (deadEndHold != null) {
      _nextNavInstruction = deadEndHold;
      _nextNavType = 'turn';
      _nextNavModifier = 'uturn';
      _activeLaneGuidance = null;
      return;
    }
    final nextInstruction = computeDriverNextNavInstruction(
      routeSteps: _routeSteps,
      nextStepIndex: _nextStepIndex,
      posLat: pos.latitude,
      posLon: pos.longitude,
      lastRouteSnap: _lastRouteSnap,
      routeCoords: _routeCoords,
      useMatchedVisual: _useMatchedVisual,
    );
    _nextStepIndex = nextInstruction.nextStepIndex;
    if (nextInstruction.reResolved) {
      _logNavR12Banner(state: 're_resolved', reason: 'backtrack_re_resolve');
    } else if (_navRouteAdaptationActive()) {
      _logNavR12Banner(
        state: nextInstruction.hasInstruction
            ? 'suppressed_stale'
            : 'route_adaptation',
        reason: _isRerouting ? 'reroute_pending' : 'route_deviation_signals',
      );
    } else {
      _logNavR12Banner(
        state: nextInstruction.shouldClear ? 'skipped' : 'route_instruction',
        reason: nextInstruction.progressSource,
      );
    }
    // NAV-SIGNAL-P1: distance-based banner ownership for accepted route version.
    final presentation = buildDriverNavInstructionPresentation(
      routeSteps: _routeSteps,
      nextStepIndex: _nextStepIndex,
      posLat: pos.latitude,
      posLon: pos.longitude,
      lastRouteSnap: _lastRouteSnap,
      routeCoords: _routeCoords,
      useMatchedVisual: _useMatchedVisual,
      tr: _tr,
      routeVersion: _routeStepsVersion,
      previousActiveBanner: _activeBanner,
      previousLaneGuidance: _activeLaneGuidance,
      previousManeuverOwner: _navManeuverOwner,
      progressEpoch: ++_navProgressEpoch,
      navStepsLoading: _navStepsLoading,
      destinationReached: _navParkingArrivalConfirmed,
    );
    final snapshot = presentation.snapshot;
    _navInstructionSnapshot = snapshot;
    _activeBanner = presentation.activeBanner;
    _activeLaneGuidance = presentation.laneGuidance;
    _navManeuverOwner = presentation.maneuverOwner;
    final owner = presentation.maneuverOwner;
    if (owner != null) {
      final ownerDiag = formatNavManeuverOwnerDiag(owner);
      if (_lastNavManeuverOwnerDiag != ownerDiag) {
        _lastNavManeuverOwnerDiag = ownerDiag;
        debugPrint(ownerDiag);
      }
    }
    final laneDiag = formatNavLaneResolveDiag(presentation.laneGuidance);
    if (_lastLaneResolveDiag != laneDiag) {
      _lastLaneResolveDiag = laneDiag;
      debugPrint(laneDiag);
    }

    if (nextInstruction.shouldClear) {
      _activeBanner = null;
      _activeLaneGuidance = presentation.laneGuidance;
      if (_nextNavInstruction != null ||
          _nextNavStreet != null ||
          _nextNavDistanceM != null ||
          _nextNavType != null ||
          _nextNavModifier != null ||
          _navInstructionSnapshot != NavInstructionSnapshot.none) {
        if (mounted) {
          setState(() {
            _nextNavInstruction = null;
            _nextNavStreet = null;
            _nextNavDistanceM = null;
            _nextNavType = null;
            _nextNavModifier = null;
            _navInstructionSnapshot = snapshot;
            _activeBanner = null;
            _activeLaneGuidance = presentation.laneGuidance;
          });
        } else {
          _nextNavInstruction = null;
          _nextNavStreet = null;
          _nextNavDistanceM = null;
          _nextNavType = null;
          _nextNavModifier = null;
        }
      }
      return;
    }

    final distanceM = nextInstruction.distanceMeters!;
    final activeBanner = presentation.activeBanner;
    if (activeBanner != null) {
      _logNavBounded(
        'NAV_BANNER_RESOLVE',
        formatNavBannerResolveDiag(
          banner: activeBanner,
          upcomingIndex: _nextStepIndex,
          remainingAlongRouteM: presentation.bannerRemainingAlongRouteM,
        ).replaceFirst('[NAV_BANNER_RESOLVE] ', ''),
        intervalMs: 1500,
      );
    }
    _logNavBounded(
      'NAV_STEP',
      'progressSource=${nextInstruction.progressSource} nextDistanceM=${distanceM.toStringAsFixed(1)}',
    );
    unawaited(
      NavDiagnosticsRecorder.instance.recordManeuverProgress(
        distanceToNextM: distanceM,
        instructionType: snapshot.maneuverType,
        modifier: snapshot.maneuverModifier,
      ),
    );
    if (snapshot.hasInstruction) {
      _logNavBounded(
        'NAV_E2',
        'source=${snapshot.source.name} highway=${snapshot.isHighwayLike} lanes=${snapshot.lanes.length}',
      );
      final maneuverIndex =
          activeBanner?.maneuverStepIndex ?? _nextStepIndex;
      if (maneuverIndex >= 0 && maneuverIndex < _routeSteps.length) {
        final step = _routeSteps[maneuverIndex];
        final rawPrimary = snapshot.primaryText.trim();
        final rawSecondaryLen = snapshot.secondaryText.trim().length;
        final displaySnap = applyDriverNavInstructionDisplayLines(
          snapshot: snapshot,
          step: step,
        );
        final swapped =
            rawPrimary.isNotEmpty &&
            displaySnap.primaryText.trim() != rawPrimary;
        final primaryKind = driverNavBannerPrimaryKind(
          primaryText: displaySnap.primaryText,
          step: step,
        );
        final tgtFrom = driverNavManeuverTargetSource(step);
        _logNavBounded(
          'NAV_E3_TEXT',
          'source=${snapshot.source.name} swapped=$swapped primaryKind=$primaryKind hasBannerSec=${rawSecondaryLen > 0 ? 1 : 0} bannerSecLen=$rawSecondaryLen tgtFrom=$tgtFrom',
        );
      }
    }

    // Prefer ownership-resolved maneuver identity for legacy fields / icons.
    final resolvedType = snapshot.maneuverType.isNotEmpty
        ? snapshot.maneuverType
        : nextInstruction.type;
    final resolvedModifier = snapshot.maneuverModifier.isNotEmpty
        ? snapshot.maneuverModifier
        : nextInstruction.modifier;
    final resolvedInstruction = snapshot.primaryText.isNotEmpty
        ? snapshot.primaryText
        : nextInstruction.instruction;
    final resolvedStreet = snapshot.secondaryText.isNotEmpty
        ? snapshot.secondaryText
        : nextInstruction.street;

    if (!mounted) {
      _nextNavInstruction = resolvedInstruction;
      _nextNavStreet = resolvedStreet;
      _nextNavDistanceM = distanceM;
      _nextNavType = resolvedType;
      _nextNavModifier = resolvedModifier;
      return;
    }

    setState(() {
      _nextNavInstruction = resolvedInstruction;
      _nextNavStreet = resolvedStreet;
      _nextNavDistanceM = distanceM;
      _nextNavType = resolvedType;
      _nextNavModifier = resolvedModifier;
    });
  }

  Future<bool> _buildNavRouteToPickup(BookingItem b) async {
    final epoch = _routeCleanupEpoch;
    final expectedBookingId = b.bookingId;
    if (!_isRouteTaskStillValid(
      epoch: epoch,
      expectedBookingId: expectedBookingId,
    )) {
      return false;
    }
    if (_lastPos == null) return false;
    final pickupText = (b.from ?? '').trim();
    final hasStoredPickup =
        _usableNavLonLat(_extractPreviewEndpoints(b).pickup) != null;
    if (pickupText.isEmpty && !hasStoredPickup) return false;
    final storedPickup = _usableNavLonLat(_extractPreviewEndpoints(b).pickup);
    _installActiveNavTarget(
      bookingId: b.bookingId,
      phase: ActiveNavigationPhase.toPickup,
      targetLat: storedPickup?.lat,
      targetLng: storedPickup?.lon,
      targetAddress: pickupText,
      reason: 'nav_to_pickup',
    );
    final request = _beginDriverRouteRequest(
      purpose: DriverRouteApplyPurpose.pickup,
      expectedBookingId: expectedBookingId,
    );
    if (mounted) {
      setState(() {
        _routePhase = _RideRoutePhase.toPickup;
        _navStepsLoading = true;
      });
    } else {
      _routePhase = _RideRoutePhase.toPickup;
      _navStepsLoading = true;
    }
    debugPrint('[NAV_PHASE] toPickup');
    try {
      final toLL = await _resolvePickupLonLat(b);
      // RELEASE-P0: always use the newest raw GPS at send time — never a
      // pre-await snapshot and never a snapped/projected point.
      final originPos = _lastPos;
      if (originPos == null) return false;
      final fromLL = _LonLat(originPos.longitude, originPos.latitude);
      final package = await _directionsRoute(fromLL, toLL);
      if (_isRerouting &&
          !_navRerouteCoordinator.acceptResponseGeneration(
            _activeRerouteRequestGeneration,
          )) {
        return false;
      }
      if (!_tryActivatePreparedDriverRoute(
        context: request,
        package: package,
      )) {
        return false;
      }
      _bindActiveNavTargetToActivatedRoute(
        purpose: DriverRouteApplyPurpose.pickup,
        destination: toLL,
      );
      final renderEpoch = _routeRenderEpoch;
      if (mounted) setState(() {});
      if (_lastPos != null) {
        _updateRouteSnapState(_lastPos!);
        _updateNextNavInstruction(_lastPos!);
        await _syncVisibleRouteLineWithProgress(
          _lastPos!,
          reason: 'route_rebuilt',
          routeRenderEpoch: renderEpoch,
        );
      }
      await _drawPins(fromLL, toLL, routeRenderEpoch: renderEpoch);
      // RELEASE-P0: when apply already trimmed + synced the ahead line, do not
      // redraw the full polyline (avoids briefly-correct-then-wrong).
      if (!_routeLineProgressTrimmed) {
        await _drawRouteLine(
          _routeCoords,
          routeRenderEpoch: renderEpoch,
        );
      }
      unawaited(
        _syncNavigationDestinationMarker(
          reason: 'nav_route_pickup',
          routeRenderEpoch: renderEpoch,
        ),
      );
      _clearNavRouteFailure();
      return true;
    } catch (e) {
      // NAV-DIRECTIONS-FAILURE-SECURITY-AND-RECOVERY-1: sanitize (no raw
      // exception/token/URI/coords). Keep any existing route authoritative.
      _handleNavRouteRequestFailure(e, isReroute: _isRerouting);
      return false;
    } finally {
      if (_isRouteTaskStillValid(
        epoch: epoch,
        expectedBookingId: expectedBookingId,
      )) {
        if (mounted) {
          setState(() => _navStepsLoading = false);
        } else {
          _navStepsLoading = false;
        }
      }
    }
  }

  Future<bool> _buildNavRouteToDestination(BookingItem b) async {
    final epoch = _routeCleanupEpoch;
    final expectedBookingId = b.bookingId;
    if (!_isRouteTaskStillValid(
      epoch: epoch,
      expectedBookingId: expectedBookingId,
    )) {
      return false;
    }
    if (_lastPos == null) return false;
    final dropoffText = (b.to ?? '').trim();
    final hasStoredDropoff =
        _usableNavLonLat(_extractPreviewEndpoints(b).dropoff) != null;
    if (dropoffText.isEmpty && !hasStoredDropoff) return false;
    final storedDropoff = _usableNavLonLat(_extractPreviewEndpoints(b).dropoff);
    final existing = _activeNavTargetOwner.current;
    if (existing == null ||
        existing.destinationKind != NavigationDestinationKind.dropoff ||
        existing.bookingId != b.bookingId) {
      _installActiveNavTarget(
        bookingId: b.bookingId,
        phase: ActiveNavigationPhase.passengerLeg,
        targetLat: storedDropoff?.lat,
        targetLng: storedDropoff?.lon,
        targetAddress: dropoffText,
        reason: 'nav_to_destination',
      );
    }
    final request = _beginDriverRouteRequest(
      purpose: DriverRouteApplyPurpose.destination,
      expectedBookingId: expectedBookingId,
      expectedTripId: _activeTripId,
    );
    if (mounted) {
      setState(() {
        _routePhase = _RideRoutePhase.trip;
        _navStepsLoading = true;
      });
    } else {
      _routePhase = _RideRoutePhase.trip;
      _navStepsLoading = true;
    }
    debugPrint('[NAV_PHASE] trip');
    try {
      final toLL = await _resolveDropoffLonLat(b);
      // RELEASE-P0: newest raw GPS at send time (not pre-await / not snapped).
      final originPos = _lastPos;
      if (originPos == null) return false;
      final fromLL = _LonLat(originPos.longitude, originPos.latitude);
      final package = await _directionsRoute(fromLL, toLL);
      if (!_tryActivatePreparedDriverRoute(
        context: request,
        package: package,
      )) {
        return false;
      }
      _bindActiveNavTargetToActivatedRoute(
        purpose: DriverRouteApplyPurpose.destination,
        destination: toLL,
      );
      final renderEpoch = _routeRenderEpoch;
      if (mounted) setState(() {});
      if (_lastPos != null) {
        _updateRouteSnapState(_lastPos!);
        _updateNextNavInstruction(_lastPos!);
        await _syncVisibleRouteLineWithProgress(
          _lastPos!,
          reason: 'route_rebuilt',
          routeRenderEpoch: renderEpoch,
        );
      }
      await _drawPins(fromLL, toLL, routeRenderEpoch: renderEpoch);
      if (!_routeLineProgressTrimmed) {
        await _drawRouteLine(
          _routeCoords,
          routeRenderEpoch: renderEpoch,
        );
      }
      unawaited(
        _syncNavigationDestinationMarker(
          reason: 'nav_route_destination',
          routeRenderEpoch: renderEpoch,
        ),
      );
      _clearNavRouteFailure();
      return true;
    } catch (e) {
      // NAV-DIRECTIONS-FAILURE-SECURITY-AND-RECOVERY-1: sanitize (no raw
      // exception/token/URI/coords). Keep any existing route authoritative.
      _handleNavRouteRequestFailure(e, isReroute: _isRerouting);
      return false;
    } finally {
      if (_isRouteTaskStillValid(
        epoch: epoch,
        expectedBookingId: expectedBookingId,
      )) {
        if (mounted) {
          setState(() => _navStepsLoading = false);
        } else {
          _navStepsLoading = false;
        }
      }
    }
  }

  /// NAV-PRESTART-PREVIEW-AND-STABLE-BEARING-P0 (Problem 1): builds and renders
  /// the route preview for a street-ride draft, i.e. after the destination is
  /// chosen and BEFORE START.
  ///
  /// [_buildDirectRouteToDestination] cannot serve this phase: it requires
  /// `_directRideActive`, which only START sets, so the preview map stayed empty
  /// and every control that keys off a non-empty route stayed hidden. This uses
  /// [DriverRouteApplyPurpose.overview], whose acceptance rule is "must not
  /// overwrite a live navigation session" — exactly the pre-start contract. It
  /// starts no meter, no tracking and no worker session.
  Future<bool> _buildDirectRidePreviewRoute(String destinationText) async {
    final epoch = _routeCleanupEpoch;
    if (!_isRouteTaskStillValid(epoch: epoch)) return false;
    if (_liveRideActive) return false;
    if (!_mapSupported || _map == null) return false;
    final dropoffText = destinationText.trim();
    if (dropoffText.isEmpty) return false;
    var origin = _lastPos;
    if (origin == null) {
      await _ensureLocationPermission();
      try {
        origin = await geo.Geolocator.getCurrentPosition(
          desiredAccuracy: geo.LocationAccuracy.best,
        );
        _lastPos = origin;
      } catch (_) {
        origin = null;
      }
    }
    if (origin == null) return false;
    if (!_isRouteTaskStillValid(epoch: epoch) || _liveRideActive) return false;

    final request = _beginDriverRouteRequest(
      purpose: DriverRouteApplyPurpose.overview,
    );
    if (mounted) {
      setState(() => _navStepsLoading = true);
    } else {
      _navStepsLoading = true;
    }
    debugPrint('[NAV_PHASE] direct_preview');
    try {
      final fromLL = _LonLat(origin.longitude, origin.latitude);
      final toLL =
          _directRideDestinationPoint ?? await _geocodeOne(dropoffText);
      final package = await _directionsRoute(fromLL, toLL);
      if (!_tryActivatePreparedDriverRoute(
        context: request,
        package: package,
      )) {
        return false;
      }
      final renderEpoch = _routeRenderEpoch;
      if (mounted) setState(() {});
      await _drawPins(fromLL, toLL, routeRenderEpoch: renderEpoch);
      await _drawRouteLine(_routeCoords, routeRenderEpoch: renderEpoch);
      // NAV-RELEASE-SIMPLE-STREETLEVEL-1: route-ready applies fixed streetlevel
      // once. fitBounds / overview framing is retired for the release surface.
      if (_isCurrentRouteRenderEpoch(renderEpoch)) {
        if (_navCameraViewMode != NavCameraViewMode.streetView) {
          _navCameraViewMode = NavCameraViewMode.streetView;
          _allowOverviewCamera = false;
        }
        await _applyPreviewStreetlevelCameraIfEligible(
          reason: 'preview_route_ready',
        );
      }
      unawaited(
        _attemptTaxiMarkerRestore(attempt: 0, reason: 'preview_route_ready'),
      );
      _scheduleDirectRideEstimateRefresh(reason: 'preview_route_ready');
      _clearNavRouteFailure();
      _logNavBounded(
        'NAV_PRESTART_PREVIEW',
        'event=route_ready points=${_routeCoords.length} '
        'km=${(_routeKm ?? 0).toStringAsFixed(2)} '
        'durationSec=${_routeDurationSec ?? -1}',
      );
      return true;
    } catch (e) {
      _handleNavRouteRequestFailure(e, isReroute: false);
      return false;
    } finally {
      if (_isRouteTaskStillValid(epoch: epoch)) {
        if (mounted) {
          setState(() => _navStepsLoading = false);
        } else {
          _navStepsLoading = false;
        }
      }
    }
  }

  Future<bool> _buildDirectRouteToDestination(String destinationText) async {
    final epoch = _routeCleanupEpoch;
    if (!_isRouteTaskStillValid(epoch: epoch, requireDirectRide: true)) {
      return false;
    }
    if (_lastPos == null) return false;
    final dropoffText = destinationText.trim();
    if (dropoffText.isEmpty) return false;
    final request = _beginDriverRouteRequest(
      purpose: DriverRouteApplyPurpose.direct,
      requireDirectRide: true,
      expectDirectRideActive: true,
    );
    if (mounted) {
      setState(() {
        _routePhase = _RideRoutePhase.trip;
        _navStepsLoading = true;
      });
    } else {
      _routePhase = _RideRoutePhase.trip;
      _navStepsLoading = true;
    }
    debugPrint('[NAV_PHASE] direct_trip');
    try {
      final toLL =
          _directRideDestinationPoint ?? await _geocodeOne(dropoffText);
      // RELEASE-P0: newest raw GPS at send time (not pre-await / not snapped).
      final originPos = _lastPos;
      if (originPos == null) return false;
      final fromLL = _LonLat(originPos.longitude, originPos.latitude);
      final package = await _directionsRoute(fromLL, toLL);
      if (!_tryActivatePreparedDriverRoute(
        context: request,
        package: package,
      )) {
        return false;
      }
      final renderEpoch = _routeRenderEpoch;
      if (mounted) setState(() {});
      if (_lastPos != null) {
        _updateRouteSnapState(_lastPos!);
        _updateNextNavInstruction(_lastPos!);
        await _syncVisibleRouteLineWithProgress(
          _lastPos!,
          reason: 'route_rebuilt',
          routeRenderEpoch: renderEpoch,
        );
      }
      await _drawPins(fromLL, toLL, routeRenderEpoch: renderEpoch);
      if (!_routeLineProgressTrimmed) {
        await _drawRouteLine(
          _routeCoords,
          routeRenderEpoch: renderEpoch,
        );
      }
      unawaited(
        _syncNavigationDestinationMarker(
          reason: 'nav_route_direct',
          routeRenderEpoch: renderEpoch,
        ),
      );
      _scheduleDirectRideEstimateRefresh(reason: 'route_changed');
      // NAV-DIRECTIONS-FAILURE-SECURITY-AND-RECOVERY-1: a complete valid route is
      // now applied — clear any prior connectivity-failure/retry state.
      _clearNavRouteFailure();
      return true;
    } catch (e) {
      // NAV-DIRECTIONS-FAILURE-SECURITY-AND-RECOVERY-1: never surface the raw
      // exception (token/URI/coordinates). Classify + sanitize; keep the metered
      // street ride running; enter a bounded retry state when no valid route.
      _handleNavRouteRequestFailure(e, isReroute: _isRerouting);
      return false;
    } finally {
      if (_isRouteTaskStillValid(epoch: epoch, requireDirectRide: true)) {
        if (mounted) {
          setState(() => _navStepsLoading = false);
        } else {
          _navStepsLoading = false;
        }
      }
    }
  }

  int? _gpsFixAgeMs(geo.Position pos) {
    return DateTime.now()
        .difference(pos.timestamp)
        .inMilliseconds
        .clamp(0, 600000);
  }

  Future<void> _forceFollowCameraNow({required String caller}) async {
    geo.Position? pos = _lastPos;
    // NAV-LATENCY-1 (Part B): never launch active follow-camera motion from a
    // stale last-known fix. Prefer a fresh live fix; if the cached fix is stale
    // or missing, try one fresh read, then decide by age.
    var ageMs = pos == null ? null : _gpsFixAgeMs(pos);
    var action = NavFreshStartGate.resolve(ageMs: ageMs);
    if (pos == null || action != NavFreshStartAction.animateFollow) {
      try {
        final fresh = await geo.Geolocator.getCurrentPosition(
          desiredAccuracy: geo.LocationAccuracy.best,
        );
        pos = fresh;
        _lastPos = fresh;
        ageMs = _gpsFixAgeMs(fresh);
        action = NavFreshStartGate.resolve(ageMs: ageMs);
      } catch (_) {
        // Keep the cached position/action; may still be a bounded placeholder.
      }
    }

    if (pos == null || action == NavFreshStartAction.waitForFix) {
      _navWaitingForFreshFix = true;
      _logNavBounded(
        'NAV_FRESH_START',
        'caller=$caller action=wait_for_fix ageMs=${ageMs ?? -1}',
        intervalMs: 1000,
      );
      if (pos == null) {
        _toast(
          _tr(
            nl: 'GPS-locatie nog niet beschikbaar',
            en: 'GPS location not available yet',
            fr: 'Position GPS pas encore disponible',
            es: 'Ubicación GPS aún no disponible',
          ),
        );
      }
      return;
    }

    _updateRouteSnapState(pos);
    await _syncVisibleRouteLineWithProgress(pos);
    _refreshNavEngineForPosition(pos);

    if (action == NavFreshStartAction.animateFollow) {
      _navWaitingForFreshFix = false;
      await _followCameraTesla(pos, force: true);
    } else {
      // staticPlaceholder: bounded static orientation only — no follow
      // animation from a stale target. Live follow resumes on the next fresh
      // GPS callback (see the position listener freshness clear).
      _navWaitingForFreshFix = true;
      _logNavBounded(
        'NAV_FRESH_START',
        'caller=$caller action=static_placeholder ageMs=${ageMs ?? -1}',
        intervalMs: 1000,
      );
    }
  }

  double _cameraBearingFor(geo.Position pos) {
    if (pos.heading.isFinite && pos.heading >= 0) return pos.heading;
    if (_lastMovementBearing != null && _lastMovementBearing!.isFinite) {
      return _lastMovementBearing!;
    }
    if (_lastKnownBearing.isFinite && _lastKnownBearing > 0)
      return _lastKnownBearing;
    return 0.0;
  }

  bool _hasReliableRouteSnapForBearing() {
    if (!_isActiveDriverNavEngineContext()) {
      return _useMatchedVisual;
    }
    final progress = _lastNavRouteProgress;
    final confidence = _lastNavConfidence;
    return progress != null &&
        progress.hasReliableSnap &&
        progress.forwardProgress &&
        !progress.offRouteLikely &&
        (confidence?.trustRouteSnap ?? true);
  }

  void _logNavR11Bearing({
    required String source,
    required double speedKmh,
    double? accuracyM,
    double? confidence,
    double? deltaDeg,
    required double appliedDeg,
    required String reason,
    double? headingDeltaDeg,
    bool routeDeviationLikely = false,
    bool oppositeDirectionLikely = false,
    bool backwardProgressLikely = false,
    bool offRouteLikely = false,
    bool routeBearingAllowed = false,
  }) {
    if (!_isActiveDriverNavEngineContext()) return;
    _logNavBounded(
      'NAV_R11_BEARING',
      'source=$source '
          'speedKmh=${speedKmh.toStringAsFixed(1)} '
          'accuracyM=${accuracyM?.toStringAsFixed(1) ?? 'na'} '
          'confidence=${confidence?.toStringAsFixed(0) ?? 'na'} '
          'deltaDeg=${deltaDeg?.toStringAsFixed(1) ?? 'na'} '
          'headingDeltaDeg=${headingDeltaDeg?.toStringAsFixed(0) ?? 'na'} '
          'routeDeviationLikely=$routeDeviationLikely '
          'oppositeDirectionLikely=$oppositeDirectionLikely '
          'backwardProgressLikely=$backwardProgressLikely '
          'offRouteLikely=$offRouteLikely '
          'routeBearingAllowed=$routeBearingAllowed '
          'displayBearing=${appliedDeg.toStringAsFixed(1)} '
          'reason=$reason',
      intervalMs: 1200,
    );
  }

  ({
    double bearing,
    String source,
    double? gpsHeading,
    double? movementBearing,
    double? routeBearing,
    double? bearingDeltaDeg,
  })
  _adaptiveBearingFor(geo.Position pos, {_RouteSnap? snap}) {
    final speedKmh = _speedKmhFor(pos);
    final gpsHeading = (pos.heading.isFinite && pos.heading >= 0)
        ? pos.heading
        : null;
    final movementBearing = _lastMovementBearing;
    final routeBearing = _resolveForwardRouteBearing(pos, snap: snap);
    final reliableSnap = _hasReliableRouteSnapForBearing();
    final confidence = _lastNavConfidence;
    final progress = _lastNavRouteProgress;

    final policy = NavBearingPolicy.resolve(
      NavBearingPolicyInput(
        rawHeading: gpsHeading,
        routeBearing: routeBearing,
        movementBearing: movementBearing,
        lastBearing: _lastKnownBearing.isFinite && _lastKnownBearing > 0
            ? _lastKnownBearing
            : null,
        speedKmh: speedKmh,
        accuracyM: pos.accuracy.isFinite && pos.accuracy > 0
            ? pos.accuracy
            : null,
        routeConfidence: progress?.confidence ?? confidence?.routeScore,
        hasReliableSnap: reliableSnap,
        offRouteLikely: progress?.offRouteLikely ?? _offRouteLikely,
        trustBearing: confidence?.trustBearing ?? true,
        trustRouteSnap: reliableSnap,
        routeDeviationLikely: progress?.routeDeviationLikely ?? false,
        oppositeDirectionLikely: progress?.oppositeDirectionLikely ?? false,
        backwardProgressLikely: progress?.backwardProgressLikely ?? false,
        headingDeltaDeg: progress?.headingDeltaDeg,
        forwardProgress: progress?.forwardProgress ?? true,
      ),
    );

    final previous = _lastKnownBearing.isFinite && _lastKnownBearing > 0
        ? _lastKnownBearing
        : null;
    final bearing = NavBearingPolicy.stepToward(
      previous: previous,
      target: policy.targetBearing,
      maxStepDeg: policy.maxStepDeg,
    );
    _lastKnownBearing = bearing;

    final appliedDelta = previous == null
        ? policy.targetDeltaDeg
        : NavBearingSmoother.bearingDelta(previous, bearing);

    _logNavR11Bearing(
      source: policy.source,
      speedKmh: speedKmh,
      accuracyM: pos.accuracy.isFinite && pos.accuracy > 0
          ? pos.accuracy
          : null,
      confidence: progress?.confidence ?? confidence?.routeScore,
      deltaDeg: appliedDelta,
      appliedDeg: bearing,
      reason: policy.reason,
      headingDeltaDeg: progress?.headingDeltaDeg,
      routeDeviationLikely: progress?.routeDeviationLikely ?? false,
      oppositeDirectionLikely: progress?.oppositeDirectionLikely ?? false,
      backwardProgressLikely: progress?.backwardProgressLikely ?? false,
      offRouteLikely: progress?.offRouteLikely ?? _offRouteLikely,
      routeBearingAllowed: policy.routeBearingAllowed,
    );
    _logNavBounded(
      'NAV_BEARING',
      'speedKmh=${speedKmh.toStringAsFixed(1)} '
          'gpsHeading=${gpsHeading?.toStringAsFixed(1) ?? 'na'} '
          'routeBearing=${routeBearing?.toStringAsFixed(1) ?? 'na'} '
          'usedBearing=${bearing.toStringAsFixed(1)} source=${policy.source} '
          'deltaDeg=${appliedDelta?.toStringAsFixed(1) ?? 'na'}',
    );
    _logNavBounded(
      'NAV_OS_R2_BEARING',
      'source=${_r2BearingSourceLabel(policy.source)} '
          'delta=${(_lastR2BearingDeltaDeg ?? policy.targetDeltaDeg)?.toStringAsFixed(1) ?? 'na'} '
          'reversedGuard=$_lastR2ReversedGuard',
    );
    return (
      bearing: bearing,
      source: policy.source,
      gpsHeading: gpsHeading,
      movementBearing: movementBearing,
      routeBearing: routeBearing,
      bearingDeltaDeg: appliedDelta,
    );
  }

  double? _bearingFromPoints(
    double lat1,
    double lon1,
    double lat2,
    double lon2,
  ) {
    return driverBearingFromPoints(lat1, lon1, lat2, lon2);
  }

  Future<geo.Position?> _fetchCurrentPositionForRecenter() async {
    final serviceEnabled = await geo.Geolocator.isLocationServiceEnabled();
    if (!serviceEnabled) {
      debugPrint('[GPS][RECENTER][SERVICE_DISABLED]');
      _toast(
        _tr(
          nl: 'Locatieservice staat uit. Zet GPS aan om te centreren.',
          en: 'Location service is disabled. Enable GPS to recenter.',
          fr: 'Le service de localisation est desactive. Activez le GPS pour recentrer.',
          es: 'El servicio de ubicacion esta desactivado. Activa el GPS para recentrar.',
        ),
      );
      return null;
    }

    var permission = await geo.Geolocator.checkPermission();
    if (permission == geo.LocationPermission.denied) {
      permission = await geo.Geolocator.requestPermission();
    }
    if (permission == geo.LocationPermission.denied ||
        permission == geo.LocationPermission.deniedForever) {
      debugPrint('[GPS][RECENTER][PERMISSION_DENIED]');
      _toast(
        _tr(
          nl: 'Geen locatiepermissie. Geef toegang om te centreren.',
          en: 'Location permission denied. Grant access to recenter.',
          fr: 'Permission de localisation refusee. Autorisez-la pour recentrer.',
          es: 'Permiso de ubicacion denegado. Concedelo para recentrar.',
        ),
      );
      return null;
    }

    debugPrint('[GPS][RECENTER][FETCH_START]');
    try {
      final pos = await geo.Geolocator.getCurrentPosition(
        desiredAccuracy: geo.LocationAccuracy.best,
      ).timeout(const Duration(seconds: 10));
      debugPrint(
        '[GPS][RECENTER][FETCH_OK] lat=${pos.latitude.toStringAsFixed(6)} lng=${pos.longitude.toStringAsFixed(6)}',
      );
      return pos;
    } catch (e) {
      debugPrint('[GPS][RECENTER][ERROR] $e');
      _toast(
        _tr(
          nl: 'GPS-positie ophalen mislukt. Probeer opnieuw.',
          en: 'Failed to get GPS position. Please try again.',
          fr: 'Impossible de recuperer la position GPS. Reessayez.',
          es: 'No se pudo obtener la posicion GPS. Intentalo de nuevo.',
        ),
      );
      return null;
    }
  }

  Future<void> _centerOnMe() async {
    debugPrint('[GPS][RECENTER][TAP]');
    // NAV-PHASE-CAMERA-TARGET-1: during a route phase the fixed HUD owns the
    // camera deterministically. A user-issued recenter must not mutate zoom,
    // target or bearing — the previous behaviour ran through
    // `DriverNavCameraPolicy.update`, which produced the speed-band
    // ~17.0-17.6 zoom seen in the field ([NAV_R1_CAMERA] zoom=17.6 reason=
    // manual_recenter). We reapply the phase-fixed preview camera instead in
    // prepared and toPickup phases, and let the normal follow pipeline own
    // the live ride.
    if (!navPhaseManualCameraMutationAllowed(phase: _navFixedHudPhase)) {
      debugPrint(
        '[GPS][RECENTER][IGNORED_PHASE_LOCKED] '
        'phase=${navFixedHudPhaseLabel(_navFixedHudPhase)}',
      );
      if (_navFixedHudPhase == NavFixedHudPhase.preparedRoute ||
          _navFixedHudPhase == NavFixedHudPhase.toPickup) {
        await _applyPreviewStreetlevelCameraIfEligible(
          reason: 'phase_recenter_reapply',
        );
      }
      return;
    }
    geo.Position? pos = _lastPos;
    if (pos != null) {
      debugPrint('[GPS][RECENTER][CACHE_HIT]');
    } else {
      pos = await _fetchCurrentPositionForRecenter();
      if (pos == null) return;
      _lastPos = pos;
    }

    // NAV-LATENCY-1 (Part B): manual recenter must not silently animate to a
    // stale target. If the fix is not fresh, attempt one fresh read; if it is
    // still stale, refuse to animate and report a waiting-for-fresh-fix state.
    if (!NavFreshStartGate.mayAnimateFollow(ageMs: _gpsFixAgeMs(pos))) {
      final fresh = await _fetchCurrentPositionForRecenter();
      if (fresh != null) {
        pos = fresh;
        _lastPos = fresh;
      }
      if (!NavFreshStartGate.mayAnimateFollow(ageMs: _gpsFixAgeMs(pos))) {
        _navWaitingForFreshFix = true;
        _logNavBounded(
          'NAV_FRESH_START',
          'caller=manual_recenter action=wait_for_fix '
              'ageMs=${_gpsFixAgeMs(pos)}',
          intervalMs: 1000,
        );
        _toast(
          _tr(
            nl: 'Wachten op een verse GPS-positie...',
            en: 'Waiting for a fresh GPS position...',
            fr: 'En attente d\'une position GPS recente...',
            es: 'Esperando una posicion GPS reciente...',
          ),
        );
        return;
      }
    }
    _navWaitingForFreshFix = false;

    if (_mapSupported && _map != null && _driverPointManager != null) {
      await _updateDriverMarker(pos, moveCamera: false);
    }

    if (_liveRideActive) {
      if (mounted) {
        setState(() {
          _cameraMode = _CameraMode.follow;
          _followCar = true;
          _hasSwitchedToFollow = true;
          _allowOverviewCamera = false;
        });
      } else {
        _cameraMode = _CameraMode.follow;
        _followCar = true;
        _hasSwitchedToFollow = true;
        _allowOverviewCamera = false;
      }
      await _applyMapStyleForMode();
      _lastSmoothedCameraBearing = null;
      _updateRouteSnapState(pos);
      await _syncVisibleRouteLineWithProgress(pos);
      await _syncMapboxUserLocationPuckVisibility();
      await _followCameraTesla(
        pos,
        force: true,
        cameraReason: 'manual_recenter',
      );
      debugPrint('[GPS][RECENTER][FOLLOW_RESTORED]');
      return;
    }

    if (_cameraMode == _CameraMode.follow) {
      await _followCameraTesla(
        pos,
        force: true,
        cameraReason: 'manual_recenter',
      );
      return;
    }

    final p = _mbPoint(pos.longitude, pos.latitude);
    await _map?.flyTo(
      mb.CameraOptions(center: p, zoom: 13.5),
      mb.MapAnimationOptions(duration: 650),
    );
  }

  void _toast(String msg) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(msg), behavior: SnackBarBehavior.floating),
    );
  }

  /// FLUXIDI-EXTERNAL-NAV-FALLBACK-POPUP-LOOP-P0-1: single owner for any
  /// automatic Waze/Google recommendation. Almost always a no-op under the
  /// release policy; never invoked from build, GPS ticks, or reroute loops
  /// without going through [resolveExternalNavAutoPrompt] + the session latch.
  void _maybeAutoPromptExternalNavFallback({
    required String reason,
    required bool failureIsTerminal,
    bool transientNavigationSignal = false,
  }) {
    final activeNav =
        _liveRideActive ||
        _cameraMode == _CameraMode.follow ||
        _routePhase == _RideRoutePhase.toPickup ||
        _routePhase == _RideRoutePhase.trip;
    final hasUsable =
        _hasValidActiveRoute || _routeCoords.length >= 2;
    final decision = resolveExternalNavAutoPrompt(
      NavExternalFallbackPromptInput(
        navigationSuccessfullyStarted:
            hasUsable || _liveRideActive || activeNav,
        hasUsableRoute: hasUsable,
        failureIsTerminal: failureIsTerminal,
        fluxidiCanProvideNavigation: hasUsable || activeNav,
        driverInActiveNavigation: activeNav,
        alreadyShownOrDismissedThisAttempt:
            _externalNavFallbackLatch.isLatched,
        transientNavigationSignal: transientNavigationSignal,
      ),
    );
    _logNavBounded(
      'NAV_EXTERNAL_FALLBACK',
      'show=${decision.shouldShow ? 1 : 0} reason=${decision.reason} '
          'caller=$reason latch=${_externalNavFallbackLatch.isLatched ? 1 : 0} '
          'attempt=${_externalNavFallbackLatch.attemptId}',
      intervalMs: 2000,
    );
    if (!decision.shouldShow) return;
    if (!_externalNavFallbackLatch.tryBeginPresentation()) return;
    if (!mounted) {
      _externalNavFallbackLatch.cancelInFlight();
      return;
    }
    _externalNavFallbackLatch.markShownOrDismissed();
    _toast(
      _tr(
        nl: 'Navigatie kon niet worden gestart. Open Waze of Google Maps via Meer.',
        en: 'Navigation could not start. Open Waze or Google Maps from More.',
        fr: 'La navigation n’a pas pu démarrer. Ouvrez Waze ou Google Maps via Plus.',
        es: 'No se pudo iniciar la navegación. Abre Waze o Google Maps en Más.',
      ),
    );
  }

  void _resetExternalNavFallbackLatchForNewAttempt({
    required String reason,
  }) {
    _externalNavFallbackLatch.beginNewNavigationAttempt();
    _logNavBounded(
      'NAV_EXTERNAL_FALLBACK',
      'event=attempt_reset reason=$reason '
          'attempt=${_externalNavFallbackLatch.attemptId}',
      intervalMs: 500,
    );
  }

  _ExternalNavTarget? _resolveExternalNavTarget() {
    if (_directRideDestinationPoint != null) {
      return _ExternalNavTarget(
        lat: _directRideDestinationPoint!.lat,
        lon: _directRideDestinationPoint!.lon,
      );
    }

    if (_routeCoords.isNotEmpty) {
      final destination = _routeCoords.last;
      return _ExternalNavTarget(lat: destination.lat, lon: destination.lon);
    }

    final bookingDestination = (_activeBooking?.to ?? '').trim();
    if (bookingDestination.isNotEmpty) {
      return _ExternalNavTarget(query: bookingDestination);
    }

    final directDestination = (_directRideDestinationText ?? '').trim();
    if (directDestination.isNotEmpty) {
      return _ExternalNavTarget(query: directDestination);
    }

    return null;
  }

  Future<void> _launchExternalNavUri(Uri uri) async {
    final ok = await launchUrl(uri, mode: LaunchMode.externalApplication);
    if (ok || !mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          _tr(
            nl: 'Navigatie-app kon niet worden geopend.',
            en: 'Could not open navigation app.',
            fr: 'Impossible d’ouvrir l’application de navigation.',
            es: 'No se pudo abrir la aplicación de navegación.',
          ),
        ),
      ),
    );
  }

  Future<void> _openInGoogleMaps() async {
    // GOOGLE-MAPS-DIRECT-LAUNCH-ANDROID-1: never open the HTTPS browser URL.
    await _launchGoogleMapsWithFluxidiPip(
      phase: _resolveExternalNavPhase(),
    );
  }

  bool get _externalNavGuidanceSuppressed =>
      shouldSuppressNativeGuidance(_externalNavigationSession);

  /// TABLET-LOCALIZED-NAV-SIGNAGE-1: on tablet, suppress duplicate external
  /// maneuver verbs (caption lives on the language PNG plate). Asset root is
  /// always `png/` (BLACK-CONTOUR-V3) — never legacy `png_captioned/`.
  bool get _useCaptionedNavSigns {
    if (!mounted) return false;
    return isNavSignageTabletLayout(MediaQuery.sizeOf(context));
  }

  ExternalNavPhase _resolveExternalNavPhase() {
    if (_liveRideActive) return ExternalNavPhase.activeRide;
    return ExternalNavPhase.toPickup;
  }

  ExternalNavigationDestinationPoint _resolveGoogleNavDestinationPoint(
    ExternalNavPhase phase,
  ) {
    // PLANNED-BOOKING-CANONICAL-GMAPS-HANDOFF-P0-6: street-direct path is
    // unchanged and must win over any planned snapshot leftovers.
    if (_directRideActive || _directRideDestinationPoint != null) {
      if (_directRideDestinationPoint != null) {
        return ExternalNavigationDestinationPoint(
          latitude: _directRideDestinationPoint!.lat,
          longitude: _directRideDestinationPoint!.lon,
          address: (_directRideDestinationText ?? '').trim(),
        );
      }
    }

    final booking = _activeBooking;
    if (booking != null && !_directRideActive) {
      final canonical = _resolvePlannedCanonicalEndpoints(booking);
      final toPickup = phase == ExternalNavPhase.toPickup;
      final ep = canonical.endpointForPhase(toPickup: toPickup);
      _logNavBounded(
        'EXTERNAL_NAV',
        PlannedBookingCanonicalDestinationResolver.auditLine(
          endpoints: canonical,
          toPickup: toPickup,
          rideKind: 'planned',
          activePhase: phase.name,
          externalSessionToken: _externalNavigationSession == null
              ? null
              : navigationBookingIdLogToken(
                  _externalNavigationSession!.bookingId,
                ),
        ),
        intervalMs: 1,
      );
      // Prefer active-target snap only when it still matches the canonical
      // leg hash (prevents stale parent/quote coords surviving into Maps).
      final snap = _activeNavTargetOwner.current;
      if (snap != null &&
          snap.isValid &&
          snap.hasCoordinates &&
          snap.bookingId == booking.bookingId) {
        final snapHash = snap.targetCoordinateHash;
        final canonHash = ep.coordinateHash;
        final phaseOk = (toPickup &&
                snap.navigationPhase == ActiveNavigationPhase.toPickup) ||
            (!toPickup &&
                (snap.navigationPhase == ActiveNavigationPhase.passengerLeg ||
                    snap.navigationPhase == ActiveNavigationPhase.returnLeg));
        if (phaseOk &&
            (canonHash == 'none' || snapHash == canonHash || !ep.hasCoordinates)) {
          return ExternalNavigationDestinationPoint(
            latitude: snap.targetLat,
            longitude: snap.targetLng,
            address: snap.targetAddress ?? ep.address,
          );
        }
      }
      if (ep.isLaunchable) {
        return ExternalNavigationDestinationPoint(
          latitude: ep.hasCoordinates ? ep.latitude : null,
          longitude: ep.hasCoordinates ? ep.longitude : null,
          address: ep.address,
        );
      }
    }

    // NAVIGATION-SINGLE-ACTIVE-TARGET-TRUTH-P0-5 fallback.
    final snap = _activeNavTargetOwner.current;
    if (snap != null && snap.isValid) {
      final snapPhaseMatches = (phase == ExternalNavPhase.toPickup &&
              snap.navigationPhase == ActiveNavigationPhase.toPickup) ||
          (phase == ExternalNavPhase.activeRide &&
              (snap.navigationPhase == ActiveNavigationPhase.passengerLeg ||
                  snap.navigationPhase == ActiveNavigationPhase.returnLeg));
      if (snapPhaseMatches || phase == ExternalNavPhase.activeRide) {
        return ExternalNavigationDestinationPoint(
          latitude: snap.targetLat,
          longitude: snap.targetLng,
          address: snap.targetAddress,
        );
      }
    }
    final endpoints =
        booking == null ? null : _extractPreviewEndpoints(booking);
    final pickup = endpoints?.pickup;
    final dropoff = endpoints?.dropoff;
    if (phase == ExternalNavPhase.toPickup && booking != null) {
      return ExternalNavDestinationResolver.resolve(
        phase: ExternalNavPhase.toPickup,
        pickupLat: pickup?.lat,
        pickupLon: pickup?.lon,
        pickupAddress: (booking.from ?? '').trim(),
        dropoffLat: dropoff?.lat,
        dropoffLon: dropoff?.lon,
        dropoffAddress: (booking.to ?? '').trim(),
      );
    }
    if (_routeCoords.isNotEmpty && phase == ExternalNavPhase.activeRide) {
      final last = _routeCoords.last;
      return ExternalNavigationDestinationPoint(
        latitude: last.lat,
        longitude: last.lon,
        address: (booking?.to ?? _directRideDestinationText ?? '').trim(),
      );
    }
    return ExternalNavDestinationResolver.resolve(
      phase: phase,
      pickupLat: pickup?.lat,
      pickupLon: pickup?.lon,
      pickupAddress: (booking?.from ?? '').trim(),
      dropoffLat: dropoff?.lat,
      dropoffLon: dropoff?.lon,
      dropoffAddress:
          (booking?.to ?? _directRideDestinationText ?? '').trim(),
    );
  }

  void _ensureExternalNavPipListener() {
    if (_externalNavPipSub != null) return;
    _externalNavPipSub = _externalNavigationHost.pipEvents().listen((event) {
      if (!mounted) return;
      if (event['type'] != 'pipModeChanged') return;
      final active = event['pipActive'] == true;
      final session = _externalNavigationSession;
      if (session == null) return;
      if (session.pipActive == active) return;
      if (active) {
        _markerSelfHealTimer?.cancel();
        _markerSelfHealTimer = null;
        debugPrint(
          '[EXTERNAL_NAV] event=external_nav_background_entered '
          'pipActive=true session=${session.bookingId}',
        );
        setState(() {
          _externalNavigationSession = session.copyWith(pipActive: true);
        });
        return;
      }
      debugPrint(
        '[EXTERNAL_NAV] event=external_nav_return_received '
        'pipActive=false session=${session.bookingId} '
        'active_ride_present=$_liveRideActive',
      );
      // GOOGLE-MAPS-NAV-RETURN-SIGNAGE-RESTORE-P1: returning to full Fluxidi
      // NAV must unsuppress + rehydrate the current maneuver signage.
      _restoreFluxidiNavSignageAfterExternalReturn(
        trigger: ExternalNavSignageRestoreTrigger.pipReturnToFluxidi,
        reason: 'pip_return',
      );
    });
  }

  /// GOOGLE-MAPS-NAV-RETURN-SIGNAGE-RESTORE-P1
  ///
  /// Rebinds DriverTurnInstructionBanner / NavManeuverSign from the CURRENT
  /// route + maneuver owner without recreating MapWidget, clearing the route,
  /// or inventing a fake straight maneuver.
  void _restoreFluxidiNavSignageAfterExternalReturn({
    required ExternalNavSignageRestoreTrigger trigger,
    required String reason,
    bool hadExternalSession = true,
  }) {
    if (!mounted) return;
    final decision = decideExternalNavSignageRestore(
      trigger: trigger,
      liveRideActive: _liveRideActive,
      cameraFollow: _cameraMode == _CameraMode.follow,
      hadExternalSession: hadExternalSession,
    );
    final nextSession = applyExternalNavSignageRestoreToSession(
      session: _externalNavigationSession,
      decision: decision,
    );
    setState(() {
      if (trigger == ExternalNavSignageRestoreTrigger.pipReturnToFluxidi) {
        _externalNavigationSession = nextSession;
      }
      if (decision.restoreNavigationGuidanceActive) {
        _navigationGuidanceActive = true;
      }
    });
    debugPrint(
      '[EXTERNAL_NAV] event=signage_restore reason=$reason '
      'trigger=${trigger.name} '
      'unsuppress=${decision.unsuppressNativeGuidance} '
      'guidance=${decision.restoreNavigationGuidanceActive} '
      'rehydrate=${decision.rehydrateManeuverFromCurrentState} '
      'has_snapshot=${_navInstructionSnapshot?.hasInstruction == true} '
      'route_steps=${_routeSteps.length} '
      'camera=$_cameraMode',
    );
    if (!decision.rehydrateManeuverFromCurrentState) return;
    final pos = _lastPos;
    if (pos == null) return;
    if (shouldSuppressNativeGuidance(_externalNavigationSession)) return;
    _updateNextNavInstruction(pos);
  }

  Future<void> _endExternalNavigationSession({
    required String reason,
    bool exitPip = true,
  }) async {
    final session = _externalNavigationSession;
    if (session == null) return;
    _logNavBounded(
      'EXTERNAL_NAV',
      'event=end reason=$reason pip=${session.pipActive}',
      intervalMs: 1,
    );
    if (exitPip && session.pipActive) {
      try {
        await _externalNavigationHost.exitFluxidiPip();
      } catch (_) {}
    }
    if (!mounted) {
      _externalNavigationSession = null;
      return;
    }
    final shouldRestoreSignage =
        reason != 'stop_trip' && reason != 'maps_launch_failed';
    setState(() {
      _externalNavigationSession = null;
    });
    // GOOGLE-MAPS-NAV-RETURN-SIGNAGE-RESTORE-P1: after ending Google Maps
    // ownership, immediately restore banner presentation for NAV FLX.
    if (shouldRestoreSignage) {
      _restoreFluxidiNavSignageAfterExternalReturn(
        trigger: ExternalNavSignageRestoreTrigger.endExternalSession,
        reason: reason,
        hadExternalSession: true,
      );
    }
  }

