  ExternalNavPipMeterModel _buildCurrentPipMeterModel([
    DriverRideMetersSnapshot? snapshot,
    AppLanguage? language,
  ]) {
    // GOOGLE-MAPS-PIP-LIVE-METER-P0: project the same authoritative meter
    // snapshot that Tellers/HUD observe. Never invent a second fare path.
    // PIP-TABLET-READABILITY-LOCALE-P1: driver app language owns overlay copy.
    final snap = snapshot ?? _buildDriverRideMetersSnapshot();
    final phase =
        _externalNavigationSession?.phase ?? _resolveExternalNavPhase();
    final fixed = _fixedBookingPriceEur;
    final fixedText = fixed == null ? null : _fmtMoney(fixed, 'EUR');
    return buildExternalNavPipMeterModelFromRideMeters(
      snapshot: snap,
      phase: phase,
      isStreetRide: _directRideActive || _activeBookingIsStreetDirect,
      isFixedPrice: fixed != null && !_activeBookingIsStreetDirect,
      fixedPriceText: fixedText,
      language: language ?? appConfig.currentLanguage,
    );
  }

  Future<void> _launchGoogleMapsWithFluxidiPip({
    required ExternalNavPhase phase,
  }) async {
    // GOOGLE-MAPS-LAUNCH-CONTRACT-NOOP-P0-2 /
    // GOOGLE-MAPS-LAUNCH-FAILURE-UI-P0-2:
    // Never silent no-op. Maps launch is independent of PiP. PiP only after
    // launch_dispatched=true. All failures show an explicit dialog/toast.
    final gen = _googleMapsLaunchBusyGate.tryBegin();
    if (gen == null) {
      _logNavBounded(
        'EXTERNAL_NAV',
        'event=google_button_pressed ignored=busy',
        intervalMs: 1,
      );
      _toast(
        _tr(
          nl: 'Google Maps wordt al gestart…',
          en: 'Google Maps is already starting…',
          fr: 'Google Maps démarre déjà…',
          es: 'Google Maps ya se está iniciando…',
        ),
      );
      return;
    }
    final destinationSource =
        phase == ExternalNavPhase.toPickup ? 'pickup_a' : 'destination_b';
    _logNavBounded(
      'EXTERNAL_NAV',
      'event=google_button_pressed phase=${phase.name} '
          'external_navigation_phase=${phase.name} '
          'destination_source=$destinationSource',
      intervalMs: 1,
    );
    try {
      if (!_externalNavigationHost.isAndroid) {
        await _showGoogleMapsLaunchFailureDialog(
          status: GoogleMapsLaunchStatus.unsupportedPlatform,
          failureCode: 'unsupported_platform',
        );
        return;
      }

      // PLANNED-BOOKING-CANONICAL-GMAPS-HANDOFF-P0-6: never reuse a stale
      // external session from another booking/leg.
      final activeBookingId = (_activeBooking?.bookingId ?? '').trim();
      final existingSession = _externalNavigationSession;
      if (existingSession != null &&
          activeBookingId.isNotEmpty &&
          existingSession.bookingId.trim() != activeBookingId) {
        await _endExternalNavigationSession(
          reason: 'stale_session_booking_mismatch',
          exitPip: true,
        );
      }

      final destination = _resolveGoogleNavDestinationPoint(phase);
      final mapsHash = navigationTargetCoordinateHash(
        destination.latitude,
        destination.longitude,
      );
      _logNavTargetTruthEvent(
        event: 'google_maps_open',
        arrivalFlagSource: destinationSource,
        googleMapsTargetHash: mapsHash,
        pipTargetHash: mapsHash,
      );
      final channelDest = ExternalNavigationDestination(
        latitude: destination.latitude,
        longitude: destination.longitude,
        address: destination.address,
      );
      final latValid =
          GoogleMapsDestinationValidator.isValidLatitude(channelDest.latitude);
      final lngValid =
          GoogleMapsDestinationValidator.isValidLongitude(channelDest.longitude);
      final addressPresent =
          GoogleMapsDestinationValidator.hasUsableAddress(channelDest.address);
      _logNavBounded(
        'EXTERNAL_NAV',
        'event=external_navigation_phase phase=${phase.name} '
            'destination_source=$destinationSource '
            'destination_lat_valid=$latValid '
            'destination_lng_valid=$lngValid '
            'destination_address_present=$addressPresent',
        intervalMs: 1,
      );
      if (!GoogleMapsDestinationValidator.isLaunchable(channelDest)) {
        await _showGoogleMapsLaunchFailureDialog(
          status: GoogleMapsLaunchStatus.invalidDestination,
          failureCode: 'invalid_destination',
        );
        return;
      }

      final pipSupported = await _externalNavigationHost.isPipSupported();
      var usePip = pipSupported;
      if (!pipSupported) {
        final continueWithout = await _confirmContinueWithoutPip();
        if (!continueWithout) {
          _toast(
            _tr(
              nl: 'Google Maps-start geannuleerd.',
              en: 'Google Maps launch cancelled.',
              fr: 'Lancement de Google Maps annulé.',
              es: 'Inicio de Google Maps cancelado.',
            ),
          );
          return;
        }
        usePip = false;
      }

      if (_posSub == null) {
        _startTrackingInternal();
      }
      _ensureExternalNavPipListener();
      _setNavigationWakelock(true);

      final bookingId = (_activeBooking?.bookingId ??
              _activeDirectBookingId ??
              _directRideKey ??
              'pending')
          .trim();
      // Session is pending until Maps launch succeeds; guidance stays active
      // until then so a failed handoff never leaves the driver without Fluxidi.
      final pendingSession = ExternalNavigationSession(
        provider: ExternalNavProvider.googleMaps,
        bookingId: bookingId,
        legId: _activeBooking?.bookingId,
        phase: phase,
        destination: destination,
        launchedAt: DateTime.now().toUtc(),
        pipActive: false,
        nativeGuidanceSuppressed: false,
      );

      // Prepare PiP params only; never enter PiP before Maps dispatch.
      // PiP prepare failure must not block Maps.
      if (usePip) {
        try {
          await _externalNavigationHost.prepareFluxidiPipForHandoff();
        } catch (_) {
          usePip = false;
        }
      }

      final launch =
          await _externalNavigationHost.launchGoogleNavigationResult(
        channelDest,
        destinationSource: destinationSource,
      );
      _logNavBounded(
        'EXTERNAL_NAV',
        'event=maps_launch_result '
            'status=${launch.status.name} '
            'failure_code=${launch.failureCode} '
            'maps_package_installed=${launch.mapsPackageInstalled} '
            'maps_package_enabled=${launch.mapsPackageEnabled} '
            'maps_intent_resolved=${launch.mapsIntentResolved} '
            'maps_start_activity_result=${launch.launchDispatched} '
            'launch_dispatched=${launch.launchDispatched} '
            'pip_supported=${launch.pipSupported} '
            'uri_present=${(launch.uri ?? '').isNotEmpty}',
        intervalMs: 1,
      );

      final decision = GoogleMapsLaunchDecision.fromResult(
        result: launch,
        userWantsPip: usePip,
      );
      if (!decision.activateExternalSession) {
        // Ensure no stale external session remains after a failed launch.
        if (_externalNavigationSession != null) {
          await _endExternalNavigationSession(
            reason: 'maps_launch_failed',
            exitPip: false,
          );
        }
        switch (decision.uiAction) {
          case GoogleMapsLaunchUiAction.showInstallDialog:
            await _promptGoogleMapsMissing(
              disabled: launch.status == GoogleMapsLaunchStatus.mapsDisabled,
            );
            return;
          case GoogleMapsLaunchUiAction.showInvalidDestination:
            await _showGoogleMapsLaunchFailureDialog(
              status: GoogleMapsLaunchStatus.invalidDestination,
              failureCode: launch.failureCode,
            );
            return;
          case GoogleMapsLaunchUiAction.showCancelledToast:
            _toast(
              _tr(
                nl: 'Google Maps-start geannuleerd.',
                en: 'Google Maps launch cancelled.',
                fr: 'Lancement de Google Maps annulé.',
                es: 'Inicio de Google Maps cancelado.',
              ),
            );
            return;
          case GoogleMapsLaunchUiAction.showFailureDialog:
          case GoogleMapsLaunchUiAction.none:
          case GoogleMapsLaunchUiAction.proceedWithPip:
          case GoogleMapsLaunchUiAction.proceedWithoutPip:
            await _showGoogleMapsLaunchFailureDialog(
              status: launch.status,
              failureCode: launch.failureCode,
            );
            return;
        }
      }

      // Launch succeeded — own the external session and suppress Fluxidi
      // turn-by-turn. PiP only after Maps was dispatched.
      final activeSession = pendingSession.copyWith(
        nativeGuidanceSuppressed: true,
      );
      if (mounted) {
        setState(() {
          _externalNavigationSession = activeSession;
          _navigationGuidanceActive = false;
        });
      } else {
        _externalNavigationSession = activeSession;
      }
      // ACTIVE-RIDE-DURABLE-RESTORE-P0-7: persist before PiP / background.
      await _persistActiveRideDurableSnapshot(
        reason: 'maps_handoff',
        externalSession: activeSession,
      );
      if (_directRideActive) {
        unawaited(_persistDirectTripSession(
          localLifecycle: kDirectTripLocalLifecycleActive,
          bookingFinalizeState: kDirectTripFinalizePending,
        ));
      }
      debugPrint(
        '[EXTERNAL_NAV] event=external_nav_return_requested '
        'booking=$bookingId phase=${phase.name} '
        'active_ride_present=true',
      );

      var pipOk = false;
      if (decision.requestPip && launch.launchDispatched) {
        _logNavBounded(
          'EXTERNAL_NAV',
          'event=pip_requested after_launch_dispatched=true',
          intervalMs: 1,
        );
        final pipResult = await _externalNavigationHost.enterFluxidiPip();
        pipOk = pipResult['ok'] == true || pipResult['pipActive'] == true;
        if (mounted) {
          setState(() {
            _externalNavigationSession =
                (_externalNavigationSession ?? activeSession).copyWith(
              pipActive: pipOk,
            );
          });
        }
        _logNavBounded(
          'EXTERNAL_NAV',
          'event=pip_after_handoff ok=$pipOk',
          intervalMs: 1,
        );
      }

      _logNavBounded(
        'EXTERNAL_NAV',
        'event=launched provider=google_maps phase=${phase.name} '
            'pip=$pipOk source=$destinationSource booking=$bookingId '
            'dispatched=${launch.launchDispatched} '
            'external_session_created=true',
        intervalMs: 1,
      );
    } catch (e) {
      _logNavBounded(
        'EXTERNAL_NAV',
        'event=maps_platform_exception_code=${e.runtimeType} '
            'message_present=${e.toString().isNotEmpty}',
        intervalMs: 1,
      );
      // Never leave a half-created external session on unexpected errors.
      if (_externalNavigationSession != null &&
          !_externalNavigationSession!.nativeGuidanceSuppressed) {
        _externalNavigationSession = null;
      }
      await _showGoogleMapsLaunchFailureDialog(
        status: GoogleMapsLaunchStatus.nativeException,
        failureCode: e is PlatformException ? e.code : 'native_exception',
      );
    } finally {
      _googleMapsLaunchBusyGate.end(gen);
    }
  }

  Future<void> _maybeRelaunchGoogleMapsAfterStart() async {
    final session = _externalNavigationSession;
    if (session == null || !session.isGoogleMaps) return;
    await _launchGoogleMapsWithFluxidiPip(
      phase: ExternalNavPhase.activeRide,
    );
  }

  Future<void> _openInWaze() async {
    final target = _resolveExternalNavTarget();
    if (target == null) return;
    Uri uri;
    if (target.hasCoordinates) {
      uri = Uri.https('waze.com', '/ul', <String, String>{
        'll': '${target.lat},${target.lon}',
        'navigate': 'yes',
      });
    } else if (target.hasQuery) {
      uri = Uri.https('waze.com', '/ul', <String, String>{
        'q': target.query!.trim(),
        'navigate': 'yes',
      });
    } else {
      return;
    }
    await _launchExternalNavUri(uri);
  }

  DriverRideMetersSnapshot _buildDriverRideMetersSnapshot() {
    final km = _kmDriven;
    final distanceText = !km.isFinite
        ? '—'
        : (km < 0.05 ? '0.0 km' : '${km.toStringAsFixed(1)} km');
    final remaining = _kmRemainingText.trim();
    final remainingText = remaining.isEmpty
        ? ''
        : (remaining.endsWith('km') ? remaining : '$remaining km');
    // NAV-TELLERS-RECENTER-CONTROL-1: status through the shared localization
    // helper so Dutch always shows `Rit actief` / `Rit gepauzeerd` (never the
    // English "Ride active" string in NL UI).
    final String status;
    if (_isWaiting || _liveRideActive) {
      status = driverTellersStatusText(
        language: appLanguageNotifier.value,
        isWaiting: _isWaiting,
        liveRideActive: _liveRideActive,
      );
    } else if (_cameraMode == _CameraMode.follow) {
      status = _tr(
        nl: 'Navigatie',
        en: 'Navigation',
        fr: 'Navigation',
        es: 'Navegación',
      );
    } else {
      status = driverTellersStatusText(
        language: appLanguageNotifier.value,
        isWaiting: false,
        liveRideActive: false,
      );
    }
    return DriverRideMetersSnapshot(
      fareText: _displayTotalText,
      fareLabel: _tellersFareLabel,
      distanceTravelledText: distanceText,
      rideDurationText: _formatHms(_activeElapsed),
      waitingTimeText: _formatHms(_effectiveWaitElapsed),
      statusText: status,
      etaText: _etaText,
      remainingDistanceText: remainingText,
    );
  }

  void _openTellersView() {
    if (!_navPresentationMode.showTellers()) return;
    // NAV-PARKING-2 Commit 4: activate a latest-wins Tellers viewport. The
    // navigation session (route, GPS, fare, timers, View level) stays alive;
    // only the presentation changes and the map becomes the live window.
    // NAV-STYLE-MANAGER-CRASH-TELLERS-MARKER-1: Tellers must NEVER request or
    // alter map style — viewport/HUD only. cockpit_style_choice is an explicit
    // user map-style action via _setDriverCockpitMapVisualStyle, not Tellers.
    assert(tellersPresentationMustNotChangeMapStyle());
    final viewportToken = _tellersViewport.open();
    // Seed orientation so the first build does not treat open as a rotation.
    if (mounted) {
      _lastTellersLandscape =
          MediaQuery.of(context).orientation == Orientation.landscape;
    }
    _logNavBounded(
      'NAV_TELLERS',
      'event=open viewportGeneration=$viewportToken styleRequest=false '
      'markerOwner=tellersLiveWindow',
      intervalMs: 1,
    );
    // One viewport/opacity request per actual mode transition — not on every
    // fare/timer tick. Marker choice is unchanged.
    unawaited(
      _applyMapboxTaxiMarkerPresentationOpacity(source: 'tellers_open'),
    );
    // NAV-TELLERS-STREETLEVEL-SCREEN-UP-MARKER-1: entering Tellers may make
    // the Mapbox annotation the visible owner (Streetlevel) — re-apply the
    // screen-up policy so alignment flips to VIEWPORT and any lingering
    // pose-bearing iconRotate is snapped to 0 immediately, without waiting
    // for the next GPS/route tick.
    unawaited(
      _reapplyDriverMarkerRotationPolicy(source: 'tellers_open'),
    );
    final pos = _lastPos;
    if (pos != null &&
        _cameraMode == _CameraMode.follow &&
        _liveRideActive) {
      unawaited(
        _followCameraTesla(pos, force: true, cameraReason: 'tellers_open'),
      );
    }
    if (!mounted) return;
    setState(() {});
  }

  /// NAV-ORIENTATION-VIEWPORT-STABILITY-P0-1: observe the current build-time
  /// navigation viewport and bump [_navViewportEpoch] exactly once per
  /// materially changed signature. Any cached camera geometry that would
  /// otherwise carry from the previous orientation is invalidated on the
  /// spot; a post-frame rebuild is requested so the two-observation
  /// stability rule can settle the new epoch and schedule a single
  /// latest-wins follow-camera reseed after the layout is stable.
  ///
  /// Pure widget mutation: never touches MapWidget identity/key or the
  /// Navigator stack.
  void _observeNavViewport({required Size size, required bool isLandscape}) {
    final sig = _NavViewportSignature.fromSize(
      size: size,
      isLandscape: isLandscape,
    );
    final last = _lastObservedNavViewportSignature;
    if (last == null) {
      _lastObservedNavViewportSignature = sig;
      _navViewportReseedEpoch = _navViewportEpoch;
      _navViewportReseedFired = false;
      return;
    }
    if (last == sig) {
      final pending = _pendingReseedSignature;
      if (pending == sig &&
          _pendingReseedEpoch == _navViewportEpoch &&
          !_navViewportReseedFired &&
          sig.isShapeConsistent) {
        _pendingReseedSignature = null;
        _pendingReseedEpoch = null;
        _navViewportReseedFired = true;
        _navViewportReseedEpoch = _navViewportEpoch;
        final epochAtSchedule = _navViewportEpoch;
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (!mounted) return;
          if (_navViewportEpoch != epochAtSchedule) return;
          _reseedFollowCameraForCurrentViewport(
            epochAtSchedule: epochAtSchedule,
          );
        });
      }
      return;
    }
    _navViewportEpoch += 1;
    _lastObservedNavViewportSignature = sig;
    _streetlevelFollowPadding = null;
    _pendingTellersAnchorGeometry = null;
    _pendingTellersAnchorPoseLat = null;
    _pendingTellersAnchorPoseLon = null;
    _pendingTellersSnappedRouteLat = null;
    _pendingTellersSnappedRouteLon = null;
    _pendingTellersPoseSource = null;
    _pendingReseedSignature = sig;
    _pendingReseedEpoch = _navViewportEpoch;
    _navViewportReseedFired = false;
    _navViewportReseedEpoch = _navViewportEpoch;
    if (!_navViewportRecheckScheduled) {
      _navViewportRecheckScheduled = true;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        _navViewportRecheckScheduled = false;
        if (!mounted) return;
        setState(() {});
      });
    }
    _logNavBounded(
      'NAV_VIEWPORT',
      'event=epoch_bump epoch=$_navViewportEpoch '
          'w=${sig.widthKey} h=${sig.heightKey} '
          'landscape=${sig.isLandscape}',
      intervalMs: 1,
    );
  }

  /// NAV-ORIENTATION-VIEWPORT-STABILITY-P0-1: issue exactly one forced
  /// follow-camera application after the current viewport has been observed
  /// stable across two consecutive builds. Runs only when the epoch is still
  /// current and a follow-mode live ride is active — the reseed re-derives
  /// fresh camera padding for the current viewport, unpausing the streetlevel
  /// pump (which had paused while `_streetlevelFollowPadding` was null).
  void _reseedFollowCameraForCurrentViewport({required int epochAtSchedule}) {
    if (!mounted) return;
    if (_navViewportEpoch != epochAtSchedule) return;
    final map = _map;
    if (map == null || _mapStyleChanging) return;
    final pos = _lastPos;
    if (pos == null) return;
    if (_cameraMode != _CameraMode.follow || !_liveRideActive) return;
    _logNavBounded(
      'NAV_VIEWPORT',
      'event=reseed_follow epoch=$_navViewportEpoch',
      intervalMs: 1,
    );
    unawaited(
      _followCameraTesla(
        pos,
        force: true,
        cameraReason: 'viewport_reseed',
      ),
    );
  }

  /// NAV-TELLERS-EXACT-LIVE-VIEWPORT-1: on portrait ↔ landscape while Tellers
  /// is active, bump the viewport generation once and issue one latest-wins
  /// camera update. Never recreates MapWidget, GPS, style, route, fare or
  /// marker choice.
  void _syncTellersGeometryForOrientation({required bool isLandscape}) {
    if (!_navPresentationMode.isTellers) {
      _lastTellersLandscape = null;
      return;
    }
    if (_lastTellersLandscape == isLandscape) return;
    final previous = _lastTellersLandscape;
    _lastTellersLandscape = isLandscape;
    if (previous == null) return; // first paint after open — open() already ran
    final token = _tellersViewport.open();
    _logNavBounded(
      'NAV_TELLERS',
      'event=orientation_geometry viewportGeneration=$token '
      'landscape=$isLandscape styleRequest=false',
      intervalMs: 1,
    );
    final pos = _lastPos;
    if (pos != null &&
        _cameraMode == _CameraMode.follow &&
        _liveRideActive) {
      unawaited(
        _followCameraTesla(
          pos,
          force: true,
          cameraReason: 'tellers_orientation',
        ),
      );
    }
  }

  void _closeTellersView() {
    if (!_navPresentationMode.showNavigation()) return;
    // NAV-PARKING-2 Commit 4: restore normal follow presentation and invalidate
    // any pending Tellers camera callback so an old viewport cannot resurrect.
    // NAV-STYLE-MANAGER-CRASH-TELLERS-MARKER-1: closing Tellers is HUD-only —
    // never a map-style request.
    assert(tellersPresentationMustNotChangeMapStyle());
    _tellersViewport.close();
    _lastTellersLandscape = null;
    _logNavBounded(
      'NAV_TELLERS',
      'event=close viewportGeneration=${_tellersViewport.generation} '
      'styleRequest=false',
      intervalMs: 1,
    );
    // Restore normal Mapbox/HUD opacity ownership once per transition.
    unawaited(
      _applyMapboxTaxiMarkerPresentationOpacity(source: 'tellers_close'),
    );
    // NAV-TELLERS-STREETLEVEL-SCREEN-UP-MARKER-1: leaving Tellers hands the
    // visible owner back to ordinary Navigation (Flutter HUD or hidden
    // Mapbox marker) — restore MAP alignment so any subsequent visible
    // Mapbox marker rotates with the road again. The next GPS tick writes
    // the pose bearing back through the legacy policy.
    unawaited(
      _reapplyDriverMarkerRotationPolicy(source: 'tellers_close'),
    );
    // NAV-RELEASE-SIMPLE-STREETLEVEL-1: returning to Navigatie restores the
    // single fixed streetlevel camera owner (no presentation re-init).
    if (_navCameraViewMode != NavCameraViewMode.streetView) {
      _navCameraViewMode = NavCameraViewMode.streetView;
    }
    _allowOverviewCamera = false;
    final pos = _lastPos;
    if (pos != null &&
        _cameraMode == _CameraMode.follow &&
        _liveRideActive) {
      unawaited(
        _followCameraTesla(pos, force: true, cameraReason: 'tellers_close'),
      );
    } else if (!_liveRideActive && _directRideDraft) {
      unawaited(
        _applyPreviewStreetlevelCameraIfEligible(reason: 'tellers_close'),
      );
    }
    if (!mounted) return;
    setState(() {});
  }

  Widget _buildTellersEntryChip({
    required ({Color accent, Color text, Color surface}) colors,
    required DriverCompactNavControlsLayout layout,
  }) {
    // Tablet / roomy layouts: icon + label. Constrained phone: icon + tooltip.
    final showLabel = layout.isTablet || layout.buttonVisualSize >= 48;
    final visual = layout.buttonVisualSize;
    final touch = layout.minTouchTarget;
    final label = driverTellersTitle(appConfig.currentLanguage);
    if (!showLabel) {
      return _buildCompactNavIconChip(
        icon: Icons.speed_outlined,
        tooltip: label,
        onPressed: _openTellersView,
        navAccent: colors.accent,
        navText: colors.text,
        navSurface: colors.surface,
        layout: layout,
      );
    }
    return SizedBox(
      height: touch,
      child: Tooltip(
        message: label,
        child: Material(
          color: colors.surface,
          borderRadius: BorderRadius.circular(12),
          child: InkWell(
            key: const ValueKey<String>('driver_tellers_open'),
            onTap: _openTellersView,
            borderRadius: BorderRadius.circular(12),
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 10),
              child: Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Icon(Icons.speed_outlined, size: layout.iconSize, color: colors.text),
                  const SizedBox(width: 6),
                  Text(
                    label,
                    style: TextStyle(
                      fontSize: visual >= 52 ? 14 : 12,
                      fontWeight: FontWeight.w800,
                      color: colors.text,
                    ),
                  ),
                ],
              ),
            ),
          ),
        ),
      ),
    );
  }

  /// TELLERS-LIVE-NAV-INSTRUCTION-OVERLAY-1: hands the Tellers live map the
  /// already-resolved maneuver presentation.
  ///
  /// Every input is the authoritative value the main navigation banner uses:
  /// `_effectiveNavInstructionSnapshot()` for the maneuver (including its
  /// roundabout exit number, arrival flag and reroute suppression),
  /// `_showNavInstructionBanner()` for the instruction gate, and
  /// `_routeStepsVersion` for the accepted route generation. A new route
  /// generation therefore replaces the whole Tellers view atomically instead
  /// of leaving a stale maneuver on the map.
  DriverTellersGuidanceView _resolveTellersGuidance() {
    final showInstruction = _showNavInstructionBanner();
    final snapshot = _effectiveNavInstructionSnapshot();
    return resolveDriverTellersGuidance(
      tellersActive: _navPresentationMode.isTellers,
      followCameraActive: _cameraMode == _CameraMode.follow,
      liveRideActive: _liveRideActive,
      showInstructionBanner: showInstruction,
      navStepsLoading: _navStepsLoading,
      isRerouting: _isRerouting,
      snapshotIsLoadingSource:
          snapshot.source == NavInstructionSource.loading,
      presentation: showInstruction
          ? buildResponsiveManeuverPresentation(
              snapshot: snapshot,
              tr: _tr,
              // The active customer language is the only source for the
              // sign language; device locale never overrides it.
              languageCode: currentLanguageCode,
              useCaptionedSign: _useCaptionedNavSigns,
            )
          : null,
      loadingText: _navLoadingBannerText(),
      routeVersion: _routeStepsVersion,
    );
  }

  Widget _buildTellersOverlay({
    required bool isTablet,
    required bool isLandscape,
  }) {
    final followLive = _cameraMode == _CameraMode.follow && _liveRideActive;
    // NAV-MOBILE-DATA-MINIMAL-SAFE-RELEASE-P0-1 Part E: seed the notifier
    // with the freshest authoritative snapshot at build time, then subscribe
    // via ValueListenableBuilder so subsequent meter ticks repaint ONLY the
    // meters subtree (the MapWidget subtree remains untouched).
    _driverRideMetersNotifier.publish(_buildDriverRideMetersSnapshot());
    return Positioned.fill(
      child: ValueListenableBuilder<DriverRideMetersSnapshot>(
        valueListenable: _driverRideMetersNotifier,
        builder: (context, snapshot, _) => DriverRideMetersView(
        // TELLERS-LIVE-NAV-INSTRUCTION-OVERLAY-1: the Tellers live map shows
        // the SAME maneuver the main navigation banner shows. Both read
        // _effectiveNavInstructionSnapshot() and the same gates in the same
        // build, so the two surfaces cannot disagree, and Tellers keeps no
        // route steps, maneuver index or exit number of its own.
        guidance: _resolveTellersGuidance(),
        snapshot: snapshot,
        themeListenable: _activeDriverThemeListenable,
        isTablet: isTablet,
        isLandscape: isLandscape,
        isWaiting: _isWaiting,
        // NAV-ORIENTATION-VIEWPORT-STABILITY-P0-1: forward the current
        // navigation viewport epoch so the DriverTellersGeometryLatch treats
        // the FIRST valid candidate after a portrait ↔ landscape flip as
        // unsettled — it must match a second consecutive candidate at the
        // same epoch before promoting a new committed Tellers geometry.
        viewportEpoch: _navViewportEpoch,
        // NAV-PARKING-2 Commit 4: reserve a transparent live-navigation window
        // over the single mounted MapWidget. No second MapWidget is created.
        showLiveWindow: true,
        // NAV-TELLERS-SINGLE-MAP-MARKER-OWNER-1: the single vehicle marker in
        // Tellers is the SAME Mapbox annotation ordinary Navigation owns,
        // projected at the Tellers marker anchor by the follow-camera padding.
        // No Flutter Car/Arrow child is painted inside the live window; the
        // param is retained on the widget's public API but has no visual
        // effect here (defense-in-depth false).
        showVehicleMarker: false,
        showMarkerSelector: followLive,
        markerChoice: _driverNavigationMarkerChoice,
        onMarkerChoiceSelected: _setDriverNavigationMarkerChoice,
        markerLanguage: appLanguageNotifier.value,
        onBackToNavigation: _closeTellersView,
        onStop: _liveRideActive ? _stopTrip : null,
        onToggleWait: _liveRideActive
            ? () {
                if (_isWaiting) {
                  _exitWaitMode();
                } else {
                  _enterWaitMode();
                }
              }
            : null,
        // NAV-TELLERS-RECENTER-CONTROL-1: existing authoritative recenter/
        // follow owner. Preserves View level + Tellers padding (applied inside
        // _followCameraTesla while Tellers is active). Idempotent when already
        // following. Does not leave Tellers or create a second camera/GPS owner.
        onRecenter: _liveRideActive ? () => unawaited(_centerOnMe()) : null,
      ),
      ),
    );
  }

  Widget _buildCompactNavIconChip({
    required IconData icon,
    required String tooltip,
    required VoidCallback onPressed,
    required Color navAccent,
    required Color navText,
    required Color navSurface,
    required DriverCompactNavControlsLayout layout,
  }) {
    final visual = layout.buttonVisualSize;
    final touch = layout.minTouchTarget;
    return SizedBox(
      width: touch,
      height: touch,
      child: Tooltip(
        message: tooltip,
        child: Material(
          color: navSurface,
          borderRadius: BorderRadius.circular(12),
          child: InkWell(
            onTap: onPressed,
            borderRadius: BorderRadius.circular(12),
            child: Center(
              child: Container(
                width: visual,
                height: visual,
                decoration: BoxDecoration(
                  borderRadius: BorderRadius.circular(12),
                  border: Border.all(
                    color: navAccent.withOpacity(0.72),
                    width: 1.1,
                  ),
                ),
                child: Icon(icon, size: layout.iconSize, color: navText),
              ),
            ),
          ),
        ),
      ),
    );
  }

  ({Color accent, Color text, Color surface}) _navActionThemeColors() {
    final isMidnightBlue =
        driverThemeNotifier.value == DriverThemeVariant.midnightBlue;
    final isMiddayGold =
        driverThemeNotifier.value == DriverThemeVariant.highContrast;
    return (
      accent: isMidnightBlue
          ? _midnightBlueAccent()
          : (isMiddayGold ? const Color(0xFFE8C57E) : kFluxidiYellow),
      text: isMidnightBlue
          ? _midnightBlueTextPrimary()
          : (isMiddayGold ? _middayGoldTextPrimary() : Colors.white),
      surface: isMidnightBlue
          ? const Color(0xCC07111F)
          : (isMiddayGold ? const Color(0xCC2C2113) : const Color(0xCC0B1326)),
    );
  }

  /// NAV-UI-R6F: compact icon-only map actions rendered inside the bottom
  /// cockpit bar during route preview / navigation: recenter, satellite,
  /// offline, diagnostics, more (Google/Waze expand from "more").
  List<Widget> _buildCockpitSecondaryActions({
    bool phoneLandscapeKpiPriorityCollapsed = false,
  }) {
    final hasExternal = _resolveExternalNavTarget() != null;
    // NAV-PRESTART-PREVIEW-AND-STABLE-BEARING-P0 (Problem 1): style + offline
    // entry are part of the pre-start preview, not only of an active ride. The
    // active-ride style *tap* stays blocked by [navStyleTapDecision]; hiding the
    // chip before START was what made the whole flow unusable.
    final navMapControls = _navMapControls;
    final showNavMapTools =
        _cameraMode == _CameraMode.follow ||
        _routeCoords.length >= 2 ||
        navMapControls.phase == NavMapSurfacePhase.preview;
    // NAV-RELEASE-FINAL-FLOW-1: style control available only while the
    // preview surface advertises styleSelector (before NAV/START). Locked
    // during active NAV guidance and the paid customer trip.
    final showMapStyleToggle =
        kDriverMapSatelliteToggleEnabled &&
        showNavMapTools &&
        navMapControls.styleSelector;
    final showOffline = showNavMapTools;
    final inFollowNav = _cameraMode == _CameraMode.follow;

    final colors = _navActionThemeColors();
    // NAV-PRESTART-FIELD-BLOCKER-3 (Problem D): classify by shortest side so
    // a wide phone in landscape (>=600 px width) still resolves the compact
    // phone metrics used by the map overlays. `classifyWidth` incorrectly
    // upgraded phone-landscape to tablet metrics, producing 64 px chips and
    // a taller secondary row that overlapped the +/- zoom column.
    final compactNavLayout = resolveDriverCompactNavControlsLayoutForNav(
      screenClass: FluxidiBreakpoints.classifyDeviceSize(
        MediaQuery.sizeOf(context),
      ),
      orientation: MediaQuery.of(context).orientation,
    );
    final isPhoneLandscape =
        !compactNavLayout.isTablet &&
        MediaQuery.of(context).orientation == Orientation.landscape;

    if (inFollowNav &&
        showOffline &&
        kUseNavigationWorker &&
        _routeCoords.length >= 2) {
      unawaited(_maybeFetchOfflineCorridorMetadata());
    }

    // NAV-MOBILE-LANDSCAPE-KPI-PRIORITY-AND-FIRST-3D-CHOICE-FIX-1: after the
    // existing X closes the action expansion, phone landscape retains only
    // the existing … entry point. This restores ETA/KM/fare width and keeps
    // stop/end + pause in CockpitWidget; all non-critical actions reopen from
    // this existing overflow path without deleting functionality.
    if (isPhoneLandscape && phoneLandscapeKpiPriorityCollapsed) {
      return <Widget>[
        _buildCompactNavIconChip(
          icon: Icons.more_horiz,
          tooltip: _tr(
            nl: 'Meer acties',
            en: 'More actions',
            fr: 'Plus d’actions',
            es: 'Mas acciones',
          ),
          onPressed: () {
            if (!mounted) return;
            setState(() {
              _phoneLandscapeKpiPriorityCollapsed = false;
              _navQuickActionsMoreExpanded = true;
            });
          },
          navAccent: colors.accent,
          navText: colors.text,
          navSurface: colors.surface,
          layout: compactNavLayout,
        ),
      ];
    }

    final chips = <Widget>[
      // NAV-PHASE-CAMERA-TARGET-1: the recenter chip is hidden in every
      // route phase. The fixed HUD contract owns the camera; a manual
      // recenter would rewrite zoom and target off the phase-fixed L7
      // Street Level profile.
      if (navPhaseRecenterVisible(phase: _navFixedHudPhase))
        _buildCompactNavIconChip(
          icon: Icons.my_location,
          tooltip: kCenterOnMeLabel,
          onPressed: _centerOnMe,
          navAccent: colors.accent,
          navText: colors.text,
          navSurface: colors.surface,
          layout: compactNavLayout,
        ),
    ];

    // NAV-RELEASE-SIMPLE-STREETLEVEL-1: presentation / cube / View-mode chips
    // removed. Fixed streetlevel owns the camera automatically.

    // NAV-PRESENTATION-COMPACT-BANNER-LANES-TELLERS-1: Tellers entry point.
    // Presentation mode only — does not touch GPS/fare/route ownership.
    if (inFollowNav || _liveRideActive) {
      chips.add(_buildTellersEntryChip(colors: colors, layout: compactNavLayout));
    }

    if (showMapStyleToggle) {
      if (kNavigation3dCockpitSceneEnabled) {
        chips.add(
          _buildDriverCockpitMapStyleMenuChip(
            colors: colors,
            layout: compactNavLayout,
          ),
        );
      } else {
        final isSatellite =
            _driverMapVisualMode == DriverMapVisualMode.satellite;
        chips.add(
          _buildCompactNavIconChip(
            icon: isSatellite
                ? Icons.map_outlined
                : Icons.satellite_alt_outlined,
            tooltip: isSatellite
                ? _tr(
                    nl: 'Terug naar kaartweergave',
                    en: 'Back to map view',
                    fr: 'Retour à la carte',
                    es: 'Volver al mapa',
                  )
                : _tr(
                    nl: 'Satellietweergave',
                    en: 'Satellite view',
                    fr: 'Vue satellite',
                    es: 'Vista satélite',
                  ),
            onPressed: _toggleDriverMapVisualMode,
            navAccent: colors.accent,
            navText: colors.text,
            navSurface: colors.surface,
            layout: compactNavLayout,
          ),
        );
      }
    }
    if (showOffline) {
      chips.add(
        _buildCompactNavIconChip(
          icon: Icons.wifi_off_rounded,
          // P0-FIELD-REPAIR-1 (C): "Offline kaarten" implied full offline
          // navigation. Only basemap tiles are downloadable; routing, search,
          // traffic and rerouting still require network.
          tooltip: _tr(
            nl: 'Offline kaarttegels',
            en: 'Offline map tiles',
            fr: 'Tuiles de carte hors ligne',
            es: 'Teselas de mapa sin conexión',
          ),
          onPressed: _openOfflineMaps,
          navAccent: colors.accent,
          navText: colors.text,
          navSurface: colors.surface,
          layout: compactNavLayout,
        ),
      );
    }
    // NAV-TELLERS-POSE-ANCHOR-AND-DIAGNOSTICS-UI-1: the visible navigation
    // diagnostics/log button has been removed from every driver navigation
    // toolbar (phone/tablet, portrait/landscape, debug/profile/release).
    // Internal diagnostics recording, PII-safe logs and the ADB/logcat output
    // remain untouched; `_shareNavDiagnostics` stays available for internal
    // export paths but is no longer surfaced as a driver-facing chip.
    if (hasExternal) {
      final moreExpanded = _navQuickActionsMoreExpanded;
      chips.add(
        _buildCompactNavIconChip(
          icon: moreExpanded ? Icons.close : Icons.more_horiz,
          tooltip: moreExpanded
              ? _tr(
                  nl: 'Minder acties',
                  en: 'Fewer actions',
                  fr: 'Moins d\u2019actions',
                  es: 'Menos acciones',
                )
              : _tr(
                  nl: 'Meer acties',
                  en: 'More actions',
                  fr: 'Plus d\u2019actions',
                  es: 'Mas acciones',
                ),
          onPressed: () {
            if (mounted) {
              setState(() {
                // The X is the existing collapse control. On phone landscape
                // it restores KPI priority instead of leaving the expanded
                // secondary-action row competing with ETA/KM/fare.
                if (isPhoneLandscape && moreExpanded) {
                  _navQuickActionsMoreExpanded = false;
                  _phoneLandscapeKpiPriorityCollapsed = true;
                } else {
                  _navQuickActionsMoreExpanded = !_navQuickActionsMoreExpanded;
                  _phoneLandscapeKpiPriorityCollapsed = false;
                }
              });
            } else {
              if (isPhoneLandscape && moreExpanded) {
                _navQuickActionsMoreExpanded = false;
                _phoneLandscapeKpiPriorityCollapsed = true;
              } else {
                _navQuickActionsMoreExpanded = !_navQuickActionsMoreExpanded;
                _phoneLandscapeKpiPriorityCollapsed = false;
              }
            }
          },
          navAccent: colors.accent,
          navText: colors.text,
          navSurface: colors.surface,
          layout: compactNavLayout,
        ),
      );
      if (moreExpanded) {
        chips.add(
          _buildCompactNavIconChip(
            icon: Icons.map,
            tooltip: _tr(
              nl: 'Google Maps + Fluxidi-teller',
              en: 'Google Maps + Fluxidi meter',
              fr: 'Google Maps + compteur Fluxidi',
              es: 'Google Maps + contador Fluxidi',
            ),
            onPressed: _openInGoogleMaps,
            navAccent: colors.accent,
            navText: colors.text,
            navSurface: colors.surface,
            layout: compactNavLayout,
          ),
        );
        chips.add(
          _buildCompactNavIconChip(
            icon: Icons.alt_route,
            tooltip: _tr(
              nl: 'Openen in Waze',
              en: 'Open in Waze',
              fr: 'Ouvrir dans Waze',
              es: 'Abrir en Waze',
            ),
            onPressed: _openInWaze,
            navAccent: colors.accent,
            navText: colors.text,
            navSurface: colors.surface,
            layout: compactNavLayout,
          ),
        );
      }
    }
    return chips;
  }

  Widget _buildDriverCockpitMapStyleMenuChip({
    required ({Color accent, Color text, Color surface}) colors,
    required DriverCompactNavControlsLayout layout,
  }) {
    final currentStyle = _driverCockpitMapVisualStyle;
    // NAV-ANNOTATION-MANAGER-TRANSACTIONAL-LIFECYCLE-2 / Phase 6: a bounded
    // busy state while a style transaction runs. Taps are also coalesced in
    // _setDriverCockpitMapVisualStyle (latest-wins), so disabling here just
    // avoids queueing visual churn.
    final busy = _styleSwapBusy;
