        return DriverCockpitMapVisualStyle.values.map((style) {
          return PopupMenuItem<DriverCockpitMapVisualStyle>(
            value: style,
            child: Row(
              children: [
                Icon(
                  _driverCockpitMapVisualStyleIcon(style),
                  size: 18,
                  color: style == currentStyle ? colors.accent : colors.text,
                ),
                const SizedBox(width: 10),
                Text(
                  _driverCockpitMapVisualStyleLabel(style),
                  style: TextStyle(
                    color: style == currentStyle ? colors.accent : colors.text,
                    fontWeight: style == currentStyle
                        ? FontWeight.w700
                        : FontWeight.w500,
                  ),
                ),
              ],
            ),
          );
        }).toList();
      },
      child: Tooltip(
        message: _tr(
          nl: 'Kaartstijl',
          en: 'Map style',
          fr: 'Style de carte',
          es: 'Estilo de mapa',
        ),
        child: SizedBox(
          width: layout.minTouchTarget,
          height: layout.minTouchTarget,
          child: Material(
            color: colors.surface,
            borderRadius: BorderRadius.circular(12),
            child: Center(
              child: Container(
                width: layout.buttonVisualSize,
                height: layout.buttonVisualSize,
                decoration: BoxDecoration(
                  borderRadius: BorderRadius.circular(12),
                  border: Border.all(
                    color: colors.accent.withOpacity(0.72),
                    width: 1.1,
                  ),
                ),
                child: busy
                    ? Center(
                        child: SizedBox(
                          width: layout.iconSize * 0.9,
                          height: layout.iconSize * 0.9,
