  /// NAV-UI-R6F: R9 tunnel / GPS-reacquire status chip shown centered above
  /// the cockpit bar during follow navigation.
  Widget _buildCockpitR9StatusChip() {
    final r9 = _navR9OfflineReadiness();
    _logNavR9Offline(state: r9.state, reason: r9.reason);
    if (_cameraMode != _CameraMode.follow) return const SizedBox.shrink();
    if (!r9.showTunnelChip && !r9.showGpsReacquireChip) {
      return const SizedBox.shrink();
    }
    final colors = _navActionThemeColors();
    return _buildNavR9DataOffStatusChip(
      showTunnelChip: r9.showTunnelChip,
      showGpsReacquireChip: r9.showGpsReacquireChip,
      navText: colors.text,
      navSurface: colors.surface,
      navAccent: colors.accent,
    );
  }

  // -------------------------------
  // ROUTE (Overview -> Follow)
  // -------------------------------

  Future<void> _buildOverviewRoute(BookingItem b) async {
    final epoch = _routeCleanupEpoch;
    final expectedBookingId = b.bookingId;
    if (!_isRouteTaskStillValid(
      epoch: epoch,
      expectedBookingId: expectedBookingId,
    )) {
      return;
    }
    if (!_mapSupported || _map == null) return;
    final endpoints = _extractPreviewEndpoints(b);
    final storedPickup = _usableNavLonLat(endpoints.pickup);
    final storedDropoff = _usableNavLonLat(endpoints.dropoff);
    final pickupText = (b.from ?? '').trim();
    final dropoffText = (b.to ?? '').trim();
    if (pickupText.isEmpty &&
        storedPickup == null &&
        dropoffText.isEmpty &&
        storedDropoff == null) {
      return;
    }
    if ((pickupText.isEmpty && storedPickup == null) ||
        (dropoffText.isEmpty && storedDropoff == null)) {
      return;
    }

    final request = _beginDriverRouteRequest(
      purpose: DriverRouteApplyPurpose.overview,
      expectedBookingId: expectedBookingId,
    );

    try {
      // NAV-SIGNAL-P0B1: never clear annotations for an active live route.
      // Prefer keeping the prior overview until a replacement activates.
      if (!mayClearOverviewAnnotations(liveRideActive: _liveRideActive)) {
        debugPrint(
          formatNavRouteApplyDiag(
            requestGeneration: request.requestGeneration,
            latestGeneration: _routeRequestGeneration.latest,
            accepted: false,
            reason: DriverRouteRejectReason.phaseChanged,
          ),
        );
        return;
      }

      if (storedPickup != null && storedDropoff != null) {
        debugPrint('[NAV_COORD] overview=stored_both');
        final package = await _directionsRoute(storedPickup, storedDropoff);
        if (_tryActivatePreparedDriverRoute(
          context: request,
          package: package,
        )) {
          final renderEpoch = _routeRenderEpoch;
          setState(() {
            _routePhase = _RideRoutePhase.trip;
          });
          await _drawPins(
            storedPickup,
            storedDropoff,
            routeRenderEpoch: renderEpoch,
          );
          await _drawRouteLine(
            _routeCoords,
            routeRenderEpoch: renderEpoch,
          );
          final allowFit =
              _allowOverviewCamera &&
              _cameraMode == _CameraMode.overview &&
              _activeTripId == null;
          if (allowFit && _isCurrentRouteRenderEpoch(renderEpoch)) {
            await _fitBoundsToRoute(_routeCoords);
          }
          return;
        }
      }

      // Prefer server-side routing (Worker) so the app never needs to call Mapbox Directions directly.
      await _tryWorkerRouteFallback(
        fromText: pickupText,
        toText: dropoffText,
        epoch: epoch,
        expectedBookingId: expectedBookingId,
        request: request,
      );
      if (_routeCoords.length >= 2) return;

      // Fallback: direct Mapbox REST (dev only). If MAPBOX_TOKEN isn't provided, we stop here.
      if (kMapboxToken.trim().isEmpty) {
        await _tryWorkerRouteFallback(
          fromText: pickupText,
          toText: dropoffText,
          epoch: epoch,
          expectedBookingId: expectedBookingId,
          request: request,
        );
        return;
      }

      final fromLL = await _resolvePickupLonLat(b);
      final toLL = await _resolveDropoffLonLat(b);

      final package = await _directionsRoute(fromLL, toLL);
      if (!_tryActivatePreparedDriverRoute(
        context: request,
        package: package,
      )) {
        return;
      }
      final renderEpoch = _routeRenderEpoch;
      setState(() {
        _routePhase = _RideRoutePhase.trip;
      });
      await _drawPins(fromLL, toLL, routeRenderEpoch: renderEpoch);
      await _drawRouteLine(
        _routeCoords,
        routeRenderEpoch: renderEpoch,
      );
      final allowFit =
          _allowOverviewCamera &&
          _cameraMode == _CameraMode.overview &&
          _activeTripId == null;
      if (allowFit && _isCurrentRouteRenderEpoch(renderEpoch)) {
        await _fitBoundsToRoute(_routeCoords);
      }
    } on _UnauthorizedMapbox catch (_) {
      _toast('Mapbox REST token refused (401) — using Worker route instead.');
      await _tryWorkerRouteFallback(
        fromText: b.from!,
        toText: b.to!,
        epoch: epoch,
        expectedBookingId: expectedBookingId,
        request: request,
      );
    } catch (e) {
      // NAV-DIRECTIONS-FAILURE-SECURITY-AND-RECOVERY-1: never toast the raw
      // exception (it carries the Mapbox URI + token + coordinates). Log a
      // redacted, coarse code only; the worker fallback runs next.
      _logNavBounded(
        'NAV_ROUTE_FAIL',
        'stage=overview code=${navRouteErrorCode(classifyNavRouteError(e))} '
            'detail=${redactNavRouteDiagnostic(e.toString())}',
        intervalMs: 1500,
      );
      await _tryWorkerRouteFallback(
        fromText: b.from!,
        toText: b.to!,
        epoch: epoch,
        expectedBookingId: expectedBookingId,
        request: request,
      );
    }
  }

  Future<void> _tryWorkerRouteFallback({
    required String fromText,
    required String toText,
    required int epoch,
    required String expectedBookingId,
    required DriverRouteRequestContext request,
  }) async {
    try {
      final uri = Uri.parse('$kWorkerBaseUrl$kWorkerRoutePath');
      final payload = {'from': fromText, 'to': toText};

      final res = await http
          .post(uri, headers: _driverBearerHeaders(), body: jsonEncode(payload))
          .timeout(const Duration(seconds: 12));

      if (res.statusCode == 404) {
        _toast(
          'Route via Worker not available yet (404). Implement $kWorkerRoutePath to avoid exposing Mapbox token.',
        );
        return;
      }

      if (res.statusCode != 200) {
        throw Exception('Worker route HTTP ${res.statusCode}: ${res.body}');
      }

      final j = jsonDecode(res.body) as Map<String, dynamic>;

      final coordsAny =
          (j['coords'] ?? j['coordinates'] ?? j['route_coords'] ?? j['points']);
      List<dynamic> raw;
      if (coordsAny is List) {
        raw = coordsAny;
      } else if (j['geometry'] is Map<String, dynamic>) {
        raw = (j['geometry']['coordinates'] as List<dynamic>? ?? []);
      } else {
        raw = const [];
      }

      final out = <_LonLat>[];
      for (final c in raw) {
        if (c is List && c.length >= 2) {
          out.add(_LonLat((c[0] as num).toDouble(), (c[1] as num).toDouble()));
        }
      }

      if (out.length < 2) return;
      if (!_isRouteTaskStillValid(
        epoch: epoch,
        expectedBookingId: expectedBookingId,
      )) {
        return;
      }

      final dist =
          (j['distance_m'] ?? j['distanceMeters'] ?? j['distance'] ?? 0) as num;
      final dur =
          (j['duration_s'] ?? j['durationSec'] ?? j['duration'] ?? 0) as num;

      // NAV-SIGNAL-P0B1: booking-worker fallback uses the same prepared-package
      // + atomic activation path (overview empty-steps only).
      final package = prepareBookingWorkerOverviewPackage(
        coords: out,
        distanceMeters: dist.toDouble(),
        durationSeconds: dur.toInt(),
      );
      if (!_tryActivatePreparedDriverRoute(
        context: request,
        package: package,
      )) {
        return;
      }
      final renderEpoch = _routeRenderEpoch;
      if (mounted) {
        setState(() {
          _routePhase = _RideRoutePhase.trip;
        });
      } else {
        _routePhase = _RideRoutePhase.trip;
      }
      final fromLL = out.first;
      final toLL = out.last;
      await _drawPins(fromLL, toLL, routeRenderEpoch: renderEpoch);
      await _drawRouteLine(out, routeRenderEpoch: renderEpoch);
      final allowFit =
          _allowOverviewCamera &&
          _cameraMode == _CameraMode.overview &&
          _activeTripId == null;
      if (allowFit && _isCurrentRouteRenderEpoch(renderEpoch)) {
        await _fitBoundsToRoute(out);
      }
    } catch (e) {
      // NAV-DIRECTIONS-FAILURE-SECURITY-AND-RECOVERY-1: sanitize — no raw
      // exception/body reaches the driver. Localized, concise copy only.
      _logNavBounded(
        'NAV_ROUTE_FAIL',
        'stage=worker_fallback '
            'code=${navRouteErrorCode(classifyNavRouteError(e))} '
            'detail=${redactNavRouteDiagnostic(e.toString())}',
        intervalMs: 1500,
      );
      _toast(navRouteErrorMessage(classifyNavRouteError(e), tr: _tr).message);
    }
  }

  Future<_LonLat> _geocodeOne(String query) async {
    final q = Uri.encodeComponent(query);
    final uri = Uri.parse(
      'https://api.mapbox.com/geocoding/v5/mapbox.places/$q.json'
      '?access_token=$kMapboxToken&limit=1&country=BE&language=nl',
    );

    final res = await http.get(uri).timeout(const Duration(seconds: 12));

    if (res.statusCode == 401) throw _UnauthorizedMapbox('geocoding');
    if (res.statusCode != 200) {
      throw Exception('Geocode HTTP ${res.statusCode}');
    }

    final j = jsonDecode(res.body) as Map<String, dynamic>;
    final feats = (j['features'] as List<dynamic>? ?? []);
    if (feats.isEmpty) throw Exception('No geocode result for "$query"');
    final center =
        (feats.first as Map<String, dynamic>)['center'] as List<dynamic>;
    final lon = (center[0] as num).toDouble();
    final lat = (center[1] as num).toDouble();
    return _LonLat(lon, lat);
  }

  double? _navRerouteHeadingDegForRequest() {
    if (!_isRerouting) return null;
    final fromCoordinator = _navRerouteCoordinator.requestOrigin?.headingDeg;
    if (fromCoordinator != null && fromCoordinator.isFinite) {
      return fromCoordinator;
    }
    final pos = _lastPos;
    if (pos != null && pos.heading.isFinite && pos.heading >= 0) {
      return pos.heading;
    }
    final movement = _lastMovementBearing;
    if (movement != null && movement.isFinite) return movement;
    return null;
  }

  /// NAV-SIGNAL-P0B: fetch+parse only. Never mutates active navigation state.
  Future<DriverPreparedRoutePackage> _directionsRoute(
    _LonLat from,
    _LonLat to,
  ) async {
    // NAV-REROUTE-CURRENT-POSITION-HEADING-P0: refresh origin/heading at send.
    var origin = from;
    if (_isRerouting) {
      final live = _navRerouteOriginFromLastPos();
      if (live != null) {
        _navRerouteCoordinator.requestOrigin = live;
        origin = _LonLat(live.longitude, live.latitude);
      }
    }
    final workerParsed = await _tryNavigationWorkerDirectionsRoute(origin, to);
    if (workerParsed != null) {
      if (_isRerouting) {
        _navRerouteCoordinator.noteResponseReceived(
          responseGeneration: _activeRerouteRequestGeneration,
        );
        _navRerouteCoordinator.noteRouteParsed(
          responseGeneration: _activeRerouteRequestGeneration,
        );
      }
      return prepareDriverRoutePackage(
        parsed: workerParsed,
        source: _isRerouting
            ? DriverRouteResponseSource.workerReroute
            : DriverRouteResponseSource.worker,
      );
    }

    final lang = _mapboxDirectionsLanguageCode();
    final uri = buildDriverDirectionsUri(
      from: origin,
      to: to,
      languageCode: lang,
      accessToken: kMapboxToken,
      originHeadingDeg: _navRerouteHeadingDegForRequest(),
    );

    final res = await http.get(uri).timeout(const Duration(seconds: 15));

    if (res.statusCode == 401) throw _UnauthorizedMapbox('directions');
    if (res.statusCode != 200) {
      throw Exception('Directions HTTP ${res.statusCode}');
    }

    final j = jsonDecode(res.body) as Map<String, dynamic>;
    final parsed = parseDriverDirectionsResponse(
      response: j,
      localizeInstruction: _localizeNavInstructionMvp,
      distanceAlongRouteForCoords: _distanceAlongRouteForCoords,
    );
    return prepareDriverRoutePackage(
      parsed: parsed,
      source: DriverRouteResponseSource.mapboxDirect,
    );
  }

  String _mapboxDirectionsLanguageCode() {
    // NAV-DIRECTIONS-FAILURE-SECURITY-AND-RECOVERY-1: single source of truth,
    // derived from the same active locale (`appLanguageNotifier`) the nav UI
    // uses via `_tr`, so the Directions request language always matches the UI.
    return mapboxDirectionsLanguageCode(appConfig.currentLanguage);
  }

  // NAV-DIRECTIONS-FAILURE-SECURITY-AND-RECOVERY-1 -----------------------------

  /// True when a valid route is currently applied (steps present). Distinguishes
  /// an *initial* failure (no route) from a *reroute* failure (old route stays
  /// authoritative).
  bool get _hasValidActiveRoute => _routeSteps.isNotEmpty;

  /// Central handler for a caught route/geocode request failure. NEVER logs or
  /// shows the raw exception, token, URI or coordinates. Sets the initial-failure
  /// state only when no valid route exists, and schedules bounded auto-retry.
  void _handleNavRouteRequestFailure(
    Object error, {
    required bool isReroute,
  }) {
    final kind = classifyNavRouteError(error);
    // Bounded, PII-free diagnostic: coarse code + redacted detail (no token,
    // URI, host or coordinates can survive redaction).
    _logNavBounded(
      'NAV_ROUTE_FAIL',
      'code=${navRouteErrorCode(kind)} reroute=$isReroute '
          'hasRoute=$_hasValidActiveRoute '
          'detail=${redactNavRouteDiagnostic(error.toString())}',
      intervalMs: 1500,
    );
    final copy = navRouteErrorMessage(kind, tr: _tr);
    if (isReroute && _hasValidActiveRoute) {
      // Reroute failure with an existing valid route: the old route, its version
      // and banner ownership remain authoritative. No driver popup — temporary
      // network/Directions failures must not interrupt active guidance
      // (FLUXIDI-EXTERNAL-NAV-FALLBACK-POPUP-LOOP-P0-1).
      return;
    }
    // Initial failure (no valid route): enter a sanitized connectivity/retry
    // state instead of a fabricated maneuver / generic "Follow the route" banner.
    if (mounted) {
      setState(() => _navRouteFailureKind = kind);
    } else {
      _navRouteFailureKind = kind;
    }
    _toast(copy.message);
    if (navRouteErrorIsRetryable(kind)) {
      _scheduleNavRouteRetry();
    }
  }

  void _clearNavRouteFailure() {
    _cancelNavRouteRetry();
    if (_navRouteFailureKind != null) {
      _navRouteFailureKind = null;
    }
    _navRouteRetryAttempt = 0;
  }

  void _cancelNavRouteRetry() {
    _navRouteRetryTimer?.cancel();
    _navRouteRetryTimer = null;
    // Invalidate any already-scheduled retry (latest-wins / stop-on-nav-end).
    _navRouteRetryGeneration++;
  }

  /// Schedules ONE bounded, latest-wins automatic retry. Never storms: each call
  /// cancels the prior pending retry, uses exponential backoff, and stops after
  /// [maxAutoRouteRetryAttempts] (the manual Retry action still works).
  void _scheduleNavRouteRetry() {
    _navRouteRetryTimer?.cancel();
    if (_navRouteRetryAttempt >= maxAutoRouteRetryAttempts) return;
    final delay = navRouteRetryBackoff(_navRouteRetryAttempt);
    final generation = ++_navRouteRetryGeneration;
    _navRouteRetryTimer = Timer(delay, () {
      if (!mounted) return;
      if (generation != _navRouteRetryGeneration) return; // stale request
      if (_navRouteFailureKind == null) return; // already recovered
      if (!_navRetryContextActive()) {
        _clearNavRouteFailure();
        return;
      }
      _navRouteRetryAttempt++;
      unawaited(_retryFailedNavRoute());
    });
  }

  /// Immediate manual retry from the connectivity banner ("Opnieuw proberen").
  Future<void> _retryFailedNavRouteManually() async {
    _cancelNavRouteRetry();
    _navRouteRetryAttempt = 0;
    await _retryFailedNavRoute();
  }

  /// Re-issues the current route request for the active navigation context. The
  /// builder's own catch re-schedules bounded auto-retry on repeated failure; a
  /// success clears the failure state. Cancels itself once navigation ends.
  Future<void> _retryFailedNavRoute() async {
    if (!_navRetryContextActive()) {
      _clearNavRouteFailure();
      return;
    }
    if (_directRideActive) {
      final destination = (_directRideDestinationText ?? '').trim();
      if (destination.isNotEmpty) {
        await _buildDirectRouteToDestination(destination);
      }
      return;
    }
    final booking = _activeBooking;
    if (booking == null) return;
    if (_routePhase == _RideRoutePhase.toPickup) {
      await _buildNavRouteToPickup(booking);
    } else if (_activeTripId != null) {
      await _buildNavRouteToDestination(booking);
    }
  }

  /// Whether a live navigation/route context still exists for retrying.
  bool _navRetryContextActive() {
    return _directRideActive || _activeTripId != null || _activeBooking != null;
  }

  String _navigationWorkerCountryCode() {
    const allowed = {'BE', 'NL', 'FR', 'ES', 'PT'};
    String? normalize(dynamic raw) {
      final text = raw?.toString().trim().toUpperCase();
      if (text == null || text.isEmpty) return null;
      if (allowed.contains(text)) return text;
      if (text.length >= 2) {
        final short = text.substring(0, 2);
        if (allowed.contains(short)) return short;
      }
      return null;
    }

    final booking = _activeBooking;
    if (booking != null) {
      final details = booking.details;
      final paths = <List<String>>[
        ['quote', 'inputs', 'country'],
        ['quote', 'country'],
        ['booking', 'country'],
        ['customer_country'],
        ['country'],
        ['record', 'payload', 'country'],
      ];
      for (final path in paths) {
        dynamic current = details;
        for (final key in path) {
          if (current is Map && current.containsKey(key)) {
            current = current[key];
          } else {
            current = null;
            break;
          }
        }
        final code = normalize(current);
        if (code != null) return code;
      }
    }
    return 'BE';
  }

  Future<DriverRouteParseResult?> _tryNavigationWorkerDirectionsRoute(
    _LonLat from,
    _LonLat to,
  ) async {
    if (!kUseNavigationWorker) return null;
    final baseUrl = kNavigationWorkerBaseUrl.trim();
    if (baseUrl.isEmpty) return null;

    final client = DriverNavigationWorkerClient(baseUrl: baseUrl);
    final country = _navigationWorkerCountryCode();
    // NAV-SIGNAL-P0A1: same UI language as direct Mapbox Directions path.
    final language = _mapboxDirectionsLanguageCode();
    final tripId = _activeTripId?.trim();

    NavigationWorkerRouteResult? workerResult;
    try {
      if (_isRerouting) {
        workerResult = await client.reroute(
          current: from,
          destination: to,
          country: country,
          tripId: tripId,
          reason: _rerouteReason ?? 'unknown',
          language: language,
          headingDeg: _navRerouteHeadingDegForRequest(),
        );
      } else {
        workerResult = await client.route(
          origin: from,
          destination: to,
          country: country,
          tripId: tripId,
          language: language,
        );
      }
    } catch (_) {
      debugPrint(
        '[CLOUD_NAV_2] endpoint=${_isRerouting ? 'reroute' : 'route'} '
        'result=fallback reason=worker_exception country=$country',
      );
      return null;
    }

    if (workerResult == null || !workerResult.isValid) {
      debugPrint(
        '[CLOUD_NAV_2] endpoint=${_isRerouting ? 'reroute' : 'route'} '
        'result=fallback reason=invalid_worker_payload country=$country',
      );
      return null;
    }

    final mapboxShape = workerResult.toMapboxDirectionsShape();
    // NAV-SIGNAL-P0A: bounded non-PII signaling counts (no coords/text).
    logNavSignalResponseSummary(
      summarizeNavSignalResponse(
        source: _isRerouting ? 'worker_reroute' : 'worker',
        mapboxShape: mapboxShape,
      ),
    );
    final parsed = parseDriverDirectionsResponse(
      response: mapboxShape,
      localizeInstruction: _localizeNavInstructionMvp,
      distanceAlongRouteForCoords: _distanceAlongRouteForCoords,
    );
    if (parsed.coords.length < 2) {
      debugPrint(
        '[CLOUD_NAV_2] endpoint=${_isRerouting ? 'reroute' : 'route'} '
        'result=fallback reason=parse_empty country=$country',
      );
      return null;
    }

    return parsed;
  }

  // NAV-SIGNAL-P0B: step application is only allowed via
  // `_tryActivatePreparedDriverRoute` (atomic with geometry).

  String _localizeNavInstructionMvp(String raw) {
    return localizeDriverNavInstructionMvp(
      raw: raw,
      languageCode: _mapboxDirectionsLanguageCode(),
      tr: _tr,
    );
  }

  String _nextRidePreviewCacheKey(BookingItem booking) {
    final bookingRowKey = booking.rowKey.trim();
    final from = (booking.from ?? '').trim().toLowerCase();
    final to = (booking.to ?? '').trim().toLowerCase();
    final pickupIso = (booking.pickupIso ?? '').trim();
    return '$bookingRowKey|$from|$to|$pickupIso';
  }

  Future<_RoutePreviewData?> _nextRidePreviewFuture(BookingItem booking) {
    final key = _nextRidePreviewCacheKey(booking);
    final cached = _nextRidePreviewCache[key];
    if (cached != null) return cached;
    final future = _loadNextRideRoutePreview(booking);
    _nextRidePreviewCache[key] = future;
    if (_nextRidePreviewCache.length > 16) {
      final oldestKey = _nextRidePreviewCache.keys.first;
      _nextRidePreviewCache.remove(oldestKey);
    }
    return future;
  }

  num? _previewNum(dynamic raw) {
    if (raw is num) return raw;
    if (raw is String) return num.tryParse(raw.trim().replaceAll(',', '.'));
    return null;
  }

  _LonLat? _previewPointFromDetailPaths(
    Map<String, dynamic> details,
    List<List<String>> latPaths,
    List<List<String>> lonPaths,
  ) {
    num? lat;
    num? lon;
    for (final path in latPaths) {
      final v = _previewNum(_getNested(details, path));
      if (v != null) {
        lat = v;
        break;
      }
    }
    for (final path in lonPaths) {
      final v = _previewNum(_getNested(details, path));
      if (v != null) {
        lon = v;
        break;
      }
    }
    if (lat == null || lon == null) return null;
    return _usableNavLonLat(_LonLat(lon.toDouble(), lat.toDouble()));
  }

  /// NAV-B: stored booking coordinates are preferred over geocoded address text.
  _LonLat? _usableNavLonLat(_LonLat? point) {
    if (point == null) return null;
    if (!point.lat.isFinite || !point.lon.isFinite) return null;
    if (point.lat.abs() > 90 || point.lon.abs() > 180) return null;
    if (point.lat == 0 && point.lon == 0) return null;
    return point;
  }

  Future<_LonLat> _resolvePickupLonLat(BookingItem booking) async {
    final stored = _usableNavLonLat(_extractPreviewEndpoints(booking).pickup);
    if (stored != null) {
      debugPrint('[NAV_COORD] pickup=stored');
      return stored;
    }
    final text = (booking.from ?? '').trim();
    if (text.isEmpty) {
      throw Exception('Pickup coordinates and address are missing.');
    }
    debugPrint('[NAV_COORD] pickup=geocode');
    return _geocodeOne(text);
  }

  Future<_LonLat> _resolveDropoffLonLat(BookingItem booking) async {
    final stored = _usableNavLonLat(_extractPreviewEndpoints(booking).dropoff);
    if (stored != null) {
      debugPrint('[NAV_COORD] dropoff=stored');
      return stored;
    }
    final text = (booking.to ?? '').trim();
    if (text.isEmpty) {
      throw Exception('Dropoff coordinates and address are missing.');
    }
    debugPrint('[NAV_COORD] dropoff=geocode');
    return _geocodeOne(text);
  }

  PlannedCanonicalEndpoints _resolvePlannedCanonicalEndpoints(
    BookingItem booking,
  ) {
    return PlannedBookingCanonicalDestinationResolver.resolve(
      bookingId: booking.bookingId,
      details: booking.details,
      fromLabel: booking.from,
      toLabel: booking.to,
    );
  }

  ({_LonLat? pickup, _LonLat? dropoff}) _extractPreviewEndpoints(
    BookingItem booking,
  ) {
    // PLANNED-BOOKING-CANONICAL-GMAPS-HANDOFF-P0-6: active leg coords beat
    // parent/quote package fields; never mix parent pickup with leg dropoff.
    final canonical = _resolvePlannedCanonicalEndpoints(booking);
    _LonLat? toLonLat(PlannedCanonicalEndpoint ep) {
      if (!ep.hasCoordinates) return null;
      return _usableNavLonLat(_LonLat(ep.longitude!, ep.latitude!));
    }
    return (
      pickup: toLonLat(canonical.pickup),
      dropoff: toLonLat(canonical.dropoff),
    );
  }

  Future<List<_LonLat>> _workerRouteForPreview({
    required String fromText,
    required String toText,
  }) async {
    if (fromText.trim().isEmpty || toText.trim().isEmpty)
      return const <_LonLat>[];
    final uri = Uri.parse('$kWorkerBaseUrl$kWorkerRoutePath');
    final payload = <String, dynamic>{
      'from': fromText.trim(),
      'to': toText.trim(),
    };
    final res = await http
        .post(uri, headers: _driverBearerHeaders(), body: jsonEncode(payload))
        .timeout(const Duration(seconds: 12));
    if (res.statusCode != 200) return const <_LonLat>[];
    final j = jsonDecode(res.body);
    if (j is! Map<String, dynamic>) return const <_LonLat>[];
    final coordsAny =
        (j['coords'] ?? j['coordinates'] ?? j['route_coords'] ?? j['points']);
    List<dynamic> raw = const <dynamic>[];
    if (coordsAny is List<dynamic>) {
      raw = coordsAny;
    } else if (j['geometry'] is Map<String, dynamic>) {
      raw =
          (j['geometry']['coordinates'] as List<dynamic>? ?? const <dynamic>[]);
    }
    final out = <_LonLat>[];
    for (final c in raw) {
      if (c is List && c.length >= 2) {
        final lon = _previewNum(c[0])?.toDouble();
        final lat = _previewNum(c[1])?.toDouble();
        if (lon != null && lat != null) out.add(_LonLat(lon, lat));
      }
    }
    return out.length >= 2 ? out : const <_LonLat>[];
  }

  Future<List<_LonLat>> _mapboxRouteForPreview({
    required _LonLat from,
    required _LonLat to,
  }) async {
    if (kMapboxToken.trim().isEmpty) return const <_LonLat>[];
    final coords = '${from.lon},${from.lat};${to.lon},${to.lat}';
    final uri = Uri.parse(
      'https://api.mapbox.com/directions/v5/mapbox/driving/$coords'
      '?alternatives=false&geometries=geojson&overview=full'
      '&access_token=$kMapboxToken',
    );
    final res = await http.get(uri).timeout(const Duration(seconds: 12));
    if (res.statusCode != 200) return const <_LonLat>[];
    final j = jsonDecode(res.body);
    if (j is! Map<String, dynamic>) return const <_LonLat>[];
    final routes = (j['routes'] as List<dynamic>? ?? const <dynamic>[]);
    if (routes.isEmpty) return const <_LonLat>[];
    final r0 = routes.first;
    if (r0 is! Map<String, dynamic>) return const <_LonLat>[];
    final geometry =
        (r0['geometry'] as Map<String, dynamic>? ?? const <String, dynamic>{});
    final line =
        (geometry['coordinates'] as List<dynamic>? ?? const <dynamic>[]);
    final out = <_LonLat>[];
    for (final c in line) {
      if (c is List && c.length >= 2) {
        final lon = _previewNum(c[0])?.toDouble();
        final lat = _previewNum(c[1])?.toDouble();
        if (lon != null && lat != null) out.add(_LonLat(lon, lat));
      }
    }
    return out.length >= 2 ? out : const <_LonLat>[];
  }

  List<_LonLat> _downsamplePreviewRoute(
    List<_LonLat> coords, {
    int maxPoints = 100,
  }) {
    if (coords.length <= maxPoints) return coords;
    final out = <_LonLat>[coords.first];
    final stride = (coords.length - 2) / (maxPoints - 2);
    var cursor = 1.0;
    while (out.length < maxPoints - 1) {
      final idx = cursor.round().clamp(1, coords.length - 2);
      out.add(coords[idx]);
      cursor += stride;
    }
    out.add(coords.last);
    return out;
  }

  String _encodePolyline5(List<_LonLat> points) {
    if (points.isEmpty) return '';
    final sb = StringBuffer();
    var lastLat = 0;
    var lastLon = 0;
    void encodeDelta(int delta) {
      var v = delta < 0 ? ~(delta << 1) : (delta << 1);
      while (v >= 0x20) {
        sb.writeCharCode((0x20 | (v & 0x1f)) + 63);
        v >>= 5;
      }
      sb.writeCharCode(v + 63);
    }

    for (final p in points) {
      final lat = (p.lat * 1e5).round();
      final lon = (p.lon * 1e5).round();
      encodeDelta(lat - lastLat);
      encodeDelta(lon - lastLon);
      lastLat = lat;
      lastLon = lon;
    }
    return sb.toString();
  }

  String _buildStaticRoutePreviewUrl({
    required List<_LonLat> route,
    required _LonLat pickup,
    required _LonLat dropoff,
  }) {
    final compact = _downsamplePreviewRoute(route, maxPoints: 92);
    final polyline = Uri.encodeComponent(_encodePolyline5(compact));
    final overlays =
        'pin-s-a+f4c542(${pickup.lon},${pickup.lat}),'
        'pin-s-b+ff5a4f(${dropoff.lon},${dropoff.lat}),'
        'path-5+2d8cff-0.86($polyline)';
    return 'https://api.mapbox.com/styles/v1/mapbox/navigation-night-v1/static/'
        '$overlays/auto/720x280?padding=34,22,34,22&access_token=$kMapboxToken';
  }

  Future<_RoutePreviewData?> _loadNextRideRoutePreview(
    BookingItem booking,
  ) async {
    if (kMapboxToken.trim().isEmpty) return null;
    final fromText = (booking.from ?? '').trim();
    final toText = (booking.to ?? '').trim();
    if (fromText.isEmpty || toText.isEmpty) return null;

    final endpoints = _extractPreviewEndpoints(booking);
    _LonLat? pickup = endpoints.pickup;
    _LonLat? dropoff = endpoints.dropoff;

    List<_LonLat> routeCoords = await _workerRouteForPreview(
      fromText: fromText,
      toText: toText,
    );
    if (routeCoords.isNotEmpty) {
      pickup ??= routeCoords.first;
      dropoff ??= routeCoords.last;
    }

    if ((pickup == null || dropoff == null) && kMapboxToken.trim().isNotEmpty) {
      try {
        pickup ??= await _geocodeOne(fromText);
        dropoff ??= await _geocodeOne(toText);
      } catch (_) {}
    }
    if (pickup == null || dropoff == null) return null;

    if (routeCoords.length < 2) {
      routeCoords = await _mapboxRouteForPreview(from: pickup, to: dropoff);
    }
    if (routeCoords.length < 2) return null;

    final staticUrl = _buildStaticRoutePreviewUrl(
      route: routeCoords,
      pickup: pickup,
      dropoff: dropoff,
    );
    return _RoutePreviewData(
      staticMapUrl: staticUrl,
      routePointCount: routeCoords.length,
    );
  }

