  Future<void> _drawPins(
    _LonLat pickup,
    _LonLat dropoff, {
    int? routeRenderEpoch,
  }) async {
    final drawEpoch = routeRenderEpoch ?? _routeRenderEpoch;
    final drawSession = _navigationSessionGeneration;
    final mgr = _pinsPointManager;
    if (mgr == null) return;
    if (!_isCurrentRouteRenderEpoch(drawEpoch)) return;
    final now = DateTime.now();
    final signature = driverPinsDrawSignature(pickup: pickup, dropoff: dropoff);
    if (driverShouldSkipDraw(
      signature: signature,
      lastSignature: _lastPinsDrawSignature,
      lastDrawAt: _lastPinsDrawAt,
      debounce: _routeDrawDebounce,
      now: now,
    )) {
      return;
    }

    // Capture previous shared refs; do not delete until commit.
    final previousPickup = _pickupPin;
    final previousDropoff = _dropoffPin;

    // NAV-ANNOTATION-MANAGER-TRANSACTIONAL-LIFECYCLE-2: pin creates + orphan
    // deletes under one lease; disposal awaits it before removeAnnotationManager.
    final draw = await _runAnnotationTx<bool>(
      gate: _pinsAnnotationGate,
      kind: NavAnnotationOperationKind.create,
      nativeOp: () async {
        final pickupPin = await mgr.create(
          mb.PointAnnotationOptions(
            geometry: _mbPoint(pickup.lon, pickup.lat),
            iconSize: 1.1,
          ),
        );
        final dropoffPin = await mgr.create(
          mb.PointAnnotationOptions(
            geometry: _mbPoint(dropoff.lon, dropoff.lat),
            iconSize: 1.1,
          ),
        );
        final commit = evaluateRouteAnnotationCommit(
          capturedRenderEpoch: drawEpoch,
          currentRenderEpoch: _routeRenderEpoch,
          capturedSessionGeneration: drawSession,
          currentSessionGeneration: _navigationSessionGeneration,
        );
        if (commit.shouldDeleteLocalOrphansOnly) {
          await mgr.delete(pickupPin);
          await mgr.delete(dropoffPin);
          _logNavRouteRenderOwner(
            event: NavRouteRenderOwnerEvent.staleCallbackIgnored,
            rejectionReason: 'render_epoch_or_session_mismatch',
          );
          _logNavAnnotationTx(
            gate: _pinsAnnotationGate,
            event: NavAnnotationTxEvent.commitRejected,
            operation: NavAnnotationOperationKind.create,
          );
          return false;
        }
        _pickupPin = pickupPin;
        _dropoffPin = dropoffPin;
        _lastPinsDrawSignature = signature;
        _lastPinsDrawAt = now;
        _logNavAnnotationTx(
          gate: _pinsAnnotationGate,
          event: NavAnnotationTxEvent.commitAllowed,
          operation: NavAnnotationOperationKind.create,
        );
        if (previousPickup != null && !identical(previousPickup, pickupPin)) {
          await mgr.delete(previousPickup);
        }
        if (previousDropoff != null &&
            !identical(previousDropoff, dropoffPin)) {
          await mgr.delete(previousDropoff);
        }
        return true;
      },
    );
    if (!draw.ran) {
      _logNavAnnotationManager(
        gate: _pinsAnnotationGate,
        event: 'stale_operation_rejected',
        operation: NavAnnotationOperationKind.create,
        reason: draw.rejectReason,
      );
    }
  }

  Future<void> _drawRouteLine(
    List<_LonLat> coords, {
    bool force = false,
    List<_LonLat>? completedCoords,
    int? routeRenderEpoch,
    bool preferInPlaceUpdate = false,
  }) async {
    final drawEpoch = routeRenderEpoch ?? _routeRenderEpoch;
    final drawSession = _navigationSessionGeneration;
    final mgr = _routeLineManager;
    if (mgr == null) return;
    if (coords.length < 2) return;
    if (!_isCurrentRouteRenderEpoch(drawEpoch)) return;
    final now = DateTime.now();
    final signature = driverRouteDrawSignature(coords);
    if (driverShouldSkipDraw(
      signature: signature,
      lastSignature: _lastRouteDrawSignature,
      lastDrawAt: _lastRouteDrawAt,
      debounce: _routeDrawDebounce,
      force: force || preferInPlaceUpdate,
      now: now,
    )) {
      return;
    }

    final geometry = mb.LineString(
      coordinates: coords.map((c) => mb.Position(c.lon, c.lat)).toList(),
    );

    // PART C: trim/progress updates reuse existing polyline annotations.
    // Reroute / first draw still recreate (preferInPlaceUpdate=false).
    if (preferInPlaceUpdate &&
        _routeLine != null &&
        _routeLineOutline != null &&
        _isCurrentRouteRenderEpoch(drawEpoch)) {
      final update = await _runAnnotationTx<bool>(
        gate: _routeAnnotationGate,
        kind: NavAnnotationOperationKind.update,
        nativeOp: () async {
          if (!_isCurrentRouteRenderEpoch(drawEpoch)) return false;
          if (_navigationSessionGeneration != drawSession) return false;
          final line = _routeLine;
          final outline = _routeLineOutline;
          if (line == null || outline == null) return false;
          line.geometry = geometry;
          outline.geometry = geometry;
          await mgr.update(line);
          await mgr.update(outline);
          final completed = _routeLineCompleted;
          if (completedCoords != null &&
              completedCoords.length >= 2 &&
              completed != null) {
            completed.geometry = mb.LineString(
              coordinates: completedCoords
                  .map((c) => mb.Position(c.lon, c.lat))
                  .toList(),
            );
            await mgr.update(completed);
          }
          if (!_isCurrentRouteRenderEpoch(drawEpoch)) return false;
          _lastRouteDrawSignature = signature;
          _lastRouteDrawAt = now;
          return true;
        },
      );
      if (update.ran && update.value == true) {
        _logNavBounded(
          'NAV_OS_R2_ROUTE_PROGRESS_LINE',
          'write=update_in_place points=${coords.length}',
        );
        return;
      }
      // Fall through to recreate when in-place update is rejected.
    }

    // NAV-SIGNAL-P0B1: operation-owned creates; shared refs untouched until commit.
    final previousOutline = _routeLineOutline;
    final previousLine = _routeLine;
    final previousCompleted = _routeLineCompleted;

    // NAV-ANNOTATION-MANAGER-TRANSACTIONAL-LIFECYCLE-2: all route-line native
    // creates AND their orphan/previous deletes run under ONE lease. Disposal
    // (style swap) waits for this lease before removeAnnotationManager, so no
    // create can reach a removed manager; a draining/stale generation rejects
    // the whole block before the first native call.
    final draw = await _runAnnotationTx<bool>(
      gate: _routeAnnotationGate,
      kind: NavAnnotationOperationKind.create,
      nativeOp: () async {
        // NAV-OS-R2: muted grey line for the already-driven section.
        mb.PolylineAnnotation? completedLine;
        if (completedCoords != null && completedCoords.length >= 2) {
          completedLine = await mgr.create(
            mb.PolylineAnnotationOptions(
              geometry: mb.LineString(
                coordinates: completedCoords
                    .map((c) => mb.Position(c.lon, c.lat))
                    .toList(),
              ),
              lineWidth: kDriverRouteLineCompletedWidth,
              lineOpacity: kDriverRouteLineCompletedOpacity,
              lineColor: kDriverRouteLineCompletedColor,
            ),
          );
        }

        // Dark underlay for contrast on light navigation / satellite maps.
        final outline = await mgr.create(
          mb.PolylineAnnotationOptions(
            geometry: geometry,
            lineWidth: kDriverRouteLineOutlineWidth,
            lineOpacity: kDriverRouteLineOutlineOpacity,
            lineColor: kDriverRouteLineOutlineColor,
          ),
        );

        final line = await mgr.create(
          mb.PolylineAnnotationOptions(
            geometry: geometry,
            lineWidth: kDriverRouteLineWidth,
            lineOpacity: kDriverRouteLineOpacity,
            lineColor: kDriverRouteLineColor,
          ),
        );
        final commit = evaluateRouteAnnotationCommit(
          capturedRenderEpoch: drawEpoch,
          currentRenderEpoch: _routeRenderEpoch,
          capturedSessionGeneration: drawSession,
          currentSessionGeneration: _navigationSessionGeneration,
        );
        if (commit.shouldDeleteLocalOrphansOnly) {
          // Ownership advanced during create: never commit these handles.
          // The manager is still alive under this lease, so removing the
          // just-created orphans is safe (no crash) and prevents leaks.
          // NAV-ANNOTATION-LIFECYCLE-REPAIR-1: idempotent deletes (never throw).
          await _safeDeleteRoutePolylines(
            <mb.PolylineAnnotation?>[completedLine, outline, line],
            mgr: mgr,
            reason: 'orphan_after_stale_commit',
          );
          _logNavRouteRenderOwner(
            event: NavRouteRenderOwnerEvent.staleCallbackIgnored,
            rejectionReason: 'render_epoch_or_session_mismatch',
          );
          _logNavAnnotationTx(
            gate: _routeAnnotationGate,
            event: NavAnnotationTxEvent.commitRejected,
            operation: NavAnnotationOperationKind.create,
          );
          return false;
        }
        _routeLineCompleted = completedLine;
        _routeLineOutline = outline;
        _routeLine = line;
        _lastRouteDrawSignature = signature;
        _lastRouteDrawAt = now;
        _routeRedrawCountThisMinute += 1;
        _logNavAnnotationTx(
          gate: _routeAnnotationGate,
          event: NavAnnotationTxEvent.commitAllowed,
          operation: NavAnnotationOperationKind.create,
        );
        // Delete previous generation only — never the just-committed handles.
        // Stale overlapping clears that already removed these ids are no-ops.
        final previousToDelete = <mb.PolylineAnnotation?>[
          if (previousOutline != null && !identical(previousOutline, outline))
            previousOutline,
          if (previousLine != null && !identical(previousLine, line))
            previousLine,
          if (previousCompleted != null &&
              !identical(previousCompleted, completedLine))
            previousCompleted,
        ];
        if (previousToDelete.isNotEmpty) {
          await _safeDeleteRoutePolylines(
            previousToDelete,
            mgr: mgr,
            reason: 'replace_previous_route',
          );
        }
        return true;
      },
    );
    if (!draw.ran) {
      _logNavAnnotationManager(
        gate: _routeAnnotationGate,
        event: 'stale_operation_rejected',
        operation: NavAnnotationOperationKind.create,
        reason: draw.rejectReason,
      );
      return;
    }
    await _syncMapboxUserLocationPuckVisibility();
  }

  Future<void> _fitBoundsToRoute(List<_LonLat> coords) async {
    // NAV-RELEASE-FINAL-FLOW-1: fixed streetlevel owns the camera whenever a
    // destination draft, prepared booking, or live ride exists. fitBounds is
    // a no-op — overview framing must never take ownership.
    if (fixedStreetLevelOwnsCamera(
          hasPreviewDraft: _fixedStreetLevelPreviewDraft,
          liveRideActive: _liveRideActive || _navigationGuidanceActive,
        ) ||
        _cameraMode == _CameraMode.follow ||
        _activeTripId != null ||
        !_allowOverviewCamera ||
        _navCameraViewMode == NavCameraViewMode.streetView ||
        !mayOverviewFitBoundsInPreview(
          allowOverviewCamera: _allowOverviewCamera,
          selectedViewMode: _navPreviewViewModeToken(),
          liveRideActive: _liveRideActive,
        )) {
      return;
    }
    if (_map == null || coords.isEmpty) return;

    double minLon = coords.first.lon, maxLon = coords.first.lon;
    double minLat = coords.first.lat, maxLat = coords.first.lat;
    for (final c in coords) {
      if (c.lon < minLon) minLon = c.lon;
      if (c.lon > maxLon) maxLon = c.lon;
      if (c.lat < minLat) minLat = c.lat;
      if (c.lat > maxLat) maxLat = c.lat;
    }

    final topPad = MediaQuery.of(context).padding.top + 86;
    final bottomPad = MediaQuery.of(context).padding.bottom + 210;

    try {
      final cam = await _map!.cameraForCoordinateBounds(
        mb.CoordinateBounds(
          southwest: _mbPoint(minLon, minLat),
          northeast: _mbPoint(maxLon, maxLat),
          infiniteBounds: false,
        ),
        mb.MbxEdgeInsets(top: topPad, left: 40, bottom: bottomPad, right: 40),
        null,
        null,
        null,
        null,
      );
      await _map!.flyTo(cam, mb.MapAnimationOptions(duration: 900));
    } catch (_) {
      final center = _mbPoint((minLon + maxLon) / 2, (minLat + maxLat) / 2);
      await _map!.flyTo(
        mb.CameraOptions(center: center, zoom: 12.5),
        mb.MapAnimationOptions(duration: 900),
      );
    }
  }

  void _markBootFirstLoadDone() {
    if (_bootFirstLoadDone) return;
    _bootFirstLoadDone = true;
    _maybeHideBootSplash();
  }

  void _maybeHideBootSplash() {
    if (!_bootSplashVisible) return;
    if (!_bootMinElapsed) return;
    if (!_bootFirstLoadDone) return;
    if (!mounted) return;
    setState(() {
      _bootSplashVisible = false;
      _showBootSplash = false;
    });
  }

