  String _hintPanelText() {
    final lang = appConfig.currentLanguage;
    if (lang == AppLanguage.en) {
      return 'Open menu -> Bookings to choose a ride and start it to drive.';
    }
    if (lang == AppLanguage.fr) {
      return 'Ouvrez le menu -> Courses pour choisir une course et la demarrer.';
    }
    if (lang == AppLanguage.es) {
      return 'Abre el menu -> Reservas para elegir un viaje e iniciarlo.';
    }
    return 'Open menu -> Ritten om een rit te kiezen en start hem om te rijden.';
  }

  @override
  Widget build(BuildContext context) {
    // EXTERNAL-NAV-RETURN-LIFECYCLE-P0-7: while Android PiP is active, overlay
    // the compact meter card but KEEP the Mapbox MapWidget mounted (Offstage).
    // Field evidence SM-X400: swapping the tree to meter-only disposed
    // annotation managers while GPS/nav still called update → fatal
    // "No manager found with id" → process death → PIN cold start → lost ride.
    final externalPip = _externalNavigationSession;
    final pipActive = externalPip != null && externalPip.pipActive;

    // SECURITY-REMOVE-CLIENT-ADMIN-TOKEN-P0-1 (Field Failure Fix, Blocker Fix):
    // `build()` must NOT publish `operatorMintedBearerInFlightNotifier`.
    // The global lifecycle notifier is updated only at explicit state
    // transitions (initState/hydration, ride START/STOP, teardown
    // enter/finally, reconcile enter/exit, mint enter/exit, dispose).
    // Mutating a `ValueNotifier` from `build()` couples render scheduling
    // to global state and can leave the notifier `true` after unmount or
    // stale-response drops. See `_publishBearerBusyState` doc comment for
    // the exhaustive transition list.
    final now = DateTime.now();
    final lastBuildLog = _lastDriverBuildLogAt;
    if (lastBuildLog == null || now.difference(lastBuildLog).inSeconds >= 5) {
      _lastDriverBuildLogAt = now;
      debugPrint(
        '[DRIVER][BUILD] live=$_liveRideActive mode=$_cameraMode loadingBookings=$_loadingBookings',
      );
    }
    final bool liveActive = _liveRideActive;
    final bool hasSelection = _activeBooking != null;
    final bool hasDirectDraft = _directRideDraft;
    final int state = liveActive
        ? 2
        : ((hasSelection || hasDirectDraft) ? 1 : 0);
    final bool showCockpit = liveActive || hasSelection || hasDirectDraft;
    // NAV-TELLERS-COMPOSITION-CORRECTION-1: one HUD at a time. While Tellers is
    // active the normal navigation cockpit HUD (top strip, banners, screen-fixed
    // arrow, recenter, camera/zoom/marker controls, bottom KPI + nav controls)
    // is fully suppressed so nothing shows through beneath the Tellers HUD. The
    // MapWidget, GPS, route progress, camera, fare and timers stay live.
    final bool tellersActive = _navPresentationMode.isTellers;
    final bool followLiveActiveForHud =
        _cameraMode == _CameraMode.follow && _liveRideActive;
    final navPresentationForHud = _navigationPresentationStateFor(
      _navCameraViewMode,
    );
    final DriverNavHudVisibility hudVisibility = DriverNavHudVisibility.resolve(
      showCockpit: showCockpit,
      cameraFollow: _cameraMode == _CameraMode.follow,
      tellersActive: tellersActive,
      followLiveActive: followLiveActiveForHud,
      showDriverHudOverlay: navPresentationForHud.showDriverHudOverlay,
    );
    final bool cockpitHudVisible = hudVisibility.cockpitHud;
    final bool navHudVisible =
        hudVisibility.navBannerHud && !_externalNavGuidanceSuppressed;
    // NAV-PRESTART-PREVIEW-AND-STABLE-BEARING-P0 (Problem 1): the pre-start
    // preview surface owns the map actions row. Previously this required follow
    // mode or an already-built route, both of which only existed after START.
    final navMapControls = _navMapControls;
    final bool previewPhase =
        navMapControls.phase == NavMapSurfacePhase.preview;
    final bool showNavQuickActions =
        showCockpit &&
        (_cameraMode == _CameraMode.follow ||
            previewPhase ||
            _resolveExternalNavTarget() != null ||
            _routeCoords.length >= 2);
    final screenH = MediaQuery.of(context).size.height;
    final screenW = MediaQuery.of(context).size.width;
    // NAV-MOBILE-COMPACT-CONTROLS-UNIFY-LANDSCAPE-1: classify form factor by
    // the shortest side. A landscape phone can be 600+ logical px wide but
    // must keep the exact same compact phone controls as portrait.
    final screenClass = FluxidiBreakpoints.classifyDeviceSize(
      Size(screenW, screenH),
    );
    final bool isTablet =
        screenClass == FluxidiScreenClass.tablet ||
        screenClass == FluxidiScreenClass.desktop;
    final bool isLandscape =
        MediaQuery.of(context).orientation == Orientation.landscape;
    // NAV-SIGNAGE-TABLET-READABILITY-1: shortestSide >= 600 only. Phones keep
    // the historic below-logo portrait banner and smaller top-row metrics.
    final bool navSignageTablet = isNavSignageTabletLayout(
      Size(screenW, screenH),
    );
    // NAV-ORIENTATION-VIEWPORT-STABILITY-P0-1: observe the current navigation
    // viewport before any downstream geometry/camera work so a materially
    // changed viewport bumps [_navViewportEpoch] and invalidates cached
    // camera state (streetlevel follow padding + pending Tellers anchor)
    // exactly once per settled transition.
    _observeNavViewport(
      size: Size(screenW, screenH),
      isLandscape: isLandscape,
    );
    // NAV-TELLERS-EXACT-LIVE-VIEWPORT-1: portrait ↔ landscape recalculates the
    // authoritative liveWindowRect once (latest-wins camera), no MapWidget/
    // GPS/style recreation.
    _syncTellersGeometryForOrientation(isLandscape: isLandscape);
    final bool collapseTopBarInLandscapeNav =
        isLandscape && _cameraMode == _CameraMode.follow;
    final bool collapseTopBarInPortraitNav =
        !isLandscape && _cameraMode == _CameraMode.follow;
    final double arrowBottom = isLandscape ? 88.0 : 138.0;
    final double safeBottomInset = MediaQuery.of(context).padding.bottom;
    // NAV-UI-R6F: floating recenter only exists outside route/nav context
    // (map actions are inside the cockpit bar there).
    final double recenterBottom = isLandscape
        ? (showCockpit ? 96.0 : 80.0) + safeBottomInset
        : (showCockpit ? 148.0 : 120.0) + safeBottomInset;
    final double navBannerPortraitMaxWidth = math.min(
      screenW * (isTablet ? 0.94 : 0.92),
      isTablet ? 820.0 : 700.0,
    );
    final bool collapsedNavHeader =
        collapseTopBarInLandscapeNav || collapseTopBarInPortraitNav;
    final double navBannerTop =
        MediaQuery.of(context).padding.top + (collapsedNavHeader ? 58 : 74);
    final bool hideMapUserPuck = _shouldHideMapboxUserLocationPuck();
    // NAV-PRESTART-FIELD-BLOCKER-3 (Problem B + Problem C): decide the
    // pre-start preview presentation explicitly. Before this the build folded
    // every non-live combination into overview, so the driver could never
    // reach streetlevel before START. The decision keeps overview during
    // live rides (that path is unchanged) but promotes preview streetlevel
    // to the driver cockpit presentation.
    final navPreviewDecision = decideNavPreviewPresentation(
      NavPreviewPresentationInputs(
        // NAV-FIXED-HUD-PRESENTATION-1: a prepared *booking* is a preview
        // draft too. Passing only the street draft folded prepared bookings
        // into overview, so they never reached the driver cockpit
        // presentation and could not mount the screen-fixed HUD.
        hasPreviewDraft: _fixedStreetLevelPreviewDraft,
        selectedViewMode: _navPreviewViewModeToken(),
        routePointCount: _routeCoords.length,
        liveRideActive: liveActive,
      ),
    );
    final NavigationPresentationState navPresentationState =
        _navFixedHudPresentationActive
            ? _navigationPresentationStateFor(_navCameraViewMode)
            : (navPreviewDecision.isStreetLevel
                ? _navigationPresentationStateFor(NavCameraViewMode.streetView)
                : _navigationPresentationStateFor(NavCameraViewMode.overview));
    // NAV-VEHICLE-MODE-CAR-ARROW-1 (Phase 7): in Street Level (driver cockpit)
    // mode the marker sits just above the KPI meters, derived from the real
    // KPI panel layout. The resolved offset is shared with the cockpit camera
    // nose anchor (see [_driverCockpitCameraOverrides]) so marker and camera
    // move together and switching Car ↔ Arrow never shifts either.
    final bool streetLevelCockpit = showCockpit &&
        navPresentationState.useDriverCockpitCamera &&
        navPresentationState.mode == NavigationPresentationMode.driver;
    final kpiNavControlsLayout = resolveDriverCompactNavControlsLayoutForNav(
      screenClass: screenClass,
      orientation:
          isLandscape ? Orientation.landscape : Orientation.portrait,
    );
    // NAV-CAMERA-FIELD-REGRESSION-1: include the fare-estimate panel in the
    // streetlevel nose-anchor / marker bottom offset so the vehicle clears
    // the same chrome the View-column bottomStripReserve already reserves.
    const double kDirectRideEstimatePanelReserveForAnchor = 96.0;
    final bool estimatePanelForAnchor =
        hasDirectDraft &&
        _activeBooking == null &&
        (_directRideDestinationText ?? '').trim().isNotEmpty;
    final double? streetLevelHudBottomOffset = streetLevelCockpit
        ? resolveStreetLevelMarkerBottomOffset(
            isLandscape: isLandscape,
            hasSecondaryActions: showNavQuickActions,
            secondaryActionRowHeight: kpiNavControlsLayout.rowHeight,
            primaryToSecondaryGap:
                kpiNavControlsLayout.primaryToSecondaryGap,
            extraBottomChrome: estimatePanelForAnchor
                ? kDirectRideEstimatePanelReserveForAnchor
                : 0.0,
          )
        : null;
    _streetLevelHudBottomOffset = streetLevelHudBottomOffset;
    final double driverHudBottom = streetLevelHudBottomOffset != null
        ? streetLevelHudBottomOffset + safeBottomInset
        : (showCockpit
            ? driverCockpitFixedHudBottomOffset(
                    isLandscape: isLandscape,
                    cockpitChaseCamera:
                        navPresentationState.useDriverCockpitCamera,
                    isTablet: isTablet,
                  ) +
                  safeBottomInset
            : arrowBottom);
    final double driverHudIconSize = navPresentationState.showDriverHudOverlay
        ? NavigationDriverHudOverlay.resolveIconSize(
            // NAV-PHONE-LANDSCAPE-MARKER-SCALE-1: pass both axes so phone
            // landscape is classified by shortestSide, not wide width.
            screenWidth: screenW,
            screenHeight: screenH,
            cockpitBoost: navPresentationState.useDriverCockpitCamera,
            viewLevel: _driverCockpitViewLevel,
          )
        : 56.0;
    // NAV-MARKER-ARROW-RESPONSIVE-SCALE-1: arrow-only responsive scale. Auto
    // and the camera nose-anchor keep [driverHudIconSize] unchanged so the
    // Street Level bottom anchor and Car ↔ Arrow camera stay stable.
    final double driverHudArrowScale = resolveDriverNavigationArrowScale(
      viewportWidth: screenW,
      viewportHeight: screenH,
      isTablet: isTablet,
      orientation: isLandscape
          ? Orientation.landscape
          : Orientation.portrait,
      presentationMode: navPresentationState.mode,
    );
    if (_cameraMode == _CameraMode.follow &&
        liveActive &&
        navPresentationState.useDriverCockpitCamera &&
        navPresentationState.showDriverHudOverlay) {
      _logNavPresHudScaleIfChanged(
        isLandscape: isLandscape,
        isTablet: isTablet,
        level: _driverCockpitViewLevel,
        hudSize: driverHudIconSize,
      );
    }
    if (_cameraMode == _CameraMode.follow && liveActive) {
      _logNavPres3dVehicleVisibleStateIfChanged(navPresentationState);
    }
    // NAV-FIXED-HUD-PRESENTATION-1: prepared route, NAV-to-pickup and the
    // live ride all mount the screen-fixed HUD as the sole visible owner.
    final followLiveActive = _navFixedHudPresentationActive;
    final nav3dHudRenderDecision = _resolveNav3dHudRenderDecision(
      navPresentationState,
      followLiveActive: followLiveActive,
    );
    if (followLiveActive) {
      _logNav3dHudRenderDecisionIfChanged(nav3dHudRenderDecision);
      _syncNav3d2dPresentationIfChanged(
        nav3dHudRenderDecision,
        followLiveActive: followLiveActive,
      );
      if (nav3dHudRenderDecision.actualHudVisible) {
        _logNavMarkerRenderIfChanged(
          choice: _driverNavigationMarkerChoice,
          mode: navPresentationState.mode,
        );
      }
    }
    final navActionColors = _navActionThemeColors();
    // NAV-MOBILE-DATA-MINIMAL-SAFE-RELEASE-P0-1 Part D: hide the manual +/-
    // controls during an active ride. Camera follow uses the existing
    // bounded latest-wins lifecycle; live customization is deferred to
    // AFTER STOP.
    // NAV-PRESTART-PREVIEW-AND-STABLE-BEARING-P0 (Problem 1): the active-ride
    // block is unchanged, but manual zoom is now available on the pre-start
    // preview surface, where it was previously unreachable in both phases.
    // NAV-RELEASE-SIMPLE-STREETLEVEL-1: zoom +/- visible in preview and live
    // follow under fixed streetlevel (no View-mode presentation required).
    final bool showDriverCockpitCameraControls =
        (previewPhase && navMapControls.zoomControls) ||
        (_cameraMode == _CameraMode.follow &&
            liveActive &&
            navMapControls.zoomControls &&
            navActiveRideZoomAllowed(liveRideActive: liveActive) ==
                NavActiveRideBlockReason.none);
    // NAV-VEHICLE-MODE-CAR-ARROW-1: the Car/Arrow marker selector is shown
    // during live navigation independent of the map style (Light / Dark /
    // 3D-buildings / Satellite) and independent of any 3D eligibility gate.
    final bool showNavMarkerSelector =
        followLiveActive || (previewPhase && navMapControls.markerSelector);
    final AppLanguage navMarkerLanguage = appConfig.currentLanguage;
    final safePadding = MediaQuery.of(context).padding;
    final deviceOrientation = MediaQuery.of(context).orientation;
    final tabletPortraitNavLayout = resolveDriverTabletPortraitNavLayout(
      screenClass: screenClass,
      orientation: deviceOrientation,
    );
    final viewPanelPortraitLayout = tabletPortraitNavLayout?.viewPanel;
    final cockpitControlsPlacementHints =
        resolveDriverCockpitCameraControlsPlacementHints(
          screenClass: screenClass,
          orientation: deviceOrientation,
        );
    // NAV-MOBILE-ENTERPRISE-COCKPIT-COMPACT-CONTROLS-1: phone uses two
    // independent compact zoom buttons (no panel, no View/debug labels);
    // tablet keeps its existing View panel untouched.
    final cockpitControlsPanelSize = isTablet
        ? estimateDriverCockpitCameraControlsPanelSize(
            buttonSize: 40.0,
            hasLevelLabel: true,
            hasDebugSubLabel: false,
            compactLandscape: isLandscape,
            panelWidthExtra: viewPanelPortraitLayout?.panelWidthExtra ?? 0,
            panelHorizontalPadding:
                viewPanelPortraitLayout?.panelHorizontalPadding ?? 4,
            levelLabelFontSize: viewPanelPortraitLayout?.levelLabelFontSize,
            debugLabelFontSize: viewPanelPortraitLayout?.debugLabelFontSize,
          )
        : driverPhoneZoomControlsSize();
    // NAV-PRESTART-FIELD-BLOCKER-3 (Problem D): measure the actual bottom
    // chrome (cockpit + secondary + optional estimate panel) so the portrait
    // zoom column is anchored above it instead of behind the fixed 168dp
    // assumption. The measured value only increases the offset — layouts
    // whose chrome fits under the fixed anchor keep their previous placement.
    final bool directRideEstimatePanelVisible =
        _directRideDraft &&
        _activeBooking == null &&
        (_directRideDestinationText ?? '').trim().isNotEmpty;
    const double kDirectRideEstimatePanelReserve = 96.0;
    final double measuredBottomChromeReserve = !isLandscape
        ? (kCockpitPortraitBasePanelHeight +
            (showNavQuickActions
                ? (kpiNavControlsLayout.rowHeight +
                    kpiNavControlsLayout.primaryToSecondaryGap)
                : 0.0) +
            (directRideEstimatePanelVisible
                ? kDirectRideEstimatePanelReserve
                : 0.0))
        : 0.0;
    final double bottomChromeReserve = stickyBottomChromeReserve(
      measured: measuredBottomChromeReserve,
      lastReliable: _lastReliableBottomChromeReserve,
    );
    if (bottomChromeReserve > 0) {
      _lastReliableBottomChromeReserve = bottomChromeReserve;
    }
    final DriverCockpitCameraControlsLayoutResult? cockpitControlsLayout =
        showDriverCockpitCameraControls
        ? resolveDriverCockpitCameraControlsLayout(
            screenHeight: screenH,
            safeTop: safePadding.top,
            safeBottom: safePadding.bottom,
            safeRight: safePadding.right,
            isLandscape: isLandscape,
            panelHeight: cockpitControlsPanelSize.height,
            panelWidth: cockpitControlsPanelSize.width,
            navBannerReserve: isLandscape && collapsedNavHeader
                ? kDriverCockpitControlsLandscapeBannerReserve
                : 0.0,
            bottomStripReserve: bottomChromeReserve,
            placementHints: cockpitControlsPlacementHints,
          )
        : null;
    // NAV-MOBILE-ENTERPRISE-COCKPIT-COMPACT-CONTROLS-1: compact phone vehicle
    // icon placement — left side of the map-control zone, aligned with the
    // zoom zone in portrait, mid-left in landscape, safe-area clamped.
    final DriverPhoneVehicleButtonPlacement? phoneVehicleButtonPlacement =
        (!isTablet && cockpitControlsLayout != null)
        ? resolveDriverPhoneVehicleButtonPlacement(
            screenHeight: screenH,
            safeTop: safePadding.top,
            safeBottom: safePadding.bottom,
            safeLeft: safePadding.left,
            isLandscape: isLandscape,
            zoomControlsBottom: cockpitControlsLayout.bottom,
            navBannerReserve: isLandscape && collapsedNavHeader
                ? kDriverCockpitControlsLandscapeBannerReserve
                : 0.0,
          )
        : null;
    final compactNavControlsLayout =
        resolveDriverCompactNavControlsLayoutForNav(
          screenClass: screenClass,
          orientation: deviceOrientation,
        );
    if (cockpitControlsLayout != null) {
      _logNavPresControlsLayoutIfChanged(
        isLandscape: isLandscape,
        level: _driverCockpitViewLevel,
        layout: cockpitControlsLayout,
      );
    }
    final Widget driverBody = PopScope(
      // SECURITY-REMOVE-CLIENT-ADMIN-TOKEN-P0-1 (Field Failure Fix, Blocker Fix):
      // In business-preview mode, system back is routed through the shared
      // exit guard so it blocks during live ride / STOP teardown / direct
      // finalize, invalidates a pending switch before allowing the pop,
      // and clears the owned operator-minted session before navigating.
      // Standalone driver mode retains the default pop behaviour.
      canPop: !widget.openedFromBusinessHome,
      onPopInvokedWithResult: (bool didPop, Object? _) {
        if (didPop) return;
        if (!widget.openedFromBusinessHome) return;
        _attemptBusinessPreviewRouteExit(source: 'pop_scope_system_back');
      },
      child: Scaffold(
      key: _scaffoldKey,
      // NAV-TELLERS-ROTATION-COMPOSITION-AND-POSE-LOCK-1 (Commit 1): fully
      // opaque Fluxidi root surface. This driver page is pushed OVER the
      // Business page (which stays mounted below in the Navigator); an opaque
      // Scaffold background guarantees the previous route can never paint
      // through during an orientation change or PlatformView surface delay.
      backgroundColor: kFluxidiBlack,
      drawer: _buildDrawer(),
      // NAV-ORIENTATION-VIEWPORT-STABILITY-P0-1: hard-clip the entire
      // navigation composition to the current Scaffold body viewport bounds
      // so no Positioned child computed from a previous-epoch geometry
      // (banner, HUD, chrome, cockpit control) can ever paint outside the
      // new viewport during a portrait ↔ landscape transition. This is a
      // NESTED clip (wraps the body Stack) so the outer Scaffold drawer /
      // Navigator overlay behaviour is untouched, and the inner Stack keeps
      // its existing `Clip.none` layout semantics.
      body: ClipRect(
        clipBehavior: Clip.hardEdge,
        child: Stack(
        clipBehavior: Clip.none,
        children: [
          // NAV-TELLERS-ROTATION-COMPOSITION-AND-POSE-LOCK-1 (Commit 1):
          // ALWAYS-present opaque theme backing directly BELOW the retained
          // MapWidget (independent of showCockpit). During Android
          // portrait↔landscape rotation the Hybrid-Composition map surface is
          // briefly unavailable; this backing makes the live-window aperture —
          // and any transient PlatformView gap — reveal an opaque neutral map
          // background, never the underlying Business/previous route.
          Positioned.fill(
            key: const ValueKey<String>('driver_root_opaque_backing'),
            child: const IgnorePointer(
              child: ColoredBox(color: kFluxidiMapBackdrop),
            ),
          ),
          // Map always at the back (above the opaque backing).
          // NAV-PHONE-DRIVER-VIEW-FLICKER-1: isolate the Android HC platform
          // view in its own repaint boundary so overlay/meter/timer repaints
          // above it never dirty the map layer (prevents phone HC flicker).
          Positioned.fill(child: RepaintBoundary(child: _buildMapLayer())),
          if (!showCockpit)
            Positioned.fill(
              child: IgnorePointer(
                child: Container(
                  color: const Color(0xFF040404).withOpacity(0.985),
                ),
              ),
            ),

          // Top status / header (Fluxidi strip).
          if (cockpitHudVisible &&
              !collapseTopBarInLandscapeNav &&
              !collapseTopBarInPortraitNav)
            Positioned(
              top: MediaQuery.of(context).padding.top + 10,
              left: 12,
              right: 12,
              child: _buildStatusStrip(state),
            ),
          if (cockpitHudVisible &&
              (collapseTopBarInLandscapeNav || collapseTopBarInPortraitNav))
            Positioned(
              top:
                  MediaQuery.of(context).padding.top +
                  (collapseTopBarInLandscapeNav ? 6 : 8),
              left: 10,
              // Tablet portrait/landscape: reserve trailing room for the
              // Mapbox compass so the larger banner never overlaps it.
              right: collapseTopBarInLandscapeNav ||
                      (collapseTopBarInPortraitNav && navSignageTablet)
                  ? (navSignageTablet
                        ? NavSignageTabletReadabilityMetrics
                              .defaultCompassReserve
                        : 10)
                  : null,
              child: collapseTopBarInLandscapeNav ||
                      (collapseTopBarInPortraitNav && navSignageTablet)
                  ? _buildCollapsedNavTopRowWithBanner(
                      isTablet: isTablet || navSignageTablet,
                      isLandscape: isLandscape,
                    )
                  : Row(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        _buildCollapsedNavMenuButton(),
                        const SizedBox(width: 8),
                        _buildCollapsedNavLogoCapsule(
                          isLandscape: false,
                          hasInlineBanner: false,
                        ),
                      ],
                    ),
            ),
          // Phone portrait (and non-tablet): banner stays on its own row under
          // the logo. Tablet portrait mounts the banner inline above instead.
          if (navHudVisible &&
              _showNavInstructionBanner() &&
              !collapseTopBarInLandscapeNav &&
              !(collapseTopBarInPortraitNav && navSignageTablet))
            Positioned(
              top: navBannerTop,
              left: 12,
              right: 12,
              child: Align(
                alignment: Alignment.topCenter,
                child: ConstrainedBox(
                  constraints: BoxConstraints(
                    maxWidth: navBannerPortraitMaxWidth,
                  ),
                  child: _wrapNavBannerWithComplexityCaution(
                    banner: _buildTurnInstructionBanner(
                      compact: false,
                      isTablet: isTablet,
                      portraitTabletMetrics: tabletPortraitNavLayout?.banner,
                    ),
                    compact: false,
                    isTablet: isTablet,
                  ),
                ),
              ),
            ),
          if (navHudVisible &&
              !_showNavInstructionBanner() &&
              (_navStepsLoading ||
                  _isRerouting ||
                  _navInstructionSnapshot?.source ==
                      NavInstructionSource.loading) &&
              !collapseTopBarInLandscapeNav &&
              !(collapseTopBarInPortraitNav && navSignageTablet))
            Positioned(
              top: navBannerTop,
              left: 12,
              right: 12,
              child: Align(
                alignment: Alignment.topCenter,
                child: ConstrainedBox(
                  constraints: BoxConstraints(
                    maxWidth: navBannerPortraitMaxWidth,
                  ),
                  child: _wrapNavBannerWithComplexityCaution(
                    banner: _buildNavLoadingBanner(
                      compact: false,
                      isTablet: isTablet,
                    ),
                    compact: false,
                    isTablet: isTablet,
                  ),
                ),
              ),
            ),
          if (navHudVisible &&
              !_showNavInstructionBanner() &&
              !_navStepsLoading &&
              !_isRerouting &&
              _routeSteps.isEmpty &&
              !collapseTopBarInLandscapeNav &&
              !(collapseTopBarInPortraitNav && navSignageTablet))
            Positioned(
              top: navBannerTop,
              left: 12,
              right: 12,
              child: Align(
                alignment: Alignment.topCenter,
                child: ConstrainedBox(
                  constraints: BoxConstraints(
                    maxWidth: navBannerPortraitMaxWidth,
                  ),
                  child: _wrapNavBannerWithComplexityCaution(
                    // NAV-DIRECTIONS-FAILURE-SECURITY-AND-RECOVERY-1: a failed
                    // initial route shows the sanitized connectivity/retry
                    // banner instead of the generic "Follow the route".
                    banner: _showRouteUnavailableBanner
                        ? _buildRouteUnavailableBanner(
                            compact: false,
                            isTablet: isTablet,
                          )
                        : _buildNoNavInstructionsBanner(
                            compact: false,
                            isTablet: isTablet,
                          ),
                    compact: false,
                    isTablet: isTablet,
                  ),
                ),
              ),
            ),
          if (!hideMapUserPuck && !tellersActive)
            Positioned(
              left: 0,
              right: 0,
              bottom: arrowBottom,
              child: IgnorePointer(
                child: Center(
                  child: Transform.rotate(
                    angle: _uiArrowBearing * math.pi / 180.0,
                    child: Container(
                      width: 52,
                      height: 52,
                      decoration: BoxDecoration(
                        color: const Color(0xFF2D8CFF).withOpacity(0.96),
                        shape: BoxShape.circle,
                        border: Border.all(
                          color: Colors.white.withOpacity(0.92),
                          width: 2.0,
                        ),
                        boxShadow: [
                          BoxShadow(
                            color: Colors.black.withOpacity(0.42),
                            blurRadius: 14,
                            spreadRadius: 1.0,
                          ),
                        ],
                      ),
                      child: const Icon(
                        Icons.navigation,
                        color: Colors.white,
                        size: 34,
                      ),
                    ),
                  ),
                ),
              ),
            ),
          // NAV-UI-R6F: map actions live inside the bottom cockpit bar during
          // route/nav context; only the idle map keeps a floating recenter.
          // NAV-PHASE-CAMERA-TARGET-1: also gate on the route phase so the
          // floating button can never re-appear on top of a prepared route.
          if (_mapSupported &&
              !showNavQuickActions &&
              !tellersActive &&
              navPhaseRecenterVisible(phase: _navFixedHudPhase))
            Positioned(
              right: 14,
              bottom: recenterBottom,
              child: _buildRecenterButton(),
            ),

          // NAV-PRES-2A / 3K-C / NAV-3D-HUD-ACTUAL-VISIBILITY-FIX-2:
          // optional screen-fixed driver HUD vehicle icon.
          if (followLiveActive &&
              nav3dHudRenderDecision.actualHudVisible &&
              !tellersActive)
            Positioned(
              left: 0,
              right: 0,
              bottom: driverHudBottom,
              child: Center(
                child: NavigationDriverHudOverlay(
                  iconSize: driverHudIconSize,
                  markerChoice: _driverNavigationMarkerChoice,
                  arrowScale: driverHudArrowScale,
                ),
              ),
            ),

          // NAV-PRES-3C / NAV-MOBILE-ENTERPRISE-COCKPIT-COMPACT-CONTROLS-1:
          // live +/- cockpit camera controls. Tablet keeps the existing View
          // panel (level + debug labels); phone gets two independent compact
          // buttons with no panel and no View/debug text.
          if (showDriverCockpitCameraControls &&
              cockpitControlsLayout != null &&
              !tellersActive)
            Positioned(
              right: cockpitControlsLayout.right,
              bottom: cockpitControlsLayout.bottom,
              child: isTablet
                  ? NavigationDriverCockpitCameraControls(
                      onPlus: () =>
                          _adjustDriverCockpitCameraViewLevel(increase: true),
                      onMinus: () =>
                          _adjustDriverCockpitCameraViewLevel(increase: false),
                      accentColor: navActionColors.accent,
                      textColor: navActionColors.text,
                      surfaceColor: navActionColors.surface,
                      // Compact zoom value only — never View N/13 / preset names.
                      levelLabel: _driverCockpitViewLevelLabel(),
                      debugSubLabel: null,
                      compactLandscape: isLandscape,
                      portraitPanelLayout: viewPanelPortraitLayout,
                    )
                  : NavigationDriverPhoneZoomControls(
                      onPlus: () =>
                          _adjustDriverCockpitCameraViewLevel(increase: true),
                      onMinus: () =>
                          _adjustDriverCockpitCameraViewLevel(increase: false),
                      accentColor: navActionColors.accent,
                      textColor: navActionColors.text,
                      surfaceColor: navActionColors.surface,
                    ),
            ),

          // NAV-VEHICLE-MODE-CAR-ARROW-1: tablet gets two direct marker
          // buttons [ Auto ] [ Pijl ] above the View panel — on every map
          // style.
          if (showNavMarkerSelector &&
              cockpitControlsLayout != null &&
              isTablet &&
              !tellersActive)
            Positioned(
              right: cockpitControlsLayout.right,
              bottom:
                  cockpitControlsLayout.bottom +
                  cockpitControlsPanelSize.height +
                  8,
              child: NavigationDriverMarkerChoiceSelector(
                selectedChoice: _driverNavigationMarkerChoice,
                onSelected: _setDriverNavigationMarkerChoice,
                accentColor: navActionColors.accent,
                textColor: navActionColors.text,
                surfaceColor: navActionColors.surface,
                language: navMarkerLanguage,
                compactLandscape: isLandscape,
              ),
            ),

          // NAV-VEHICLE-MODE-CAR-ARROW-1: phone gets one compact marker icon
          // on the left side of the map-control zone; the popup drives the
          // same Car/Arrow callback — on every map style.
          if (showNavMarkerSelector &&
              phoneVehicleButtonPlacement != null &&
              !isTablet &&
              !tellersActive)
            Positioned(
              left: phoneVehicleButtonPlacement.left,
              bottom: phoneVehicleButtonPlacement.bottom,
              child: NavigationDriverMarkerCompactButton(
                selectedChoice: _driverNavigationMarkerChoice,
                onSelected: _setDriverNavigationMarkerChoice,
                accentColor: navActionColors.accent,
                textColor: navActionColors.text,
                surfaceColor: navActionColors.surface,
                language: navMarkerLanguage,
              ),
            ),

          if (!showCockpit) Positioned.fill(child: _buildHintPanel()),

          // Bottom overlay layer (cockpit only).
          if (cockpitHudVisible)
            Positioned.fill(
              child: AnimatedSwitcher(
                duration: const Duration(milliseconds: 180),
                switchInCurve: Curves.easeOut,
                switchOutCurve: Curves.easeOut,
                // NAV-UI-R6F: cockpit is full width in both orientations and
                // hosts the compact map action icons (recenter, satellite,
                // offline, diagnostics, more) during route/nav context.
                child: SafeArea(
                  key: ValueKey<String>(
                    isLandscape ? 'landscape_cockpit' : 'portrait_cockpit',
                  ),
                  minimum: EdgeInsets.zero,
                  child: Align(
                    alignment: Alignment.bottomCenter,
                    child: Padding(
                      padding: EdgeInsets.only(
                        left: 8,
                        right: 8,
                        bottom: MediaQuery.of(context).viewInsets.bottom,
                      ),
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          if (showNavQuickActions) _buildCockpitR9StatusChip(),
                          CockpitWidget(
                            embedded: true,
                            themeListenable: _activeDriverThemeListenable,
                            etaText: _etaText,
                            kmText: _kmRemainingText,
                            priceText: _cockpitPriceText,
                            priceLabel: _displayPriceLabel,
                            tripStarted: _liveRideActive,
                            isWaiting: _isWaiting,
                            navActive: _cameraMode == _CameraMode.follow,
                            showNavToPickupAction: _showNavToPickupAction,
                            onNav: _openNavigation,
                            onStart: _handleCockpitStart,
                            onStop: _stopTrip,
                            onWait: _enterWaitMode,
                            onGo: _exitWaitMode,
                            secondaryActions: showNavQuickActions
                                ? _buildCockpitSecondaryActions(
                                    phoneLandscapeKpiPriorityCollapsed:
                                        isLandscape &&
                                        !isTablet &&
                                        _phoneLandscapeKpiPriorityCollapsed,
                                  )
                                : const <Widget>[],
                            landscapeKpiPriority:
                                isLandscape &&
                                !isTablet &&
                                _phoneLandscapeKpiPriorityCollapsed,
                            secondaryActionGap:
                                compactNavControlsLayout.horizontalGap,
                            secondaryActionRowHeight:
                                compactNavControlsLayout.rowHeight,
                            metricsToPrimaryGap:
                                compactNavControlsLayout.metricsToPrimaryGap,
                            primaryToSecondaryGap:
                                compactNavControlsLayout.primaryToSecondaryGap,
                            secondaryRowHorizontalInset:
                                compactNavControlsLayout
                                    .secondaryRowHorizontalInset,
                            distributeSecondaryRowEvenly:
                                compactNavControlsLayout
                                    .distributeSecondaryRowEvenly,
                          ),
                          _buildDirectRideEstimatePanel(),
                        ],
                      ),
                    ),
                  ),
                ),
              ),
            ),
          // NAV-PRESENTATION-COMPACT-BANNER-LANES-TELLERS-1:
          // Opaque Tellers overlay keeps MapWidget + nav State mounted below.
          if (_navPresentationMode.isTellers)
            _buildTellersOverlay(isTablet: isTablet, isLandscape: isLandscape),
        ],
      ),
      ),
    ),
    );
    if (!pipActive) return driverBody;
    // EXTERNAL-NAV-RETURN-LIFECYCLE-P0-7: meter overlay + keep MapWidget alive.
    debugPrint(
      '[EXTERNAL_NAV] event=pip_overlay_active '
      'process_id=dart map_kept_mounted=true',
    );
    // GOOGLE-MAPS-PIP-LIVE-METER-P0: listen to the same meter notifier as
    // Tellers. Parent setState is rare while Maps owns the foreground; without
    // this, PiP would freeze on the enter-time snapshot while GPS/fare continue.
    // MapWidget stays Offstage-mounted — do NOT setState every meter tick.
    // PIP-TABLET-READABILITY-LOCALE-P1: also observe driver app language so a
    // language change while PiP is active updates chrome without relaunch.
    return Stack(
      fit: StackFit.expand,
      children: [
        Offstage(offstage: true, child: driverBody),
        Scaffold(
          backgroundColor: const Color(0xFF0B0F14),
          body: ValueListenableBuilder<AppLanguage>(
            valueListenable: appLanguageNotifier,
            builder: (context, lang, _) {
              return ValueListenableBuilder<DriverRideMetersSnapshot>(
                valueListenable: _driverRideMetersNotifier,
                builder: (context, snap, _) {
                  return ExternalNavPipMeterCard(
                    model: _buildCurrentPipMeterModel(snap, lang),
                  );
                },
              );
            },
          ),
        ),
      ],
    );
  }

  Widget _buildMapLayer() {
    // NAV-DRIVER-VIEW-EXIT-MAP-FLASH-P0-FIELD-2026-07-30: while the route exit
    // is in flight the retained Hybrid-Composition MapWidget is replaced by an
    // opaque backdrop, detaching the native surface so it cannot be presented
    // during the Navigator pop transition. Checked FIRST so no map build log
    // or platform-view build happens on the exiting frame.
    if (_routeExitInProgress) {
      return const ColoredBox(
        key: ValueKey<String>('driver_map_route_exit_backdrop'),
        color: kFluxidiMapBackdrop,
      );
    }
    final now = DateTime.now();
    final lastBuildLog = _lastMapWidgetBuildLogAt;
    if (lastBuildLog == null || now.difference(lastBuildLog).inSeconds >= 5) {
      _lastMapWidgetBuildLogAt = now;
      debugPrint(
        '[MAP][WIDGET_BUILD] mapSupported=$_mapSupported hasMap=${_map != null}',
      );
    }
    if (kIsWindows) {
      return _mapPlaceholder(
        title: 'Map unavailable on Windows',
        subtitle: 'Run on Android to see the live map.',
      );
    }

    if (kIsWeb) {
      return _mapPlaceholder(
        title: 'Map unavailable on Web',
        subtitle: 'Run on Android to see the live map.',
      );
    }

    return _stableMapWidget;
  }

  Widget _mapPlaceholder({required String title, required String subtitle}) {
    return Container(
      decoration: const BoxDecoration(
        gradient: RadialGradient(
          radius: 1.2,
          colors: [Color(0xFF141B2F), Color(0xFF070A10)],
        ),
      ),
      child: Center(
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 520),
          child: Container(
            margin: const EdgeInsets.all(18),
            padding: const EdgeInsets.all(16),
            decoration: BoxDecoration(
              color: const Color(0xFF141B2F),
              borderRadius: BorderRadius.circular(18),
              border: Border.all(color: Colors.white12),
            ),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  title,
                  style: const TextStyle(
                    fontSize: 18,
                    fontWeight: FontWeight.w700,
                  ),
                ),
                const SizedBox(height: 8),
                Text(subtitle, style: const TextStyle(color: Colors.white70)),
              ],
            ),
          ),
        ),
      ),
    );
  }

  Widget _buildTopStatus(bool active) {
    if (!active) return const SizedBox.shrink();

    final eta = _fmtDur(_remainingSec());
    final km = _fmtRemainingKm();

    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 11),
      decoration: BoxDecoration(
        color: const Color(0xFF141B2F).withOpacity(0.92),
        borderRadius: BorderRadius.circular(18),
        border: Border.all(color: Colors.white12),
      ),
      child: Row(
        children: [
          const Icon(Icons.circle, size: 10, color: Color(0xFF4CD964)),
          const SizedBox(width: 10),
          Expanded(
            child: Text(
              'Tracking actief • Ping: $_lastPing • ETA: $eta • KM: $km',
              style: const TextStyle(fontWeight: FontWeight.w800),
              overflow: TextOverflow.ellipsis,
            ),
          ),
          const SizedBox(width: 10),
          FilledButton(
            style: FilledButton.styleFrom(
              backgroundColor: const Color(0xFFED6A5A).withOpacity(0.28),
              foregroundColor: const Color(0xFFFFB4AA),
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(16),
              ),
            ),
            onPressed: _stopTrip,
            child: Text(kStopShortLabel),
          ),
        ],
      ),
    );
  }

  Widget _buildBookingsSheet(double screenH) {
    final padding = MediaQuery.of(context).padding.bottom;
    final isMidnightBlue =
        driverThemeNotifier.value == DriverThemeVariant.midnightBlue;
    final isMiddayGold =
        driverThemeNotifier.value == DriverThemeVariant.highContrast;
    final sheetGradient = isMiddayGold
        ? _middayGoldSurfaceGradient(soft: true)
        : (isMidnightBlue
              ? _midnightBlueSurfaceGradient(soft: true)
              : const LinearGradient(
                  begin: Alignment.topLeft,
                  end: Alignment.bottomRight,
                  colors: [Color(0xFF141B2F), Color(0xFF101113)],
                ));
    final sheetBorder = isMiddayGold
        ? _middayGoldBorderColor(0.34)
        : (isMidnightBlue ? _midnightBlueBorderColor(0.38) : Colors.white12);
    final sheetGlow = isMidnightBlue
        ? _midnightBlueAccent().withOpacity(0.20)
        : (isMiddayGold
              ? const Color(0x66E8C57E).withOpacity(0.34)
              : kFluxidiYellowSoft);

    return Container(
      margin: const EdgeInsets.all(12),
      padding: EdgeInsets.only(
        left: 14,
        right: 14,
        top: 14,
        bottom: 14 + padding,
      ),
      decoration: BoxDecoration(
        gradient: sheetGradient,
        borderRadius: BorderRadius.circular(22),
        border: Border.all(color: sheetBorder),
        boxShadow: [
          BoxShadow(blurRadius: 18, spreadRadius: 2, color: Colors.black54),
          BoxShadow(blurRadius: 26, spreadRadius: 1, color: sheetGlow),
        ],
      ),
      child: _buildBookingsList(screenH),
    );
  }

  Widget _buildBookingsList(double screenH) {
    final isMidnightBlue =
        driverThemeNotifier.value == DriverThemeVariant.midnightBlue;
    final isMiddayGold =
        driverThemeNotifier.value == DriverThemeVariant.highContrast;
    final panelGradient = isMiddayGold
        ? _middayGoldSurfaceGradient(soft: true)
        : (isMidnightBlue ? _midnightBlueSurfaceGradient(soft: true) : null);
    final panelFill = (isMiddayGold || isMidnightBlue)
        ? null
        : const Color(0xFF101113);
    final panelBorder = isMiddayGold
        ? _middayGoldBorderColor(0.34)
        : (isMidnightBlue
              ? _midnightBlueBorderColor(0.40)
              : kFluxidiYellow.withOpacity(0.30));
    final textPrimary = isMiddayGold
        ? _middayGoldTextPrimary()
        : (isMidnightBlue ? _midnightBlueTextPrimary() : Colors.white);
    final textMuted = isMiddayGold
        ? _middayGoldTextMuted()
        : (isMidnightBlue
              ? _midnightBlueTextMuted()
              : Colors.white.withOpacity(0.72));
    final spinnerColor = isMidnightBlue
        ? _midnightBlueAccent()
        : (isMiddayGold ? const Color(0xFFE8C57E) : kFluxidiYellow);
    final visibleBookings = _ridesHubSegmentBookings();
    final emptyTitle = switch (_ridesHubSegment) {
      _DriverRidesHubSegment.available => _tr(
        nl: 'Geen beschikbare ritten',
        en: 'No available rides',
        fr: 'Aucune course disponible',
        es: 'No hay viajes disponibles',
      ),
      _DriverRidesHubSegment.myRides => _tr(
        nl: 'Geen ritten klaar',
        en: 'No rides ready',
        fr: 'Aucune course prête',
        es: 'No hay viajes listos',
      ),
      _DriverRidesHubSegment.history => _tr(
        nl: 'Geen historiek',
        en: 'No history',
        fr: 'Aucun historique',
        es: 'Sin historial',
      ),
    };
    final emptyBody = switch (_ridesHubSegment) {
      _DriverRidesHubSegment.available => _tr(
        nl: 'Nieuwe beschikbare ritten verschijnen hier zodra ze door het systeem zijn vrijgegeven.',
        en: 'New available rides appear here once released by the system.',
        fr: 'Les nouvelles courses disponibles apparaissent ici une fois libérées par le système.',
        es: 'Los nuevos viajes disponibles aparecerán aquí cuando el sistema los publique.',
      ),
      _DriverRidesHubSegment.myRides => _tr(
        nl: 'Nieuwe boekingen verschijnen hier zodra ze aan jou of je bedrijf zijn gekoppeld.',
        en: 'New bookings appear here once they are assigned to you or your company.',
        fr: 'Les nouvelles réservations apparaissent ici dès qu’elles sont liées à vous ou à votre entreprise.',
        es: 'Las nuevas reservas aparecerán aquí cuando estén vinculadas a ti o a tu empresa.',
      ),
      _DriverRidesHubSegment.history => _tr(
        nl: 'Afgeronde ritten verschijnen hier zodra ze zijn voltooid of geannuleerd.',
        en: 'Completed rides appear here once they are finished or cancelled.',
        fr: 'Les courses terminées apparaissent ici une fois achevées ou annulées.',
        es: 'Los viajes completados aparecerán aquí cuando finalicen o se cancelen.',
      ),
    };
    final emptyInfoTitle = _tr(
      nl: 'Geen rit gevonden?',
      en: 'No ride found?',
      fr: 'Aucune course trouvée ?',
      es: '¿No encontraste un viaje?',
    );
    final emptyInfoBody = _tr(
      nl: 'Er zijn momenteel geen ritten beschikbaar. Trek omlaag om te vernieuwen.',
      en: 'There are currently no rides available. Pull down to refresh.',
      fr: 'Aucune course n’est disponible pour le moment. Tirez vers le bas pour actualiser.',
      es: 'Actualmente no hay viajes disponibles. Desliza hacia abajo para actualizar.',
    );
    return Column(
      mainAxisSize: MainAxisSize.max,
      children: [
        Container(
          width: double.infinity,
          padding: const EdgeInsets.all(5),
          decoration: BoxDecoration(
            color: panelFill,
            gradient: panelGradient,
            borderRadius: BorderRadius.circular(14),
            border: Border.all(color: panelBorder),
          ),
          child: SingleChildScrollView(
            scrollDirection: Axis.horizontal,
            physics: const BouncingScrollPhysics(),
            clipBehavior: Clip.none,
            padding: const EdgeInsets.symmetric(horizontal: 2),
            child: Row(
              children: [
                _ridesSegmentChip(
                  label: _tr(
                    nl: 'Beschikbaar',
                    en: 'Available',
                    fr: 'Disponibles',
                    es: 'Disponibles',
                  ),
                  active: _ridesHubSegment == _DriverRidesHubSegment.available,
                  onTap: () {
                    if (_ridesHubSegment == _DriverRidesHubSegment.available) {
                      return;
                    }
                    debugPrint(
                      '[DRIVER_RIDES][SEGMENT] segment=${_DriverRidesHubSegment.available} source=hub_chip',
                    );
                    setState(
                      () => _ridesHubSegment = _DriverRidesHubSegment.available,
                    );
                    _markBookingsUiDirty();
                  },
                ),
                const SizedBox(width: 6),
                _ridesSegmentChip(
                  label: _tr(
                    nl: 'Mijn ritten',
                    en: 'My rides',
                    fr: 'Mes courses',
                    es: 'Mis viajes',
                  ),
                  active: _ridesHubSegment == _DriverRidesHubSegment.myRides,
                  onTap: () {
                    if (_ridesHubSegment == _DriverRidesHubSegment.myRides) {
                      return;
                    }
                    debugPrint(
                      '[DRIVER_RIDES][SEGMENT] segment=${_DriverRidesHubSegment.myRides} source=hub_chip',
                    );
                    setState(
                      () => _ridesHubSegment = _DriverRidesHubSegment.myRides,
                    );
                    _markBookingsUiDirty();
                    _maybeForceRefreshOnMyRidesOpen(source: 'hub_chip');
                  },
                ),
                const SizedBox(width: 6),
                _ridesSegmentChip(
                  label: _tr(
                    nl: 'Historiek',
                    en: 'History',
                    fr: 'Historique',
                    es: 'Historial',
                  ),
                  active: _ridesHubSegment == _DriverRidesHubSegment.history,
                  onTap: () {
                    debugPrint(
                      '[DRIVER_RIDES][SEGMENT] segment=${_DriverRidesHubSegment.history} source=hub_chip action=open_trip_history',
                    );
                    _openTripHistoryFromDashboard();
                  },
                ),
                const SizedBox(width: 4),
              ],
            ),
          ),
        ),
        const SizedBox(height: 10),
        if (_loadingBookings)
          Container(
            width: double.infinity,
            padding: const EdgeInsets.symmetric(vertical: 26, horizontal: 18),
            decoration: BoxDecoration(
              color: panelFill,
              gradient: panelGradient,
              borderRadius: BorderRadius.circular(18),
              border: Border.all(color: panelBorder),
            ),
            child: Column(
              children: [
                SizedBox(
                  width: 24,
                  height: 24,
                  child: CircularProgressIndicator(
                    strokeWidth: 2.2,
                    color: spinnerColor,
                  ),
                ),
                const SizedBox(height: 10),
                Text(
                  _tr(
                    nl: 'Ritten worden geladen...',
                    en: 'Loading rides...',
                    fr: 'Chargement des courses...',
                    es: 'Cargando viajes...',
                  ),
                  style: TextStyle(
                    color: textMuted,
                    fontWeight: FontWeight.w600,
                  ),
                ),
              ],
            ),
          )
        else if (_bookingsError != null)
          Container(
            width: double.infinity,
            padding: const EdgeInsets.all(14),
            decoration: BoxDecoration(
              color: const Color(0xFF1B1212),
              borderRadius: BorderRadius.circular(16),
              border: Border.all(
                color: const Color(0xFF7A2A2A).withOpacity(0.8),
              ),
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  _tr(
                    nl: 'Ritten konden niet geladen worden.',
                    en: 'Could not load rides.',
                    fr: 'Impossible de charger les courses.',
                    es: 'No se pudieron cargar los viajes.',
                  ),
                  style: const TextStyle(
                    color: Color(0xFFFFB3B3),
                    fontWeight: FontWeight.w700,
                  ),
                ),
                const SizedBox(height: 4),
                Text(
                  'Error: $_bookingsError',
                  style: const TextStyle(color: Colors.redAccent),
                ),
              ],
            ),
          )
        else if (visibleBookings.isEmpty)
          Column(
            children: [
              Container(
                width: double.infinity,
                padding: const EdgeInsets.all(16),
                decoration: BoxDecoration(
                  color: panelFill,
                  gradient: panelGradient,
                  borderRadius: BorderRadius.circular(18),
                  border: Border.all(color: panelBorder),
                ),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      emptyTitle,
                      style: TextStyle(
                        color: textPrimary,
                        fontSize: 15.5,
                        fontWeight: FontWeight.w800,
                      ),
                    ),
                    const SizedBox(height: 6),
                    Text(
                      emptyBody,
                      style: TextStyle(color: textMuted, height: 1.35),
                    ),
                  ],
                ),
              ),
              const SizedBox(height: 10),
              Container(
                width: double.infinity,
                padding: const EdgeInsets.all(14),
                decoration: BoxDecoration(
                  color: panelFill,
                  gradient: panelGradient,
                  borderRadius: BorderRadius.circular(14),
                  border: Border.all(
                    color: isMiddayGold
                        ? _middayGoldBorderColor(0.28)
                        : (isMidnightBlue
                              ? _midnightBlueBorderColor(0.34)
                              : kFluxidiYellow.withOpacity(0.25)),
                  ),
                ),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      emptyInfoTitle,
                      style: TextStyle(
                        color: textPrimary,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                    const SizedBox(height: 4),
                    Text(
                      emptyInfoBody,
                      style: TextStyle(
                        color: textMuted,
                        fontSize: 12.4,
                        height: 1.35,
                      ),
                    ),
                  ],
                ),
              ),
            ],
          )
        else
          Expanded(
            child: ListView.separated(
              padding: EdgeInsets.only(
                bottom: MediaQuery.of(context).padding.bottom + 12,
              ),
              itemCount: visibleBookings.length,
              separatorBuilder: (_, __) => const SizedBox(height: 10),
              itemBuilder: (context, i) {
                final booking = visibleBookings[i];
                if (_ridesHubSegment == _DriverRidesHubSegment.available) {
                  return _buildAvailableUnassignedBookingCard(booking);
                }
                return _bookingCard(booking);
              },
            ),
          ),
      ],
    );
  }

  ({String label, String value}) _driverCardReferenceDisplay(BookingItem b) {
    final canonicalBookingId = _cleanBusinessReferenceText(b.bookingId) ?? '';
    final detailsMap = Map<String, dynamic>.from(b.details);
    if (canonicalBookingId.isNotEmpty) {
      detailsMap['booking_id'] = canonicalBookingId;
      detailsMap['bookingId'] = canonicalBookingId;
    }
    final maps = _referenceLookupMaps(<Map<String, dynamic>>[detailsMap]);
    final refs = _extractBusinessReferenceAliasesFromMaps(maps);
    final planning = refs.planning ?? '';
    final publicBooking =
        refs.publicBooking ?? refs.booking ?? refs.publicRef ?? '';

    String label;
    String value;
    if (planning.isNotEmpty) {
      label = _tr(
        nl: 'Planningnummer',
        en: 'Planning no.',
        fr: 'N° de planning',
        es: 'N.º de planificación',
      );
      value = planning;
    } else if (publicBooking.isNotEmpty) {
      label = _tr(
        nl: 'Boekingsnummer',
        en: 'Booking no.',
        fr: 'N° de réservation',
        es: 'N.º de reserva',
      );
      value = publicBooking;
    } else {
      label = _tr(
        nl: 'Interne boeking',
        en: 'Internal booking',
        fr: 'Réservation interne',
        es: 'Reserva interna',
      );
      value = canonicalBookingId.isEmpty ? b.shortId : canonicalBookingId;
    }
    debugPrint(
      '[RIDES][CARD_REF_SELECTED] booking=${_safeRefPreview(canonicalBookingId)} planning=$planning public=$publicBooking selected=$value',
    );
    return (label: label, value: value);
  }

  bool _bookingIsOperationalLeg(BookingItem b) {
    return b.isOperationalLeg;
  }

  bool _bookingIsRoundtripParent(BookingItem b) {
    final token =
        (b.details['is_roundtrip_parent'] ??
                b.details['isRoundtripParent'] ??
                '')
            .toString()
            .trim()
            .toLowerCase();
    return token == 'true' || token == '1';
  }

  String _bookingLegType(BookingItem b) {
    return (b.details['leg_type'] ?? b.details['legType'] ?? '')
        .toString()
        .trim()
        .toLowerCase();
  }

  String _bookingLegLabel(BookingItem b) {
    final legType = _bookingLegType(b);
    if (legType == 'return') {
      return _tr(
        nl: 'Terugrit',
        en: 'Return ride',
        fr: 'Trajet retour',
        es: 'Viaje de vuelta',
      );
    }
    if (legType == 'outbound') {
      return _tr(
        nl: 'Heenrit',
        en: 'Outbound ride',
        fr: 'Trajet aller',
        es: 'Viaje de ida',
      );
    }
    return _tr(
      nl: 'Geplande rit',
      en: 'Planned ride',
      fr: 'Course planifiée',
      es: 'Viaje planificado',
    );
  }

  Widget _buildAvailableUnassignedBookingCard(BookingItem b) {
    debugPrint('[DRIVER_RIDES][AVAILABLE_CARD] booking_id=${b.bookingId}');
    final isMidnightBlue =
        driverThemeNotifier.value == DriverThemeVariant.midnightBlue;
    final isMiddayGold =
        driverThemeNotifier.value == DriverThemeVariant.highContrast;
    final cardPrimary = isMiddayGold
        ? _middayGoldTextPrimary()
        : (isMidnightBlue ? _midnightBlueTextPrimary() : Colors.white);
    final cardMuted = isMiddayGold
        ? _middayGoldTextMuted()
        : (isMidnightBlue
              ? _midnightBlueTextMuted()
              : Colors.white.withOpacity(0.66));
    final cardAccent = isMidnightBlue
        ? _midnightBlueAccent()
        : (isMiddayGold ? const Color(0xFFE8C57E) : const Color(0xFFFFD36A));
    final dt = _formatPickup(b.pickupIso);
    final cardReference = _driverCardReferenceDisplay(b);
    final customerName =
        _bookingScopeFirstText(_bookingScopeViewFor(b), const [
          ['customer_name'],
          ['customerName'],
          ['customer', 'name'],
          ['booking', 'customer_name'],
          ['booking', 'customerName'],
          ['booking', 'customer', 'name'],
        ]) ??
        '';
    final awaitingDispatchLabel = _tr(
      nl: 'Wacht op toewijzing',
      en: 'Awaiting dispatch',
      fr: 'En attente d\'assignation',
      es: 'En espera de asignacion',
    );
    final readOnlyHint = _tr(
      nl: 'Deze rit is zichtbaar maar nog niet aan jou toegewezen.',
      en: 'This ride is visible but not assigned to you yet.',
      fr: 'Cette course est visible mais pas encore assignee.',
      es: 'Este viaje es visible pero aun no esta asignado.',
    );

    return Container(
      padding: const EdgeInsets.fromLTRB(14, 14, 14, 18),
      decoration: BoxDecoration(
        gradient: isMiddayGold
            ? _middayGoldSurfaceGradient()
            : (isMidnightBlue
                  ? _midnightBlueSurfaceGradient()
                  : const LinearGradient(
                      begin: Alignment.topLeft,
                      end: Alignment.bottomRight,
                      colors: [Color(0xFF151515), Color(0xFF0B0B0B)],
                    )),
        borderRadius: BorderRadius.circular(22),
        border: Border.all(
          color: isMiddayGold
              ? _middayGoldBorderColor(0.36)
              : (isMidnightBlue
                    ? _midnightBlueBorderColor(0.42)
                    : kFluxidiYellow.withOpacity(0.24)),
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          _pill(
            icon: Icons.schedule,
            text: dt,
            borderColor: isMidnightBlue
                ? _midnightBlueBorderColor(0.50)
                : const Color(0x55FFD36A),
            textColor: isMidnightBlue
                ? _midnightBlueTextPrimary()
                : const Color(0xFFFFD98A),
            compact: true,
          ),
          const SizedBox(height: 10),
          Text(
            b.from ?? '—',
            maxLines: 2,
            overflow: TextOverflow.ellipsis,
            style: TextStyle(
              color: cardPrimary,
              fontSize: 15.1,
              fontWeight: FontWeight.w700,
              height: 1.2,
            ),
          ),
          const SizedBox(height: 8),
          Text(
            b.to ?? '—',
            maxLines: 2,
            overflow: TextOverflow.ellipsis,
            style: TextStyle(
              color: cardPrimary.withOpacity(0.92),
              fontSize: 15.0,
              fontWeight: FontWeight.w600,
              height: 1.2,
            ),
          ),
          if (customerName.trim().isNotEmpty) ...[
            const SizedBox(height: 7),
            Text(
              '${_tr(nl: 'Klant', en: 'Customer', fr: 'Client', es: 'Cliente')}: $customerName',
              maxLines: 2,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(
                color: cardMuted.withOpacity(0.92),
                fontSize: 11.8,
                fontWeight: FontWeight.w500,
              ),
            ),
          ],
          const SizedBox(height: 10),
          Wrap(
            spacing: 6,
            runSpacing: 6,
            children: [
              _pill(
                text: awaitingDispatchLabel,
                borderColor: const Color(0xFF52B6FF),
                textColor: const Color(0xFF9DD8FF),
                compact: true,
              ),
              if (_driverDisplayPriceForBooking(b) != null)
                _pill(
                  text: _fmtMoney(
                    _driverDisplayPriceForBooking(b)!,
                    b.currency ?? 'EUR',
                  ),
                  borderColor: isMidnightBlue
                      ? _midnightBlueBorderColor(0.50)
                      : const Color(0x55FFD36A),
                  textColor: cardAccent,
                  compact: true,
                ),
            ],
          ),
          if (cardReference.value.trim().isNotEmpty) ...[
            const SizedBox(height: 8),
            Text(
              '${cardReference.label}: ${cardReference.value}',
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(
                color: cardMuted.withOpacity(0.82),
                fontSize: 10.8,
                fontWeight: FontWeight.w500,
              ),
            ),
          ],
          const SizedBox(height: 10),
          Text(
            readOnlyHint,
            style: TextStyle(
              color: cardMuted,
              fontSize: 12.2,
              height: 1.35,
              fontWeight: FontWeight.w500,
            ),
          ),
          const SizedBox(height: 10),
          SizedBox(
            width: double.infinity,
            height: 40,
            child: OutlinedButton.icon(
              onPressed: null,
              icon: const Icon(Icons.hourglass_empty_rounded, size: 16),
              label: Text(
                awaitingDispatchLabel,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(fontWeight: FontWeight.w700),
              ),
            ),
          ),
        ],
      ),
