        '';

    return LayoutBuilder(
      builder: (context, c) {
        final compactPortrait =
            c.maxWidth < 390 &&
            MediaQuery.of(context).orientation == Orientation.portrait;
        final narrow = c.maxWidth < 380;
        final tight = c.maxWidth < 340;
